INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e1b6607-1440-4c27-a25a-233c079b8011', '自薊北歸', '自薊北归', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["驅馬薊門北，北風邊馬哀。","蒼茫遠山口，豁達胡天開。","五將已深入，前軍止半廻。","誰憐不得意，長劒獨歸來。"]', '["驱马薊门北，北风邊马哀。","蒼茫远山口，豁達胡天开。","五將已深入，前軍止半廻。","誰怜不得意，长劒独归来。"]', '诗', 'shi', '', NULL, '自薊北歸 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c3562c-6d4b-464b-9a0f-e00747aed961', '東平別前衛縣李寀少府', '东平別前衛縣李寀少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["黃鳥翩翩楊柳垂，春風送客使人悲。","怨別自驚千里外，論交却憶十年時。","雲開汶水孤帆遠，路繞梁山匹馬遲。","此地從來可乘興，留君不住益淒其。"]', '["黄鸟翩翩楊柳垂，春风送客使人悲。","怨別自驚千里外，論交却憶十年时。","云开汶水孤帆远，路繞梁山匹马遲。","此地從来可乘兴，留君不住益淒其。"]', '诗', 'shi', '', NULL, '東平別前衛縣李寀少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dddc5861-5ad3-438a-999e-f068b10fc886', '夜別韋司士得城字', '夜別韋司士得城字', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["高館張燈酒復清，夜鐘殘月雁歸聲。","只言啼鳥堪求侶，無那春風欲送行。","黃河曲裏沙爲岸，白馬津邊柳向城。","莫怨他鄉暫離別，知君到處有逢迎。"]', '["高館張灯酒复清，夜鐘殘月雁归声。","只言啼鸟堪求侶，無那春风欲送行。","黄河曲裏沙爲岸，白马津邊柳向城。","莫怨他乡暫離別，知君到处有逢迎。"]', '诗', 'shi', '', NULL, '夜別韋司士得城字 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c24cec1-4105-4511-bf8b-bc6d5d8d48c7', '送李少府貶峽中王少府貶長沙', '送李少府貶峽中王少府貶长沙', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["嗟君此別意何如，駐馬銜桮問謫居。","巫峽啼猿數行淚，衡陽歸雁幾封書。","青楓江上秋天遠，白帝城邊古木疎。","聖代即今多雨露，暫時分手莫躊躇。"]', '["嗟君此別意何如，駐马銜桮问謫居。","巫峽啼猿數行泪，衡陽归雁幾封书。","青楓江上秋天远，白帝城邊古木疎。","聖代即今多雨露，暫时分手莫躊躇。"]', '诗', 'shi', '', NULL, '送李少府貶峽中王少府貶長沙 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616f4ecc-b50f-4045-b99b-82cb54059843', '同陳留崔司戶早春宴蓬池', '同陳留崔司戶早春宴蓬池', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["同官載酒出郊圻，晴日東馳雁北飛。","隔岸春雲邀翰墨，傍簷垂柳報芳菲。","池邊轉覺虛無盡，臺上偏宜酩酊歸。","州縣徒勞那可度，後時連騎莫相違。"]', '["同官載酒出郊圻，晴日东驰雁北飞。","隔岸春云邀翰墨，傍簷垂柳報芳菲。","池邊轉覺虛無尽，台上偏宜酩酊归。","州縣徒勞那可度，後时連騎莫相違。"]', '诗', 'shi', '', NULL, '同陳留崔司戶早春宴蓬池 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cf9dad-6b92-4761-a28c-a170b60bcf84', '金城北樓', '金城北楼', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["北樓西望滿晴空，積水連山勝畫中。","湍上急流聲若箭，城頭殘月勢如弓。","垂竿已羨磻谿老，體道猶思塞上翁。","爲問邊庭更何事，至今羌笛怨無窮。"]', '["北楼西望满晴空，積水連山勝畫中。","湍上急流声若箭，城头殘月勢如弓。","垂竿已羨磻谿老，體道猶思塞上翁。","爲问邊庭更何事，至今羌笛怨無窮。"]', '诗', 'shi', '', NULL, '金城北樓 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15abc23d-8849-43a1-aeb8-28eebdaac884', '同顏六少府旅宦秋中之作', '同顏六少府旅宦秋中之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["傳君昨夜悵然悲，獨坐新齋木落時。","逸氣舊來凌燕雀，高才何得混妍媸。","跡留黃綬人多歎，心在青雲世莫知。","不是鬼神無正直，從來州縣有瑕疵。"]', '["傳君昨夜悵然悲，独坐新斋木落时。","逸氣旧来凌燕雀，高才何得混妍媸。","跡留黄綬人多歎，心在青云世莫知。","不是鬼神無正直，從来州縣有瑕疵。"]', '诗', 'shi', '', NULL, '同顏六少府旅宦秋中之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1fa02b3-3fdd-4de6-86d8-264f36cfee99', '重陽', '重陽', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["節物驚心兩鬢華，東籬空繞未開花。","百年將半仕三已，五畝就荒天一涯。","豈有白衣來剝啄，一從烏帽自攲斜。","真成獨坐空搔首，門柳蕭蕭噪暮鴉。"]', '["節物驚心兩鬢华，东籬空繞未开花。","百年將半仕三已，五畝就荒天一涯。","豈有白衣来剝啄，一從烏帽自攲斜。","真成独坐空搔首，门柳蕭蕭噪暮鴉。"]', '诗', 'shi', '', NULL, '重陽 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be2bff30-cbdc-4dde-87d4-ea7021125a4b', '古樂府飛龍曲留上陳左相', '古乐府飞龙曲留上陳左相', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["德以精靈降，時膺夢寐求。","蒼生謝安石，天子富平侯。","尊俎資高論，巖廊挹大猷。","相門連戶牖，卿族嗣弓裘。","豁達雲開霽，清明月映秋。","能爲吉甫頌，善用子房籌。","階砌思攀陟，門闌尚阻修。","高山不易仰，大匠本難投。","跡與松喬合，心緣啓沃留。","公才山吏部，書癖杜荆州。","幸沐千年聖，何辭一尉休。","折腰知寵辱，廻首見沈浮。","天地莊生馬，江湖范蠡舟。","逍遙堪自樂，浩蕩信無憂。","去此從黃綬，歸歟任白頭。","風塵與霄漢，瞻望日悠悠。"]', '["德以精靈降，时膺梦寐求。","蒼生謝安石，天子富平侯。","尊俎資高論，巖廊挹大猷。","相门連戶牖，卿族嗣弓裘。","豁達云开霽，清明月映秋。","能爲吉甫頌，善用子房籌。","階砌思攀陟，门闌尚阻修。","高山不易仰，大匠本难投。","跡與松喬合，心緣啓沃留。","公才山吏部，书癖杜荆州。","幸沐千年聖，何辞一尉休。","折腰知寵辱，廻首见沈浮。","天地莊生马，江湖范蠡舟。","逍遙堪自乐，浩蕩信無憂。","去此從黄綬，归歟任白头。","风塵與霄漢，瞻望日悠悠。"]', '诗', 'shi', '', NULL, '古樂府飛龍曲留上陳左相 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a388eb-dd3d-4735-aacc-392ff3a2bed1', '留上李右相', '留上李右相', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["風俗登淳古，君臣挹大庭。","深沈謀九德，密勿契千齡。","獨立調元氣，清心豁窅冥。","本枝連帝系，長策冠生靈。","傅說明殷道，蕭何律漢刑。","鈞衡持國柄，柱石總朝經。","隱軫江山藻，氛氳鼎鼐銘。","興中皆白雪，身外即丹青。","江海呼窮鳥，詩書問聚螢。","吹噓成羽翼，提握動芳馨。","倚伏悲還笑，棲遲醉復醒。","恩榮初就列，含育忝宵形。","有竊丘山惠，無時枕席寧。","壯心瞻落景，生事感浮萍。","莫以才難用，終期善易聽。","未爲門下客，徒謝少微星。"]', '["风俗登淳古，君臣挹大庭。","深沈謀九德，密勿契千齡。","独立調元氣，清心豁窅冥。","本枝連帝系，长策冠生靈。","傅说明殷道，蕭何律漢刑。","鈞衡持国柄，柱石總朝經。","隐軫江山藻，氛氳鼎鼐銘。","兴中皆白雪，身外即丹青。","江海呼窮鸟，诗书问聚螢。","吹噓成羽翼，提握动芳馨。","倚伏悲還笑，棲遲醉复醒。","恩榮初就列，含育忝宵形。","有竊丘山惠，無时枕席寧。","壯心瞻落景，生事感浮萍。","莫以才难用，終期善易听。","未爲门下客，徒謝少微星。"]', '诗', 'shi', '', NULL, '留上李右相 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89948763-087c-4404-b98d-eedc526849ec', '同李員外賀哥舒大夫破九曲之作', '同李員外賀哥舒大夫破九曲之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["遙傳副丞相，昨日破西蕃。","作氣羣山動，揚軍大斾翻。","奇兵邀轉戰，連孥絕歸奔。","泉噴諸戎血，風驅死虜魂。","頭飛攢萬戟，面縛聚轅門。","鬼哭黃埃暮，天愁白日昏。","石城與巖險，鐵騎皆雲屯。","長策一言決，高蹤百代存。","威稜懾沙漠，忠義感乾坤。","老將黯無色，儒生安敢論。","解圍憑廟算，止殺報君恩。","唯有關河渺，蒼茫空樹墩。"]', '["遙傳副丞相，昨日破西蕃。","作氣羣山动，揚軍大斾翻。","奇兵邀轉戰，連孥絕归奔。","泉噴諸戎血，风驱死虜魂。","头飞攢万戟，面縛聚轅门。","鬼哭黄埃暮，天愁白日昏。","石城與巖險，鐵騎皆云屯。","长策一言決，高蹤百代存。","威稜懾沙漠，忠義感乾坤。","老將黯無色，儒生安敢論。","解圍憑廟算，止殺報君恩。","唯有关河渺，蒼茫空樹墩。"]', '诗', 'shi', '', NULL, '同李員外賀哥舒大夫破九曲之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce3c231-ae05-436d-8939-7c3885b708e1', '信安王幕府詩', '信安王幕府诗', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["雲紀軒皇代，星高太白年。","廟堂咨上策，幕府制中權。","盤石藩維固，昇壇禮樂先。","國章榮印綬，公服貴貂蟬。","樂善旌深德，輸忠格上玄。","剪桐光寵錫，題劒美貞堅。","聖祚雄圖廣，師貞武德虔。","雷霆七校發，旌斾五營連。","華省徵羣乂，霜臺舉二賢。","豈伊公望遠，曾是茂才遷。","並秉韜鈐術，兼該翰墨筵。","帝思麟閣像，臣獻柏梁篇。","振玉登遼甸，摐金歷薊壖。","度河飛羽檄，橫海泛樓船。","北伐聲逾邁，東征務以專。","講戎喧涿野，料敵靜居延。","軍勢持三略，兵戎自九天。","朝瞻授鉞去，時聽偃戈旋。","大漠風沙裏，長城雨雪邊。","雲端臨碣石，波際隱朝鮮。","夜壁沖高斗，寒空駐彩旃。","倚弓玄兔月，飲馬白狼川。","庶物隨交泰，蒼生解倒懸。","四郊增氣象，萬里絕風煙。","關塞鴻勳著，京華甲第全。","落梅橫吹後，春色凱歌前。","直道常兼濟，微才獨棄捐。","曳裾誠已矣，投筆尚悽然。","作賦同元淑，能詩匪仲宣。","雲霄不可望，空欲仰神仙。"]', '["云紀軒皇代，星高太白年。","廟堂咨上策，幕府制中權。","盤石藩維固，昇壇禮乐先。","国章榮印綬，公服貴貂蟬。","乐善旌深德，輸忠格上玄。","剪桐光寵錫，題劒美貞堅。","聖祚雄圖廣，師貞武德虔。","雷霆七校發，旌斾五營連。","华省徵羣乂，霜台舉二賢。","豈伊公望远，曾是茂才遷。","並秉韜鈐術，兼該翰墨筵。","帝思麟閣像，臣獻柏梁篇。","振玉登遼甸，摐金歷薊壖。","度河飞羽檄，橫海泛楼船。","北伐声逾邁，东征務以專。","講戎喧涿野，料敵静居延。","軍勢持三略，兵戎自九天。","朝瞻授鉞去，时听偃戈旋。","大漠风沙裏，长城雨雪邊。","云端臨碣石，波際隐朝鲜。","夜壁沖高斗，寒空駐彩旃。","倚弓玄兔月，饮马白狼川。","庶物隨交泰，蒼生解倒懸。","四郊增氣象，万里絕风煙。","关塞鴻勳著，京华甲第全。","落梅橫吹後，春色凱歌前。","直道常兼濟，微才独棄捐。","曳裾誠已矣，投笔尚悽然。","作賦同元淑，能诗匪仲宣。","云霄不可望，空欲仰神仙。"]', '诗', 'shi', '', NULL, '信安王幕府詩 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1176207a-3b89-480b-8032-3def1e6a5d05', '東平旅遊奉贈薛太守二十四韻', '东平旅游奉贈薛太守二十四韻', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["頌美馳千古，欽賢仰大猷。","晉公標逸氣，汾水注長流。","神與公忠節，天生將相儔。","青雲本自負，赤縣獨推尤。","御史風逾勁，郎官草屢修。","鵷鸞粉署起，鷹隼柏臺秋。","出入交三事，飛鳴揖五侯。","軍書陳上策，廷議借前籌。","肅肅趨朝列，雝雝引帝求。","一麾俄出守，千里再分憂。","不改任棠水，仍傳晏子裘。","歌謠隨舉扇，旌斾逐鳴騶。","郡國長河繞，川原大野幽。","地連堯泰嶽，山向禹青州。","汶上春帆渡，秦亭晚日愁。","遺墟當少昊，懸象逼奎婁。","即此逢清鑒，終然喜暗投。","叨承解榻禮，更得問縑遊。","高興陪登陟，嘉言忝獻酬。","觀棊知戰勝，探象會冥搜。","眺聽情何限，沖融惠勿休。","祗應齊語默，寧肯問沈浮。","然諾長懷季，棲遑輙累丘。","平生感知己，方寸豈悠悠。"]', '["頌美驰千古，欽賢仰大猷。","晉公標逸氣，汾水注长流。","神與公忠節，天生將相儔。","青云本自負，赤縣独推尤。","御史风逾勁，郎官草屢修。","鵷鸾粉署起，鷹隼柏台秋。","出入交三事，飞鳴揖五侯。","軍书陳上策，廷議借前籌。","肅肅趨朝列，雝雝引帝求。","一麾俄出守，千里再分憂。","不改任棠水，仍傳晏子裘。","歌謠隨舉扇，旌斾逐鳴騶。","郡国长河繞，川原大野幽。","地連堯泰嶽，山向禹青州。","汶上春帆渡，秦亭晚日愁。","遺墟當少昊，懸象逼奎婁。","即此逢清鑒，終然喜暗投。","叨承解榻禮，更得问縑游。","高兴陪登陟，嘉言忝獻酬。","观棊知戰勝，探象會冥搜。","眺听情何限，沖融惠勿休。","祗應齊語默，寧肯问沈浮。","然諾长懷季，棲遑輙累丘。","平生感知己，方寸豈悠悠。"]', '诗', 'shi', '', NULL, '東平旅遊奉贈薛太守二十四韻 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16668b6e-7a0c-4421-b374-d62a8b9c81eb', '真定即事奉贈韋使君二十八韻', '真定即事奉贈韋使君二十八韻', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["飄泊懷書客，遲迴此路隅。","問津驚棄置，投刺忽踟躕。","方伯恩彌重，蒼生詠已蘇。","郡稱廉叔度，朝議管夷吾。","乃繼三台側，仍將四岳俱。","江山澄氣象，崖谷倚冰壺。","詔寵金門策，官榮葉縣鳧。","擢才登粉署，飛步躡雲衢。","起草徵調墨，焚香即宴娛。","光華揚盛矣，霄漢在茲乎。","隱軫推公望，逶迤協帝俞。","軒車辭魏闕，旌節副幽都。","始佩仙郎印，俄兼太守符。","尤多蜀郡理，更得潁川謨。","城邑推雄鎮，山川列簡圖。","舊燕當絕漠，全趙對平蕪。","曠野何瀰漫，長亭復鬱紆。","始泉遺俗近，活水戰場無。","月換思鄉陌，星廻記斗樞。","歲容歸萬象，和氣發鴻罏。","淪落而誰遇，棲遑有是夫。","不才羞擁腫，干祿謝侏儒。","契闊慙行邁，羈離憶友于。","田園同季子，儲蓄異陶朱。","方欲呈高義，吹噓揖大巫。","永懷吐肝膽，猶憚阻榮枯。","解榻情何限，忘言道未殊。","從來貴縫掖，應是念窮途。"]', '["飄泊懷书客，遲迴此路隅。","问津驚棄置，投刺忽踟躕。","方伯恩彌重，蒼生詠已蘇。","郡稱廉叔度，朝議管夷吾。","乃繼三台側，仍將四岳俱。","江山澄氣象，崖谷倚冰壺。","詔寵金门策，官榮葉縣鳧。","擢才登粉署，飞步躡云衢。","起草徵調墨，焚香即宴娛。","光华揚盛矣，霄漢在茲乎。","隐軫推公望，逶迤協帝俞。","軒车辞魏闕，旌節副幽都。","始佩仙郎印，俄兼太守符。","尤多蜀郡理，更得潁川謨。","城邑推雄鎮，山川列簡圖。","旧燕當絕漠，全趙对平蕪。","曠野何瀰漫，长亭复鬱紆。","始泉遺俗近，活水戰場無。","月換思乡陌，星廻記斗樞。","歲容归万象，和氣發鴻罏。","淪落而誰遇，棲遑有是夫。","不才羞擁腫，干祿謝侏儒。","契闊慙行邁，羈離憶友于。","田园同季子，儲蓄異陶朱。","方欲呈高義，吹噓揖大巫。","永懷吐肝膽，猶憚阻榮枯。","解榻情何限，忘言道未殊。","從来貴縫掖，應是念窮途。"]', '诗', 'shi', '', NULL, '真定即事奉贈韋使君二十八韻 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1122ecf1-e7da-41c0-a35c-16a9ee1dca5f', '和竇侍御登涼州七級浮圖之作', '和竇侍御登涼州七級浮圖之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["化塔屹中起，孤高宜上躋。","鐵冠雄賞眺，金界寵招攜。","空色在軒戶，邊聲連鼓鼙。","天寒萬里北，地豁九州西。","清興揖才彥，峻風和端倪。","始知陽春後，具物皆筌蹄。"]', '["化塔屹中起，孤高宜上躋。","鐵冠雄賞眺，金界寵招携。","空色在軒戶，邊声連鼓鼙。","天寒万里北，地豁九州西。","清兴揖才彥，峻风和端倪。","始知陽春後，具物皆筌蹄。"]', '诗', 'shi', '', NULL, '和竇侍御登涼州七級浮圖之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ace6ac4-c8c7-4ccd-beee-c6cffc1719b6', '酬河南節度使賀蘭大夫見贈之作', '酬河南節度使賀蘭大夫见贈之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["高閣憑欄檻，中軍倚斾旌。","感時常激切，於己即忘情。","河華屯妖氣，伊瀍有戰聲。","媿無戡難策，多謝出師名。","秉鉞知恩重，臨戎覺命輕。","股肱瞻列岳，脣齒賴長城。","隱隱摧鋒勢，光光弄印榮。","魯連真義士，陸遜豈書生。","直道寧殊智，先鞭忽抗行。","楚雲隨去馬，淮月尚連營。","撫劒堪投分，悲歌益不平。","從來重然諾，況值欲橫行。"]', '["高閣憑欄檻，中軍倚斾旌。","感时常激切，於己即忘情。","河华屯妖氣，伊瀍有戰声。","媿無戡难策，多謝出師名。","秉鉞知恩重，臨戎覺命轻。","股肱瞻列岳，脣齒賴长城。","隐隐摧鋒勢，光光弄印榮。","魯連真義士，陸遜豈书生。","直道寧殊智，先鞭忽抗行。","楚云隨去马，淮月尚連營。","撫劒堪投分，悲歌益不平。","從来重然諾，況值欲橫行。"]', '诗', 'shi', '', NULL, '酬河南節度使賀蘭大夫見贈之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8687726e-b4b8-48f3-be61-f73ccf881e92', '奉酬睢陽路太守見贈之作', '奉酬睢陽路太守见贈之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["盛才膺命代，高價動良時。","帝簡登藩翰，人和發詠思。","神仙去華省，鵷鷺憶丹墀。","清淨能無事，優游即賦詩。","江山紛想像，雲物共萎蕤。","逸氣劉公幹，玄言向子期。","多慙汲引速，翻愧激昂遲。","相馬知何限，登龍反自疑。","風塵吏道迫，行邁旅心悲。","拙疾徒爲爾，窮愁欲問誰。","秋庭一片葉，朝鏡數莖絲。","州縣甘無取，丘園悔莫追。","瓊瑤生篋笥，光景借茅茨。","他日青霄裏，猶應訪所知。"]', '["盛才膺命代，高價动良时。","帝簡登藩翰，人和發詠思。","神仙去华省，鵷鷺憶丹墀。","清淨能無事，優游即賦诗。","江山紛想像，云物共萎蕤。","逸氣劉公幹，玄言向子期。","多慙汲引速，翻愧激昂遲。","相马知何限，登龙反自疑。","风塵吏道迫，行邁旅心悲。","拙疾徒爲爾，窮愁欲问誰。","秋庭一片葉，朝镜數莖絲。","州縣甘無取，丘园悔莫追。","瓊瑤生篋笥，光景借茅茨。","他日青霄裏，猶應訪所知。"]', '诗', 'shi', '', NULL, '奉酬睢陽路太守見贈之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4506e47c-d89b-45ca-a9c5-8f9c457409b6', '奉酬睢陽李太守', '奉酬睢陽李太守', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["公族稱王佐，朝經允帝求。","本枝疆我李，盤石冠諸劉。","禮樂光輝盛，山河氣象幽。","系高周柱史，名重晉陽秋。","華省膺推擇，青雲寵宴遊。","握蘭多具美，前席有嘉謀。","賦得黃金賜，言皆白璧酬。","着鞭驅駟馬，操刃解全牛。","出鎮兼方伯，承家復列侯。","朝瞻孔北海，時用杜荆州。","廣固纔登陟，毘陵忽阻修。","三台冀入夢，四岳尚分憂。","郡邑連京口，山川望石頭。","海門當建節，江路引鳴騶。","俗見中興理，人逢至道休。","先移白額橫，更息赭衣偷。","梁國歌來晚，徐方怨不留。","豈伊齊政術，將以變澆浮。","訟簡知能吏，刑寬察要囚。","坐堂風偃草，行縣雨隨輈。","地是蒙莊宅，城遺閼伯丘。","孝王餘井徑，微子故田疇。","冬至招搖轉，天寒螮蝀收。","猿巖飛雨雪，兔苑落梧楸。","列戟霜侵戶，褰幃月在鈎。","好賢常解榻，乘興每登樓。","逸足橫千里，高談注九流。","詩題青玉案，衣贈黑貂裘。","窮巷軒車靜，閑齋耳目愁。","未能方管樂，翻欲慕巢由。","講德良難敵，觀風豈易儔。","寸心仍有適，江海一扁舟。"]', '["公族稱王佐，朝經允帝求。","本枝疆我李，盤石冠諸劉。","禮乐光輝盛，山河氣象幽。","系高周柱史，名重晉陽秋。","华省膺推擇，青云寵宴游。","握蘭多具美，前席有嘉謀。","賦得黄金賜，言皆白璧酬。","着鞭驱駟马，操刃解全牛。","出鎮兼方伯，承家复列侯。","朝瞻孔北海，时用杜荆州。","廣固纔登陟，毘陵忽阻修。","三台冀入梦，四岳尚分憂。","郡邑連京口，山川望石头。","海门當建節，江路引鳴騶。","俗见中兴理，人逢至道休。","先移白額橫，更息赭衣偷。","梁国歌来晚，徐方怨不留。","豈伊齊政術，將以变澆浮。","訟簡知能吏，刑寬察要囚。","坐堂风偃草，行縣雨隨輈。","地是蒙莊宅，城遺閼伯丘。","孝王餘井徑，微子故田疇。","冬至招搖轉，天寒螮蝀收。","猿巖飞雨雪，兔苑落梧楸。","列戟霜侵戶，褰幃月在鈎。","好賢常解榻，乘兴每登楼。","逸足橫千里，高談注九流。","诗題青玉案，衣贈黑貂裘。","窮巷軒车静，闲斋耳目愁。","未能方管乐，翻欲慕巢由。","講德良难敵，观风豈易儔。","寸心仍有適，江海一扁舟。"]', '诗', 'shi', '', NULL, '奉酬睢陽李太守 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08d54a6-354f-4f0b-8454-a0303339a4cb', '送柴司戶充劉卿判官之嶺外', '送柴司戶充劉卿判官之嶺外', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["嶺外資雄鎮，朝端寵節旄。","月卿臨幕府，星使出詞曹。","海對羊城闊，山連象郡高。","風霜驅瘴癘，忠信涉波濤。","別恨隨流水，交情脫寶刀。","有才無不適，行矣莫徒勞。"]', '["嶺外資雄鎮，朝端寵節旄。","月卿臨幕府，星使出词曹。","海对羊城闊，山連象郡高。","风霜驱瘴癘，忠信涉波濤。","別恨隨流水，交情脫寶刀。","有才無不適，行矣莫徒勞。"]', '诗', 'shi', '', NULL, '送柴司戶充劉卿判官之嶺外 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57f1fe9-7772-4f2d-bc07-868841e21890', '送蔡少府赴登州推事', '送蔡少府赴登州推事', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["膠東連即墨，萊水入滄溟。","國小常多事，人訛屢抵刑。","公才徵郡邑，詔使出郊坰。","標格誰當犯，風謠信可聽。","崢嶸大峴口，邐迤汶陽亭。","地迥雲偏白，天秋山更青。","祖筵方卜晝，王事急侵星。","勸爾將爲德，斯言蓋有聽。"]', '["膠东連即墨，萊水入滄溟。","国小常多事，人訛屢抵刑。","公才徵郡邑，詔使出郊坰。","標格誰當犯，风謠信可听。","崢嶸大峴口，邐迤汶陽亭。","地迥云偏白，天秋山更青。","祖筵方卜晝，王事急侵星。","勸爾將爲德，斯言蓋有听。"]', '诗', 'shi', '', NULL, '送蔡少府赴登州推事 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1dacf07-db06-4ed7-bb07-6891a34273c8', '秦中送李九赴越', '秦中送李九赴越', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["攜手望千里，于今將十年。","如何每離別，心事復迍邅。","適越雖有以，出關終耿然。","愁霖不可向，長路或難前。","吳會獨行客，山陰秋夜船。","謝家徵故事，禹穴訪遺編。","鏡水君所憶，蓴羹余舊便。","歸來莫忘此，兼示濟江篇。"]', '["携手望千里，于今將十年。","如何每離別，心事复迍邅。","適越雖有以，出关終耿然。","愁霖不可向，长路或难前。","吳會独行客，山陰秋夜船。","謝家徵故事，禹穴訪遺編。","镜水君所憶，蓴羹余旧便。","归来莫忘此，兼示濟江篇。"]', '诗', 'shi', '', NULL, '秦中送李九赴越 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e41409-32f8-475d-b06c-814e28100c8d', '餞宋八充彭中丞判官之嶺南', '餞宋八充彭中丞判官之嶺南', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["覩君濟時略，使我氣填膺。","長策竟不用，高才徒見稱。","一朝知己達，累日詔書徵。","羽翮忽然就，風飆誰敢凌。","舉鞭趨嶺嶠，屈指冒炎蒸。","北雁送馳驛，南人思飲冰。","彼邦本倔強，習俗多驕矜。","翠羽干平法，黃金撓直繩。","若將除害馬，慎勿信蒼蠅。","魑魅寧無患，忠貞適有憑。","猿啼山不斷，鳶跕路難登。","海岸出交趾，江城連始興。","繡衣當節制，幕府盛威稜。","勿憚九嶷險，須令百越澄。","立談多感激，行李即嚴凝。","離別胡爲者，雲霄遲爾昇。"]', '["覩君濟时略，使我氣填膺。","长策竟不用，高才徒见稱。","一朝知己達，累日詔书徵。","羽翮忽然就，风飆誰敢凌。","舉鞭趨嶺嶠，屈指冒炎蒸。","北雁送驰驛，南人思饮冰。","彼邦本倔強，習俗多驕矜。","翠羽干平法，黄金撓直繩。","若將除害马，慎勿信蒼蠅。","魑魅寧無患，忠貞適有憑。","猿啼山不斷，鳶跕路难登。","海岸出交趾，江城連始兴。","繡衣當節制，幕府盛威稜。","勿憚九嶷險，須令百越澄。","立談多感激，行李即嚴凝。","離別胡爲者，云霄遲爾昇。"]', '诗', 'shi', '', NULL, '餞宋八充彭中丞判官之嶺南 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d716d017-0695-4d22-a161-c28b88567b15', '陪竇侍御泛靈雲池', '陪竇侍御泛靈云池', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["白露時先降，清川思不窮。","江湖仍塞上，舟楫在軍中。","舞換臨津樹，歌饒向迥風。","夕陽連積水，邊色滿秋空。","乘興宜投轄，邀歡莫避驄。","誰憐持弱羽，猶欲伴鵷鴻。"]', '["白露时先降，清川思不窮。","江湖仍塞上，舟楫在軍中。","舞換臨津樹，歌饒向迥风。","夕陽連積水，邊色满秋空。","乘兴宜投轄，邀歡莫避驄。","誰怜持弱羽，猶欲伴鵷鴻。"]', '诗', 'shi', '', NULL, '陪竇侍御泛靈雲池 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829d9dfd-b384-4d00-a13e-dd8bd1beb5e5', '陪竇侍御靈雲南亭宴詩得雷字', '陪竇侍御靈云南亭宴诗得雷字', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["人幽宜眺聽，目極喜亭臺。","風景知愁在，關山憶夢迴。","秪言殊語默，何意忝遊陪。","連唱波瀾動，冥搜物象開。","新秋歸遠樹，殘雨擁輕雷。","簷外長天盡，尊前獨鳥來。","常吟塞下曲，多謝幕中才。"]', '["人幽宜眺听，目極喜亭台。","风景知愁在，关山憶梦迴。","秪言殊語默，何意忝游陪。","連唱波瀾动，冥搜物象开。","新秋归远樹，殘雨擁轻雷。","簷外长天尽，尊前独鸟来。","常吟塞下曲，多謝幕中才。"]', '诗', 'shi', '', NULL, '陪竇侍御靈雲南亭宴詩得雷字 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61c206e-7b6f-4c94-ad64-bfb843c5269d', '同熊少府題盧主簿茅齋', '同熊少府題盧主簿茅斋', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["虛院野情在，茅齋秋興存。","孝廉趨下位，才子出高門。","乃繼幽人靜，能令學者尊。","江山歸謝客，神鬼下劉根。","階樹時攀折，窗書任討論。","自堪成獨往，何必武陵源。"]', '["虛院野情在，茅斋秋兴存。","孝廉趨下位，才子出高门。","乃繼幽人静，能令学者尊。","江山归謝客，神鬼下劉根。","階樹时攀折，窗书任討論。","自堪成独往，何必武陵源。"]', '诗', 'shi', '', NULL, '同熊少府題盧主簿茅齋 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff727be9-d103-4627-890a-94808ee85a13', '同朱五題盧使君義井', '同朱五題盧使君義井', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["高義唯良牧，深仁自下車。","寧知鑿井處，還是飲冰餘。","地即泉源久，人當汲引初。","體清能鑒物，色洞每含虛。","上善滋來往，中和浹里閭。","濟時應未竭，懷惠復何如。"]', '["高義唯良牧，深仁自下车。","寧知鑿井处，還是饮冰餘。","地即泉源久，人當汲引初。","體清能鑒物，色洞每含虛。","上善滋来往，中和浹里閭。","濟时應未竭，懷惠复何如。"]', '诗', 'shi', '', NULL, '同朱五題盧使君義井 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('820f1c82-3269-433c-967a-fdd643cb3e76', '同郭十題楊主簿新廳', '同郭十題楊主簿新廳', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["華館曙沈沈，惟良正在今。","用材兼柱石，聞物象高深。","更得芝蘭地，兼營枳棘林。","向風扃戟戶，當署近棠陰。","勿改安卑節，聊閑理劇心。","多君有知己，一和郢中吟。"]', '["华館曙沈沈，惟良正在今。","用材兼柱石，闻物象高深。","更得芝蘭地，兼營枳棘林。","向风扃戟戶，當署近棠陰。","勿改安卑節，聊闲理劇心。","多君有知己，一和郢中吟。"]', '诗', 'shi', '', NULL, '同郭十題楊主簿新廳 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47dbfc92-dd51-458f-859a-1953cde28460', '秋日作', '秋日作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["端居值秋節，此日更愁辛。","寂寞無一事，蒿萊通四鄰。","閉門生白髮，回首憶青春。","歲月不相待，交游隨衆人。","雲霄何處託，愚直有誰親。","舉酒聊自勸，窮通信爾身。"]', '["端居值秋節，此日更愁辛。","寂寞無一事，蒿萊通四鄰。","閉门生白髮，回首憶青春。","歲月不相待，交游隨衆人。","云霄何处託，愚直有誰親。","舉酒聊自勸，窮通信爾身。"]', '诗', 'shi', '', NULL, '秋日作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d8d9dcc-9ef1-4fa9-9138-39a17fce08b4', '辟陽城', '辟陽城', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["荒城在高岸，凌眺俯清淇。","傳道漢天子，而封審食其。","奸淫且不戮，茅土孰云宜。","何得英雄主，返令兒女欺。","母儀良已失，臣節豈如斯。","太息一朝事，乃令人所嗤。"]', '["荒城在高岸，凌眺俯清淇。","傳道漢天子，而封審食其。","奸淫且不戮，茅土孰云宜。","何得英雄主，返令兒女欺。","母儀良已失，臣節豈如斯。","太息一朝事，乃令人所嗤。"]', '诗', 'shi', '', NULL, '辟陽城 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62c94f3-c060-4595-86c6-b7d32afb146d', '赴彭州山行之作', '赴彭州山行之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["峭壁連崆峒，攢峰疊翠微。","鳥聲堪駐馬，林色可忘機。","怪石時侵徑，輕蘿乍拂衣。","路長愁作客，年老更思歸。","且悅巖巒勝，寧嗟意緒違。","山行應未盡，誰與玩芳菲。"]', '["峭壁連崆峒，攢峰叠翠微。","鸟声堪駐马，林色可忘機。","怪石时侵徑，轻蘿乍拂衣。","路长愁作客，年老更思归。","且悅巖巒勝，寧嗟意緒違。","山行應未尽，誰與玩芳菲。"]', '诗', 'shi', '', NULL, '赴彭州山行之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea06c25-d7c8-48f4-ab3e-133bfbae14f3', '詠史', '詠史', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["尚有綈袍贈，應憐范叔寒。","不知天下士，猶作布衣看。"]', '["尚有綈袍贈，應怜范叔寒。","不知天下士，猶作布衣看。"]', '诗', 'shi', '', NULL, '詠史 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48a91ea-6d94-42d1-8466-f5a9f42cc1d6', '送兵到薊北', '送兵到薊北', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["積雪與天迥，屯軍連塞愁。","誰知此行邁，不爲覓封侯。"]', '["積雪與天迥，屯軍連塞愁。","誰知此行邁，不爲覓封侯。"]', '诗', 'shi', '', NULL, '送兵到薊北 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a466652-6517-480e-aad3-2d5e4df247be', '同羣公題張處士菜園', '同羣公題張处士菜园', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["耕地桑柘間，地肥菜常熟。","爲問葵藿資，何如廟堂肉。"]', '["耕地桑柘间，地肥菜常熟。","爲问葵藿資，何如廟堂肉。"]', '诗', 'shi', '', NULL, '同羣公題張處士菜園 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a14b06-eb3f-4534-9f3b-fc81842cefd9', '逢謝偃', '逢謝偃', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["紅顏愴爲別，白髮始相逢。","唯餘昔時淚，無復舊時容。"]', '["紅顏愴爲別，白髮始相逢。","唯餘昔时泪，無复旧时容。"]', '诗', 'shi', '', NULL, '逢謝偃 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('992319d5-c110-4285-9302-cb6d8144bd85', '田家春望', '田家春望', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["出門何所見，春色滿平蕪。","可歎無知己，高陽一酒徒。"]', '["出门何所见，春色满平蕪。","可歎無知己，高陽一酒徒。"]', '诗', 'shi', '', NULL, '田家春望 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('040e5130-04ad-4f82-9991-05dece70949e', '閑居', '闲居', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["柳色驚心事，春風厭索居。","方知一杯酒，猶勝百家書。"]', '["柳色驚心事，春风厭索居。","方知一杯酒，猶勝百家书。"]', '诗', 'shi', '', NULL, '閑居 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e925245d-1bce-4553-b1e1-df64fe87a148', '封丘作', '封丘作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["州縣才難適，雲山道欲窮。","揣摩慚黠吏，棲隱謝愚公。"]', '["州縣才难適，云山道欲窮。","揣摩慚黠吏，棲隐謝愚公。"]', '诗', 'shi', '', NULL, '封丘作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7ec3cb-95db-45a4-9cac-1d00de533802', '九曲詞三首 一', '九曲词三首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["許國從來徹廟堂，連年不爲在疆塲。","將軍天上封侯印，御史臺中異姓王。"]', '["許国從来徹廟堂，連年不爲在疆塲。","將軍天上封侯印，御史台中異姓王。"]', '诗', 'shi', '', NULL, '九曲詞三首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f613e665-0ed5-449e-9f4f-e094a102f993', '九曲詞三首 二', '九曲词三首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["萬騎爭歌楊柳春，千塲對舞繡騏驎。","到處盡逢歡洽事，相看總是太平人。"]', '["万騎爭歌楊柳春，千塲对舞繡騏驎。","到处尽逢歡洽事，相看總是太平人。"]', '诗', 'shi', '', NULL, '九曲詞三首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6c721e-3383-47a7-ab92-d04732ab8d61', '九曲詞三首 三', '九曲词三首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["鐵騎橫行鐵嶺頭，西看邏逤取封侯。","青海只今將飲馬，黃河不用更防秋。"]', '["鐵騎橫行鐵嶺头，西看邏逤取封侯。","青海只今將饮马，黄河不用更防秋。"]', '诗', 'shi', '', NULL, '九曲詞三首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43a140a-9152-4bbf-8d94-7254f913f969', '營州歌', '營州歌', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["營州少年厭原野，狐裘蒙茸獵城下。","虜酒千鍾不醉人，胡兒十歲能騎馬。"]', '["營州少年厭原野，狐裘蒙茸獵城下。","虜酒千鍾不醉人，胡兒十歲能騎马。"]', '诗', 'shi', '', NULL, '營州歌 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262c4021-fb39-4065-8308-552aa119d46b', '玉真公主歌 一', '玉真公主歌 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["常言龍德本天仙，誰謂仙人每學仙。","更道玄元指李白，多於王母種桃年。"]', '["常言龙德本天仙，誰謂仙人每学仙。","更道玄元指李白，多於王母種桃年。"]', '诗', 'shi', '', NULL, '玉真公主歌 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3cb481-d0f2-48ec-8c6f-a62288e66416', '玉真公主歌 二', '玉真公主歌 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["仙宮仙府有真仙，天寶天仙秘莫傳。","爲問軒皇三百歲，何如大道一千年。"]', '["仙宮仙府有真仙，天寶天仙秘莫傳。","爲问軒皇三百歲，何如大道一千年。"]', '诗', 'shi', '', NULL, '玉真公主歌 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58e934ab-546f-4f26-88a3-fe7e825a613c', '和王七玉門關聽吹笛', '和王七玉门关听吹笛', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["胡人吹笛戍樓間，樓上蕭條海月閑。","借問落梅凡幾曲，從風一夜滿關山。"]', '["胡人吹笛戍楼间，楼上蕭條海月闲。","借问落梅凡幾曲，從风一夜满关山。"]', '诗', 'shi', '', NULL, '和王七玉門關聽吹笛 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d65b5a-7b4d-4b3d-a1b7-6fd144360f8f', '別董大二首 一', '別董大二首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["十里黃雲白日曛，北風吹雁雪紛紛。","莫愁前路無知己，天下誰人不識君。"]', '["十里黄云白日曛，北风吹雁雪紛紛。","莫愁前路無知己，天下誰人不識君。"]', '诗', 'shi', '', NULL, '別董大二首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87bd86ac-59ad-4733-b9cc-8dc465e9f445', '別董大二首 二', '別董大二首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["六翮飄颻私自憐，一離京洛十餘年。","丈夫貧賤應未足，今日相逢無酒錢。"]', '["六翮飄颻私自怜，一離京洛十餘年。","丈夫貧賤應未足，今日相逢無酒錢。"]', '诗', 'shi', '', NULL, '別董大二首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d11196-da71-464b-9058-241799947513', '送桂陽孝廉', '送桂陽孝廉', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["桂陽年少西入秦，數經甲科猶白身。","即今江海一歸客，他日雲霄萬里人。"]', '["桂陽年少西入秦，數經甲科猶白身。","即今江海一归客，他日云霄万里人。"]', '诗', 'shi', '', NULL, '送桂陽孝廉 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7704e8f6-d94f-441c-88de-f064adf709b3', '送李少府時在客舍作', '送李少府时在客舍作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["相逢旅館意多違，暮雪初晴候雁飛。","主人酒盡君未醉，薄暮途遙歸不歸。"]', '["相逢旅館意多違，暮雪初晴候雁飞。","主人酒尽君未醉，薄暮途遙归不归。"]', '诗', 'shi', '', NULL, '送李少府時在客舍作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec848e8-02b7-43e4-90f3-d2c09813d6c2', '聽張立本女吟', '听張立本女吟', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["危冠廣袖楚宮妝，獨步閑庭逐夜涼。","自把玉釵敲砌竹，清歌一曲月如霜。"]', '["危冠廣袖楚宮妝，独步闲庭逐夜涼。","自把玉釵敲砌竹，清歌一曲月如霜。"]', '诗', 'shi', '', NULL, '聽張立本女吟 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac349977-82f5-485f-80b1-3a827a4ed0cb', '初至封丘作', '初至封丘作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["可憐薄暮宦遊子，獨臥虛齋思無已。","去家百里不得歸，到官數日秋風起。"]', '["可怜薄暮宦游子，独臥虛斋思無已。","去家百里不得归，到官數日秋风起。"]', '诗', 'shi', '', NULL, '初至封丘作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d3dbf4-bc0f-4b19-ab8d-fce4d9e2af10', '除夜作', '除夜作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["旅館寒燈獨不眠，客心何事轉悽然。","故鄉今夜思千里，愁鬢明朝又一年。"]', '["旅館寒灯独不眠，客心何事轉悽然。","故乡今夜思千里，愁鬢明朝又一年。"]', '诗', 'shi', '', NULL, '除夜作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b49ae18-32e1-406a-be79-b882da27d61a', '劒池', '劒池', 'e5d26ba6-62ea-40ca-b2ec-80c3ef02c452', '唐', '["闔閭葬日勞人力，嬴政穿來役鬼功。","澄碧尚疑神物在，等閑雷雨起潭中。"]', '["闔閭葬日勞人力，嬴政穿来役鬼功。","澄碧尚疑神物在，等闲雷雨起潭中。"]', '诗', 'shi', '', NULL, '劒池 李峴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f3ca70-4faa-4aff-b2b5-28320a22636d', '張公洞', '張公洞', 'f185e26f-3325-40a4-8f2f-b9f3e7b1ad19', '唐', '["一徑深窈窕，上升翠微中。","忽然靈洞前，日月開仙宮。","道士十二人，往還馭清風。","焚香入深洞，巨石如虛空。","夙夜備蘋藻，詔書祠張公。","五雲何裴回，玄鶴下蒼穹。","我本道門子，願言出塵籠。","掃除方寸間，幾與神靈通。","宿昔勤夢想，契之在深衷。","遲迴將不還，章綬擊我躬。","稽首謝真侶，辭滿歸崆峒。"]', '["一徑深窈窕，上升翠微中。","忽然靈洞前，日月开仙宮。","道士十二人，往還馭清风。","焚香入深洞，巨石如虛空。","夙夜備蘋藻，詔书祠張公。","五云何裴回，玄鹤下蒼穹。","我本道门子，願言出塵籠。","掃除方寸间，幾與神靈通。","宿昔勤梦想，契之在深衷。","遲迴將不還，章綬擊我躬。","稽首謝真侶，辞满归崆峒。"]', '诗', 'shi', '', NULL, '張公洞 李栖筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e4c81e-e4e5-4779-be2b-9dc10d14c83c', '投宋大夫', '投宋大夫', 'f185e26f-3325-40a4-8f2f-b9f3e7b1ad19', '唐', '["十處投人九處違，家鄉萬里又空歸。","嚴霜昨夜侵人骨，誰念高堂未授衣。"]', '["十处投人九处違，家乡万里又空归。","嚴霜昨夜侵人骨，誰念高堂未授衣。"]', '诗', 'shi', '', NULL, '投宋大夫 李栖筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209d2029-4af8-471c-91e1-f67ffc20c5b1', '寶林寺作', '寶林寺作', '112c4420-04c5-498a-ba29-cb5654ad7e32', '唐', '["茲山昔飛來，遠自琅琊臺。","孤岫龜形在，深泉鰻井開。","越王屢登陟，何相傳詞才。","塔廟宗其巔，規模稱壯哉。","禪堂清溽潤，高閣無恢炱。","照耀珠吐月，鏗轟鐘隱雷。","揆余久纓弁，末路遭邅迴。","一棄滄海曲，六年稽嶺隈。","逝川惜東駛，馳景憐西頹。","腰帶愁疾減，容顏衰悴催。","賴居茲寺中，法士多瓌能。","洗心聽經論，禮足蠲凶灾。","永願依勝侶，清江乘度杯。"]', '["茲山昔飞来，远自琅琊台。","孤岫龟形在，深泉鰻井开。","越王屢登陟，何相傳词才。","塔廟宗其巔，規模稱壯哉。","禪堂清溽潤，高閣無恢炱。","照耀珠吐月，鏗轟鐘隐雷。","揆余久纓弁，末路遭邅迴。","一棄滄海曲，六年稽嶺隈。","逝川惜东駛，驰景怜西頹。","腰带愁疾減，容顏衰悴催。","賴居茲寺中，法士多瓌能。","洗心听經論，禮足蠲凶灾。","永願依勝侶，清江乘度杯。"]', '诗', 'shi', '', NULL, '寶林寺作 徐浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1817f2-140c-47c4-b6f3-0f374d7eaded', '謁禹廟', '謁禹廟', '112c4420-04c5-498a-ba29-cb5654ad7e32', '唐', '["畝澮敷四海，川源滌九州。","既膺九命錫，乃建洪範疇。","鼎革固天啓，運興匪人謀。","肇開宅土業，永庇昏墊憂。","山足靈廟在，門前清鏡流。","象筵陳玉帛，容衛儼戈矛。","探穴圖書朽，卑宮堂殿修。","梅梁今不壞，松祏古仍留。","負責故鄉近，朅來申俎羞。","爲魚知造化，歎鳳仰徽猷。","不復聞夏樂，唯餘奏楚幽。","婆娑非舞羽，鏜鞳異鳴球。","盛德吾無間，高功誰與儔。","灾淫破凶慝，祚聖擁神休。","出谷鶯初語，空山猨獨愁。","春暉生草樹，柳色暖汀洲。","恩貸題輿重，榮殊衣錦遊。","宦情同械擊，生理任桴浮。","地極臨滄海，天遙過斗牛。","精誠如可諒，他日寄冥搜。"]', '["畝澮敷四海，川源滌九州。","既膺九命錫，乃建洪範疇。","鼎革固天啓，運兴匪人謀。","肇开宅土業，永庇昏墊憂。","山足靈廟在，门前清镜流。","象筵陳玉帛，容衛儼戈矛。","探穴圖书朽，卑宮堂殿修。","梅梁今不壞，松祏古仍留。","負責故乡近，朅来申俎羞。","爲鱼知造化，歎鳳仰徽猷。","不复闻夏乐，唯餘奏楚幽。","婆娑非舞羽，鏜鞳異鳴球。","盛德吾無间，高功誰與儔。","灾淫破凶慝，祚聖擁神休。","出谷鶯初語，空山猨独愁。","春暉生草樹，柳色暖汀洲。","恩貸題輿重，榮殊衣錦游。","宦情同械擊，生理任桴浮。","地極臨滄海，天遙過斗牛。","精誠如可諒，他日寄冥搜。"]', '诗', 'shi', '', NULL, '謁禹廟 徐浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae31da45-73ca-411d-ada1-d564ed9c765a', '自悼', '自悼', '928d386f-e6b7-4736-a303-978a5fe7b998', '唐', '["朝日上團團，照見先生盤。","盤中何所有，苜蓿長闌干。","飯澁匙難綰，羹稀筯易寬。","只可謀朝夕，何由保歲寒。"]', '["朝日上團團，照见先生盤。","盤中何所有，苜蓿长闌干。","飯澁匙难綰，羹稀筯易寬。","只可謀朝夕，何由保歲寒。"]', '诗', 'shi', '', NULL, '自悼 薛令之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c70f0e2-8df5-42da-975b-927f7093a3d0', '靈巖寺', '靈巖寺', '928d386f-e6b7-4736-a303-978a5fe7b998', '唐', '["草堂棲在靈山谷，勤苦詩書向燈燭。","柴門半掩寂無人，惟有白雲相伴宿。"]', '["草堂棲在靈山谷，勤苦诗书向灯燭。","柴门半掩寂無人，惟有白云相伴宿。"]', '诗', 'shi', '', NULL, '靈巖寺 薛令之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29027186-38fc-499d-8208-ba6d79db3518', '湘夫人', '湘夫人', '5a515500-5a3d-4d73-a4ef-a41eaa5bd467', '唐', '["楓葉下秋渚，二妃愁渡湘。","疑山空杳藹，何處望君王。","日落水雲裏，悠悠心自傷。"]', '["楓葉下秋渚，二妃愁渡湘。","疑山空杳藹，何处望君王。","日落水云裏，悠悠心自傷。"]', '诗', 'shi', '', NULL, '湘夫人 鄒紹先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ceea366-5fc7-4572-9da3-43f181a8dbbc', '寄妻父劉長卿', '寄妻父劉长卿', '09380d71-c8bd-4acb-bfce-64606e2d66ea', '唐', '["處處雲山無盡時，桐廬南望轉參差。","舟人莫道新安近，欲上潺湲行自遲。"]', '["处处云山無尽时，桐廬南望轉參差。","舟人莫道新安近，欲上潺湲行自遲。"]', '诗', 'shi', '', NULL, '寄妻父劉長卿 李穆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a5027b-b4c8-4f7b-a79a-0590bbba125d', '短歌行', '短歌行', 'c7c885b9-4e5c-4988-9fbe-9633bab84fb8', '唐', '["寂寞草中蘭，亭亭山上松。","貞芳日有分，生長耐相容。","結根各得地，幸沾雨露功。","參辰無停泊，且顧一西東。","君但開懷抱，猜恨莫怱怱。"]', '["寂寞草中蘭，亭亭山上松。","貞芳日有分，生长耐相容。","結根各得地，幸沾雨露功。","參辰無停泊，且顧一西东。","君但开懷抱，猜恨莫怱怱。"]', '诗', 'shi', '', NULL, '短歌行 馮著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db34a982-621d-44d8-81c6-e8675b33253e', '洛陽道', '洛陽道', 'c7c885b9-4e5c-4988-9fbe-9633bab84fb8', '唐', '["洛陽宮中花柳春，洛陽道上無行人。","皮裘氈帳不相識，萬戶千門閉春色。","春色深，春色深，君王一去何時尋。","春雨灑，春雨灑，周南一望堪淚下。","蓬萊殿中寢胡人，鳷鵲樓前放胡馬。","聞君欲行西入秦，君行不用過天津。","天津橋上多胡塵，洛陽道上愁殺人。"]', '["洛陽宮中花柳春，洛陽道上無行人。","皮裘氈帳不相識，万戶千门閉春色。","春色深，春色深，君王一去何时尋。","春雨灑，春雨灑，周南一望堪泪下。","蓬萊殿中寢胡人，鳷鵲楼前放胡马。","闻君欲行西入秦，君行不用過天津。","天津橋上多胡塵，洛陽道上愁殺人。"]', '诗', 'shi', '', NULL, '洛陽道 馮著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ac6bba-d692-4203-9bef-62c9decf88a4', '行路難', '行路难', 'c7c885b9-4e5c-4988-9fbe-9633bab84fb8', '唐', '["男兒轗軻徒搔首，入市脫衣且沽酒。","行路難，權門慎勿干，平人爭路相摧殘。","春秋四氣更迴換，人事何須再三歎。","君不見雀爲鴿，鷹爲鳩，東海成田谷爲岸。","負薪客，歸去來，龜反顧，鶴裴回，黃河岸上起塵埃。","相逢未相識，何用強相猜。","行路難，故山應不改，茅舍漢中在。","白酒杯中聊一歌，蒼蠅蒼蠅奈爾何。"]', '["男兒轗軻徒搔首，入市脫衣且沽酒。","行路难，權门慎勿干，平人爭路相摧殘。","春秋四氣更迴換，人事何須再三歎。","君不见雀爲鴿，鷹爲鳩，东海成田谷爲岸。","負薪客，归去来，龟反顧，鹤裴回，黄河岸上起塵埃。","相逢未相識，何用強相猜。","行路难，故山應不改，茅舍漢中在。","白酒杯中聊一歌，蒼蠅蒼蠅奈爾何。"]', '诗', 'shi', '', NULL, '行路難 馮著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891b2c80-f3fc-4841-93a9-6d68605e175a', '燕銜泥', '燕銜泥', 'c7c885b9-4e5c-4988-9fbe-9633bab84fb8', '唐', '["雙燕碌碌飛入屋，屋中老人喜燕歸。","裴回繞我牀頭飛，去年爲爾逐黃雀。","雨多屋漏泥土落，爾莫厭老翁茅屋低，梁頭作窠梁下栖。","爾不見東家黃鷇鳴嘖嘖，蛇盤瓦溝鼠穿壁。","豪家大屋爾莫居，嬌兒少婦採爾雛。","井旁寫水泥自足，銜泥上屋隨爾欲。"]', '["雙燕碌碌飞入屋，屋中老人喜燕归。","裴回繞我牀头飞，去年爲爾逐黄雀。","雨多屋漏泥土落，爾莫厭老翁茅屋低，梁头作窠梁下栖。","爾不见东家黄鷇鳴嘖嘖，蛇盤瓦溝鼠穿壁。","豪家大屋爾莫居，嬌兒少婦採爾雛。","井旁寫水泥自足，銜泥上屋隨爾欲。"]', '诗', 'shi', '', NULL, '燕銜泥 馮著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('149b4657-90d4-4415-8dd4-1ac824e81dc5', '同孟浩然宴賦', '同孟浩然宴賦', '29c42cc9-360b-4b84-9158-27e53620da8b', '唐', '["屈宋英聲今止已，江山繼嗣多才子。","作者于今盡相似，聚宴王家其樂矣。","共賦新詩發宮徵，書于屋壁彰厥美。"]', '["屈宋英声今止已，江山繼嗣多才子。","作者于今尽相似，聚宴王家其乐矣。","共賦新诗發宮徵，书于屋壁彰厥美。"]', '诗', 'shi', '', NULL, '同孟浩然宴賦 王迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68b6697-98a2-488a-b620-77a99420cc3b', '尚書都堂瓦松', '尚书都堂瓦松', '989ca66c-9407-4bbd-b465-a368657067e4', '唐', '["華省祕僊蹤，高堂露瓦松。","葉因春後長，花爲雨來濃。","影混鴛鴦色，光含翡翠容。","天然斯所寄，地勢太無從。","接棟臨雙闕，連甍近九重。","寧知深澗底，霜雪歲兼封。"]', '["华省祕僊蹤，高堂露瓦松。","葉因春後长，花爲雨来濃。","影混鴛鴦色，光含翡翠容。","天然斯所寄，地勢太無從。","接棟臨雙闕，連甍近九重。","寧知深澗底，霜雪歲兼封。"]', '诗', 'shi', '', NULL, '尚書都堂瓦松 李曄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89433c6-deba-4097-b892-bbe2eb27d422', '省試七月流火', '省試七月流火', '27c18399-5d92-4823-8d82-6a23d56dc951', '唐', '["前庭一葉下，言念忽悲秋。","變節金初至，分寒火正流。","氣含涼夜早，光拂夏雲收。","助月微明散，沿河麗景浮。","禮標時令爽，詩興國風幽。","自此觀邦正，深知王業休。"]', '["前庭一葉下，言念忽悲秋。","变節金初至，分寒火正流。","氣含涼夜早，光拂夏云收。","助月微明散，沿河丽景浮。","禮標时令爽，诗兴国风幽。","自此观邦正，深知王業休。"]', '诗', 'shi', '', NULL, '省試七月流火 敬括 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce77cf0-244d-435a-8a25-8d28a83bc4b9', '奉贈韋左丞二十二韻', '奉贈韋左丞二十二韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["紈袴不餓死，儒冠多誤身。","丈人試靜聽，賤子請具陳。","甫昔少年日，早充觀國賓。","讀書破萬卷，下筆如有神。","賦料揚雄敵，詩看子建親。","李邕求識面，王翰願卜鄰。","自謂頗挺出，立登要路津。","致君堯舜上，再使風俗淳。","此意竟蕭條，行歌非隱淪。","騎驢三十載，旅食京華春。","朝扣富兒門，暮隨肥馬塵。","殘杯與冷炙，到處潛悲辛。","主上頃見徵，歘然欲求伸。","青冥却垂翅，蹭蹬無縱鱗。","甚媿丈人厚，甚知丈人真。","每於百僚上，猥誦佳句新。","竊效貢公喜，難甘原憲貧。","焉能心怏怏，秪是走踆踆。","今欲東入海，即將西去秦。","尚憐終南山，回首清渭濱。","常擬報一飯，況懷辭大臣。","白鷗沒浩蕩，萬里誰能馴。"]', '["紈袴不餓死，儒冠多誤身。","丈人試静听，賤子請具陳。","甫昔少年日，早充观国賓。","读书破万卷，下笔如有神。","賦料揚雄敵，诗看子建親。","李邕求識面，王翰願卜鄰。","自謂頗挺出，立登要路津。","致君堯舜上，再使风俗淳。","此意竟蕭條，行歌非隐淪。","騎驢三十載，旅食京华春。","朝扣富兒门，暮隨肥马塵。","殘杯與冷炙，到处潛悲辛。","主上頃见徵，歘然欲求伸。","青冥却垂翅，蹭蹬無縱鱗。","甚媿丈人厚，甚知丈人真。","每於百僚上，猥誦佳句新。","竊效貢公喜，难甘原憲貧。","焉能心怏怏，秪是走踆踆。","今欲东入海，即將西去秦。","尚怜終南山，回首清渭濱。","常擬報一飯，況懷辞大臣。","白鷗沒浩蕩，万里誰能馴。"]', '诗', 'shi', '', NULL, '奉贈韋左丞二十二韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e63635-0caa-43c2-b4b8-b459f9983fbf', '送高三十五書記', '送高三十五书記', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["崆峒小麥熟，且願休王師。","請公問主將，焉用窮荒爲。","飢鷹未飽肉，側翅隨人飛。","高生跨鞍馬，有似幽幷兒。","脫身簿尉中，始與捶楚辭。","借問今何官，觸熱向武威。","答云一書記，所媿國士知。","人實不易知，更須慎其儀。","十年出幕府，自可持旌麾。","此行既特達，足以慰所思。","男兒功名遂，亦在老大時。","常恨結驩淺，各在天一涯。","又如參與商，慘慘中腸悲。","驚風吹鴻鵠，不得相追隨。","黃塵翳沙漠，念子何當歸。","邊城有餘力，早寄從軍詩。"]', '["崆峒小麦熟，且願休王師。","請公问主將，焉用窮荒爲。","飢鷹未飽肉，側翅隨人飞。","高生跨鞍马，有似幽幷兒。","脫身簿尉中，始與捶楚辞。","借问今何官，觸熱向武威。","答云一书記，所媿国士知。","人實不易知，更須慎其儀。","十年出幕府，自可持旌麾。","此行既特達，足以慰所思。","男兒功名遂，亦在老大时。","常恨結驩淺，各在天一涯。","又如參與商，慘慘中腸悲。","驚风吹鴻鵠，不得相追隨。","黄塵翳沙漠，念子何當归。","邊城有餘力，早寄從軍诗。"]', '诗', 'shi', '', NULL, '送高三十五書記 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ac1ff8-366f-42d0-af96-e5c174b42b92', '贈李白', '贈李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二年客東都，所歷厭機巧。","野人對羶腥，蔬食常不飽。","豈無青精飯，使我顏色好。","苦乏大藥資，山林迹如掃。","李侯金閨彥，脫身事幽討。","亦有梁宋遊，方期拾瑤草。"]', '["二年客东都，所歷厭機巧。","野人对羶腥，蔬食常不飽。","豈無青精飯，使我顏色好。","苦乏大藥資，山林迹如掃。","李侯金閨彥，脫身事幽討。","亦有梁宋游，方期拾瑤草。"]', '诗', 'shi', '', NULL, '贈李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('176bc0de-6659-46ab-8ab4-fd67e4aa5852', '遊龍門奉先寺', '游龙门奉先寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["已從招提遊，更宿招提境。","陰壑生虛籟，月林散清影。","天闕象緯逼，雲臥衣裳冷。","欲覺聞晨鐘，令人發深省。"]', '["已從招提游，更宿招提境。","陰壑生虛籟，月林散清影。","天闕象緯逼，云臥衣裳冷。","欲覺闻晨鐘，令人發深省。"]', '诗', 'shi', '', NULL, '遊龍門奉先寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fdaad8-b197-4526-b56d-c7c713267248', '望嶽', '望嶽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["岱宗夫如何，齊魯青未了。","造化鍾神秀，陰陽割昏曉。","盪胷生曾雲，決眥入歸鳥。","會當凌絕頂，一覽衆山小。"]', '["岱宗夫如何，齊魯青未了。","造化鍾神秀，陰陽割昏晓。","盪胷生曾云，決眥入归鸟。","會當凌絕頂，一覽衆山小。"]', '诗', 'shi', '', NULL, '望嶽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19360992-900d-448d-abe0-5526fcca731e', '陪李北海宴歷下亭', '陪李北海宴歷下亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東藩駐皁蓋，北渚凌青荷。","海內此亭古，濟南名士多。","雲山已發興，玉佩仍當歌。","修竹不受暑，交流空湧波。","蘊真愜所遇，落日將如何。","貴賤俱物役，從公難重過。"]', '["东藩駐皁蓋，北渚凌青荷。","海內此亭古，濟南名士多。","云山已發兴，玉佩仍當歌。","修竹不受暑，交流空湧波。","蘊真愜所遇，落日將如何。","貴賤俱物役，從公难重過。"]', '诗', 'shi', '', NULL, '陪李北海宴歷下亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2c1932-4219-483b-a14b-52dc7265f6fb', '同李太守登歷下古城員外新亭亭對鵲湖', '同李太守登歷下古城員外新亭亭对鵲湖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["新亭結搆罷，隱見清湖陰。","跡籍臺觀舊，氣溟海嶽深。","圓荷想自昔，遺堞感至今。","芳宴此時具，哀絲千古心。","主稱壽尊客，筵秩宴北林。","不阻蓬蓽興，得兼梁甫吟。"]', '["新亭結搆罷，隐见清湖陰。","跡籍台观旧，氣溟海嶽深。","圓荷想自昔，遺堞感至今。","芳宴此时具，哀絲千古心。","主稱壽尊客，筵秩宴北林。","不阻蓬蓽兴，得兼梁甫吟。"]', '诗', 'shi', '', NULL, '同李太守登歷下古城員外新亭亭對鵲湖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6d1c12-1eb1-4ee7-aacd-a3f7f6edec37', '玄都壇歌寄元逸人', '玄都壇歌寄元逸人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故人昔隱東蒙峰，已佩含景蒼精龍。","故人今居子午谷，獨在陰崖結茅屋。","屋前太古玄都壇，青石漠漠常風寒。","子規夜啼山竹裂，王母晝下雲旗翻。","知君此計成長往，芝草琅玕日應長。","鐵鏁高垂不可攀，致身福地何蕭爽。"]', '["故人昔隐东蒙峰，已佩含景蒼精龙。","故人今居子午谷，独在陰崖結茅屋。","屋前太古玄都壇，青石漠漠常风寒。","子規夜啼山竹裂，王母晝下云旗翻。","知君此計成长往，芝草琅玕日應长。","鐵鏁高垂不可攀，致身福地何蕭爽。"]', '诗', 'shi', '', NULL, '玄都壇歌寄元逸人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092c35a3-eaf8-4078-86e6-fb338c21f085', '今夕行', '今夕行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今夕何夕歲云徂，更長燭明不可孤。","咸陽客舍一事無，相與博塞爲歡娛。","馮陵大叫呼五白，袒跣不肯成梟盧。","英雄有時亦如此，邂逅豈即非良圖。","君莫笑劉毅從來布衣願，家無儋石輸百萬。"]', '["今夕何夕歲云徂，更长燭明不可孤。","咸陽客舍一事無，相與博塞爲歡娛。","馮陵大叫呼五白，袒跣不肯成梟盧。","英雄有时亦如此，邂逅豈即非良圖。","君莫笑劉毅從来布衣願，家無儋石輸百万。"]', '诗', 'shi', '', NULL, '今夕行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7014a7a3-6b60-46bc-9631-63c6a724574d', '貧交行', '貧交行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["飜手作雲覆手雨，紛紛輕薄何須數。","不見管鮑貧時交，此道今人棄如土。"]', '["飜手作云覆手雨，紛紛轻薄何須數。","不见管鲍貧时交，此道今人棄如土。"]', '诗', 'shi', '', NULL, '貧交行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd57a0b0-28a1-4d53-bc09-51899d2dac38', '兵車行', '兵车行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["車轔轔，馬蕭蕭，行人弓箭各在腰。","耶孃妻子走相送，塵埃不見咸陽橋。","牽衣頓足闌道哭，哭聲直上干雲霄。","道傍過者問行人，行人但云點行頻。","或從十五北防河，便至四十西營田。","去時里正與裹頭，歸來頭白還戍邊。","邊亭流血成海水，武皇開邊意未已。","君不聞漢家山東二百州，千村萬落生荆杞。","縱有健婦把鋤犂，禾生隴畝無東西。","況復秦兵耐苦戰，被驅不異犬與雞。","長者雖有問，役夫敢申恨。","且如今年冬，未休關西卒。","縣官急索租，租稅從何出？","信知生男惡，反是生女好。","生女猶是嫁比鄰，生男埋沒隨百草。","君不見青海頭，古來白骨無人收。","新鬼煩冤舊鬼哭，天陰雨濕聲啾啾。"]', '["车轔轔，马蕭蕭，行人弓箭各在腰。","耶孃妻子走相送，塵埃不见咸陽橋。","牽衣頓足闌道哭，哭声直上干云霄。","道傍過者问行人，行人但云点行頻。","或從十五北防河，便至四十西營田。","去时里正與裹头，归来头白還戍邊。","邊亭流血成海水，武皇开邊意未已。","君不闻漢家山东二百州，千村万落生荆杞。","縱有健婦把鋤犂，禾生隴畝無东西。","況复秦兵耐苦戰，被驱不異犬與雞。","长者雖有问，役夫敢申恨。","且如今年冬，未休关西卒。","縣官急索租，租稅從何出？","信知生男惡，反是生女好。","生女猶是嫁比鄰，生男埋沒隨百草。","君不见青海头，古来白骨無人收。","新鬼煩冤旧鬼哭，天陰雨濕声啾啾。"]', '诗', 'shi', '', NULL, '兵車行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b100d5-9899-4ae0-9eb8-66983943969f', '高都護驄馬行', '高都護驄马行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["安西都護胡青驄，聲價歘然來向東。","此馬臨陣久無敵，與人一心成大功。","功成惠養隨所致，飄飄遠自流沙至。","雄姿未受伏櫪恩，猛氣猶思戰場利。","腕促蹄高如踣鐵，交河幾蹴曾冰裂。","五花散作雲滿身，萬里方看汗流血。","長安壯兒不敢騎，走過掣電傾城知。","青絲絡頭爲君老，何由却出橫門道。"]', '["安西都護胡青驄，声價歘然来向东。","此马臨陣久無敵，與人一心成大功。","功成惠養隨所致，飄飄远自流沙至。","雄姿未受伏櫪恩，猛氣猶思戰場利。","腕促蹄高如踣鐵，交河幾蹴曾冰裂。","五花散作云满身，万里方看汗流血。","长安壯兒不敢騎，走過掣電傾城知。","青絲絡头爲君老，何由却出橫门道。"]', '诗', 'shi', '', NULL, '高都護驄馬行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28c271b-70b9-422c-8bfd-6a062f40d40c', '天育驃騎歌', '天育驃騎歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾聞天子之馬走千里，今之畫圖無乃是。","是何意態雄且傑，駿尾蕭梢朔風起。","毛爲綠縹兩耳黃，眼有紫燄雙瞳方。","矯矯龍性合變化，卓立天骨森開張。","伊昔太僕張景順，監牧攻駒閱清峻。","遂令大奴守天育，別養驥子憐神俊。","當時四十萬匹馬，張公歎其材盡下。","故獨寫真傳世人，見之座右久更新。","年多物化空形影，嗚呼健步無由騁。","如今豈無騕褭與驊騮，時無王良伯樂死即休。"]', '["吾闻天子之马走千里，今之畫圖無乃是。","是何意態雄且傑，駿尾蕭梢朔风起。","毛爲綠縹兩耳黄，眼有紫燄雙瞳方。","矯矯龙性合变化，卓立天骨森开張。","伊昔太僕張景順，監牧攻駒閱清峻。","遂令大奴守天育，別養驥子怜神俊。","當时四十万匹马，張公歎其材尽下。","故独寫真傳世人，见之座右久更新。","年多物化空形影，嗚呼健步無由騁。","如今豈無騕褭與驊騮，时無王良伯乐死即休。"]', '诗', 'shi', '', NULL, '天育驃騎歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76b78f3-965d-49fe-8151-44568c0e5c37', '白絲行', '白絲行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["繅絲須長不須白，越羅蜀錦金粟尺。","象牀玉手亂殷紅，萬草千花動凝碧。","已悲素質隨時染，裂下鳴機色相射。","美人細意熨帖平，裁縫滅盡鍼線迹。","春天衣著爲君舞，蛺蜨飛來黃鸝語。","落絮游絲亦有情，隨風照日宜輕舉。","香汗輕塵污顏色，開新合故置何許。","君不見才士汲引難，恐懼棄捐忍羈旅。"]', '["繅絲須长不須白，越羅蜀錦金粟尺。","象牀玉手亂殷紅，万草千花动凝碧。","已悲素質隨时染，裂下鳴機色相射。","美人細意熨帖平，裁縫滅尽鍼線迹。","春天衣著爲君舞，蛺蜨飞来黄鸝語。","落絮游絲亦有情，隨风照日宜轻舉。","香汗轻塵污顏色，开新合故置何許。","君不见才士汲引难，恐懼棄捐忍羈旅。"]', '诗', 'shi', '', NULL, '白絲行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dccdf60-ec93-4a4d-be1c-4d725b92cb8e', '秋雨歎三首 一', '秋雨歎三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨中百草秋爛死，階下決明顏色鮮。","著葉滿枝翠羽蓋，開花無樹黃金錢。","涼風蕭蕭吹汝急，恐汝後時難獨立。","堂上書生空白頭，臨風三齅馨香泣。"]', '["雨中百草秋爛死，階下決明顏色鲜。","著葉满枝翠羽蓋，开花無樹黄金錢。","涼风蕭蕭吹汝急，恐汝後时难独立。","堂上书生空白头，臨风三齅馨香泣。"]', '诗', 'shi', '', NULL, '秋雨歎三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92fa6241-0397-448c-8a97-27f659ef9dd9', '秋雨歎三首 二', '秋雨歎三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["闌風長雨（一作「東風細雨」）秋紛紛，四海（一作「萬里」）八荒同一雲。","去馬來牛不復辨，濁涇清渭何當分。","禾（一作「木」）頭生耳黍穗黑，農夫田婦（一作「父」）無消息。","城中斗米換（一作「抱」）衾裯，相許寧論兩相直。"]', '["闌风长雨（一作「东风細雨」）秋紛紛，四海（一作「万里」）八荒同一云。","去马来牛不复辨，濁涇清渭何當分。","禾（一作「木」）头生耳黍穗黑，農夫田婦（一作「父」）無消息。","城中斗米換（一作「抱」）衾裯，相許寧論兩相直。"]', '诗', 'shi', '', NULL, '秋雨歎三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c725632-fe02-4fc7-b443-9410da36c7e5', '秋雨歎三首 三', '秋雨歎三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長安布衣誰比數，反鏁衡門守環堵。","老夫不出長蓬蒿，穉子無憂走（一作「奏」）風雨。","雨聲颼颼催早寒，胡雁翅濕高飛難。","秋來未曾（一作「省」）見白日，埿污后（一作「厚」）土何時乾？"]', '["长安布衣誰比數，反鏁衡门守环堵。","老夫不出长蓬蒿，穉子無憂走（一作「奏」）风雨。","雨声颼颼催早寒，胡雁翅濕高飞难。","秋来未曾（一作「省」）见白日，埿污后（一作「厚」）土何时乾？"]', '诗', 'shi', '', NULL, '秋雨歎三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0da6bc2-f1d1-468f-885f-4b515398106b', '歎庭前甘菊花', '歎庭前甘菊花', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["檐前甘菊移時晚，青蘂重陽不堪摘。","明日蕭條醉盡醒，殘花爛熳開何益。","籬邊野外多衆芳，采擷細瑣升中堂。","念茲空長大枝葉，結根失所纏風霜。"]', '["檐前甘菊移时晚，青蘂重陽不堪摘。","明日蕭條醉尽醒，殘花爛熳开何益。","籬邊野外多衆芳，采擷細瑣升中堂。","念茲空长大枝葉，結根失所纏风霜。"]', '诗', 'shi', '', NULL, '歎庭前甘菊花 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ec1415-85ee-4aa1-8838-62aa3c9b66dd', '醉時歌', '醉时歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["諸公衮衮登臺省，廣文先生官獨冷。","甲第紛紛厭粱肉，廣文先生飯不足。","先生有道出羲皇，先生有才過屈宋。","德尊一代常轗軻，名垂萬古知何用。","杜陵野客人更嗤，被褐短窄鬢如絲。","日糴太倉五升米，時赴鄭老同襟期。","得錢即相覓，沽酒不復疑。","忘形到爾汝，痛飲真吾師。","清夜沈沈動春酌，燈前細雨檐花落。","但覺高歌有鬼神，焉知餓死填溝壑。","相如逸才親滌器，子雲識字終投閣。","先生早賦歸去來，石田茅屋荒蒼苔。","儒術於我何有哉，孔丘盜跖俱塵埃。","不須聞此意慘愴，生前相遇且銜杯。"]', '["諸公衮衮登台省，廣文先生官独冷。","甲第紛紛厭粱肉，廣文先生飯不足。","先生有道出羲皇，先生有才過屈宋。","德尊一代常轗軻，名垂万古知何用。","杜陵野客人更嗤，被褐短窄鬢如絲。","日糴太倉五升米，时赴鄭老同襟期。","得錢即相覓，沽酒不复疑。","忘形到爾汝，痛饮真吾師。","清夜沈沈动春酌，灯前細雨檐花落。","但覺高歌有鬼神，焉知餓死填溝壑。","相如逸才親滌器，子云識字終投閣。","先生早賦归去来，石田茅屋荒蒼苔。","儒術於我何有哉，孔丘盜跖俱塵埃。","不須闻此意慘愴，生前相遇且銜杯。"]', '诗', 'shi', '', NULL, '醉時歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a34aac-4478-4911-bafe-19658d500275', '醉歌行', '醉歌行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陸機二十作文賦，汝更小年能綴文。","總角草書又神速，世上兒子徒紛紛。","驊騮作駒已汗血，鷙鳥舉翮連青雲。","詞源倒流三峽水，筆陣獨埽千人軍。","只今年纔十六七，射策軍門期第一。","舊穿楊葉真自知，暫蹶霜蹄未爲失。","偶然擢秀非難取，會是排風有毛質。","汝身已見唾成珠，汝伯何由髮如漆。","春光澹沲秦東亭，渚蒲牙白水荇青。","風吹客衣日杲杲，樹攪離思花冥冥。","酒盡沙頭雙玉缾，衆賓皆醉我獨醒。","乃知貧賤別更苦，吞聲躑躅涕淚零。"]', '["陸機二十作文賦，汝更小年能綴文。","總角草书又神速，世上兒子徒紛紛。","驊騮作駒已汗血，鷙鸟舉翮連青云。","词源倒流三峽水，笔陣独埽千人軍。","只今年纔十六七，射策軍门期第一。","旧穿楊葉真自知，暫蹶霜蹄未爲失。","偶然擢秀非难取，會是排风有毛質。","汝身已见唾成珠，汝伯何由髮如漆。","春光澹沲秦东亭，渚蒲牙白水荇青。","风吹客衣日杲杲，樹攪離思花冥冥。","酒尽沙头雙玉缾，衆賓皆醉我独醒。","乃知貧賤別更苦，吞声躑躅涕泪零。"]', '诗', 'shi', '', NULL, '醉歌行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7c45a6-c944-4ff3-aa99-f5cb0440436f', '贈衛八處士', '贈衛八处士', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["人生不相見，動如參與商。","今夕復何夕，共此燈燭光。","少壯能幾時，鬢髮各已蒼。","訪舊半爲鬼，驚呼熱中腸。","焉知二十載，重上君子堂。","昔別君未婚，兒女忽成行。","怡然敬父執，問我來何方。","問荅乃未已，兒女羅酒漿。","夜雨剪春韭，新炊間黃粱。","主稱會面難，一舉累十觴。","十觴亦不醉，感子故意長。","明日隔山岳，世事兩茫茫。"]', '["人生不相见，动如參與商。","今夕复何夕，共此灯燭光。","少壯能幾时，鬢髮各已蒼。","訪旧半爲鬼，驚呼熱中腸。","焉知二十載，重上君子堂。","昔別君未婚，兒女忽成行。","怡然敬父執，问我来何方。","问荅乃未已，兒女羅酒漿。","夜雨剪春韭，新炊间黄粱。","主稱會面难，一舉累十觴。","十觴亦不醉，感子故意长。","明日隔山岳，世事兩茫茫。"]', '诗', 'shi', '', NULL, '贈衛八處士 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e018d77b-84a8-4e85-b9af-d81845efe2a6', '苦雨奉寄隴西公兼呈王徵士', '苦雨奉寄隴西公兼呈王徵士', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今秋乃淫雨，仲月來寒風。","羣木水光下，萬象雲氣中。","所思礙行潦，九里信不通。","悄悄素滻路，迢迢天漢東。","願騰六尺馬，背若孤征鴻。","劃見公子面，超然歡笑同。","奮飛既胡越，局促傷樊籠。","一飯四五起，憑軒心力窮。","嘉蔬沒混濁，時菊碎榛叢。","鷹隼亦屈猛，烏鳶何所蒙。","式瞻北鄰居，取適南巷翁。","挂席釣川漲，焉知清興終。"]', '["今秋乃淫雨，仲月来寒风。","羣木水光下，万象云氣中。","所思礙行潦，九里信不通。","悄悄素滻路，迢迢天漢东。","願腾六尺马，背若孤征鴻。","劃见公子面，超然歡笑同。","奮飞既胡越，局促傷樊籠。","一飯四五起，憑軒心力窮。","嘉蔬沒混濁，时菊碎榛叢。","鷹隼亦屈猛，烏鳶何所蒙。","式瞻北鄰居，取適南巷翁。","挂席釣川漲，焉知清兴終。"]', '诗', 'shi', '', NULL, '苦雨奉寄隴西公兼呈王徵士 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2595ed8-1345-4194-86f6-ec71bd785110', '同諸公登慈恩寺塔', '同諸公登慈恩寺塔', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高標跨蒼天，烈風無時休。","自非曠士懷，登茲翻百憂。","方知象教力，足可追冥搜。","仰穿龍蛇窟，始出枝撐幽。","七星在北戶，河漢聲西流。","羲和鞭白日，少昊行清秋。","秦山忽破碎，涇渭不可求。","俯視但一氣，焉能辨皇州。","回首叫虞舜，蒼梧雲正愁。","惜哉瑤池飲，日宴崑崙丘。","黃鵠去不息，哀鳴何所投。","君看隨陽雁，各有稻粱謀。"]', '["高標跨蒼天，烈风無时休。","自非曠士懷，登茲翻百憂。","方知象教力，足可追冥搜。","仰穿龙蛇窟，始出枝撐幽。","七星在北戶，河漢声西流。","羲和鞭白日，少昊行清秋。","秦山忽破碎，涇渭不可求。","俯視但一氣，焉能辨皇州。","回首叫虞舜，蒼梧云正愁。","惜哉瑤池饮，日宴崑崙丘。","黄鵠去不息，哀鳴何所投。","君看隨陽雁，各有稻粱謀。"]', '诗', 'shi', '', NULL, '同諸公登慈恩寺塔 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4746c39-49bc-4a22-a6fb-68d7bf0f3fda', '示從孫濟', '示從孫濟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["平明跨驢出，未知適誰門。","權門多噂𠴲，且復尋諸孫。","諸孫貧無事，宅舍如荒村。","堂前自生竹，堂後自生萱。","萱草秋已死，竹枝霜不蕃。","淘米少汲水，汲多井水渾。","刈葵莫放手，放手傷葵根。","阿翁嬾惰久，覺兒行步奔。","所來爲宗族，亦不爲盤飧。","小人利口實，薄俗難可論。","勿受外嫌猜，同姓古所敦。"]', '["平明跨驢出，未知適誰门。","權门多噂𠴲，且复尋諸孫。","諸孫貧無事，宅舍如荒村。","堂前自生竹，堂後自生萱。","萱草秋已死，竹枝霜不蕃。","淘米少汲水，汲多井水渾。","刈葵莫放手，放手傷葵根。","阿翁嬾惰久，覺兒行步奔。","所来爲宗族，亦不爲盤飧。","小人利口實，薄俗难可論。","勿受外嫌猜，同姓古所敦。"]', '诗', 'shi', '', NULL, '示從孫濟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5fb4a5-5b1f-4eff-8e7f-a59f35d9d835', '九日寄岑參', '九日寄岑參', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["出門復入門，兩脚但如舊。","所向泥活活，思君令人瘦。","沈吟坐西軒，飲食錯昏晝。","寸步曲江頭，難爲一相就。","吁嗟呼蒼生，稼穡不可救。","安得誅雲師，疇能補天漏。","大明韜日月，曠野號禽獸。","君子強逶迤，小人困馳驟。","維南有崇山，恐與川浸溜。","是節東籬菊，紛披爲誰秀。","岑生多新詩，性亦嗜醇酎。","采采黃金花，何由滿衣袖。"]', '["出门复入门，兩脚但如旧。","所向泥活活，思君令人瘦。","沈吟坐西軒，饮食錯昏晝。","寸步曲江头，难爲一相就。","吁嗟呼蒼生，稼穡不可救。","安得誅云師，疇能補天漏。","大明韜日月，曠野號禽獸。","君子強逶迤，小人困驰驟。","維南有崇山，恐與川浸溜。","是節东籬菊，紛披爲誰秀。","岑生多新诗，性亦嗜醇酎。","采采黄金花，何由满衣袖。"]', '诗', 'shi', '', NULL, '九日寄岑參 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8040db71-8a96-49e2-9f4d-5417af0a0e3e', '送孔巢父謝病歸遊江東兼呈李白', '送孔巢父謝病归游江东兼呈李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巢父掉頭不肯住，東將入海隨煙霧。","詩卷長流天地間，釣竿欲拂珊瑚樹。","深山大澤龍蛇遠，春寒野陰風景暮。","蓬萊織女回雲車，指點虛無是征路。","自是君身有仙骨，世人那得知其故。","惜君只欲苦死留，富貴何如草頭露。","蔡侯靜者意有餘，清夜置酒臨前除。","罷琴惆悵月照席，幾歲寄我空中書。","南尋禹穴見李白，道甫問信今何如。"]', '["巢父掉头不肯住，东將入海隨煙霧。","诗卷长流天地间，釣竿欲拂珊瑚樹。","深山大澤龙蛇远，春寒野陰风景暮。","蓬萊织女回云车，指点虛無是征路。","自是君身有仙骨，世人那得知其故。","惜君只欲苦死留，富貴何如草头露。","蔡侯静者意有餘，清夜置酒臨前除。","罷琴惆悵月照席，幾歲寄我空中书。","南尋禹穴见李白，道甫问信今何如。"]', '诗', 'shi', '', NULL, '送孔巢父謝病歸遊江東兼呈李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb1e181-617c-4e12-b818-48666992ebf6', '飲中八仙歌', '饮中八仙歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["知章騎馬似乘船，眼花落井水底眠。","汝陽三斗始朝天，道逢麴車口流涎。","恨不移封向酒泉，左相日興費萬錢。","飲如長鯨吸百川，銜杯樂聖稱世賢。","宗之瀟灑美少年，舉觴白眼望青天。","皎如玉樹臨風前，蘇晉長齋繡佛前。","醉中往往愛逃禪，李白一斗詩百篇。","長安市上酒家眠，天子呼來不上船。","自稱臣是酒中仙，張旭三杯草聖傳。","脫帽露頂王公前，揮毫落紙如雲煙。","焦遂五斗方卓然，高談雄辨驚四筵。"]', '["知章騎马似乘船，眼花落井水底眠。","汝陽三斗始朝天，道逢麴车口流涎。","恨不移封向酒泉，左相日兴費万錢。","饮如长鯨吸百川，銜杯乐聖稱世賢。","宗之瀟灑美少年，舉觴白眼望青天。","皎如玉樹臨风前，蘇晉长斋繡佛前。","醉中往往愛逃禪，李白一斗诗百篇。","长安市上酒家眠，天子呼来不上船。","自稱臣是酒中仙，張旭三杯草聖傳。","脫帽露頂王公前，揮毫落紙如云煙。","焦遂五斗方卓然，高談雄辨驚四筵。"]', '诗', 'shi', '', NULL, '飲中八仙歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8483aa2d-27c5-4e40-816a-d0f84a04bddc', '曲江三章章五句 一', '曲江三章章五句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["曲江蕭條秋氣高，菱荷枯折隨風濤。","遊子空嗟垂二毛，白石素沙亦相蕩，哀鴻獨叫求其曹。"]', '["曲江蕭條秋氣高，菱荷枯折隨风濤。","游子空嗟垂二毛，白石素沙亦相蕩，哀鴻独叫求其曹。"]', '诗', 'shi', '', NULL, '曲江三章章五句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e39e3f-8aa2-40cb-bc2d-3cb08d009c95', '曲江三章章五句 二', '曲江三章章五句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["即事非今亦非古，長歌激越梢林莽。","比屋豪華固難數，吾人甘作心似灰，弟姪何傷淚如雨。"]', '["即事非今亦非古，长歌激越梢林莽。","比屋豪华固难數，吾人甘作心似灰，弟姪何傷泪如雨。"]', '诗', 'shi', '', NULL, '曲江三章章五句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba84f73-7c00-4307-ba41-09a68002d058', '曲江三章章五句 三', '曲江三章章五句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自斷此生休問天，杜曲幸有桑麻田。","故將移住南山邊，短衣匹馬隨李廣，看射猛虎終殘年。"]', '["自斷此生休问天，杜曲幸有桑麻田。","故將移住南山邊，短衣匹马隨李廣，看射猛虎終殘年。"]', '诗', 'shi', '', NULL, '曲江三章章五句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370b53ae-949e-45cf-92b0-3aca072c1b86', '麗人行', '丽人行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三月三日天氣新，長安水邊多麗人。","態濃意遠淑且真，肌理細膩骨肉勻。","繡羅衣裳照暮春，蹙金孔雀銀麒麟。","頭上何所有，翠微㔩葉垂鬢脣。","背後何所見，珠壓腰衱穩稱身。","就中雲幕椒房親，賜名大國虢與秦。","紫駝之峰出翠釜，水精之盤行素鱗。","犀箸厭飫久未下，鑾刀縷切空紛綸。","黃門飛鞚不動塵，御廚絡繹送八珍。","簫鼓哀吟感鬼神，賓從雜遝實要津。","後來鞍馬何逡巡，當軒下馬入錦茵。","楊花雪落覆白蘋，青鳥飛去銜紅巾。","炙手可熱勢絕倫，慎莫近前丞相嗔。"]', '["三月三日天氣新，长安水邊多丽人。","態濃意远淑且真，肌理細膩骨肉勻。","繡羅衣裳照暮春，蹙金孔雀銀麒麟。","头上何所有，翠微㔩葉垂鬢脣。","背後何所见，珠壓腰衱穩稱身。","就中云幕椒房親，賜名大国虢與秦。","紫駝之峰出翠釜，水精之盤行素鱗。","犀箸厭飫久未下，鑾刀縷切空紛綸。","黄门飞鞚不动塵，御廚絡繹送八珍。","簫鼓哀吟感鬼神，賓從杂遝實要津。","後来鞍马何逡巡，當軒下马入錦茵。","楊花雪落覆白蘋，青鸟飞去銜紅巾。","炙手可熱勢絕倫，慎莫近前丞相嗔。"]', '诗', 'shi', '', NULL, '麗人行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785330b1-8050-4b3b-beec-8b50916cdb7a', '樂遊園歌', '乐游园歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樂游古園崒森爽，煙緜碧草萋萋長。","公子華筵勢最高，秦川對酒平如掌。","長生木瓢示真率，更調鞍馬狂歡賞。","青春波浪芙蓉園，白日雷霆夾城仗。","閶闔晴開昳蕩蕩，曲江翠幕排銀牓。","拂水低徊舞袖飜，緣雲清切歌聲上。","却憶年年人醉時，只今未醉已先悲。","數莖白髮那拋得，百罰深杯亦不辭。","聖朝亦知賤士醜，一物自荷皇天慈。","此身飲罷無歸處，獨立蒼茫自詠詩。"]', '["乐游古园崒森爽，煙緜碧草萋萋长。","公子华筵勢最高，秦川对酒平如掌。","长生木瓢示真率，更調鞍马狂歡賞。","青春波浪芙蓉园，白日雷霆夾城仗。","閶闔晴开昳蕩蕩，曲江翠幕排銀牓。","拂水低徊舞袖飜，緣云清切歌声上。","却憶年年人醉时，只今未醉已先悲。","數莖白髮那拋得，百罰深杯亦不辞。","聖朝亦知賤士醜，一物自荷皇天慈。","此身饮罷無归处，独立蒼茫自詠诗。"]', '诗', 'shi', '', NULL, '樂遊園歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efa1a341-99b5-4f81-9c2e-4a1e372e41d1', '渼陂行', '渼陂行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["岑參兄弟皆好奇，攜我遠來游渼陂。","天地黤慘忽異色，波濤萬頃堆琉璃。","琉璃汗漫泛舟入，事殊興極憂思集。","鼉作鯨吞不復知，惡風白浪何嗟及。","主人錦帆相爲開，舟子喜甚無氛埃。","鳧鷖散亂櫂謳發，絲管啁啾空翠來。","沈竿續蔓深莫測，菱葉荷花靜如拭。","宛在中流渤澥清，下歸無極終南黑。","半陂已南純浸山，動影褭窕沖融間。","船舷暝戛雲際寺，水面月出藍田關。","此時驪龍亦吐珠，馮夷擊鼓羣龍趨。","湘妃漢女出歌舞，金支翠旗光有無。","咫尺但愁雷雨至，蒼茫不曉神靈意。","少壯幾時奈老何，向來哀樂何其多。"]', '["岑參兄弟皆好奇，携我远来游渼陂。","天地黤慘忽異色，波濤万頃堆琉璃。","琉璃汗漫泛舟入，事殊兴極憂思集。","鼉作鯨吞不复知，惡风白浪何嗟及。","主人錦帆相爲开，舟子喜甚無氛埃。","鳧鷖散亂櫂謳發，絲管啁啾空翠来。","沈竿續蔓深莫測，菱葉荷花静如拭。","宛在中流渤澥清，下归無極終南黑。","半陂已南純浸山，动影褭窕沖融间。","船舷暝戛云際寺，水面月出藍田关。","此时驪龙亦吐珠，馮夷擊鼓羣龙趨。","湘妃漢女出歌舞，金支翠旗光有無。","咫尺但愁雷雨至，蒼茫不晓神靈意。","少壯幾时奈老何，向来哀乐何其多。"]', '诗', 'shi', '', NULL, '渼陂行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d43a429-0280-47db-a8cd-cbd9e6d3fa8b', '渼陂西南臺', '渼陂西南台', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高臺面蒼陂，六月風日冷。","蒹葭離披去，天水相與永。","懷新目似擊，接要心已領。","仿像識鮫人，空蒙辨魚艇。","錯磨終南翠，顛倒白閣影。","崷崒增光輝，乘陵惜俄頃。","勞生媿嚴鄭，外物慕張邴。","世復輕驊騮，吾甘雜鼃黽。","知歸俗可忽，取適事莫竝。","身退豈待官，老來苦便靜。","況資菱芡足，庶結茅茨迥。","從此具扁舟，彌年逐清景。"]', '["高台面蒼陂，六月风日冷。","蒹葭離披去，天水相與永。","懷新目似擊，接要心已領。","仿像識鮫人，空蒙辨鱼艇。","錯磨終南翠，顛倒白閣影。","崷崒增光輝，乘陵惜俄頃。","勞生媿嚴鄭，外物慕張邴。","世复轻驊騮，吾甘杂鼃黽。","知归俗可忽，取適事莫竝。","身退豈待官，老来苦便静。","況資菱芡足，庶結茅茨迥。","從此具扁舟，彌年逐清景。"]', '诗', 'shi', '', NULL, '渼陂西南臺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ecd1880-117b-4442-86e0-b79993ea4ca6', '戲簡鄭廣文虔兼呈蘇司業源明', '戲簡鄭廣文虔兼呈蘇司業源明', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["廣文到官舍，繫馬堂階下。","醉則騎馬歸，頗遭官長駡。","才名四十年，坐客寒無氊。","賴有蘇司業，時時與酒錢。"]', '["廣文到官舍，繫马堂階下。","醉則騎马归，頗遭官长駡。","才名四十年，坐客寒無氊。","賴有蘇司業，时时與酒錢。"]', '诗', 'shi', '', NULL, '戲簡鄭廣文虔兼呈蘇司業源明 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d27f63af-0f0a-4408-8c43-877b18d98620', '夏日李公見訪', '夏日李公见訪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遠林暑氣薄，公子過我遊。","貧居類村塢，僻近城南樓。","旁舍頗淳樸，所願亦易求。","隔屋喚西家，借問有酒不。","牆頭過濁醪，展席俯長流。","清風左右至，客意已驚秋。","巢多衆鳥鬬，葉密鳴蟬稠。","苦道此物聒，孰謂吾廬幽。","水花晚色靜，庶足充淹留。","預恐尊中盡，更起爲君謀。"]', '["远林暑氣薄，公子過我游。","貧居類村塢，僻近城南楼。","旁舍頗淳樸，所願亦易求。","隔屋喚西家，借问有酒不。","牆头過濁醪，展席俯长流。","清风左右至，客意已驚秋。","巢多衆鸟鬬，葉密鳴蟬稠。","苦道此物聒，孰謂吾廬幽。","水花晚色静，庶足充淹留。","預恐尊中尽，更起爲君謀。"]', '诗', 'shi', '', NULL, '夏日李公見訪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f980b6f-473d-4f04-8090-0e04da5e2655', '奉同郭給事湯東靈湫作', '奉同郭給事湯东靈湫作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東山氣鴻濛，宮殿居上頭。","君來必十月，樹羽臨九州。","陰火煮玉泉，噴薄漲巖幽。","有時浴赤日，光抱空中摟。","閬風入轍跡，曠原延冥搜。","沸天萬乘動，觀水百丈湫。","幽靈斯可佳，王命宮屬休。","初聞龍用壯，擘石摧林丘。","中夜窟宅改，移因風雨秋。","倒懸瑤池影，屈注蒼江流。","味如甘露漿，揮弄滑且柔。","翠旗澹偃蹇，雲車紛少留。","簫鼓蕩四溟，異香泱漭浮。","鮫人獻微綃，曾祝沈豪牛。","百祥奔盛明，古先莫能儔。","坡陀金蝦蟆，出見蓋有由。","至尊顧之笑，王母不肯收。","復歸虛無底，化作長黃虯。","飄飄青瑣郎，文采珊瑚鉤。","浩歌淥水曲，清絕聽者愁。"]', '["东山氣鴻濛，宮殿居上头。","君来必十月，樹羽臨九州。","陰火煮玉泉，噴薄漲巖幽。","有时浴赤日，光抱空中摟。","閬风入轍跡，曠原延冥搜。","沸天万乘动，观水百丈湫。","幽靈斯可佳，王命宮屬休。","初闻龙用壯，擘石摧林丘。","中夜窟宅改，移因风雨秋。","倒懸瑤池影，屈注蒼江流。","味如甘露漿，揮弄滑且柔。","翠旗澹偃蹇，云车紛少留。","簫鼓蕩四溟，異香泱漭浮。","鮫人獻微綃，曾祝沈豪牛。","百祥奔盛明，古先莫能儔。","坡陀金蝦蟆，出见蓋有由。","至尊顧之笑，王母不肯收。","复归虛無底，化作长黄虯。","飄飄青瑣郎，文采珊瑚鉤。","浩歌淥水曲，清絕听者愁。"]', '诗', 'shi', '', NULL, '奉同郭給事湯東靈湫作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b45024f9-099b-4057-897c-f5a2e3016dd3', '夜聽許十損誦詩愛而有作', '夜听許十損誦诗愛而有作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["許生五臺賓，業白出石壁。","余亦師粲可，身猶縛禪寂。","何階子方便，謬引爲匹敵。","離索晚相逢，包蒙欣有擊。","誦詩渾遊衍，四座皆辟易。","應手看捶鉤，清心聽鳴鏑。","精微穿溟涬，飛動摧霹靂。","陶謝不枝梧，風騷共推激。","紫燕自超詣，翠駮誰翦剔。","君意人莫知，人間夜寥闃。"]', '["許生五台賓，業白出石壁。","余亦師粲可，身猶縛禪寂。","何階子方便，謬引爲匹敵。","離索晚相逢，包蒙欣有擊。","誦诗渾游衍，四座皆辟易。","應手看捶鉤，清心听鳴鏑。","精微穿溟涬，飞动摧霹靂。","陶謝不枝梧，风騷共推激。","紫燕自超詣，翠駮誰翦剔。","君意人莫知，人间夜寥闃。"]', '诗', 'shi', '', NULL, '夜聽許十損誦詩愛而有作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e319756-6b63-4706-b074-b79db30a8f1b', '橋陵詩三十韻因呈縣內諸官', '橋陵诗三十韻因呈縣內諸官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["先帝昔晏駕，茲山朝百靈。","崇岡擁象設，沃野開天庭。","即事壯重險，論功超五丁。","坡陀因厚地，却略羅峻屏。","雲闕虛冉冉，風松肅泠泠。","石門霜露白，玉殿莓苔青。","宮女晚知曙，祠官朝見星。","空梁簇畫戟，陰井敲銅缾。","中使日夜繼，惟王心不寧。","豈徒卹備享，尚謂求無形。","孝理敦國政，神凝推道經。","瑞芝產廟柱，好鳥鳴巖扃。","高岳前嵂崒，洪河左瀅濙。","金城蓄峻址，沙苑交回汀。","永與奧區固，川原紛眇冥。","居然赤縣立，臺榭爭岧亭。","官屬果稱是，聲華真可聽。","王劉美竹潤，裴李春蘭馨。","鄭氏才振古，啖侯筆不停。","遣辭必中律，利物常發硎。","綺繡相展轉，琳瑯愈青熒。","側聞魯恭化，秉德崔瑗銘。","太史侯鳧影，王喬隨鶴翎。","朝儀限霄漢，客思回林坰。","轗軻辭下杜，飄颻陵濁涇。","諸生舊短褐，旅泛一浮萍。","荒歲兒女瘦，暮途涕泗零。","主人念老馬，廨署容秋螢。","流寓理豈愜，窮愁醉未醒。","何當擺俗累，浩蕩乘滄溟。"]', '["先帝昔晏駕，茲山朝百靈。","崇岡擁象設，沃野开天庭。","即事壯重險，論功超五丁。","坡陀因厚地，却略羅峻屏。","云闕虛冉冉，风松肅泠泠。","石门霜露白，玉殿莓苔青。","宮女晚知曙，祠官朝见星。","空梁簇畫戟，陰井敲銅缾。","中使日夜繼，惟王心不寧。","豈徒卹備享，尚謂求無形。","孝理敦国政，神凝推道經。","瑞芝產廟柱，好鸟鳴巖扃。","高岳前嵂崒，洪河左瀅濙。","金城蓄峻址，沙苑交回汀。","永與奧區固，川原紛眇冥。","居然赤縣立，台榭爭岧亭。","官屬果稱是，声华真可听。","王劉美竹潤，裴李春蘭馨。","鄭氏才振古，啖侯笔不停。","遣辞必中律，利物常發硎。","綺繡相展轉，琳瑯愈青熒。","側闻魯恭化，秉德崔瑗銘。","太史侯鳧影，王喬隨鹤翎。","朝儀限霄漢，客思回林坰。","轗軻辞下杜，飄颻陵濁涇。","諸生旧短褐，旅泛一浮萍。","荒歲兒女瘦，暮途涕泗零。","主人念老马，廨署容秋螢。","流寓理豈愜，窮愁醉未醒。","何當擺俗累，浩蕩乘滄溟。"]', '诗', 'shi', '', NULL, '橋陵詩三十韻因呈縣內諸官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d5efe6-5b52-414f-90d1-0071a61f9be0', '沙苑行', '沙苑行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見左輔白沙如白水，繚以周牆百餘里。","龍媒昔是渥洼生，汗血今稱獻於此。","苑中騋牝三千匹，豐草青青寒不死。","食之豪健西域無，每歲攻駒冠邊鄙。","王有虎臣司苑門，入門天廄皆雲屯。","驌骦一骨獨當御，春秋二時歸至尊。","至尊內外馬盈億，伏櫪在坰空大存。","逸羣絕足信殊傑，倜儻權奇難具論。","纍纍塠阜藏奔突，往往坡陀縱超越。","角壯飜同糜鹿遊，浮身簸蕩黿鼉窟。","泉出巨魚長比人，丹砂作尾黃金鱗。","豈知異物同精氣，雖未成龍亦有神。"]', '["君不见左輔白沙如白水，繚以周牆百餘里。","龙媒昔是渥洼生，汗血今稱獻於此。","苑中騋牝三千匹，豐草青青寒不死。","食之豪健西域無，每歲攻駒冠邊鄙。","王有虎臣司苑门，入门天廄皆云屯。","驌骦一骨独當御，春秋二时归至尊。","至尊內外马盈億，伏櫪在坰空大存。","逸羣絕足信殊傑，倜儻權奇难具論。","纍纍塠阜藏奔突，往往坡陀縱超越。","角壯飜同糜鹿游，浮身簸蕩黿鼉窟。","泉出巨鱼长比人，丹砂作尾黄金鱗。","豈知異物同精氣，雖未成龙亦有神。"]', '诗', 'shi', '', NULL, '沙苑行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0047aa-a695-43a5-a4a7-b1f2529ba792', '聰馬行', '聰马行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄧公馬癖人共知，初得花驄大宛種。","夙昔傳聞思一見，牽來左右神皆竦。","雄姿逸態何崷崪，顧影驕嘶自矜寵。","隅目青熒夾鏡懸，肉駿碨礌連錢動。","朝來久試華軒下，未覺千金滿高價。","赤汗微生白雪毛，銀鞍却覆香羅帕。","卿家舊賜公取之，天廄真龍此其亞。","晝洗須騰涇渭深，朝趨可刷幽幷夜。","吾聞良驥老始成，此馬數年人更驚。","豈有四蹄疾於鳥，不與八駿俱先鳴。","時俗造次那得致，雲霧晦冥方降精。","近聞下詔喧都邑，肯使騏驎地上行。"]', '["鄧公马癖人共知，初得花驄大宛種。","夙昔傳闻思一见，牽来左右神皆竦。","雄姿逸態何崷崪，顧影驕嘶自矜寵。","隅目青熒夾镜懸，肉駿碨礌連錢动。","朝来久試华軒下，未覺千金满高價。","赤汗微生白雪毛，銀鞍却覆香羅帕。","卿家旧賜公取之，天廄真龙此其亞。","晝洗須腾涇渭深，朝趨可刷幽幷夜。","吾闻良驥老始成，此马數年人更驚。","豈有四蹄疾於鸟，不與八駿俱先鳴。","时俗造次那得致，云霧晦冥方降精。","近闻下詔喧都邑，肯使騏驎地上行。"]', '诗', 'shi', '', NULL, '聰馬行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba4bd65a-2c56-4f81-b0bf-dacc0068c271', '去矣行', '去矣行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見韝上鷹，一飽則飛掣。","焉能作堂上燕，銜泥附炎熱。","野人曠蕩無靦顏，豈可久在王侯間。","未試囊中餐玉法，明朝且入藍田山。"]', '["君不见韝上鷹，一飽則飞掣。","焉能作堂上燕，銜泥附炎熱。","野人曠蕩無靦顏，豈可久在王侯间。","未試囊中餐玉法，明朝且入藍田山。"]', '诗', 'shi', '', NULL, '去矣行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ffa213-5085-4349-9866-ea0735ff7b11', '自京赴奉先縣詠懷五百字', '自京赴奉先縣詠懷五百字', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["杜陵有布衣，老大意轉拙。","許身一何愚，竊比稷與契。","居然成濩落，白手甘契闊。","蓋棺事則已，此志常覬豁。","窮年憂黎元，歎息腸內熱。","取笑同學翁，浩歌彌激烈。","非無江海志，蕭灑送日月。","生逢堯舜君，不忍便永訣。","當今廊廟具，構廈豈云缺。","葵藿傾太陽，物性固莫奪。","顧惟螻蟻輩，但自求其穴。","胡爲慕大鯨，輒擬偃溟渤。","以茲悟生理，獨恥事干謁。","兀兀遂至今，忍爲塵埃沒。","終媿巢與由，未能易其節。","沈飲聊自適，放歌頗愁絕。","歲暮百草零，疾風高岡裂。","天衢陰崢嶸，客子中夜發。","霜嚴衣帶斷，指直不得結。","凌晨過驪山，御榻在嵽嵲。","蚩尤塞寒空，蹴蹋崖谷滑。","瑤池氣鬱律，羽林相摩戛。","君臣留歡娛，樂動殷樛嶱。","賜浴皆長纓，與宴非短褐。","彤庭所分帛，本自寒女出。","鞭撻其夫家，聚斂貢城闕。","聖人筐篚恩，實欲邦國活。","臣如忽至理，君豈棄此物。","多士盈朝廷，仁者宜戰慄。","況聞內金盤，盡在衛霍室。","中堂舞神仙，煙霧散玉質。","煖客貂鼠裘，悲管逐清瑟。","勸客駝蹄羹，霜橙壓香橘。","朱門酒肉臭，路有凍死骨。","榮枯咫尺異，惆悵難再述。","北轅就涇渭，官渡又改轍。","羣冰從西下，極目高崪兀。","疑是崆峒來，恐觸天柱折。","河梁幸未坼，枝撐聲窸窣。","行旅相攀援，川廣不可越。","老妻寄異縣，十口隔風雪。","誰能久不顧，庶往共飢渴。","入門聞號咷，幼子飢已卒。","吾寧舍一哀，里巷亦嗚咽。","所媿爲人父，無食致夭折。","豈知秋未登，貧寠有蒼卒。","生常免租稅，名不隸征伐。","撫迹猶酸辛，平人固騷屑。","默思失業徒，因念遠戍卒。","憂端齊終南，澒洞不可掇。"]', '["杜陵有布衣，老大意轉拙。","許身一何愚，竊比稷與契。","居然成濩落，白手甘契闊。","蓋棺事則已，此志常覬豁。","窮年憂黎元，歎息腸內熱。","取笑同学翁，浩歌彌激烈。","非無江海志，蕭灑送日月。","生逢堯舜君，不忍便永訣。","當今廊廟具，構廈豈云缺。","葵藿傾太陽，物性固莫奪。","顧惟螻蟻輩，但自求其穴。","胡爲慕大鯨，輒擬偃溟渤。","以茲悟生理，独恥事干謁。","兀兀遂至今，忍爲塵埃沒。","終媿巢與由，未能易其節。","沈饮聊自適，放歌頗愁絕。","歲暮百草零，疾风高岡裂。","天衢陰崢嶸，客子中夜發。","霜嚴衣带斷，指直不得結。","凌晨過驪山，御榻在嵽嵲。","蚩尤塞寒空，蹴蹋崖谷滑。","瑤池氣鬱律，羽林相摩戛。","君臣留歡娛，乐动殷樛嶱。","賜浴皆长纓，與宴非短褐。","彤庭所分帛，本自寒女出。","鞭撻其夫家，聚斂貢城闕。","聖人筐篚恩，實欲邦国活。","臣如忽至理，君豈棄此物。","多士盈朝廷，仁者宜戰慄。","況闻內金盤，尽在衛霍室。","中堂舞神仙，煙霧散玉質。","煖客貂鼠裘，悲管逐清瑟。","勸客駝蹄羹，霜橙壓香橘。","朱门酒肉臭，路有凍死骨。","榮枯咫尺異，惆悵难再述。","北轅就涇渭，官渡又改轍。","羣冰從西下，極目高崪兀。","疑是崆峒来，恐觸天柱折。","河梁幸未坼，枝撐声窸窣。","行旅相攀援，川廣不可越。","老妻寄異縣，十口隔风雪。","誰能久不顧，庶往共飢渴。","入门闻號咷，幼子飢已卒。","吾寧舍一哀，里巷亦嗚咽。","所媿爲人父，無食致夭折。","豈知秋未登，貧寠有蒼卒。","生常免租稅，名不隸征伐。","撫迹猶酸辛，平人固騷屑。","默思失業徒，因念远戍卒。","憂端齊終南，澒洞不可掇。"]', '诗', 'shi', '', NULL, '自京赴奉先縣詠懷五百字 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8dc6f9-911f-4ae1-8f6a-0e6b374a5ede', '奉先劉少府新畫山水障歌', '奉先劉少府新畫山水障歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["堂上不合生楓樹，怪底江山起煙霧。","聞君埽却赤縣圖，乘興譴畫滄洲趣。","畫師亦無數，好手不可遇。","對此融心神，知君重毫素。","豈但祁岳與鄭虔，筆迹遠過楊契丹。","得非懸圃裂，無乃瀟湘飜。","悄然坐我天姥下，耳邊已似聞清猨。","反思前夜風雨急，乃是蒲城鬼神人。","元氣淋漓障猶濕，真宰上訴天應泣。","野亭春還雜花遠，漁翁暝蹋孤舟立。","滄浪水深青溟闊，攲岸側島秋毫末。","不見湘妃鼓瑟時，至今斑竹臨江活。","劉侯天機精，愛畫入骨髓。","自有兩兒郎，揮灑亦莫比。","大兒聰明到，能添老樹巔崖裏。","小兒心孔開，貌得山僧及童子。","若耶溪，雲門寺。","吾獨胡爲在泥滓，青鞵布韤從此始。"]', '["堂上不合生楓樹，怪底江山起煙霧。","闻君埽却赤縣圖，乘兴譴畫滄洲趣。","畫師亦無數，好手不可遇。","对此融心神，知君重毫素。","豈但祁岳與鄭虔，笔迹远過楊契丹。","得非懸圃裂，無乃瀟湘飜。","悄然坐我天姥下，耳邊已似闻清猨。","反思前夜风雨急，乃是蒲城鬼神人。","元氣淋漓障猶濕，真宰上訴天應泣。","野亭春還杂花远，漁翁暝蹋孤舟立。","滄浪水深青溟闊，攲岸側島秋毫末。","不见湘妃鼓瑟时，至今斑竹臨江活。","劉侯天機精，愛畫入骨髓。","自有兩兒郎，揮灑亦莫比。","大兒聰明到，能添老樹巔崖裏。","小兒心孔开，貌得山僧及童子。","若耶溪，云门寺。","吾独胡爲在泥滓，青鞵布韤從此始。"]', '诗', 'shi', '', NULL, '奉先劉少府新畫山水障歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40806e64-bb99-458f-a2a0-046eed040b76', '白水縣崔少府十九翁高齋三十韻', '白水縣崔少府十九翁高斋三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客從南縣來，浩蕩無與適。","旅食白日長，況當朱炎赫。","高齋坐林杪，信宿游衍闃。","清晨陪躋攀，傲睨俯峭壁。","崇岡相枕帶，曠野懷咫尺。","始知賢主人，贈此遣愁寂。","危階根青冥，曾冰生淅瀝。","上有無心雲，下有欲落石。","泉聲聞復急，動靜隨所擊。","鳥呼藏其身，有似懼彈射。","吏隱道性情，茲焉其窟宅。","白水見舅氏，諸翁乃仙伯。","杖藜長松陰，作尉窮谷僻。","爲我炊雕胡，逍遙展良覿。","坐久風頗愁，晚來山更碧。","相對十丈蛟，歘翻盤渦坼。","何得空裏雷，殷殷尋地脈。","煙氛藹崷崪，魍魎森慘戚。","崑崙崆峒顛，回首如不隔。","前軒頹反照，巉絕華岳赤。","兵氣漲林巒，川光雜鋒鏑。","知是相公軍，鐵馬雲霧積。","玉觴淡無味，胡羯豈強敵。","長歌激屋梁，淚下流衽席。","人生半哀樂，天地有順逆。","慨彼萬國夫，休明備征狄。","猛將紛填委，廟謀蓄長策。","東郊何時開，帶甲且來釋。","欲告清宴罷，難拒幽明迫。","三歎酒食旁，何由似平昔。"]', '["客從南縣来，浩蕩無與適。","旅食白日长，況當朱炎赫。","高斋坐林杪，信宿游衍闃。","清晨陪躋攀，傲睨俯峭壁。","崇岡相枕带，曠野懷咫尺。","始知賢主人，贈此遣愁寂。","危階根青冥，曾冰生淅瀝。","上有無心云，下有欲落石。","泉声闻复急，动静隨所擊。","鸟呼藏其身，有似懼彈射。","吏隐道性情，茲焉其窟宅。","白水见舅氏，諸翁乃仙伯。","杖藜长松陰，作尉窮谷僻。","爲我炊雕胡，逍遙展良覿。","坐久风頗愁，晚来山更碧。","相对十丈蛟，歘翻盤渦坼。","何得空裏雷，殷殷尋地脈。","煙氛藹崷崪，魍魎森慘戚。","崑崙崆峒顛，回首如不隔。","前軒頹反照，巉絕华岳赤。","兵氣漲林巒，川光杂鋒鏑。","知是相公軍，鐵马云霧積。","玉觴淡無味，胡羯豈強敵。","长歌激屋梁，泪下流衽席。","人生半哀乐，天地有順逆。","慨彼万国夫，休明備征狄。","猛將紛填委，廟謀蓄长策。","东郊何时开，带甲且来釋。","欲告清宴罷，难拒幽明迫。","三歎酒食旁，何由似平昔。"]', '诗', 'shi', '', NULL, '白水縣崔少府十九翁高齋三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('212bf433-f47a-4f05-84d1-172804896869', '三川觀水漲二十韻', '三川观水漲二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我經華原來，不復見平陸。","北上唯土山，連山走窮谷。","火雲無時出，飛電常在目。","自多窮岫雨，行潦相豗蹙。","蓊匌川氣黃，羣流會空曲。","清晨望高浪，忽謂陰崖踣。","恐泥竄蛟龍，登危聚麋鹿。","枯查卷拔樹，礧磈共充塞。","聲吹鬼神下，勢閱人代速。","不有萬穴歸，何以尊四瀆。","及觀泉源漲，反懼江海覆。","漂沙坼岸去，漱壑松柏禿。","乘陵破山門，回斡裂地軸。","交洛赴洪河，及關豈信宿。","應沈數州沒，如聽萬室哭。","穢濁殊未清，風濤怒猶蓄。","何時通舟車，陰氣不黲黷。","浮生有蕩汨，吾道正羈束。","人寰難容身，石壁滑側足。","雲雷此不已，艱險路更跼。","普天無川梁，欲濟願水縮。","因悲中林士，未脫衆魚腹。","舉頭向蒼天，安得騎鴻鵠。"]', '["我經华原来，不复见平陸。","北上唯土山，連山走窮谷。","火云無时出，飞電常在目。","自多窮岫雨，行潦相豗蹙。","蓊匌川氣黄，羣流會空曲。","清晨望高浪，忽謂陰崖踣。","恐泥竄蛟龙，登危聚麋鹿。","枯查卷拔樹，礧磈共充塞。","声吹鬼神下，勢閱人代速。","不有万穴归，何以尊四瀆。","及观泉源漲，反懼江海覆。","漂沙坼岸去，漱壑松柏禿。","乘陵破山门，回斡裂地軸。","交洛赴洪河，及关豈信宿。","應沈數州沒，如听万室哭。","穢濁殊未清，风濤怒猶蓄。","何时通舟车，陰氣不黲黷。","浮生有蕩汨，吾道正羈束。","人寰难容身，石壁滑側足。","云雷此不已，艱險路更跼。","普天無川梁，欲濟願水縮。","因悲中林士，未脫衆鱼腹。","舉头向蒼天，安得騎鴻鵠。"]', '诗', 'shi', '', NULL, '三川觀水漲二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c09e9e-e471-4489-9d3f-a598832ac638', '悲陳陶', '悲陳陶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孟冬十郡良家子，血作陳陶澤中水。","野曠天清無戰聲，四萬義軍同日死。","羣胡歸來血洗箭，仍唱胡歌飲都市。","都人回面北向啼，日夜更望官軍至。"]', '["孟冬十郡良家子，血作陳陶澤中水。","野曠天清無戰声，四万義軍同日死。","羣胡归来血洗箭，仍唱胡歌饮都市。","都人回面北向啼，日夜更望官軍至。"]', '诗', 'shi', '', NULL, '悲陳陶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee982ff4-8ff7-4f1c-b955-a6f395fb5854', '悲青坂', '悲青坂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我軍青坂在東門，天寒飲馬太白窟。","黃頭奚兒日向西，數騎彎弓敢馳突。","山雪河冰野蕭飋，青是烽煙白人骨。"]', '["我軍青坂在东门，天寒饮马太白窟。","黄头奚兒日向西，數騎彎弓敢驰突。","山雪河冰野蕭飋，青是烽煙白人骨。"]', '诗', 'shi', '', NULL, '悲青坂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8474f5c4-d18e-4b42-9702-19ad909b9ea2', '哀江頭', '哀江头', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["少陵野老吞聲哭，春日潛行曲江曲。","江頭宮殿鎖千門，細柳新蒲爲誰綠。","憶昔霓旌下南苑，苑中萬物生顏色。","昭陽殿裏第一人，同輦隨君侍君側。","輦前才人帶弓箭，白馬嚼齧黃金勒。","翻身向天仰射雲，一箭正墜雙飛翼。","明眸皓齒今何在，血污遊魂歸不得。","清渭東流劒閣深，去住彼此無消息。","人生有情淚霑臆，江水江花豈終極。","黃昏胡騎塵滿城，欲往城南忘南北。"]', '["少陵野老吞声哭，春日潛行曲江曲。","江头宮殿鎖千门，細柳新蒲爲誰綠。","憶昔霓旌下南苑，苑中万物生顏色。","昭陽殿裏第一人，同輦隨君侍君側。","輦前才人带弓箭，白马嚼齧黄金勒。","翻身向天仰射云，一箭正墜雙飞翼。","明眸皓齒今何在，血污游魂归不得。","清渭东流劒閣深，去住彼此無消息。","人生有情泪霑臆，江水江花豈終極。","黄昏胡騎塵满城，欲往城南忘南北。"]', '诗', 'shi', '', NULL, '哀江頭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7949f8-c961-4bfd-a307-1fe9e621028c', '哀王孫', '哀王孫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長安城頭頭白烏，夜飛延秋門上呼。","又向人家啄大屋，屋底達官走避胡。","金鞭斷折九馬死，骨肉不待同馳驅。","腰下實玦青珊瑚，可憐王孫泣路隅。","問之不肯道姓名，但道困苦乞爲奴。","已經百日竄荆棘，身上無有完肌膚。","高帝子孫盡隆準，龍種自與常人殊。","豺狼在邑龍在野，王孫善保千金軀。","不敢長語臨交衢，且爲王孫立斯須。","昨夜東風吹血腥，東來橐駝滿舊都。","朔方健兒好身手，昔何勇銳今何愚。","竊聞天子已傳位，賢德北服南單于。","花門剺面請雪恥，慎勿出口他人狙。","哀哉王孫慎勿疎，五陵佳氣無時無。"]', '["长安城头头白烏，夜飞延秋门上呼。","又向人家啄大屋，屋底達官走避胡。","金鞭斷折九马死，骨肉不待同驰驱。","腰下實玦青珊瑚，可怜王孫泣路隅。","问之不肯道姓名，但道困苦乞爲奴。","已經百日竄荆棘，身上無有完肌膚。","高帝子孫尽隆準，龙種自與常人殊。","豺狼在邑龙在野，王孫善保千金軀。","不敢长語臨交衢，且爲王孫立斯須。","昨夜东风吹血腥，东来橐駝满旧都。","朔方健兒好身手，昔何勇銳今何愚。","竊闻天子已傳位，賢德北服南單于。","花门剺面請雪恥，慎勿出口他人狙。","哀哉王孫慎勿疎，五陵佳氣無时無。"]', '诗', 'shi', '', NULL, '哀王孫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627b0d8c-9d75-414e-9513-4122bc2c350f', '大雲寺贊公房四首 一', '大云寺贊公房四首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["心在水精域，衣霑春雨時。","洞門盡徐步，深院果幽期。","到扉開復閉，撞鐘齋及茲。","醍醐長發性，飲食過扶衰。","把臂有多日，開懷無媿辭。","黃鸝度結構，紫鴿下罘罳。","愚意會所適，花邊行自遲。","湯休起我病，微笑索題詩。"]', '["心在水精域，衣霑春雨时。","洞门尽徐步，深院果幽期。","到扉开复閉，撞鐘斋及茲。","醍醐长發性，饮食過扶衰。","把臂有多日，开懷無媿辞。","黄鸝度結構，紫鴿下罘罳。","愚意會所適，花邊行自遲。","湯休起我病，微笑索題诗。"]', '诗', 'shi', '', NULL, '大雲寺贊公房四首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c0b327-e1a0-497a-aadb-56cf74d410bc', '大雲寺贊公房四首 二', '大云寺贊公房四首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["細軟青絲履，光明白氎巾。","深藏供老宿，取用及吾身。","自顧轉無趣，交情何尚新。","道林才不世，惠遠德過人。","雨瀉暮檐竹，風吹青井芹。","天陰對圖畫，最覺潤龍鱗。"]', '["細軟青絲履，光明白氎巾。","深藏供老宿，取用及吾身。","自顧轉無趣，交情何尚新。","道林才不世，惠远德過人。","雨瀉暮檐竹，风吹青井芹。","天陰对圖畫，最覺潤龙鱗。"]', '诗', 'shi', '', NULL, '大雲寺贊公房四首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b81ee4a9-5872-46f9-ab34-9de22f3046be', '大雲寺贊公房四首 三', '大云寺贊公房四首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["燈影照無睡，心清聞妙香。","夜深殿突兀，風動金鋃鐺。","天黑閉春院，地清棲暗芳。","玉繩回斷絕，鐵鳳森翱翔。","梵放時出寺，鐘殘仍殷牀。","明朝在沃野，苦見塵沙黃。"]', '["灯影照無睡，心清闻妙香。","夜深殿突兀，风动金鋃鐺。","天黑閉春院，地清棲暗芳。","玉繩回斷絕，鐵鳳森翱翔。","梵放时出寺，鐘殘仍殷牀。","明朝在沃野，苦见塵沙黄。"]', '诗', 'shi', '', NULL, '大雲寺贊公房四首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2148248a-2145-43aa-86a4-dc76fd1618eb', '大雲寺贊公房四首 四', '大云寺贊公房四首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["童兒汲井華，慣捷缾上手。","沾灑不濡地，埽除似無帚。","明霞爛複閣，霽霧搴高牖。","側塞被徑花，飄颻委墀柳。","艱難世事迫，隱遯佳期後。","晤語契深心，那能總箝口。","奉辭還杖策，暫別終回首。","泱泱泥污人，听听國多狗。","既未免羈絆，時來憩奔走。","近公如白雪，執熱煩何有。"]', '["童兒汲井华，慣捷缾上手。","沾灑不濡地，埽除似無帚。","明霞爛複閣，霽霧搴高牖。","側塞被徑花，飄颻委墀柳。","艱难世事迫，隐遯佳期後。","晤語契深心，那能總箝口。","奉辞還杖策，暫別終回首。","泱泱泥污人，听听国多狗。","既未免羈絆，时来憩奔走。","近公如白雪，執熱煩何有。"]', '诗', 'shi', '', NULL, '大雲寺贊公房四首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e848498b-1ab8-48c7-8b3e-e98b5550b855', '蘇端薛復筵簡薛華醉歌', '蘇端薛复筵簡薛华醉歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["文章有神交有道，端復得之名譽早。","愛客滿堂盡豪翰，開筵上日思芳草。","安得健步移遠梅，亂插繁花向晴昊。","千里猶殘舊冰雪，百壺且試開懷抱。","垂老惡聞戰鼓悲，急觴爲緩憂心擣。","少年努力縱談笑，看我形容已枯槁。","坐中薛華善醉歌，歌辭自作風格老。","近來海內爲長句，汝與山東李白好。","何劉沈謝力未工，才兼鮑昭愁絕倒。","諸生頗盡新知樂，萬事終傷不自保。","氣酣日落西風來，願吹野水添金杯。"]', '["文章有神交有道，端复得之名譽早。","愛客满堂尽豪翰，开筵上日思芳草。","安得健步移远梅，亂插繁花向晴昊。","千里猶殘旧冰雪，百壺且試开懷抱。","垂老惡闻戰鼓悲，急觴爲緩憂心擣。","少年努力縱談笑，看我形容已枯槁。","坐中薛华善醉歌，歌辞自作风格老。","近来海內爲长句，汝與山东李白好。","何劉沈謝力未工，才兼鲍昭愁絕倒。","諸生頗尽新知乐，万事終傷不自保。","氣酣日落西风来，願吹野水添金杯。"]', '诗', 'shi', '', NULL, '蘇端薛復筵簡薛華醉歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6876a62d-3e30-49cf-9e87-a55e75779844', '晦日尋崔戢李封', '晦日尋崔戢李封', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝光入甕牖，尸寢驚敝裘。","起行視天宇，春氣漸和柔。","興來不暇嬾，今晨梳我頭。","出門無所待，徒步覺自由。","杖藜復恣意，免值公與侯。","晚定崔李交，會心真罕儔。","每過得酒傾，二宅可淹留。","喜結仁里歡，況因令節求。","李生園欲荒，舊竹頗修修。","引客看埽除，隨時成獻酬。","崔侯初筵色，已畏空尊愁。","未知天下士，至性有此不。","草牙既青出，蜂聲亦暖遊。","思見農器陳，何當甲兵休。","上古葛天民，不貽黃屋憂。","至今阮籍等，熟醉爲身謀。","威鳳高其翔，長鯨吞九洲。","地軸爲之翻，百川昔亂流。","當歌欲一放，淚下恐莫收。","濁醪有妙理，庶用慰沈浮。"]', '["朝光入甕牖，尸寢驚敝裘。","起行視天宇，春氣漸和柔。","兴来不暇嬾，今晨梳我头。","出门無所待，徒步覺自由。","杖藜复恣意，免值公與侯。","晚定崔李交，會心真罕儔。","每過得酒傾，二宅可淹留。","喜結仁里歡，況因令節求。","李生园欲荒，旧竹頗修修。","引客看埽除，隨时成獻酬。","崔侯初筵色，已畏空尊愁。","未知天下士，至性有此不。","草牙既青出，蜂声亦暖游。","思见農器陳，何當甲兵休。","上古葛天民，不貽黄屋憂。","至今阮籍等，熟醉爲身謀。","威鳳高其翔，长鯨吞九洲。","地軸爲之翻，百川昔亂流。","當歌欲一放，泪下恐莫收。","濁醪有妙理，庶用慰沈浮。"]', '诗', 'shi', '', NULL, '晦日尋崔戢李封 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f063d6-b3bb-4368-ae89-1e2af8fb3a0f', '雨過蘇端', '雨過蘇端', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雞鳴風雨交，久旱雲亦好。","杖藜入春泥，無食起我早。","諸家憶所歷，一飯跡便埽。","蘇侯得數過，歡喜每傾倒。","也復可憐人，呼兒具梨棗。","濁醪必在眼，盡醉攄懷抱。","紅稠屋角花，碧委牆隅草。","親賓縱談謔，喧鬧畏衰老。","況蒙霈澤垂，糧粒或自保。","妻孥隔軍壘，撥棄不擬道。"]', '["雞鳴风雨交，久旱云亦好。","杖藜入春泥，無食起我早。","諸家憶所歷，一飯跡便埽。","蘇侯得數過，歡喜每傾倒。","也复可怜人，呼兒具梨棗。","濁醪必在眼，尽醉攄懷抱。","紅稠屋角花，碧委牆隅草。","親賓縱談謔，喧鬧畏衰老。","況蒙霈澤垂，糧粒或自保。","妻孥隔軍壘，撥棄不擬道。"]', '诗', 'shi', '', NULL, '雨過蘇端 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10283f19-0d0b-41d7-99b8-8cd117878d2c', '喜晴', '喜晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["皇天久不雨，既雨晴亦佳。","出郭眺西郊，肅肅春增華。","青熒陵陂麥，窈窕桃李花。","春夏各有實，我飢豈無涯。","干戈雖橫放，慘澹鬬龍蛇。","甘澤不猶愈，且耕今未賒。","丈夫則帶甲，婦女終在家。","力難及黍稷，得種菜與麻。","千載商山芝，往者東門瓜。","其人骨已朽，此道誰疵瑕。","英賢遇轗軻，遠引蟠泥沙。","顧慙昧所適，回首白日斜。","漢陰有鹿門，滄海有靈查。","焉能學衆口，咄咄空咨嗟。"]', '["皇天久不雨，既雨晴亦佳。","出郭眺西郊，肅肅春增华。","青熒陵陂麦，窈窕桃李花。","春夏各有實，我飢豈無涯。","干戈雖橫放，慘澹鬬龙蛇。","甘澤不猶愈，且耕今未賒。","丈夫則带甲，婦女終在家。","力难及黍稷，得種菜與麻。","千載商山芝，往者东门瓜。","其人骨已朽，此道誰疵瑕。","英賢遇轗軻，远引蟠泥沙。","顧慙昧所適，回首白日斜。","漢陰有鹿门，滄海有靈查。","焉能学衆口，咄咄空咨嗟。"]', '诗', 'shi', '', NULL, '喜晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfe208d-e421-470b-805d-b2d7262176ad', '送率府程錄事還鄉', '送率府程錄事還乡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄙夫行衰謝，抱病昏妄集。","當時往還人，記一不識十。","程侯晚相遇，與語才傑立。","熏然耳目開，頗覺聰明人。","千載得鮑叔，末契有所及。","意鍾老柏青，義動修蛇蟄。","若人可數見，慰我垂白泣。","告別無淹晷，百憂復相襲。","內媿突不黔，庶羞以賙給。","素絲挈長魚，碧酒隨玉粒。","途窮見交態，世梗悲路澀。","東風吹春冰，泱莽后土濕。","念君惜羽翮，既飽更思戢。","莫作翻雲鶻，聞呼向禽急。"]', '["鄙夫行衰謝，抱病昏妄集。","當时往還人，記一不識十。","程侯晚相遇，與語才傑立。","熏然耳目开，頗覺聰明人。","千載得鲍叔，末契有所及。","意鍾老柏青，義动修蛇蟄。","若人可數见，慰我垂白泣。","告別無淹晷，百憂复相襲。","內媿突不黔，庶羞以賙給。","素絲挈长鱼，碧酒隨玉粒。","途窮见交態，世梗悲路澀。","东风吹春冰，泱莽后土濕。","念君惜羽翮，既飽更思戢。","莫作翻云鶻，闻呼向禽急。"]', '诗', 'shi', '', NULL, '送率府程錄事還鄉 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ec8fe8-3c0a-4b2e-85b7-30fe8f267fe4', '述懷一首', '述懷一首', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去年潼關破，妻子隔絕久。","今夏草木長，脫身得西走。","麻鞋見天子，衣袖露兩肘。","朝廷慜生還，親故傷老醜。","涕淚授拾遺，流離主恩厚。","柴門雖得去，未忍即開口。","寄書問三川，不知家在否。","比聞同罹禍，殺戮到雞狗。","山中漏茅屋，誰復依戶牖。","摧頹蒼松根，地冷骨未朽。","幾人全性命，盡室豈相偶。","嶔岑猛虎場，鬱結回我首。","自寄一封書，今已十月後。","反畏消息來，寸心亦何有。","漢運初中興，生平老耽酒。","沈思歡會處，恐作窮獨叟。"]', '["去年潼关破，妻子隔絕久。","今夏草木长，脫身得西走。","麻鞋见天子，衣袖露兩肘。","朝廷慜生還，親故傷老醜。","涕泪授拾遺，流離主恩厚。","柴门雖得去，未忍即开口。","寄书问三川，不知家在否。","比闻同罹禍，殺戮到雞狗。","山中漏茅屋，誰复依戶牖。","摧頹蒼松根，地冷骨未朽。","幾人全性命，尽室豈相偶。","嶔岑猛虎場，鬱結回我首。","自寄一封书，今已十月後。","反畏消息来，寸心亦何有。","漢運初中兴，生平老耽酒。","沈思歡會处，恐作窮独叟。"]', '诗', 'shi', '', NULL, '述懷一首 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26be693a-2f82-4e8b-be8f-4e14129f185d', '送長孫九侍御赴武威判官', '送长孫九侍御赴武威判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驄馬新鑿蹄，銀鞍被來好。","繡衣黃白郎，騎向交河道。","問君適萬里，取別何草草。","天子憂涼州，嚴程到須早。","去秋羣胡反，不得無電埽。","此行收遺甿，風俗方再造。","族父領元戎，名聲國中老。","奪我同官良，飄颻按城堡。","使我不能餐，令我惡懷抱。","若人才思闊，溟漲浸絕島。","尊前失詩流，塞上得國寶。","皇天悲送遠，雲雨白浩浩。","東郊尚烽火，朝野色枯槁。","西極柱亦傾，如何正穹昊。"]', '["驄马新鑿蹄，銀鞍被来好。","繡衣黄白郎，騎向交河道。","问君適万里，取別何草草。","天子憂涼州，嚴程到須早。","去秋羣胡反，不得無電埽。","此行收遺甿，风俗方再造。","族父領元戎，名声国中老。","奪我同官良，飄颻按城堡。","使我不能餐，令我惡懷抱。","若人才思闊，溟漲浸絕島。","尊前失诗流，塞上得国寶。","皇天悲送远，云雨白浩浩。","东郊尚烽火，朝野色枯槁。","西極柱亦傾，如何正穹昊。"]', '诗', 'shi', '', NULL, '送長孫九侍御赴武威判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1e7ba7-1beb-4430-a7f2-3e5d7241beec', '送樊二十三侍御赴漢中判官', '送樊二十三侍御赴漢中判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["威弧不能弦，自爾無寧歲。","川谷血橫流，豺狼沸相噬。","天子從北來，長驅振凋敝。","頓兵岐梁下，却跨沙漠裔。","二京陷未收，四極我得制。","蕭索漢水清，緬通淮湖稅。","使者紛星散，王綱尚旒綴。","南伯從事賢，君行立談際。","生知七曜曆，手畫三軍勢。","冰雪淨聰明，雷霆走精銳。","幕府輟諫官，朝廷無此例。","至尊方旰食，仗爾布嘉惠。","補闕暮徵入，柱史晨征憩。","正當艱難時，實藉長久計。","回風吹獨樹，白日照執袂。","慟哭蒼煙根，山門萬重閉。","居人莽牢落，遊子方迢遞。","裴回悲生離，局促老一世。","陶唐歌遺民，後漢更列帝。","恨無匡復姿，聊欲從此逝。"]', '["威弧不能弦，自爾無寧歲。","川谷血橫流，豺狼沸相噬。","天子從北来，长驱振凋敝。","頓兵岐梁下，却跨沙漠裔。","二京陷未收，四極我得制。","蕭索漢水清，緬通淮湖稅。","使者紛星散，王綱尚旒綴。","南伯從事賢，君行立談際。","生知七曜曆，手畫三軍勢。","冰雪淨聰明，雷霆走精銳。","幕府輟諫官，朝廷無此例。","至尊方旰食，仗爾布嘉惠。","補闕暮徵入，柱史晨征憩。","正當艱难时，實藉长久計。","回风吹独樹，白日照執袂。","慟哭蒼煙根，山门万重閉。","居人莽牢落，游子方迢遞。","裴回悲生離，局促老一世。","陶唐歌遺民，後漢更列帝。","恨無匡复姿，聊欲從此逝。"]', '诗', 'shi', '', NULL, '送樊二十三侍御赴漢中判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ae9776-2997-4e21-9318-b0e2075c7692', '送從弟亞赴安西判官', '送從弟亞赴安西判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南風作秋聲，殺氣薄炎熾。","盛夏鷹隼擊，時危異人至。","令弟草中來，蒼然請論事。","詔書引上殿，奮舌動天意。","兵法五十家，爾腹爲篋笥。","應對如轉丸，疏通略文字。","經綸皆新語，足以正神器。","宗廟尚爲灰，君臣俱下淚。","崆峒地無軸，青海天軒輊。","西極最瘡痍，連山暗烽燧。","帝曰大布衣，藉卿佐元帥。","坐看清流沙，所以子奉使。","歸當再前席，適遠非歷試。","須存武威郡，爲畫長久利。","孤峰石戴驛，快馬金纏轡。","黃羊飫不羶，蘆酒多還醉。","踴躍常人情，慘澹苦士志。","安邊敵何有，反正計始遂。","吾聞駕鼓車，不合用騏驥。","龍吟回其頭，夾輔待所致。"]', '["南风作秋声，殺氣薄炎熾。","盛夏鷹隼擊，时危異人至。","令弟草中来，蒼然請論事。","詔书引上殿，奮舌动天意。","兵法五十家，爾腹爲篋笥。","應对如轉丸，疏通略文字。","經綸皆新語，足以正神器。","宗廟尚爲灰，君臣俱下泪。","崆峒地無軸，青海天軒輊。","西極最瘡痍，連山暗烽燧。","帝曰大布衣，藉卿佐元帥。","坐看清流沙，所以子奉使。","归當再前席，適远非歷試。","須存武威郡，爲畫长久利。","孤峰石戴驛，快马金纏轡。","黄羊飫不羶，蘆酒多還醉。","踴躍常人情，慘澹苦士志。","安邊敵何有，反正計始遂。","吾闻駕鼓车，不合用騏驥。","龙吟回其头，夾輔待所致。"]', '诗', 'shi', '', NULL, '送從弟亞赴安西判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76fbf9e9-5941-4a96-a62f-fd66183dfe38', '送韋十六評事充同谷郡防禦判官', '送韋十六評事充同谷郡防禦判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔沒賊中時，潛與子同遊。","今歸行在所，王事有去留。","偪側兵馬間，主憂急良籌。","子雖軀幹小，老氣橫九州。","挺身艱難際，張目視寇讎。","朝廷壯其節，奉詔令參謀。","鑾輿駐鳳翔，同谷爲咽喉。","西扼弱水道，南鎮枹罕陬。","此邦承平日，剽劫吏所羞。","況乃胡未滅，控帶莽悠悠。","府中韋使君，道足示懷柔。","令姪才俊茂，二美又何求。","受詞太白脚，走馬仇池頭。","古色沙土裂，積陰雪雲稠。","羌父豪豬靴，羌兒青兕裘。","吹角向月窟，蒼山旌旆愁。","鳥驚出死樹，龍怒拔老湫。","古來無人境，今代橫戈矛。","傷哉文儒士，憤激馳林丘。","中原正格鬬，後會何緣由。","百年賦命定，豈料沈與浮。","且復戀良友，握手步道周。","論兵遠壑淨，亦可縱冥搜。","題詩得秀句，札翰時相投。"]', '["昔沒賊中时，潛與子同游。","今归行在所，王事有去留。","偪側兵马间，主憂急良籌。","子雖軀幹小，老氣橫九州。","挺身艱难際，張目視寇讎。","朝廷壯其節，奉詔令參謀。","鑾輿駐鳳翔，同谷爲咽喉。","西扼弱水道，南鎮枹罕陬。","此邦承平日，剽劫吏所羞。","況乃胡未滅，控带莽悠悠。","府中韋使君，道足示懷柔。","令姪才俊茂，二美又何求。","受词太白脚，走马仇池头。","古色沙土裂，積陰雪云稠。","羌父豪豬靴，羌兒青兕裘。","吹角向月窟，蒼山旌旆愁。","鸟驚出死樹，龙怒拔老湫。","古来無人境，今代橫戈矛。","傷哉文儒士，憤激驰林丘。","中原正格鬬，後會何緣由。","百年賦命定，豈料沈與浮。","且复戀良友，握手步道周。","論兵远壑淨，亦可縱冥搜。","題诗得秀句，札翰时相投。"]', '诗', 'shi', '', NULL, '送韋十六評事充同谷郡防禦判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbebf2b4-fabb-4c07-b8bc-f2efcfe377ad', '塞蘆子', '塞蘆子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五城何迢迢，迢迢隔河水。","邊兵盡東征，城內空荆杞。","思明割懷衛，秀巖西未已。","迴略大荒來，崤函蓋虛爾。","延州秦北戶，關防猶可倚。","焉得一萬人，疾驅塞蘆子。","岐有薛大夫，旁制山賊起。","近聞昆戎徒，爲退三百里。","蘆關扼兩寇，深意實在此。","誰能叫帝閽，胡行速如鬼。"]', '["五城何迢迢，迢迢隔河水。","邊兵尽东征，城內空荆杞。","思明割懷衛，秀巖西未已。","迴略大荒来，崤函蓋虛爾。","延州秦北戶，关防猶可倚。","焉得一万人，疾驱塞蘆子。","岐有薛大夫，旁制山賊起。","近闻昆戎徒，爲退三百里。","蘆关扼兩寇，深意實在此。","誰能叫帝閽，胡行速如鬼。"]', '诗', 'shi', '', NULL, '塞蘆子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b59e2948-4c90-4b33-8af6-d02b79efd5fd', '彭衙行', '彭衙行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昔避賊初，北走經險艱。","夜深彭衙道，月照白水山。","盡室久徒步，逢人多厚顏。","參差谷鳥吟，不見遊子還。","癡女飢齩我，啼畏虎狼聞。","懷中掩其口，反側聲愈嗔。","小兒強解事，故索苦李餐。","一旬半雷雨，泥濘相牽攀。","既無禦雨備，徑滑衣又寒。","有時經契闊，竟日數里間。","野果充餱糧，卑枝成屋椽。","早行石上水，暮宿天邊煙。","少留周家窪，欲出蘆子關。","故人有孫宰，高義薄曾雲。","延客已曛黑，張燈啓重門。","煖湯濯我足，剪紙招我魂。","從此出妻孥，相視涕闌干。","衆雛爛熳睡，喚起霑盤餐。","誓將與夫子，永結爲弟昆。","遂空所坐堂，安居奉我歡。","誰肯艱難際，豁達露心肝。","別來歲月周，胡羯仍搆患。","何當有翅翎，飛去墮爾前。"]', '["憶昔避賊初，北走經險艱。","夜深彭衙道，月照白水山。","尽室久徒步，逢人多厚顏。","參差谷鸟吟，不见游子還。","癡女飢齩我，啼畏虎狼闻。","懷中掩其口，反側声愈嗔。","小兒強解事，故索苦李餐。","一旬半雷雨，泥濘相牽攀。","既無禦雨備，徑滑衣又寒。","有时經契闊，竟日數里间。","野果充餱糧，卑枝成屋椽。","早行石上水，暮宿天邊煙。","少留周家窪，欲出蘆子关。","故人有孫宰，高義薄曾云。","延客已曛黑，張灯啓重门。","煖湯濯我足，剪紙招我魂。","從此出妻孥，相視涕闌干。","衆雛爛熳睡，喚起霑盤餐。","誓將與夫子，永結爲弟昆。","遂空所坐堂，安居奉我歡。","誰肯艱难際，豁達露心肝。","別来歲月周，胡羯仍搆患。","何當有翅翎，飞去墮爾前。"]', '诗', 'shi', '', NULL, '彭衙行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a335f6c4-e9df-47d5-879d-9ebd3c1baf5c', '北征', '北征', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["皇帝二載秋，閏八月初吉。","杜子將北征，蒼茫問家室。","維時遭艱虞，朝野少暇日。","顧慙恩私被，詔許歸蓬蓽。","拜辭詣闕下，怵惕久未出。","雖乏諫諍姿，恐君有遺失。","君誠中興主，經緯固密勿。","東胡反未已，臣甫憤所切。","揮涕戀行在，道途猶恍惚。","乾坤含瘡痍，憂虞何時畢。","靡靡踰阡陌，人煙眇蕭瑟。","所遇多被傷，呻吟更流血。","回首鳳翔縣，旌旗晚明滅。","前登寒山重，屢得飲馬窟。","邠郊入地底，涇水中蕩潏。","猛虎立我前，蒼崖吼時裂。","菊垂今秋花，石戴古車轍。","青雲動高興，幽事亦可悅。","山果多瑣細，羅生雜橡栗。","或紅如丹砂，或黑如點漆。","雨露之所濡，甘苦齊結實。","緬思桃源內，益歎身世拙。","坡陀望鄜畤，巖谷互出沒。","我行已水濱，我僕猶木末。","鴟鳥鳴黃桑，野鼠拱亂穴。","夜深經戰場，寒月照白骨。","潼關百萬師，往者散何卒。","遂令半秦民，殘害爲異物。","況我墮胡塵，及歸盡華髮。","經年至茅屋，妻子衣百結。","慟哭松聲回，悲泉共幽咽。","平生所嬌兒，顏色白勝雪。","見耶背面啼，垢膩脚不韤。","牀前兩小女，補綻才過膝。","海圖坼波濤，舊繡移曲折。","天吳及紫鳳，顛倒在裋褐。","老夫情懷惡，嘔泄臥數日。","那無囊中帛，救汝寒凜慄。","粉黛亦解苞，衾裯稍羅列。","瘦妻面復光，癡女頭自櫛。","學母無不爲，曉妝隨手抹。","移時施朱鉛，狼藉畫眉闊。","生還對童穉，似欲忘飢渴。","問事競挽鬚，誰能即嗔喝。","飜思在賊愁，甘受雜亂聒。","新歸且慰意，生理焉能說。","至尊尚蒙塵，幾日休練卒。","仰觀天色改，坐覺祅氣豁。","陰風西北來，慘澹隨回鶻。","其王願助順，其俗善馳突。","送兵五千人，驅馬一萬匹。","此輩少爲貴，四方服勇決。","所用皆鷹騰，破敵過箭疾。","聖心頗虛佇，時議氣欲奪。","伊洛指掌收，西京不足拔。","官軍請深入，蓄銳何俱發。","此舉開青徐，旋瞻略恆碣。","昊天積霜露，正氣有肅殺。","禍轉亡胡歲，勢成擒胡月。","胡命其能久，皇綱未宜絕。","憶昨狼狽初，事與古先別。","姦臣竟葅醢，同惡隨蕩析。","不聞夏殷衰，中自誅褒妲。","周漢獲再興，宣光果明哲。","桓桓陳將軍，仗鉞奮忠烈。","微爾人盡非，于今國猶活。","淒涼大同殿，寂寞白獸闥。","都人望翠華，佳氣向金闕。","園陵固有神，埽灑數不缺。","煌煌太宗業，樹立甚宏達。"]', '["皇帝二載秋，閏八月初吉。","杜子將北征，蒼茫问家室。","維时遭艱虞，朝野少暇日。","顧慙恩私被，詔許归蓬蓽。","拜辞詣闕下，怵惕久未出。","雖乏諫諍姿，恐君有遺失。","君誠中兴主，經緯固密勿。","东胡反未已，臣甫憤所切。","揮涕戀行在，道途猶恍惚。","乾坤含瘡痍，憂虞何时畢。","靡靡踰阡陌，人煙眇蕭瑟。","所遇多被傷，呻吟更流血。","回首鳳翔縣，旌旗晚明滅。","前登寒山重，屢得饮马窟。","邠郊入地底，涇水中蕩潏。","猛虎立我前，蒼崖吼时裂。","菊垂今秋花，石戴古车轍。","青云动高兴，幽事亦可悅。","山果多瑣細，羅生杂橡栗。","或紅如丹砂，或黑如点漆。","雨露之所濡，甘苦齊結實。","緬思桃源內，益歎身世拙。","坡陀望鄜畤，巖谷互出沒。","我行已水濱，我僕猶木末。","鴟鸟鳴黄桑，野鼠拱亂穴。","夜深經戰場，寒月照白骨。","潼关百万師，往者散何卒。","遂令半秦民，殘害爲異物。","況我墮胡塵，及归尽华髮。","經年至茅屋，妻子衣百結。","慟哭松声回，悲泉共幽咽。","平生所嬌兒，顏色白勝雪。","见耶背面啼，垢膩脚不韤。","牀前兩小女，補綻才過膝。","海圖坼波濤，旧繡移曲折。","天吳及紫鳳，顛倒在裋褐。","老夫情懷惡，嘔泄臥數日。","那無囊中帛，救汝寒凜慄。","粉黛亦解苞，衾裯稍羅列。","瘦妻面复光，癡女头自櫛。","学母無不爲，晓妝隨手抹。","移时施朱鉛，狼藉畫眉闊。","生還对童穉，似欲忘飢渴。","问事競挽鬚，誰能即嗔喝。","飜思在賊愁，甘受杂亂聒。","新归且慰意，生理焉能说。","至尊尚蒙塵，幾日休練卒。","仰观天色改，坐覺祅氣豁。","陰风西北来，慘澹隨回鶻。","其王願助順，其俗善驰突。","送兵五千人，驱马一万匹。","此輩少爲貴，四方服勇決。","所用皆鷹腾，破敵過箭疾。","聖心頗虛佇，时議氣欲奪。","伊洛指掌收，西京不足拔。","官軍請深入，蓄銳何俱發。","此舉开青徐，旋瞻略恆碣。","昊天積霜露，正氣有肅殺。","禍轉亡胡歲，勢成擒胡月。","胡命其能久，皇綱未宜絕。","憶昨狼狽初，事與古先別。","姦臣竟葅醢，同惡隨蕩析。","不闻夏殷衰，中自誅褒妲。","周漢獲再兴，宣光果明哲。","桓桓陳將軍，仗鉞奮忠烈。","微爾人尽非，于今国猶活。","淒涼大同殿，寂寞白獸闥。","都人望翠华，佳氣向金闕。","园陵固有神，埽灑數不缺。","煌煌太宗業，樹立甚宏達。"]', '诗', 'shi', '', NULL, '北征 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6b6ef6-add3-4c51-9886-358b6795fdb7', '得舍弟消息', '得舍弟消息', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風吹紫荆樹，色與春庭暮。","花落辭故枝，風回返無處。","骨肉恩書重，漂泊難相遇。","猶有淚成河，經天復東注。"]', '["风吹紫荆樹，色與春庭暮。","花落辞故枝，风回返無处。","骨肉恩书重，漂泊难相遇。","猶有泪成河，經天复东注。"]', '诗', 'shi', '', NULL, '得舍弟消息 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800f5d12-980c-463a-acbd-4b6d675ac93d', '徒步歸行', '徒步归行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["明公壯年值時危，經濟實藉英雄姿。","國之社稷今若是，武定禍亂非公誰。","鳳翔千官且飽飯，衣馬不復能輕肥。","青袍朝士最困者，白頭拾遺徒步歸。","人生交契無老少，論交何必先同調。","妻子山中哭向天，須公櫪上追風驃。"]', '["明公壯年值时危，經濟實藉英雄姿。","国之社稷今若是，武定禍亂非公誰。","鳳翔千官且飽飯，衣马不复能轻肥。","青袍朝士最困者，白头拾遺徒步归。","人生交契無老少，論交何必先同調。","妻子山中哭向天，須公櫪上追风驃。"]', '诗', 'shi', '', NULL, '徒步歸行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb457f4a-a49c-46cc-becf-d4419d617b79', '玉華宮', '玉华宮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["溪回松風長，蒼鼠竄古瓦。","不知何王殿，遺構絕壁下。","陰房鬼火青，壞道哀湍瀉。","萬籟真笙竽，秋色正蕭灑。","美人爲黃土，況乃粉黛假。","當時侍金輿，故物獨石馬。","憂來藉草坐，浩歌淚盈把。","冉冉征途間，誰是長年者。"]', '["溪回松风长，蒼鼠竄古瓦。","不知何王殿，遺構絕壁下。","陰房鬼火青，壞道哀湍瀉。","万籟真笙竽，秋色正蕭灑。","美人爲黄土，況乃粉黛假。","當时侍金輿，故物独石马。","憂来藉草坐，浩歌泪盈把。","冉冉征途间，誰是长年者。"]', '诗', 'shi', '', NULL, '玉華宮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35de5fa-807c-4891-8749-b2c83757c89a', '九成宮', '九成宮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蒼山入百里，崖斷如杵臼。","曾宮憑風回，岌嶪土囊口。","立神扶棟梁，鑿翠開戶牖。","其陽產靈芝，其陰宿牛斗。","紛披長松倒，揭𡿗怪石走。","哀猨啼一聲，客淚迸林藪。","荒哉隋家帝，製此今頹朽。","向使國不亡，焉爲巨唐有。","雖無新增修，尚置官居守。","巡非瑤水遠，迹是雕牆後。","我行屬時危，仰望嗟歎久。","天王守太白，駐馬更搔首。"]', '["蒼山入百里，崖斷如杵臼。","曾宮憑风回，岌嶪土囊口。","立神扶棟梁，鑿翠开戶牖。","其陽產靈芝，其陰宿牛斗。","紛披长松倒，揭𡿗怪石走。","哀猨啼一声，客泪迸林藪。","荒哉隋家帝，製此今頹朽。","向使国不亡，焉爲巨唐有。","雖無新增修，尚置官居守。","巡非瑤水远，迹是雕牆後。","我行屬时危，仰望嗟歎久。","天王守太白，駐马更搔首。"]', '诗', 'shi', '', NULL, '九成宮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('872fd5bd-c6d8-4aef-bc03-85ac1550b561', '羌村 一', '羌村 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["崢嶸赤雲西，日脚下平地。","柴門鳥雀噪，歸客千里至。","妻孥怪我在，驚定還拭淚。","世亂遭飄蕩，生還偶然遂。","鄰人滿牆頭，感歎亦歔欷。","夜闌更秉燭，相對如夢寐。"]', '["崢嶸赤云西，日脚下平地。","柴门鸟雀噪，归客千里至。","妻孥怪我在，驚定還拭泪。","世亂遭飄蕩，生還偶然遂。","鄰人满牆头，感歎亦歔欷。","夜闌更秉燭，相对如梦寐。"]', '诗', 'shi', '', NULL, '羌村 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5d3f4a-dbf2-4831-b658-e75bd4a0ca38', '羌村 二', '羌村 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晚歲迫偷生，還家少歡趣。","嬌兒不離膝，畏我復却去。","憶昔好追涼，故繞池邊樹。","蕭蕭北風勁，撫事煎百慮。","賴知禾黍收，已覺糟牀注。","如今足斟酌，且用慰遲暮。"]', '["晚歲迫偷生，還家少歡趣。","嬌兒不離膝，畏我复却去。","憶昔好追涼，故繞池邊樹。","蕭蕭北风勁，撫事煎百慮。","賴知禾黍收，已覺糟牀注。","如今足斟酌，且用慰遲暮。"]', '诗', 'shi', '', NULL, '羌村 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26cbab92-a321-44e6-842b-13acc9749fc0', '羌村 三', '羌村 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣雞正亂叫，客至雞鬬爭。","驅雞上樹木，始聞叩柴荆。","父老四五人，問我久遠行。","手中各有攜，傾榼濁復清。","苦辭酒味薄，黍地無人耕。","兵革既未息，兒童盡東征。","請爲父老歌，艱難塊深情。","歌罷仰天歎，四座淚縱橫。"]', '["羣雞正亂叫，客至雞鬬爭。","驱雞上樹木，始闻叩柴荆。","父老四五人，问我久远行。","手中各有携，傾榼濁复清。","苦辞酒味薄，黍地無人耕。","兵革既未息，兒童尽东征。","請爲父老歌，艱难塊深情。","歌罷仰天歎，四座泪縱橫。"]', '诗', 'shi', '', NULL, '羌村 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71fc0b1-e5d2-42c3-b084-8076185988fc', '偪仄行贈畢曜', '偪仄行贈畢曜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["偪仄何偪仄，我居巷南子巷北。","可恨鄰里間，十日不一見顏色。","自從官馬送還宮，行路難行澀如棘。","我貧無乘非無足，昔者相過今不得。","實不是愛微軀，又非關足無力。","徒步翻愁官長怒，此心炯炯君應識。","曉來急雨春風顛，睡美不聞鐘鼓傳。","東家蹇驢許借我，泥滑不敢騎朝天。","已令請急會通籍，男兒信命絕可憐。","焉能終日心拳拳，憶君誦詩神凜然。","辛夷始花亦已落，況我與子非壯年。","街頭酒價常苦貴，方外酒徒稀醉眠。","速宜相就飲一斗，恰有三百青銅錢。"]', '["偪仄何偪仄，我居巷南子巷北。","可恨鄰里间，十日不一见顏色。","自從官马送還宮，行路难行澀如棘。","我貧無乘非無足，昔者相過今不得。","實不是愛微軀，又非关足無力。","徒步翻愁官长怒，此心炯炯君應識。","晓来急雨春风顛，睡美不闻鐘鼓傳。","东家蹇驢許借我，泥滑不敢騎朝天。","已令請急會通籍，男兒信命絕可怜。","焉能終日心拳拳，憶君誦诗神凜然。","辛夷始花亦已落，況我與子非壯年。","街头酒價常苦貴，方外酒徒稀醉眠。","速宜相就饮一斗，恰有三百青銅錢。"]', '诗', 'shi', '', NULL, '偪仄行贈畢曜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6f3cdc-531b-4a51-a6fa-fd047e45da28', '送李校書二十六韻', '送李校书二十六韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["代北有豪鷹，生子毛盡赤。","渥洼騏驥兒，尤異是龍脊。","李舟名父子，清峻流輩伯。","人間好少年，不必須白皙。","十五富文史，十八足賓客。","十九授校書，二十聲輝赫。","衆中每一見，使我潛動魄。","自恐二男兒，辛勤養無益。","乾元元年春，萬姓始安宅。","舟也衣綵衣，告我欲遠適。","倚門固有望，斂衽就行役。","南登吟白華，已見楚山碧。","藹藹咸陽都，冠蓋日雲積。","何時太夫人，堂上會親戚。","汝翁草明光，天子正前席。","歸期豈爛漫，別意終感激。","顧我蓬屋姿，謬通金閨籍。","小來習性嬾，晚節慵轉劇。","每愁悔吝作，如覺天地窄。","羨君齒髮新，行己能夕惕。","臨岐意頗切，對酒不能喫。","回身視綠野，慘澹如荒澤。","老雁春忍飢，哀號待枯麥。","時哉高飛燕，絢練新羽翮。","長雲濕褒斜，漢水饒巨石。","無令軒車遲，衰疾悲夙昔。"]', '["代北有豪鷹，生子毛尽赤。","渥洼騏驥兒，尤異是龙脊。","李舟名父子，清峻流輩伯。","人间好少年，不必須白皙。","十五富文史，十八足賓客。","十九授校书，二十声輝赫。","衆中每一见，使我潛动魄。","自恐二男兒，辛勤養無益。","乾元元年春，万姓始安宅。","舟也衣綵衣，告我欲远適。","倚门固有望，斂衽就行役。","南登吟白华，已见楚山碧。","藹藹咸陽都，冠蓋日云積。","何时太夫人，堂上會親戚。","汝翁草明光，天子正前席。","归期豈爛漫，別意終感激。","顧我蓬屋姿，謬通金閨籍。","小来習性嬾，晚節慵轉劇。","每愁悔吝作，如覺天地窄。","羨君齒髮新，行己能夕惕。","臨岐意頗切，对酒不能喫。","回身視綠野，慘澹如荒澤。","老雁春忍飢，哀號待枯麦。","时哉高飞燕，絢練新羽翮。","长云濕褒斜，漢水饒巨石。","無令軒车遲，衰疾悲夙昔。"]', '诗', 'shi', '', NULL, '送李校書二十六韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a0266d-313c-4911-b629-2418556d1b03', '洗兵馬', '洗兵马', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中興諸將收山東，捷書日報清晝同。","河廣傳聞一葦過，胡危命在破竹中。","祗殘鄴城不日得，獨任朔方無限功。","京師皆騎汗血馬，回紇餵肉葡萄宮。","已喜皇威清海岱，常思仙仗過崆峒。","三年笛裏關山月，萬國兵前草木風。","成王功大心轉小，郭相謀深古來少。","司徒清鑒懸明鏡，尚書氣與秋天杳。","二三豪俊爲時出，整頓乾坤濟時了。","東走無復憶鱸魚，南飛覺有安巢鳥。","青春復隨冠冕入，紫禁正耐煙花繞。","鶴禁通霄鳳輦備，雞鳴問寢龍樓曉。","攀龍附鳳勢莫當，天下盡化爲侯王。","汝等豈知蒙帝力，時來不得誇身強。","關中既留蕭丞相，幕下復用張子房。","張公一生江海客，身長九尺鬚眉蒼。","徵起適遇風雲會，扶顛始知籌策良。","青袍白馬更何有，後漢今周喜再昌。","寸地尺天皆入貢，奇祥異瑞爭來送。","不知何國致白環，復道諸山得銀甕。","隱士休歌紫芝曲，詞人解撰河清頌。","田家望望惜雨乾，布穀處處催春種。","淇上健兒歸莫嬾，城南思婦愁多夢。","安得壯士挽天河，淨洗甲兵長不用。"]', '["中兴諸將收山东，捷书日報清晝同。","河廣傳闻一葦過，胡危命在破竹中。","祗殘鄴城不日得，独任朔方無限功。","京師皆騎汗血马，回紇餵肉葡萄宮。","已喜皇威清海岱，常思仙仗過崆峒。","三年笛裏关山月，万国兵前草木风。","成王功大心轉小，郭相謀深古来少。","司徒清鑒懸明镜，尚书氣與秋天杳。","二三豪俊爲时出，整頓乾坤濟时了。","东走無复憶鱸鱼，南飞覺有安巢鸟。","青春复隨冠冕入，紫禁正耐煙花繞。","鹤禁通霄鳳輦備，雞鳴问寢龙楼晓。","攀龙附鳳勢莫當，天下尽化爲侯王。","汝等豈知蒙帝力，时来不得誇身強。","关中既留蕭丞相，幕下复用張子房。","張公一生江海客，身长九尺鬚眉蒼。","徵起適遇风云會，扶顛始知籌策良。","青袍白马更何有，後漢今周喜再昌。","寸地尺天皆入貢，奇祥異瑞爭来送。","不知何国致白环，复道諸山得銀甕。","隐士休歌紫芝曲，词人解撰河清頌。","田家望望惜雨乾，布穀处处催春種。","淇上健兒归莫嬾，城南思婦愁多梦。","安得壯士挽天河，淨洗甲兵长不用。"]', '诗', 'shi', '', NULL, '洗兵馬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1877173b-b4bb-467b-93da-a390559efe41', '留花門', '留花门', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北門天驕子，飽肉氣勇決。","高秋馬肥健，挾矢射漢月。","自古以爲患，詩人厭薄伐。","修德使其來，羈縻固不絕。","胡爲傾國至，出入暗金闕。","中原有驅除，隱忍用此物。","公主歌黃鵠，君王指白日。","連雲屯左輔，百里見積雪。","長戟鳥休飛，哀笳曙幽咽。","田家最恐懼，麥倒桑枝折。","沙苑臨清渭，泉香草豐潔。","渡河不用船，千騎常撇烈。","胡塵踰太行，雜種抵京室。","花門既須留，原野轉蕭瑟。"]', '["北门天驕子，飽肉氣勇決。","高秋马肥健，挾矢射漢月。","自古以爲患，诗人厭薄伐。","修德使其来，羈縻固不絕。","胡爲傾国至，出入暗金闕。","中原有驱除，隐忍用此物。","公主歌黄鵠，君王指白日。","連云屯左輔，百里见積雪。","长戟鸟休飞，哀笳曙幽咽。","田家最恐懼，麦倒桑枝折。","沙苑臨清渭，泉香草豐潔。","渡河不用船，千騎常撇烈。","胡塵踰太行，杂種抵京室。","花门既須留，原野轉蕭瑟。"]', '诗', 'shi', '', NULL, '留花門 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d1860f-cd55-488c-9c4b-3d19d5b8d3ef', '病後遇王倚飲贈歌', '病後遇王倚饮贈歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["麟角鳳觜世莫識，煎膠續弦奇自見。","尚看王生抱此懷，在于甫也何由羨。","且遇王生慰疇昔，素知賤子甘貧賤。","酷見凍餒不足恥，多病沈年苦無健。","王生怪我顏色惡，荅云伏枕艱難徧。","瘧癘三秋孰可忍，寒熱百日相交戰。","頭白眼暗坐有胝，肉黃皮皺命如綫。","惟生哀我未平復，爲我力致美殽膳。","遣人向市賒香稉，喚婦出房親自饌。","長安冬葅酸且綠，金城土酥靜如練。","兼求富豪且割鮮，密沽斗酒諧終宴。","故人情義晚誰似，令我手腳輕欲漩。","老馬爲駒信不虛，當時得意況深眷。","但使殘年飽喫飯，只願無事常相見。"]', '["麟角鳳觜世莫識，煎膠續弦奇自见。","尚看王生抱此懷，在于甫也何由羨。","且遇王生慰疇昔，素知賤子甘貧賤。","酷见凍餒不足恥，多病沈年苦無健。","王生怪我顏色惡，荅云伏枕艱难徧。","瘧癘三秋孰可忍，寒熱百日相交戰。","头白眼暗坐有胝，肉黄皮皺命如綫。","惟生哀我未平复，爲我力致美殽膳。","遣人向市賒香稉，喚婦出房親自饌。","长安冬葅酸且綠，金城土酥静如練。","兼求富豪且割鲜，密沽斗酒諧終宴。","故人情義晚誰似，令我手腳轻欲漩。","老马爲駒信不虛，當时得意況深眷。","但使殘年飽喫飯，只願無事常相见。"]', '诗', 'shi', '', NULL, '病後遇王倚飲贈歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88abad3a-4ba9-461a-a592-34eb50aa80ef', '湖城東遇孟雲卿復歸劉顥宅宿宴飲散因爲醉歌', '湖城东遇孟云卿复归劉顥宅宿宴饮散因爲醉歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["疾風吹塵暗河縣，行子隔手不相見。","湖城城南一開眼，駐馬偶識雲卿面。","向非劉顥爲地主，嬾回鞭轡成高宴。","劉侯歎我攜客來，置酒張燈促華饌。","且將款曲終今夕，休語艱難尚酣戰。","照室紅爐促曙光，縈窗素月垂文練。","天開地裂長安陌，寒盡春生洛陽殿。","豈知驅車復同軌，可惜刻漏隨更箭。","人生會合不可常，庭樹雞鳴淚如綫。"]', '["疾风吹塵暗河縣，行子隔手不相见。","湖城城南一开眼，駐马偶識云卿面。","向非劉顥爲地主，嬾回鞭轡成高宴。","劉侯歎我携客来，置酒張灯促华饌。","且將款曲終今夕，休語艱难尚酣戰。","照室紅爐促曙光，縈窗素月垂文練。","天开地裂长安陌，寒尽春生洛陽殿。","豈知驱车复同軌，可惜刻漏隨更箭。","人生會合不可常，庭樹雞鳴泪如綫。"]', '诗', 'shi', '', NULL, '湖城東遇孟雲卿復歸劉顥宅宿宴飲散因爲醉歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c166938b-f267-49e1-8a9b-a76852e97540', '閿鄉姜七少府設膾戲贈長歌', '閿乡姜七少府設膾戲贈长歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["姜侯設膾當嚴冬，昨日今日皆天風。","河凍未漁不易得，鑿冰恐侵河伯宮。","饔人受魚鮫人手，洗魚磨刀魚眼紅。","無聲細下飛碎雪，有骨已剁觜春蔥。","偏勸腹腴媿年少，軟炊香飯緣老翁。","落碪何曾白紙濕，放箸未覺金盤空。","新歡便飽姜侯德，清觴異味情屢極。","東歸貪路自覺難，欲別上馬身無力。","可憐爲人好心事，於我見子真顏色。","不恨我衰子貴時，悵望且爲今相憶。"]', '["姜侯設膾當嚴冬，昨日今日皆天风。","河凍未漁不易得，鑿冰恐侵河伯宮。","饔人受鱼鮫人手，洗鱼磨刀鱼眼紅。","無声細下飞碎雪，有骨已剁觜春蔥。","偏勸腹腴媿年少，軟炊香飯緣老翁。","落碪何曾白紙濕，放箸未覺金盤空。","新歡便飽姜侯德，清觴異味情屢極。","东归貪路自覺难，欲別上马身無力。","可怜爲人好心事，於我见子真顏色。","不恨我衰子貴时，悵望且爲今相憶。"]', '诗', 'shi', '', NULL, '閿鄉姜七少府設膾戲贈長歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f6b5485-6ead-48e3-b211-46aaa1be1238', '戲贈閿鄉秦少公短歌', '戲贈閿乡秦少公短歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去年行宮當太白，朝回君是同舍客。","同心不減骨肉親，每語見許文章伯。","今日時清兩京道，相逢苦覺人情好。","昨夜邀歡樂更無，多才依舊能潦倒。"]', '["去年行宮當太白，朝回君是同舍客。","同心不減骨肉親，每語见許文章伯。","今日时清兩京道，相逢苦覺人情好。","昨夜邀歡乐更無，多才依旧能潦倒。"]', '诗', 'shi', '', NULL, '戲贈閿鄉秦少公短歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48568d08-d789-4eca-b9a8-5dcf09d6a516', '李鄠縣丈人胡馬行', '李鄠縣丈人胡马行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丈人駿馬名胡騮，前年避胡過金牛。","回鞭却走見天子，朝飲漢水暮靈州。","自矜胡騮奇絕代，乘出千人萬人愛。","一聞說盡急難材，轉益愁向駑駘輩。","頭上銳耳批秋竹，脚下高蹄削寒玉。","始知神龍別有種，不比俗馬空多肉。","洛陽大道時再清，累日喜得俱東行。","鳳臆龍鬐未易識，側身注目長風生。"]', '["丈人駿马名胡騮，前年避胡過金牛。","回鞭却走见天子，朝饮漢水暮靈州。","自矜胡騮奇絕代，乘出千人万人愛。","一闻说尽急难材，轉益愁向駑駘輩。","头上銳耳批秋竹，脚下高蹄削寒玉。","始知神龙別有種，不比俗马空多肉。","洛陽大道时再清，累日喜得俱东行。","鳳臆龙鬐未易識，側身注目长风生。"]', '诗', 'shi', '', NULL, '李鄠縣丈人胡馬行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812e7edc-f0c2-4da9-be16-a14042619ce7', '義鶻', '義鶻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陰崖有蒼鷹，養子黑柏顛。","白蛇登其巢，吞噬恣朝餐。","雄飛遠求食，雌者鳴辛酸。","力強不可制，黃口無半存。","其父從西歸，飜身入長煙。","斯須領健鶻，痛憤寄所宣。","斗上捩孤影，噭哮來九天。","修鱗脫遠枝，巨顙坼老拳。","高空得蹭蹬，短草辭蜿蜒。","折尾能一掉，飽腸皆已穿。","生雖滅衆雛，死亦垂千年。","物情有報復，快意貴目前。","茲實鷙鳥最，急難心炯然。","功成失所往，用舍何其賢。","近經潏水湄，此事樵夫傳。","飄蕭覺素髮，凜欲衝儒冠。","人生許與分，只在顧盼間。","聊爲義鶻行，用激壯士肝。"]', '["陰崖有蒼鷹，養子黑柏顛。","白蛇登其巢，吞噬恣朝餐。","雄飞远求食，雌者鳴辛酸。","力強不可制，黄口無半存。","其父從西归，飜身入长煙。","斯須領健鶻，痛憤寄所宣。","斗上捩孤影，噭哮来九天。","修鱗脫远枝，巨顙坼老拳。","高空得蹭蹬，短草辞蜿蜒。","折尾能一掉，飽腸皆已穿。","生雖滅衆雛，死亦垂千年。","物情有報复，快意貴目前。","茲實鷙鸟最，急难心炯然。","功成失所往，用舍何其賢。","近經潏水湄，此事樵夫傳。","飄蕭覺素髮，凜欲衝儒冠。","人生許與分，只在顧盼间。","聊爲義鶻行，用激壯士肝。"]', '诗', 'shi', '', NULL, '義鶻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2fb502-1e53-4ff9-a1b8-d9f1273148a7', '畫鶻行', '畫鶻行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高堂見生鶻，颯爽動秋骨。","初驚無拘攣，何得立突兀。","乃知畫師妙，功刮造化窟。","寫作神駿姿，充君眼中物。","鳥鵲滿樛枝，軒然恐其出。","側腦看青霄，寧爲衆禽沒。","長翮如刀劒，人寰可超越。","乾坤空崢嶸，粉墨且蕭瑟。","緬思雲沙際，自有煙霧質。","吾今意何傷，顧步獨紆鬱。"]', '["高堂见生鶻，颯爽动秋骨。","初驚無拘攣，何得立突兀。","乃知畫師妙，功刮造化窟。","寫作神駿姿，充君眼中物。","鸟鵲满樛枝，軒然恐其出。","側腦看青霄，寧爲衆禽沒。","长翮如刀劒，人寰可超越。","乾坤空崢嶸，粉墨且蕭瑟。","緬思云沙際，自有煙霧質。","吾今意何傷，顧步独紆鬱。"]', '诗', 'shi', '', NULL, '畫鶻行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbadda6-7e25-4df6-bde4-cff74e45d080', '瘦馬行', '瘦马行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東郊瘦馬使我傷，骨骼硉兀如堵牆。","絆之欲動轉敧側，此豈有意仍騰驤。","細看六印帶官字，衆道三軍遺路旁。","皮乾剝落雜泥滓，毛暗蕭條連雪霜。","去歲奔波逐餘寇，驊騮不慣不得將。","士卒多騎內厩馬，惆悵恐是病乘黃。","當時歷塊誤一蹶，委棄非汝能周防。","見人慘澹若哀訴，失主錯莫無晶光。","天寒遠放雁爲伴，日暮不收烏啄瘡。","誰家且養願終惠，更試明年春草長。"]', '["东郊瘦马使我傷，骨骼硉兀如堵牆。","絆之欲动轉敧側，此豈有意仍腾驤。","細看六印带官字，衆道三軍遺路旁。","皮乾剝落杂泥滓，毛暗蕭條連雪霜。","去歲奔波逐餘寇，驊騮不慣不得將。","士卒多騎內厩马，惆悵恐是病乘黄。","當时歷塊誤一蹶，委棄非汝能周防。","见人慘澹若哀訴，失主錯莫無晶光。","天寒远放雁爲伴，日暮不收烏啄瘡。","誰家且養願終惠，更試明年春草长。"]', '诗', 'shi', '', NULL, '瘦馬行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01751db4-8ba6-43f9-a89f-4d96826f5ee1', '新安吏', '新安吏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客行新安道，喧呼聞點兵。","借問新安吏，縣小更無丁。","府帖昨夜下，次選中男行。","中男絕短小，何以守王城。","肥男有母送，瘦男獨伶俜。","白水暮東流，青山猶哭聲。","莫自使眼枯，收汝淚縱橫。","眼枯即見骨，天地終無情。","我軍取相州，日夕望其平。","豈意賊難料，歸軍星散營。","就糧近故壘，練卒依舊京。","掘壕不到水，牧馬役亦輕。","況乃王師順，撫養甚分明。","送行勿泣血，僕射如父兄。"]', '["客行新安道，喧呼闻点兵。","借问新安吏，縣小更無丁。","府帖昨夜下，次選中男行。","中男絕短小，何以守王城。","肥男有母送，瘦男独伶俜。","白水暮东流，青山猶哭声。","莫自使眼枯，收汝泪縱橫。","眼枯即见骨，天地終無情。","我軍取相州，日夕望其平。","豈意賊难料，归軍星散營。","就糧近故壘，練卒依旧京。","掘壕不到水，牧马役亦轻。","況乃王師順，撫養甚分明。","送行勿泣血，僕射如父兄。"]', '诗', 'shi', '', NULL, '新安吏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19c2a99b-507a-415a-8e66-1477861f5d71', '潼關吏', '潼关吏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["士卒何草草，築城潼關道。","大城鐵不如，小城萬丈餘。","借問潼關吏，修關還備胡。","要我下馬行，爲我指山隅。","連雲列戰格，飛鳥不能踰。","胡來但自守，豈復憂西都。","丈人視要處，窄狹容單車。","艱難奮長戟，萬古用一夫。","哀哉桃林戰，百萬化爲魚。","請囑防關將，慎勿學哥舒。"]', '["士卒何草草，築城潼关道。","大城鐵不如，小城万丈餘。","借问潼关吏，修关還備胡。","要我下马行，爲我指山隅。","連云列戰格，飞鸟不能踰。","胡来但自守，豈复憂西都。","丈人視要处，窄狹容單车。","艱难奮长戟，万古用一夫。","哀哉桃林戰，百万化爲鱼。","請囑防关將，慎勿学哥舒。"]', '诗', 'shi', '', NULL, '潼關吏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef36b613-c482-4e50-81fa-68436392346e', '石壕吏', '石壕吏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暮投石壕邨，有吏夜捉人。","老翁踰牆走，老婦出門看。","吏呼一何怒，婦啼一何苦。","聽婦前致詞，三男鄴城戍。","一男附書致，二男新戰死。","存者且偷生，死者長已矣。","室中更無人，惟有乳下孫。","有孫母未去，出入無完帬。","老嫗力雖衰，請從吏夜歸。","急應河陽役，猶得備晨炊。","夜久語聲絕，如聞泣幽咽。","天明登前途，獨與老翁別。"]', '["暮投石壕邨，有吏夜捉人。","老翁踰牆走，老婦出门看。","吏呼一何怒，婦啼一何苦。","听婦前致词，三男鄴城戍。","一男附书致，二男新戰死。","存者且偷生，死者长已矣。","室中更無人，惟有乳下孫。","有孫母未去，出入無完帬。","老嫗力雖衰，請從吏夜归。","急應河陽役，猶得備晨炊。","夜久語声絕，如闻泣幽咽。","天明登前途，独與老翁別。"]', '诗', 'shi', '', NULL, '石壕吏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895139ab-9cc7-4fb5-b43a-89416b18a4dc', '新婚別', '新婚別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兔絲附蓬麻，引蔓故不長。","嫁女與征夫，不如棄路旁。","結髮爲妻子，席不煖君牀。","暮婚晨告別，無乃太怱忙。","君行雖不遠，守邊赴河陽。","妾身未分明，何以拜姑嫜。","父母養我時，日夜令我藏。","生女有所歸，雞狗亦得將。","君今往死地，沈痛迫中腸。","誓欲隨君去，形勢反蒼黃。","勿爲新婚念，努力事戎行。","婦人在軍中，兵氣恐不揚。","自嗟貧家女，久致羅襦裳。","羅襦不復施，對君洗紅妝。","仰視百鳥飛，大小必雙翔。","人事多錯迕，與君永相望。"]', '["兔絲附蓬麻，引蔓故不长。","嫁女與征夫，不如棄路旁。","結髮爲妻子，席不煖君牀。","暮婚晨告別，無乃太怱忙。","君行雖不远，守邊赴河陽。","妾身未分明，何以拜姑嫜。","父母養我时，日夜令我藏。","生女有所归，雞狗亦得將。","君今往死地，沈痛迫中腸。","誓欲隨君去，形勢反蒼黄。","勿爲新婚念，努力事戎行。","婦人在軍中，兵氣恐不揚。","自嗟貧家女，久致羅襦裳。","羅襦不复施，对君洗紅妝。","仰視百鸟飞，大小必雙翔。","人事多錯迕，與君永相望。"]', '诗', 'shi', '', NULL, '新婚別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0435860-95e5-44e7-bf6c-9eeee324ce96', '垂老別', '垂老別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四郊未寧靜，垂老不得安。","子孫陣亡盡，焉用身獨完。","投杖出門去，同行爲辛酸。","幸有牙齒存，所悲骨髓乾。","男兒既介胄，長揖別上官。","老妻臥路啼，歲暮衣裳單。","孰知是死別，且復傷其寒。","此去必不歸，還聞勸加餐。","土門壁甚堅，杏園度亦難。","勢異鄴城下，縱死時猶寬。","人生有離合，豈擇衰老端。","憶昔少壯日，遲回竟長歎。","萬國盡征戍，烽火被岡巒。","積屍草木腥，流血川原丹。","何鄉爲樂土，安敢尚盤桓。","棄絕蓬室居，塌然摧肺肝。"]', '["四郊未寧静，垂老不得安。","子孫陣亡尽，焉用身独完。","投杖出门去，同行爲辛酸。","幸有牙齒存，所悲骨髓乾。","男兒既介胄，长揖別上官。","老妻臥路啼，歲暮衣裳單。","孰知是死別，且复傷其寒。","此去必不归，還闻勸加餐。","土门壁甚堅，杏园度亦难。","勢異鄴城下，縱死时猶寬。","人生有離合，豈擇衰老端。","憶昔少壯日，遲回竟长歎。","万国尽征戍，烽火被岡巒。","積屍草木腥，流血川原丹。","何乡爲乐土，安敢尚盤桓。","棄絕蓬室居，塌然摧肺肝。"]', '诗', 'shi', '', NULL, '垂老別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f29798-b17d-44ed-b4c2-01620eae4868', '無家別', '無家別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寂寞天寶後，園廬但蒿藜。","我里百餘家，世亂各東西。","存者無消息，死者爲塵泥。","賤子因陣敗，歸來尋舊蹊。","人行見空巷，日瘦氣慘悽。","但對狐與貍，豎毛怒我啼。","四鄰何所有，一二老寡妻。","宿鳥戀本枝，安辭且窮棲。","方春獨荷鋤，日暮還灌畦。","縣吏知我至，召令習鼓鞞。","雖從本州役，內顧無所攜。","近行止一身，遠去終轉迷。","家鄉既盪盡，遠近理亦齊。","永痛長病母，五年委溝谿。","生我不得力，終身兩酸嘶。","人生無家別，何以爲烝黎。"]', '["寂寞天寶後，园廬但蒿藜。","我里百餘家，世亂各东西。","存者無消息，死者爲塵泥。","賤子因陣敗，归来尋旧蹊。","人行见空巷，日瘦氣慘悽。","但对狐與貍，豎毛怒我啼。","四鄰何所有，一二老寡妻。","宿鸟戀本枝，安辞且窮棲。","方春独荷鋤，日暮還灌畦。","縣吏知我至，召令習鼓鞞。","雖從本州役，內顧無所携。","近行止一身，远去終轉迷。","家乡既盪尽，远近理亦齊。","永痛长病母，五年委溝谿。","生我不得力，終身兩酸嘶。","人生無家別，何以爲烝黎。"]', '诗', 'shi', '', NULL, '無家別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb087f9d-b19c-4c65-a310-c605f73a1fde', '夏日歎', '夏日歎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夏日出東北，陵天經中街。","朱光徹厚地，鬱蒸何由開。","上蒼久無雷，無乃號令乖。","雨降不濡物，良田起黃埃。","飛鳥苦熱死，池魚涸其泥。","萬人尚流冗，舉目唯蒿萊。","至今大河北，化作虎與豺。","浩蕩想幽薊，王師安在哉？","對食不能餐，我心殊未諧。","眇然貞觀初，難與數子偕。"]', '["夏日出东北，陵天經中街。","朱光徹厚地，鬱蒸何由开。","上蒼久無雷，無乃號令乖。","雨降不濡物，良田起黄埃。","飞鸟苦熱死，池鱼涸其泥。","万人尚流冗，舉目唯蒿萊。","至今大河北，化作虎與豺。","浩蕩想幽薊，王師安在哉？","对食不能餐，我心殊未諧。","眇然貞观初，难與數子偕。"]', '诗', 'shi', '', NULL, '夏日歎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63d308b-f3a7-4520-b041-f7f4e27a5c9d', '夏夜歎', '夏夜歎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["永日不可暮，炎蒸毒我腸。","安得萬里風，飄颻吹我裳。","昊天出華月，茂林延疎光。","仲夏苦夜短，開軒納微涼。","虛明見纖毫，羽蟲亦飛揚。","物情無巨細，自適固其常。","念彼荷戈士，窮年守邊疆。","何由一洗濯，執熱互相望。","竟夕擊刁斗，喧聲連萬方。","青紫雖被體，不如早還鄉。","北城悲笳發，鸛鶴號且翔。","況復煩促倦，激烈思時康。"]', '["永日不可暮，炎蒸毒我腸。","安得万里风，飄颻吹我裳。","昊天出华月，茂林延疎光。","仲夏苦夜短，开軒納微涼。","虛明见纖毫，羽蟲亦飞揚。","物情無巨細，自適固其常。","念彼荷戈士，窮年守邊疆。","何由一洗濯，執熱互相望。","竟夕擊刁斗，喧声連万方。","青紫雖被體，不如早還乡。","北城悲笳發，鸛鹤號且翔。","況复煩促倦，激烈思时康。"]', '诗', 'shi', '', NULL, '夏夜歎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8e50fc9-2d2d-4f48-9fe4-2be2d4afad73', '立秋後題', '立秋後題', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日月不相饒，節序昨夜隔。","玄蟬無停號，秋燕已如客。","平生獨往願，惆悵年半百。","罷官亦由人，何事拘形役。"]', '["日月不相饒，節序昨夜隔。","玄蟬無停號，秋燕已如客。","平生独往願，惆悵年半百。","罷官亦由人，何事拘形役。"]', '诗', 'shi', '', NULL, '立秋後題 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767aa860-e910-4294-9c3e-172277296c37', '貽阮隱居', '貽阮隐居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陳留風俗衰，人物世不數。","塞上得阮生，迥繼先父祖。","貧知靜者性，自益毛髮古。","車馬入鄰家，蓬蒿翳環堵。","清詩近道要，識子用心苦。","尋我草徑微，褰裳蹋寒雨。","更議居遠邨，避喧甘猛虎。","足明箕潁客，榮貴如糞土。"]', '["陳留风俗衰，人物世不數。","塞上得阮生，迥繼先父祖。","貧知静者性，自益毛髮古。","车马入鄰家，蓬蒿翳环堵。","清诗近道要，識子用心苦。","尋我草徑微，褰裳蹋寒雨。","更議居远邨，避喧甘猛虎。","足明箕潁客，榮貴如糞土。"]', '诗', 'shi', '', NULL, '貽阮隱居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23e9d80-b995-43a0-9321-66d14b9f3bcf', '遣興三首 一', '遣兴三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["下馬古戰場，四顧但茫然。","風悲浮雲去，黃葉墜我前。","朽骨穴螻蟻，又爲蔓草纏。","故老行歎息，今人尚開邊。","漢虜互勝負，封疆不常全。","安得廉恥將，三軍同晏眠。"]', '["下马古戰場，四顧但茫然。","风悲浮云去，黄葉墜我前。","朽骨穴螻蟻，又爲蔓草纏。","故老行歎息，今人尚开邊。","漢虜互勝負，封疆不常全。","安得廉恥將，三軍同晏眠。"]', '诗', 'shi', '', NULL, '遣興三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140c81ac-b857-408f-bf47-8938c1b2e048', '遣興三首 二', '遣兴三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高秋登塞山，南望馬邑州。","降虜東擊胡，壯健盡不留。","穹廬莽牢落，上有行雲愁。","老弱哭道路，願聞甲兵休。","鄴中事反覆，死人積如丘。","諸將已茅土，載驅誰與謀。"]', '["高秋登塞山，南望马邑州。","降虜东擊胡，壯健尽不留。","穹廬莽牢落，上有行云愁。","老弱哭道路，願闻甲兵休。","鄴中事反覆，死人積如丘。","諸將已茅土，載驱誰與謀。"]', '诗', 'shi', '', NULL, '遣興三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0cdaa5-706e-4765-95a3-95cc78fd27b9', '遣興三首 三', '遣兴三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["豐年孰云遲，甘澤不在早。","耕田秋雨足，禾黍已映道。","春苗九月交，顏色同日老。","勸汝衡門士，忽悲尚枯槁。","時來展材力，先後無醜好。","但訝鹿皮翁，忘機對芳草。"]', '["豐年孰云遲，甘澤不在早。","耕田秋雨足，禾黍已映道。","春苗九月交，顏色同日老。","勸汝衡门士，忽悲尚枯槁。","时来展材力，先後無醜好。","但訝鹿皮翁，忘機对芳草。"]', '诗', 'shi', '', NULL, '遣興三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1569e1de-29bd-4e84-a55a-7d300a92e6a7', '昔遊', '昔游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔謁華蓋君，深求洞宮脚。","玉棺已上天，白日亦寂莫。","暮升艮岑頂，巾几猶未却。","弟子四五人，入來淚俱落。","余時遊名山，發軔在遠壑。","良覿違夙願，含淒向寥廓。","林昏罷幽磬，竟夜伏石閣。","王喬下天壇，微月映皓鶴。","晨溪嚮虛駃，歸徑行已昨。","豈辭青鞋胝，悵望金匕藥。","東蒙赴舊隱，尚憶同志樂。","休事董先生，于今獨蕭索。","胡爲客關塞，道意久衰薄。","妻子亦何人，丹砂負前諾。","雖悲鬒髮變，未憂筋力弱。","扶藜望清秋，有興入廬霍。"]', '["昔謁华蓋君，深求洞宮脚。","玉棺已上天，白日亦寂莫。","暮升艮岑頂，巾几猶未却。","弟子四五人，入来泪俱落。","余时游名山，發軔在远壑。","良覿違夙願，含淒向寥廓。","林昏罷幽磬，竟夜伏石閣。","王喬下天壇，微月映皓鹤。","晨溪嚮虛駃，归徑行已昨。","豈辞青鞋胝，悵望金匕藥。","东蒙赴旧隐，尚憶同志乐。","休事董先生，于今独蕭索。","胡爲客关塞，道意久衰薄。","妻子亦何人，丹砂負前諾。","雖悲鬒髮变，未憂筋力弱。","扶藜望清秋，有兴入廬霍。"]', '诗', 'shi', '', NULL, '昔遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23f7f4c-80d5-4f3d-9328-6f0032eaf2d0', '幽人', '幽人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孤雲亦羣遊，神物有所歸。","麟鳳在赤霄，何當一來儀。","往與惠荀輩，中年滄洲期。","天高無消息，棄我忽若遺。","內懼非道流，幽人見瑕疵。","洪濤隱語笑，鼓枻蓬萊池。","崔嵬扶桑日，照耀珊瑚枝。","風帆倚翠蓋，暮把東皇衣。","咽漱元和津，所思煙霞微。","知名未足稱，局促商山芝。","五湖復浩蕩，歲暮有餘悲。"]', '["孤云亦羣游，神物有所归。","麟鳳在赤霄，何當一来儀。","往與惠荀輩，中年滄洲期。","天高無消息，棄我忽若遺。","內懼非道流，幽人见瑕疵。","洪濤隐語笑，鼓枻蓬萊池。","崔嵬扶桑日，照耀珊瑚枝。","风帆倚翠蓋，暮把东皇衣。","咽漱元和津，所思煙霞微。","知名未足稱，局促商山芝。","五湖复浩蕩，歲暮有餘悲。"]', '诗', 'shi', '', NULL, '幽人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2db30a1-f125-44b9-a8d8-287ccb69238a', '佳人', '佳人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["絕代有佳人，幽居在空谷。","自云良家子，零落依草木。","關中昔喪敗，兄弟遭殺戮。","官高何足論，不得收骨肉。","世情惡衰歇，萬事隨轉燭。","夫壻輕薄兒，新人已如玉。","合昏尚知時，鴛鴦不獨宿。","但見新人笑，那聞舊人哭。","在山泉水清，出山泉水濁。","侍婢賣珠回，牽蘿補茅屋。","摘花不插髮，采柏動盈匊。","天寒翠袖薄，日暮倚修竹。"]', '["絕代有佳人，幽居在空谷。","自云良家子，零落依草木。","关中昔喪敗，兄弟遭殺戮。","官高何足論，不得收骨肉。","世情惡衰歇，万事隨轉燭。","夫壻轻薄兒，新人已如玉。","合昏尚知时，鴛鴦不独宿。","但见新人笑，那闻旧人哭。","在山泉水清，出山泉水濁。","侍婢賣珠回，牽蘿補茅屋。","摘花不插髮，采柏动盈匊。","天寒翠袖薄，日暮倚修竹。"]', '诗', 'shi', '', NULL, '佳人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b104baa-0304-4ae1-944c-c766ace60ec1', '赤谷西崦人家', '赤谷西崦人家', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["躋險不自喧，出郊已清目。","溪回日氣暖，徑轉山田熟。","鳥雀依茅茨，藩籬帶松菊。","如行武陵暮，欲問桃花宿。"]', '["躋險不自喧，出郊已清目。","溪回日氣暖，徑轉山田熟。","鸟雀依茅茨，藩籬带松菊。","如行武陵暮，欲问桃花宿。"]', '诗', 'shi', '', NULL, '赤谷西崦人家 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46878bae-9fd8-4808-bb50-ea9bca3cb2bf', '西枝邨尋置草堂地夜宿贊公土室二首 一', '西枝邨尋置草堂地夜宿贊公土室二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["出郭眄細岑，披榛得微路。","溪行一流水，曲折方屢渡。","贊公湯休徒，好靜心迹素。","昨枉霞上作，盛論巖中趣。","怡然共攜手，恣意同遠步。","捫蘿澀先登，陟巘眩反顧。","要求陽岡暖，苦陟陰嶺沍。","惆悵老大藤，沈吟屈蟠樹。","卜居意未展，杖策回且暮。","層巔餘落日，早蔓已多露。"]', '["出郭眄細岑，披榛得微路。","溪行一流水，曲折方屢渡。","贊公湯休徒，好静心迹素。","昨枉霞上作，盛論巖中趣。","怡然共携手，恣意同远步。","捫蘿澀先登，陟巘眩反顧。","要求陽岡暖，苦陟陰嶺沍。","惆悵老大藤，沈吟屈蟠樹。","卜居意未展，杖策回且暮。","層巔餘落日，早蔓已多露。"]', '诗', 'shi', '', NULL, '西枝邨尋置草堂地夜宿贊公土室二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('842a2bf0-573b-4ad7-b8ed-f1f8844408de', '西枝邨尋置草堂地夜宿贊公土室二首 二', '西枝邨尋置草堂地夜宿贊公土室二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天寒鳥已歸，月出人更靜。","土室延白光，松門耿疎影。","躋攀倦日短，語樂寄夜永。","明燃林中薪，暗汲石底井。","大師京國舊，德業天機秉。","從來支許遊，興趣江湖迥。","數奇謫關塞，道廣存箕潁。","何知戎馬間，復接塵事屏。","幽尋豈一路，遠色有諸嶺。","晨光稍曚曨，更越西南頂。"]', '["天寒鸟已归，月出人更静。","土室延白光，松门耿疎影。","躋攀倦日短，語乐寄夜永。","明燃林中薪，暗汲石底井。","大師京国旧，德業天機秉。","從来支許游，兴趣江湖迥。","數奇謫关塞，道廣存箕潁。","何知戎马间，复接塵事屏。","幽尋豈一路，远色有諸嶺。","晨光稍曚曨，更越西南頂。"]', '诗', 'shi', '', NULL, '西枝邨尋置草堂地夜宿贊公土室二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('221f5b2d-4997-4a97-bc31-87f0305d7570', '寄贊上人', '寄贊上人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一昨陪錫杖，卜鄰南山幽。","年侵腰脚衰，未便陰崖秋。","重岡北面起，竟日陽光留。","茅屋買兼土，斯焉心所求。","近聞西枝西，有谷杉黍稠。","亭午頗和暖，石田又足收。","當期塞雨乾，宿昔齒疾瘳。","裴回虎穴上，面勢龍泓頭。","柴荆具茶茗，逕路通林丘。","與子成二老，來往亦風流。"]', '["一昨陪錫杖，卜鄰南山幽。","年侵腰脚衰，未便陰崖秋。","重岡北面起，竟日陽光留。","茅屋買兼土，斯焉心所求。","近闻西枝西，有谷杉黍稠。","亭午頗和暖，石田又足收。","當期塞雨乾，宿昔齒疾瘳。","裴回虎穴上，面勢龙泓头。","柴荆具茶茗，逕路通林丘。","與子成二老，来往亦风流。"]', '诗', 'shi', '', NULL, '寄贊上人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664bcedd-5b20-4884-a2c0-c92b127d4504', '太平寺泉眼', '太平寺泉眼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["招提憑高岡，疎散連草莽。","出泉枯柳根，汲引歲月古。","石間見海眼，天畔縈水府。","廣深丈尺間，宴息敢輕侮。","青白二小蛇，幽姿可時覩。","如絲氣或上，爛熳爲雲雨。","山頭到山下，鑿井不盡土。","取供十方僧，香美勝牛乳。","北風起寒文，弱藻舒翠縷。","明涵客衣淨，細蕩林影趣。","何當宅下流，餘潤通藥圃。","三春濕黃精，一食生毛羽。"]', '["招提憑高岡，疎散連草莽。","出泉枯柳根，汲引歲月古。","石间见海眼，天畔縈水府。","廣深丈尺间，宴息敢轻侮。","青白二小蛇，幽姿可时覩。","如絲氣或上，爛熳爲云雨。","山头到山下，鑿井不尽土。","取供十方僧，香美勝牛乳。","北风起寒文，弱藻舒翠縷。","明涵客衣淨，細蕩林影趣。","何當宅下流，餘潤通藥圃。","三春濕黄精，一食生毛羽。"]', '诗', 'shi', '', NULL, '太平寺泉眼 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9362aba-fb50-481b-a4cd-08ddd65cdd2a', '夢李白二首 一', '梦李白二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["死別已吞聲，生別常惻惻。","江南瘴癘地，逐客無消息。","故人入我夢，明我長相憶。","恐非平生魂，路遠不可測。","魂來楓葉青，魂返關塞黑。","君今在羅網，何以有羽翼。","落月滿屋梁，猶疑照顏色。","水深波浪闊，無使蛟龍得。"]', '["死別已吞声，生別常惻惻。","江南瘴癘地，逐客無消息。","故人入我梦，明我长相憶。","恐非平生魂，路远不可測。","魂来楓葉青，魂返关塞黑。","君今在羅網，何以有羽翼。","落月满屋梁，猶疑照顏色。","水深波浪闊，無使蛟龙得。"]', '诗', 'shi', '', NULL, '夢李白二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0710a746-8660-4bc1-b073-8ce51ac9f4d9', '夢李白二首 二', '梦李白二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["浮雲終日行，遊子久不至。","三夜頻夢君，情親見君意。","告歸常局促，苦道來不易。","江湖多風波，舟楫恐失墜。","出門搔白首，若負平生志。","冠蓋滿京華，斯人獨顦顇。","孰云網恢恢，將老身反累。","千秋萬歲名，寂莫身後事。"]', '["浮云終日行，游子久不至。","三夜頻梦君，情親见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失墜。","出门搔白首，若負平生志。","冠蓋满京华，斯人独顦顇。","孰云網恢恢，將老身反累。","千秋万歲名，寂莫身後事。"]', '诗', 'shi', '', NULL, '夢李白二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058cb6ad-31e4-4d05-a2d7-c1f08ae860f1', '有懷台州鄭十八司戶', '有懷台州鄭十八司戶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天台隔三江，風浪無晨暮。","鄭公縱得歸，老病不識路。","昔如水上鷗，今如罝中兔。","性命由他人，悲辛但狂顧。","山鬼獨一脚，蝮蛇長如樹。","呼號傍孤城，歲月誰與度。","從來禦魑魅，多爲才名誤。","夫子嵇阮流，更被時俗惡。","海隅微小吏，眼暗髮垂素。","黃帽映青袍，非供折腰具。","平生一杯酒，見我故人遇。","相望無所成，乾坤莽回互。"]', '["天台隔三江，风浪無晨暮。","鄭公縱得归，老病不識路。","昔如水上鷗，今如罝中兔。","性命由他人，悲辛但狂顧。","山鬼独一脚，蝮蛇长如樹。","呼號傍孤城，歲月誰與度。","從来禦魑魅，多爲才名誤。","夫子嵇阮流，更被时俗惡。","海隅微小吏，眼暗髮垂素。","黄帽映青袍，非供折腰具。","平生一杯酒，见我故人遇。","相望無所成，乾坤莽回互。"]', '诗', 'shi', '', NULL, '有懷台州鄭十八司戶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b3cec93-fc44-44d2-91fa-a4feed67aaf9', '遣興五首 一', '遣兴五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蟄龍三冬臥，老鶴萬里心。","昔時賢俊人，未遇猶視今。","嵇康不得死，孔明有知音。","又如壠底松，用舍在所尋。","大哉霜雪榦，歲久爲枯林。"]', '["蟄龙三冬臥，老鹤万里心。","昔时賢俊人，未遇猶視今。","嵇康不得死，孔明有知音。","又如壠底松，用舍在所尋。","大哉霜雪榦，歲久爲枯林。"]', '诗', 'shi', '', NULL, '遣興五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914f158e-3c55-4db4-84bb-0f8a4b620f1d', '遣興五首 二', '遣兴五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔者龐德公，未曾入州府。","襄陽耆舊間，處士節獨苦。","豈無濟時策，終竟畏羅罟。","林茂鳥有歸，水深魚知聚。","舉家依鹿門，劉表焉得取。"]', '["昔者龐德公，未曾入州府。","襄陽耆旧间，处士節独苦。","豈無濟时策，終竟畏羅罟。","林茂鸟有归，水深鱼知聚。","舉家依鹿门，劉表焉得取。"]', '诗', 'shi', '', NULL, '遣興五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('945f8864-ae77-43fb-a9f8-c2c9f34fe39e', '遣興五首 三', '遣兴五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我今日夜憂，諸弟各異方。","不知死與生，何況道路長。","避寇一分散，飢寒永相望。","豈無柴門歸，欲出畏虎狼。","仰看雲中雁，禽鳥亦有行。"]', '["我今日夜憂，諸弟各異方。","不知死與生，何況道路长。","避寇一分散，飢寒永相望。","豈無柴门归，欲出畏虎狼。","仰看云中雁，禽鸟亦有行。"]', '诗', 'shi', '', NULL, '遣興五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5404fd-70f0-47b7-a4a8-8a2a7fb671c4', '遣興五首 四', '遣兴五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蓬生非無根，漂蕩隨高風。","天寒落萬里，不復歸本叢。","客子念故宅，三年門巷空。","悵望但烽火，戎車滿關東。","生涯能幾何，常在羈旅中。"]', '["蓬生非無根，漂蕩隨高风。","天寒落万里，不复归本叢。","客子念故宅，三年门巷空。","悵望但烽火，戎车满关东。","生涯能幾何，常在羈旅中。"]', '诗', 'shi', '', NULL, '遣興五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f2246e-b05e-44aa-b907-b642cc77defc', '遣興五首 五', '遣兴五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔在洛陽時，親友相追攀。","送客東郊道，遨遊宿南山。","煙塵阻長河，樹羽成臯間。","回首載酒地，豈無一日還。","丈夫貴壯健，慘戚非朱顏。"]', '["昔在洛陽时，親友相追攀。","送客东郊道，遨游宿南山。","煙塵阻长河，樹羽成臯间。","回首載酒地，豈無一日還。","丈夫貴壯健，慘戚非朱顏。"]', '诗', 'shi', '', NULL, '遣興五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcd81fb-6fb5-4994-b9ec-6baf5bbd4142', '遣興五首 一', '遣兴五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朔風飄胡雁，慘澹帶砂礫。","長林何蕭蕭，秋草萋更碧。","北里富熏天，高樓夜吹笛。","焉知南鄰客，九月猶絺綌。"]', '["朔风飄胡雁，慘澹带砂礫。","长林何蕭蕭，秋草萋更碧。","北里富熏天，高楼夜吹笛。","焉知南鄰客，九月猶絺綌。"]', '诗', 'shi', '', NULL, '遣興五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c063d6a-0bc3-49b6-805e-e192478c1bca', '遣興五首 二', '遣兴五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長陵銳頭兒，出獵待明發。","騂弓金爪鏑，白馬蹴微雪。","未知所馳逐，但見暮光滅。","歸來懸兩狼，門戶有旌節。"]', '["长陵銳头兒，出獵待明發。","騂弓金爪鏑，白马蹴微雪。","未知所驰逐，但见暮光滅。","归来懸兩狼，门戶有旌節。"]', '诗', 'shi', '', NULL, '遣興五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc0678f-1272-47ec-89ed-233fee07d436', '遣興五首 三', '遣兴五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漆有用而割，膏以明自煎。","蘭摧白露下，桂折秋風前。","府中羅舊尹，沙道尚依然。","赫赫蕭京兆，今爲時所憐。"]', '["漆有用而割，膏以明自煎。","蘭摧白露下，桂折秋风前。","府中羅旧尹，沙道尚依然。","赫赫蕭京兆，今爲时所怜。"]', '诗', 'shi', '', NULL, '遣興五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f89a106-6ff8-4deb-a2e5-30d5fe0da0f1', '遣興五首 四', '遣兴五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["猛虎憑其威，往往遭急縛。","雷吼徒咆哮，枝撐已在脚。","忽看皮寢處，無復睛閃爍。","人有甚於斯，足以勸元惡。"]', '["猛虎憑其威，往往遭急縛。","雷吼徒咆哮，枝撐已在脚。","忽看皮寢处，無复睛閃爍。","人有甚於斯，足以勸元惡。"]', '诗', 'shi', '', NULL, '遣興五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5376f2f6-9068-40c0-947b-f752a7d79892', '遣興五首 五', '遣兴五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝逢富家葬，前後皆輝光。","共指親戚大，緦麻百夫行。","送者各有死，不須羨其強。","君看束練去，亦得歸山岡。"]', '["朝逢富家葬，前後皆輝光。","共指親戚大，緦麻百夫行。","送者各有死，不須羨其強。","君看束練去，亦得归山岡。"]', '诗', 'shi', '', NULL, '遣興五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7beb1d4a-e1c9-4fc5-9ba1-82f46a724480', '遣興五首 一', '遣兴五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天用莫如龍，有時繫扶桑。","頓轡海徒涌，神人身更長。","性命苟不存，英雄徒自強。","吞聲勿復道，真宰意茫茫。"]', '["天用莫如龙，有时繫扶桑。","頓轡海徒涌，神人身更长。","性命苟不存，英雄徒自強。","吞声勿复道，真宰意茫茫。"]', '诗', 'shi', '', NULL, '遣興五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5768d12d-f4b9-4cbe-b7ae-051ed33d6331', '遣興五首 二', '遣兴五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["地用莫如馬，無良復誰記。","此日千里鳴，追風可君意。","君看渥洼種，態與駑駘異。","不雜蹄齧間，逍遙有能事。"]', '["地用莫如马，無良复誰記。","此日千里鳴，追风可君意。","君看渥洼種，態與駑駘異。","不杂蹄齧间，逍遙有能事。"]', '诗', 'shi', '', NULL, '遣興五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd956840-16b9-4268-9e98-dabb2fc592f0', '遣興五首 三', '遣兴五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陶潛避俗翁，未必能達道。","觀其著詩集，頗亦恨枯槁。","達生豈是足，默識蓋不早。","有子賢與愚，何其挂懷抱。"]', '["陶潛避俗翁，未必能達道。","观其著诗集，頗亦恨枯槁。","達生豈是足，默識蓋不早。","有子賢與愚，何其挂懷抱。"]', '诗', 'shi', '', NULL, '遣興五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcda5041-e6dc-402d-bf55-66ece895c572', '遣興五首 四', '遣兴五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賀公雅吳語，在位常清狂。","上疏乞骸骨，黃冠歸故鄉。","爽氣不可致，斯人今則亡。","山陰一茅宇，江海日淒涼。"]', '["賀公雅吳語，在位常清狂。","上疏乞骸骨，黄冠归故乡。","爽氣不可致，斯人今則亡。","山陰一茅宇，江海日淒涼。"]', '诗', 'shi', '', NULL, '遣興五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f010162-7a84-4c3c-935e-30fbe6f02b9f', '遣興五首 五', '遣兴五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾憐孟浩然，裋褐即長夜。","賦詩何必多，往往凌鮑謝。","清江空舊魚，春雨餘甘蔗。","每望東南雲，令人幾悲吒。"]', '["吾怜孟浩然，裋褐即长夜。","賦诗何必多，往往凌鲍謝。","清江空旧鱼，春雨餘甘蔗。","每望东南云，令人幾悲吒。"]', '诗', 'shi', '', NULL, '遣興五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7464f5a-53ed-4e78-92b9-331f0c5a39e9', '前出塞九首 一', '前出塞九首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戚戚去故里，悠悠赴交河。","公家有程期，亡命嬰禍羅。","君已富士境，開邊一何多。","棄絕父母恩，吞聲行負戈。"]', '["戚戚去故里，悠悠赴交河。","公家有程期，亡命嬰禍羅。","君已富士境，开邊一何多。","棄絕父母恩，吞声行負戈。"]', '诗', 'shi', '', NULL, '前出塞九首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95e1e06-9ca3-46b0-9a8b-f5673b9c7e7d', '前出塞九首 二', '前出塞九首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["出門日已遠，不受徒旅欺。","骨肉恩豈斷，男兒死無時。","走馬脫轡頭，手中挑青絲。","捷下萬仞岡，俯身試搴旗。"]', '["出门日已远，不受徒旅欺。","骨肉恩豈斷，男兒死無时。","走马脫轡头，手中挑青絲。","捷下万仞岡，俯身試搴旗。"]', '诗', 'shi', '', NULL, '前出塞九首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db93335b-fb58-4e18-b7dc-a0f59a083af3', '前出塞九首 三', '前出塞九首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["磨刀嗚咽水，水赤刃傷手。","欲輕腸斷聲，心緒亂已久。","丈夫誓許國，憤惋復何有。","功名圖騏驎，戰骨當速朽。"]', '["磨刀嗚咽水，水赤刃傷手。","欲轻腸斷声，心緒亂已久。","丈夫誓許国，憤惋复何有。","功名圖騏驎，戰骨當速朽。"]', '诗', 'shi', '', NULL, '前出塞九首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253b667d-e9bb-44ec-8ea9-03e1d552d9a7', '前出塞九首 四', '前出塞九首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["送徒既有長，遠戍亦有身。","生死向前去，不勞吏怒嗔。","路逢相識人，附書與六親。","哀哉兩決絕，不復同苦辛。"]', '["送徒既有长，远戍亦有身。","生死向前去，不勞吏怒嗔。","路逢相識人，附书與六親。","哀哉兩決絕，不复同苦辛。"]', '诗', 'shi', '', NULL, '前出塞九首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9434b028-3ff5-4d33-866b-e0e2b2d6dc70', '前出塞九首 五', '前出塞九首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["迢迢萬餘里，領我赴三軍。","軍中異苦樂，主將寧盡聞。","隔河見胡騎，倏忽數百羣。","我始爲奴僕，幾時樹功勳。"]', '["迢迢万餘里，領我赴三軍。","軍中異苦乐，主將寧尽闻。","隔河见胡騎，倏忽數百羣。","我始爲奴僕，幾时樹功勳。"]', '诗', 'shi', '', NULL, '前出塞九首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c675b1-10eb-4a59-af03-13eb43a2f9a0', '前出塞九首 六', '前出塞九首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["挽弓當挽強，用箭當用長。","射人先射馬，擒賊先擒王。","殺人亦有限，列國自有疆。","苟能制侵陵，豈在多殺傷。"]', '["挽弓當挽強，用箭當用长。","射人先射马，擒賊先擒王。","殺人亦有限，列国自有疆。","苟能制侵陵，豈在多殺傷。"]', '诗', 'shi', '', NULL, '前出塞九首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f3eb2b-20da-4636-b1cc-a0e09a0620c4', '前出塞九首 七', '前出塞九首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驅馬天雨雪，軍行入高山。","逕危抱寒石，指落曾冰間。","已去漢月遠，何時築城還。","浮雲暮南征，可望不可攀。"]', '["驱马天雨雪，軍行入高山。","逕危抱寒石，指落曾冰间。","已去漢月远，何时築城還。","浮云暮南征，可望不可攀。"]', '诗', 'shi', '', NULL, '前出塞九首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b24339-00c0-4745-b66f-11216db55ef6', '前出塞九首 八', '前出塞九首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["單于寇我壘，百里風塵昏。","雄劒四五動，彼軍爲我奔。","虜其名王歸，繫頸授轅門。","潛身備行列，一勝何足論。"]', '["單于寇我壘，百里风塵昏。","雄劒四五动，彼軍爲我奔。","虜其名王归，繫頸授轅门。","潛身備行列，一勝何足論。"]', '诗', 'shi', '', NULL, '前出塞九首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f9beec-1292-4208-a8b5-ec971ac6d965', '前出塞九首 九', '前出塞九首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["從軍十年餘，能無分寸功。","衆人貴苟得，欲語羞雷同。","中原有鬬爭，況在狄與戎。","丈夫四方志，安可辭固窮。"]', '["從軍十年餘，能無分寸功。","衆人貴苟得，欲語羞雷同。","中原有鬬爭，況在狄與戎。","丈夫四方志，安可辞固窮。"]', '诗', 'shi', '', NULL, '前出塞九首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39687061-12a7-4ac3-b911-eb7419d4ac3e', '後出塞五首 一', '後出塞五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["男兒生世間，及壯當封侯。","戰伐有功業，焉能守舊丘。","召募赴薊門，軍動不可留。","千金買馬鞭，百金裝刀頭。","閭里送我行，親戚擁道周。","斑白居上列，酒酣進庶羞。","少年別有贈，含笑看吳鉤。"]', '["男兒生世间，及壯當封侯。","戰伐有功業，焉能守旧丘。","召募赴薊门，軍动不可留。","千金買马鞭，百金裝刀头。","閭里送我行，親戚擁道周。","斑白居上列，酒酣進庶羞。","少年別有贈，含笑看吳鉤。"]', '诗', 'shi', '', NULL, '後出塞五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e981612-b3bb-4124-93a1-06e4abd82099', '後出塞五首 二', '後出塞五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝進東門營，暮上河陽橋。","落日照大旗，馬鳴風蕭蕭。","平沙列萬幕，部伍各見招。","中天懸明月，令嚴夜寂寥。","悲笳數聲動，壯士慘不驕。","借問大將誰，恐是霍嫖姚。"]', '["朝進东门營，暮上河陽橋。","落日照大旗，马鳴风蕭蕭。","平沙列万幕，部伍各见招。","中天懸明月，令嚴夜寂寥。","悲笳數声动，壯士慘不驕。","借问大將誰，恐是霍嫖姚。"]', '诗', 'shi', '', NULL, '後出塞五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc65d380-14d7-4ed4-b225-a6a976172050', '後出塞五首 三', '後出塞五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["古人重守邊，今人重高勳。","豈知英雄主，出師亙長雲。","六合已一家，四夷且孤軍。","遂使貔虎士，奮身勇所聞。","拔劒擊大荒，日收胡馬羣。","誓開玄冥北，持以奉吾君。"]', '["古人重守邊，今人重高勳。","豈知英雄主，出師亙长云。","六合已一家，四夷且孤軍。","遂使貔虎士，奮身勇所闻。","拔劒擊大荒，日收胡马羣。","誓开玄冥北，持以奉吾君。"]', '诗', 'shi', '', NULL, '後出塞五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e31da9-682f-45e2-8c18-c5a5689c3ba9', '後出塞五首 四', '後出塞五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["獻凱日繼踵，兩蕃靜無虞。","漁陽豪俠地，擊鼓吹笙竽。","雲帆轉遼海，稉稻來東吳。","越羅與楚練，照耀輿臺軀。","主將位益崇，氣驕凌上都。","邊人不敢議，議者死路衢。"]', '["獻凱日繼踵，兩蕃静無虞。","漁陽豪俠地，擊鼓吹笙竽。","云帆轉遼海，稉稻来东吳。","越羅與楚練，照耀輿台軀。","主將位益崇，氣驕凌上都。","邊人不敢議，議者死路衢。"]', '诗', 'shi', '', NULL, '後出塞五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa40901-8543-407c-97dc-95d9e3201b85', '後出塞五首 五', '後出塞五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我本良家子，出師亦多門。","將驕益愁思，身貴不足論。","躍馬二十年，恐辜明主恩。","坐見幽州騎，長驅河洛昏。","中夜間道歸，故里但空邨。","惡名幸脫免，窮老無兒孫。"]', '["我本良家子，出師亦多门。","將驕益愁思，身貴不足論。","躍马二十年，恐辜明主恩。","坐见幽州騎，长驱河洛昏。","中夜间道归，故里但空邨。","惡名幸脫免，窮老無兒孫。"]', '诗', 'shi', '', NULL, '後出塞五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40de2a56-327b-49db-894d-dbf8735ad3a8', '別贊上人', '別贊上人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百川日東流，客去亦不息。","我生苦漂蕩，何時有終極。","贊公釋門老，放逐來上國。","還爲世塵嬰，頗帶顦顇色。","楊枝晨在手，豆子雨已熟。","是身如浮雲，安可限南北。","異縣逢舊友，初忻寫胸臆。","天長關塞寒，歲暮飢凍逼。","野風吹征衣，欲別向曛黑。","馬嘶思故櫪，歸鳥盡斂翼。","古來聚散地，宿昔長荆棘。","相看俱衰年，出處各努力。"]', '["百川日东流，客去亦不息。","我生苦漂蕩，何时有終極。","贊公釋门老，放逐来上国。","還爲世塵嬰，頗带顦顇色。","楊枝晨在手，豆子雨已熟。","是身如浮云，安可限南北。","異縣逢旧友，初忻寫胸臆。","天长关塞寒，歲暮飢凍逼。","野风吹征衣，欲別向曛黑。","马嘶思故櫪，归鸟尽斂翼。","古来聚散地，宿昔长荆棘。","相看俱衰年，出处各努力。"]', '诗', 'shi', '', NULL, '別贊上人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b841ee-a837-427e-aecc-1da457c3b102', '萬丈潭', '万丈潭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青溪合冥莫，神物有顯晦。","龍依積水蟠，窟壓萬丈內。","跼步凌垠堮，側身下煙靄。","前臨洪濤寬，却立蒼石大。","山色一徑盡，崖絕兩壁對。","削成根虛無，倒影垂澹瀩。","黑如灣澴底，清見光炯碎。","孤雲倒來深，飛鳥不在外。","高蘿成帷幄，寒木累旌旆。","遠川曲通流，嵌竇潛洩瀨。","造幽無人境，發興自我輩。","告歸遺恨多，將老斯遊最。","閉藏修鱗蟄，出入巨石礙。","何事暑天過，快意風雨㑹。"]', '["青溪合冥莫，神物有显晦。","龙依積水蟠，窟壓万丈內。","跼步凌垠堮，側身下煙靄。","前臨洪濤寬，却立蒼石大。","山色一徑尽，崖絕兩壁对。","削成根虛無，倒影垂澹瀩。","黑如灣澴底，清见光炯碎。","孤云倒来深，飞鸟不在外。","高蘿成帷幄，寒木累旌旆。","远川曲通流，嵌竇潛洩瀨。","造幽無人境，發兴自我輩。","告归遺恨多，將老斯游最。","閉藏修鱗蟄，出入巨石礙。","何事暑天過，快意风雨㑹。"]', '诗', 'shi', '', NULL, '萬丈潭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6f5381-433a-41d3-afea-2598d19fe9c1', '兩當縣吳十侍御江上宅', '兩當縣吳十侍御江上宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒城朝煙澹，山谷落葉赤。","陰風千里來，吹汝江上宅。","鵾雞號枉渚，日色傍阡陌。","借問持斧翁，幾年長沙客。","哀哀失木狖，矯矯避弓翮。","亦知故鄉樂，未敢思夙昔。","昔在鳳翔都，共通金閨籍。","天子猶蒙塵，東郊暗長戟。","兵家忌間諜，此輩常接跡。","臺中領舉劾，君必慎剖析。","不忍殺無辜，所以分白黑。","上官權許與，失意見遷斥。","仲尼甘旅人，向子識損益。","朝廷非不知，閉口休歎息。","余時忝諍臣，丹陛實咫尺。","相看受狼狽，至死難塞責。","行邁心多違，出門無與適。","於公負明義，惆悵頭更白。"]', '["寒城朝煙澹，山谷落葉赤。","陰风千里来，吹汝江上宅。","鵾雞號枉渚，日色傍阡陌。","借问持斧翁，幾年长沙客。","哀哀失木狖，矯矯避弓翮。","亦知故乡乐，未敢思夙昔。","昔在鳳翔都，共通金閨籍。","天子猶蒙塵，东郊暗长戟。","兵家忌间諜，此輩常接跡。","台中領舉劾，君必慎剖析。","不忍殺無辜，所以分白黑。","上官權許與，失意见遷斥。","仲尼甘旅人，向子識損益。","朝廷非不知，閉口休歎息。","余时忝諍臣，丹陛實咫尺。","相看受狼狽，至死难塞責。","行邁心多違，出门無與適。","於公負明義，惆悵头更白。"]', '诗', 'shi', '', NULL, '兩當縣吳十侍御江上宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aee80a3-db54-4787-9e2a-491e108b8f1d', '發秦州', '發秦州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我衰更嬾拙，生事不自謀。","無食問樂土，無衣思南州。","漢源十月交，天氣涼如秋。","草木未黃落，況聞山水幽。","栗亭名更佳，下有良田疇。","充腸多薯蕷，崖蜜亦易求。","密竹復冬筍，清池可方舟。","雖傷旅寓遠，庶遂平生遊。","此邦俯要衝，實恐人事稠。","應接非本性，登臨未銷憂。","谿谷無異石，塞田始微收。","豈復慰老夫，惘然難久留。","日色隱孤戍，烏啼滿城頭。","中宵驅車去，飲馬寒塘流。","磊落星月高，蒼茫雲霧浮。","大哉乾坤內，吾道長悠悠。"]', '["我衰更嬾拙，生事不自謀。","無食问乐土，無衣思南州。","漢源十月交，天氣涼如秋。","草木未黄落，況闻山水幽。","栗亭名更佳，下有良田疇。","充腸多薯蕷，崖蜜亦易求。","密竹复冬筍，清池可方舟。","雖傷旅寓远，庶遂平生游。","此邦俯要衝，實恐人事稠。","應接非本性，登臨未銷憂。","谿谷無異石，塞田始微收。","豈复慰老夫，惘然难久留。","日色隐孤戍，烏啼满城头。","中宵驱车去，饮马寒塘流。","磊落星月高，蒼茫云霧浮。","大哉乾坤內，吾道长悠悠。"]', '诗', 'shi', '', NULL, '發秦州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f88f34-dc04-4366-8ca7-466e5e6e241c', '赤谷', '赤谷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天寒霜雪繁，遊子有所之。","豈但歲月暮，重來未有期。","晨發赤谷亭，險艱方自茲。","亂石無改轍，我車已載脂。","山深苦多風，落日童穉飢。","悄然邨墟迥，煙火何由追。","貧病轉零落，故鄉不可思。","常恐死道路，永爲高人嗤。"]', '["天寒霜雪繁，游子有所之。","豈但歲月暮，重来未有期。","晨發赤谷亭，險艱方自茲。","亂石無改轍，我车已載脂。","山深苦多风，落日童穉飢。","悄然邨墟迥，煙火何由追。","貧病轉零落，故乡不可思。","常恐死道路，永爲高人嗤。"]', '诗', 'shi', '', NULL, '赤谷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4ed54b-6c20-4817-a102-e0ce802ba019', '鐵堂峽', '鐵堂峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山風吹遊子，縹緲乘險絕。","峽形藏堂隍，壁色立積鐵。","徑摩穹蒼蟠，石與厚地裂。","修纖無垠竹，嵌空太始雪。","威遲哀壑底，徒旅慘不悅。","水寒長冰橫，我馬骨正折。","生涯抵弧矢，盜賊殊未滅。","飄蓬踰三年，回首肝肺熱。"]', '["山风吹游子，縹緲乘險絕。","峽形藏堂隍，壁色立積鐵。","徑摩穹蒼蟠，石與厚地裂。","修纖無垠竹，嵌空太始雪。","威遲哀壑底，徒旅慘不悅。","水寒长冰橫，我马骨正折。","生涯抵弧矢，盜賊殊未滅。","飄蓬踰三年，回首肝肺熱。"]', '诗', 'shi', '', NULL, '鐵堂峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19f6e14-e964-4d21-a5c7-e9e1a607ed16', '鹽井', '鹽井', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鹵中草木白，青者官鹽煙。","官作既有程，煮鹽煙在川。","汲井歲榾榾，出車日連連。","自公斗三百，轉致斛六千。","君子慎止足，小人苦喧闐。","我何良歎嗟，物理固自然。"]', '["鹵中草木白，青者官鹽煙。","官作既有程，煮鹽煙在川。","汲井歲榾榾，出车日連連。","自公斗三百，轉致斛六千。","君子慎止足，小人苦喧闐。","我何良歎嗟，物理固自然。"]', '诗', 'shi', '', NULL, '鹽井 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a31bfdee-c214-4ace-af0e-caeead25ec0c', '寒硤', '寒硤', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["行邁日悄悄，山谷勢多端。","雲門轉絕岸，積阻霾天寒。","寒硤不可度，我實衣裳單。","況當仲冬交，泝沿增波瀾。","野人尋煙語，行子傍水餐。","此生免荷殳，未敢辭路難。"]', '["行邁日悄悄，山谷勢多端。","云门轉絕岸，積阻霾天寒。","寒硤不可度，我實衣裳單。","況當仲冬交，泝沿增波瀾。","野人尋煙語，行子傍水餐。","此生免荷殳，未敢辞路难。"]', '诗', 'shi', '', NULL, '寒硤 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd3d20d-3811-4313-9588-dfedb060eef4', '法鏡寺', '法镜寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["身危適他州，勉強終勞苦。","神傷山行深，愁破崖寺古。","嬋娟碧鮮淨，蕭摵寒籜聚。","回回山根水，冉冉松上雨。","洩雲蒙清晨，初日翳復吐。","朱甍半光炯，戶牖粲可數。","拄策忘前期，出蘿已亭午。","冥冥子規叫，微徑不復取。"]', '["身危適他州，勉強終勞苦。","神傷山行深，愁破崖寺古。","嬋娟碧鲜淨，蕭摵寒籜聚。","回回山根水，冉冉松上雨。","洩云蒙清晨，初日翳复吐。","朱甍半光炯，戶牖粲可數。","拄策忘前期，出蘿已亭午。","冥冥子規叫，微徑不复取。"]', '诗', 'shi', '', NULL, '法鏡寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f220be96-faf6-4538-b69b-12a25f93a1c9', '青陽峽', '青陽峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["塞外苦厭山，南行道彌惡。","岡巒相經亙，雲水氣參錯。","林迥硤角來，天窄壁面削。","磎西五里石，奮怒向我落。","仰看日車側，俯恐坤軸弱。","魑魅嘯有風，霜霰浩漠漠。","昨憶踰隴坂，高秋視吳岳。","東笑蓮華卑，北知崆峒薄。","超然侔壯觀，已謂殷寥廓。","突兀猶趁人，及茲歎冥莫。"]', '["塞外苦厭山，南行道彌惡。","岡巒相經亙，云水氣參錯。","林迥硤角来，天窄壁面削。","磎西五里石，奮怒向我落。","仰看日车側，俯恐坤軸弱。","魑魅嘯有风，霜霰浩漠漠。","昨憶踰隴坂，高秋視吳岳。","东笑蓮华卑，北知崆峒薄。","超然侔壯观，已謂殷寥廓。","突兀猶趁人，及茲歎冥莫。"]', '诗', 'shi', '', NULL, '青陽峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea3afcb-dbb6-4641-abfa-cb4025f43d0a', '龍門鎮', '龙门鎮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["細泉兼輕冰，沮洳棧道濕。","不辭辛苦行，迫此短景急。","石門雪雲隘，古鎮峰巒集。","旌竿暮慘澹，風水白刃澀。","胡馬屯成臯，防虞此何及。","嗟爾遠戍人，山寒夜中泣。"]', '["細泉兼轻冰，沮洳棧道濕。","不辞辛苦行，迫此短景急。","石门雪云隘，古鎮峰巒集。","旌竿暮慘澹，风水白刃澀。","胡马屯成臯，防虞此何及。","嗟爾远戍人，山寒夜中泣。"]', '诗', 'shi', '', NULL, '龍門鎮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db149aaa-c52b-4893-8b6b-7047bd84b92f', '石龕', '石龕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["熊羆哮我東，虎豹號我西。","我後鬼長嘯，我前狨又啼。","天寒昏無日，山遠道路迷。","驅車石龕下，仲冬見虹蜺。","伐竹者誰子，悲歌上雲梯。","爲官采美箭，五歲供梁齊。","苦云直簳盡，無以充提攜。","奈何漁陽騎，颯颯驚烝黎。"]', '["熊羆哮我东，虎豹號我西。","我後鬼长嘯，我前狨又啼。","天寒昏無日，山远道路迷。","驱车石龕下，仲冬见虹蜺。","伐竹者誰子，悲歌上云梯。","爲官采美箭，五歲供梁齊。","苦云直簳尽，無以充提携。","奈何漁陽騎，颯颯驚烝黎。"]', '诗', 'shi', '', NULL, '石龕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26377acb-f4ce-440c-967e-e4c5eb9ebe48', '積草嶺', '積草嶺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["連峰積長陰，白日遞隱見。","颼颼林響交，慘慘石壯變。","山分積草嶺，路異明水縣。","旅泊吾道窮，衰年歲時倦。","卜居尚百里，休駕投諸彥。","邑有佳主人，情如已會面。","來書語絕妙，遠客驚深眷。","食蕨不願餘，茅茨眼中見。"]', '["連峰積长陰，白日遞隐见。","颼颼林响交，慘慘石壯变。","山分積草嶺，路異明水縣。","旅泊吾道窮，衰年歲时倦。","卜居尚百里，休駕投諸彥。","邑有佳主人，情如已會面。","来书語絕妙，远客驚深眷。","食蕨不願餘，茅茨眼中见。"]', '诗', 'shi', '', NULL, '積草嶺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c91e4d-996f-4f29-824a-a2422b6c7971', '泥功山', '泥功山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝行青泥上，暮在青泥中。","泥濘非一時，版築勞人功。","不畏道途永，乃將汩沒同。","白馬爲鐵驪，小兒成老翁。","哀猿透却墜，死鹿力所窮。","寄語北來人，後來莫悤悤。"]', '["朝行青泥上，暮在青泥中。","泥濘非一时，版築勞人功。","不畏道途永，乃將汩沒同。","白马爲鐵驪，小兒成老翁。","哀猿透却墜，死鹿力所窮。","寄語北来人，後来莫悤悤。"]', '诗', 'shi', '', NULL, '泥功山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf03c99-a183-42d3-b280-0f955523ad22', '鳳凰臺', '鳳凰台', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亭亭鳳凰臺，北對西康州。","西伯今寂寞，凰聲亦悠悠。","山峻路絕蹤，石林氣高浮。","安得萬丈梯，爲君上上頭。","恐有無母雛，飢寒日啾啾。","我能剖心出，飲啄慰孤愁。","心以當竹實，炯然無外求。","血以當醴泉，豈徒比清流。","所貴王者瑞，敢辭微命休。","坐看綵翮長，舉意八極周。","自天銜瑞圖，飛下十二樓。","圖以奉至尊，鳳以垂鴻猷。","再光中興業，一洗蒼生憂。","深衷正爲此，羣盜何淹留。"]', '["亭亭鳳凰台，北对西康州。","西伯今寂寞，凰声亦悠悠。","山峻路絕蹤，石林氣高浮。","安得万丈梯，爲君上上头。","恐有無母雛，飢寒日啾啾。","我能剖心出，饮啄慰孤愁。","心以當竹實，炯然無外求。","血以當醴泉，豈徒比清流。","所貴王者瑞，敢辞微命休。","坐看綵翮长，舉意八極周。","自天銜瑞圖，飞下十二楼。","圖以奉至尊，鳳以垂鴻猷。","再光中兴業，一洗蒼生憂。","深衷正爲此，羣盜何淹留。"]', '诗', 'shi', '', NULL, '鳳凰臺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8396b9-da62-4b1b-9c75-580ff9bfdda3', '乾元中寓居同谷縣作歌七首 一', '乾元中寓居同谷縣作歌七首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有客有客字子美，白頭亂髮垂過耳。","歲拾橡栗隨狙公，天寒日暮山谷裏。","中原無書歸不得，手脚凍皴皮肉死。","鳴呼一歌兮歌已哀，悲風爲我從天來。"]', '["有客有客字子美，白头亂髮垂過耳。","歲拾橡栗隨狙公，天寒日暮山谷裏。","中原無书归不得，手脚凍皴皮肉死。","鳴呼一歌兮歌已哀，悲风爲我從天来。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b14b05-2686-43b7-9006-ceda18052b2a', '乾元中寓居同谷縣作歌七首 二', '乾元中寓居同谷縣作歌七首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長鑱長鑱白木柄，我生托子以爲命。","黃精無苗山雪盛，短衣數挽不掩脛。","此時與子空歸來，男呻女吟四壁靜。","鳴呼二歌兮歌始放，鄰里爲我色惆悵。"]', '["长鑱长鑱白木柄，我生托子以爲命。","黄精無苗山雪盛，短衣數挽不掩脛。","此时與子空归来，男呻女吟四壁静。","鳴呼二歌兮歌始放，鄰里爲我色惆悵。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e97927-ce01-4928-a011-37716827baeb', '乾元中寓居同谷縣作歌七首 三', '乾元中寓居同谷縣作歌七首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有弟有弟在遠方，三人各瘦何人強。","生別展轉不相見，胡塵暗天道路長。","東飛駕鵝後鶖鶬，安得送我置汝旁。","鳴呼三歌兮歌三發，汝歸何處收兄骨。"]', '["有弟有弟在远方，三人各瘦何人強。","生別展轉不相见，胡塵暗天道路长。","东飞駕鵝後鶖鶬，安得送我置汝旁。","鳴呼三歌兮歌三發，汝归何处收兄骨。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9068fa3-4453-4d44-845f-1a4ab4186a1a', '乾元中寓居同谷縣作歌七首 四', '乾元中寓居同谷縣作歌七首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有妹有妹在鍾離，良人早歿諸孤癡。","長淮浪高蛟龍怒，十年不見來何時。","扁舟欲往箭滿眼，杳杳南國多旌旗。","鳴呼四歌兮歌四奏，林猨爲我啼清晝。"]', '["有妹有妹在鍾離，良人早歿諸孤癡。","长淮浪高蛟龙怒，十年不见来何时。","扁舟欲往箭满眼，杳杳南国多旌旗。","鳴呼四歌兮歌四奏，林猨爲我啼清晝。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e93a77e9-6f3f-4f80-ac47-02924d3acfd1', '乾元中寓居同谷縣作歌七首 五', '乾元中寓居同谷縣作歌七首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四山多風溪水急，寒雨颯颯枯樹濕。","黃蒿古城雲不開，白狐跳梁黃狐立。","我生何爲在窮谷，中夜起坐萬感集。","鳴呼五歌兮歌正長，魂招不來歸故鄉。"]', '["四山多风溪水急，寒雨颯颯枯樹濕。","黄蒿古城云不开，白狐跳梁黄狐立。","我生何爲在窮谷，中夜起坐万感集。","鳴呼五歌兮歌正长，魂招不来归故乡。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143fe577-0829-4ce8-b075-0ac12d8f64fe', '乾元中寓居同谷縣作歌七首 六', '乾元中寓居同谷縣作歌七首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南有龍兮在山湫，古木巃嵷枝相樛。","木葉黃落龍正蟄，蝮蛇東來水上遊。","我行怪此安敢出，拔劒欲斬且復休。","鳴呼六歌兮歌思遲，溪壑爲我回春姿。"]', '["南有龙兮在山湫，古木巃嵷枝相樛。","木葉黄落龙正蟄，蝮蛇东来水上游。","我行怪此安敢出，拔劒欲斬且复休。","鳴呼六歌兮歌思遲，溪壑爲我回春姿。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c556427-1203-45cd-b593-eab55e582569', '乾元中寓居同谷縣作歌七首 七', '乾元中寓居同谷縣作歌七首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["男兒生不成名身已老，三年飢走荒山道。","長安卿相多少年，富貴應須致身早。","山中儒生舊相識，但話宿昔傷懷抱。","鳴呼七歌兮悄終曲，仰視皇天白日速。"]', '["男兒生不成名身已老，三年飢走荒山道。","长安卿相多少年，富貴應須致身早。","山中儒生旧相識，但話宿昔傷懷抱。","鳴呼七歌兮悄終曲，仰視皇天白日速。"]', '诗', 'shi', '', NULL, '乾元中寓居同谷縣作歌七首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b178756b-34ab-4c15-a0d3-42af871a6c55', '發同谷縣', '發同谷縣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賢有不黔突，聖有不煖席。","況我飢愚人，焉能尚安宅。","始來茲山中，休駕喜地僻。","奈何迫物累，一歲四行役。","忡忡去絕境，杳杳更遠適。","停驂龍潭雲，回首白崖石。","臨岐別數子，握手淚再滴。","交情無舊深，窮老多慘慼。","平生嬾拙意，偶值棲遁跡。","去住與願違，仰慙林間翮。"]', '["賢有不黔突，聖有不煖席。","況我飢愚人，焉能尚安宅。","始来茲山中，休駕喜地僻。","奈何迫物累，一歲四行役。","忡忡去絕境，杳杳更远適。","停驂龙潭云，回首白崖石。","臨岐別數子，握手泪再滴。","交情無旧深，窮老多慘慼。","平生嬾拙意，偶值棲遁跡。","去住與願違，仰慙林间翮。"]', '诗', 'shi', '', NULL, '發同谷縣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c36b31-8f4d-4e1c-a9dd-c10f3e6a0da5', '木皮嶺', '木皮嶺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["首路栗亭西，尚想鳳皇邨。","季冬攜童穉，辛苦赴蜀門。","南登木皮嶺，艱險不易論。","汗流被我體，祁寒爲之暄。","遠岫爭輔佐，千巖自崩奔。","始知五岳外，別有他山尊。","仰干塞大明，俯入裂厚坤。","再聞虎豹鬬，屢跼風水昏。","高有廢閣道，摧折如短轅。","下有冬青林，石上走長根。","西崖特秀發，煥若靈芝繁。","潤聚金碧氣，清無沙土痕。","憶觀崑崙圖，目擊懸圃存。","對此欲何適，默傷垂老魂。"]', '["首路栗亭西，尚想鳳皇邨。","季冬携童穉，辛苦赴蜀门。","南登木皮嶺，艱險不易論。","汗流被我體，祁寒爲之暄。","远岫爭輔佐，千巖自崩奔。","始知五岳外，別有他山尊。","仰干塞大明，俯入裂厚坤。","再闻虎豹鬬，屢跼风水昏。","高有廢閣道，摧折如短轅。","下有冬青林，石上走长根。","西崖特秀發，煥若靈芝繁。","潤聚金碧氣，清無沙土痕。","憶观崑崙圖，目擊懸圃存。","对此欲何適，默傷垂老魂。"]', '诗', 'shi', '', NULL, '木皮嶺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a9f923-e4e3-4a02-856b-892800774ad4', '白沙渡', '白沙渡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["畏途隨長江，渡口下絕岸。","差池上舟楫，杳窕入雲漢。","天寒荒野外，日暮中流半。","我馬向北嘶，山猨飲相喚。","水清石礧礧，沙白灘漫漫。","迥然洗愁辛，多病一疎散。","高壁抵嶔崟，洪濤越凌亂。","臨風獨回首，攬轡復三歎。"]', '["畏途隨长江，渡口下絕岸。","差池上舟楫，杳窕入云漢。","天寒荒野外，日暮中流半。","我马向北嘶，山猨饮相喚。","水清石礧礧，沙白灘漫漫。","迥然洗愁辛，多病一疎散。","高壁抵嶔崟，洪濤越凌亂。","臨风独回首，攬轡复三歎。"]', '诗', 'shi', '', NULL, '白沙渡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164c262f-0c01-4baa-b366-adeb077fa1ea', '水會渡', '水會渡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山行有常程，中夜尚未安。","微月沒已久，崖傾路何難。","大江動我前，洶若溟渤寬。","篙師暗理楫，歌笑輕波瀾。","霜濃木石滑，風急手足寒。","入舟已千憂，陟巘仍萬盤。","迥眺積水外，始知衆星乾。","遠遊令人瘦，衰疾慙加餐。"]', '["山行有常程，中夜尚未安。","微月沒已久，崖傾路何难。","大江动我前，洶若溟渤寬。","篙師暗理楫，歌笑轻波瀾。","霜濃木石滑，风急手足寒。","入舟已千憂，陟巘仍万盤。","迥眺積水外，始知衆星乾。","远游令人瘦，衰疾慙加餐。"]', '诗', 'shi', '', NULL, '水會渡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660a6778-c6b8-40ef-908f-c2d563d1fe0b', '飛仙閣', '飞仙閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["土門山行窄，微徑緣秋毫。","棧雲蘭干峻，梯石結搆牢。","萬壑攲疎林，積陰帶奔濤。","寒日外澹泊，長風中怒號。","歇鞍在地底，始覺所歷高。","往來雜坐臥，人馬同疲勞。","浮生有定分，飢飽豈可逃。","歎息謂妻子，我何隨汝曹。"]', '["土门山行窄，微徑緣秋毫。","棧云蘭干峻，梯石結搆牢。","万壑攲疎林，積陰带奔濤。","寒日外澹泊，长风中怒號。","歇鞍在地底，始覺所歷高。","往来杂坐臥，人马同疲勞。","浮生有定分，飢飽豈可逃。","歎息謂妻子，我何隨汝曹。"]', '诗', 'shi', '', NULL, '飛仙閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbc706e-cef1-4d8b-921e-81ca48757a0e', '五盤', '五盤', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五盤雖云險，山色佳有餘。","仰凌棧道細，俯映江木疎。","地僻無網罟，水清反多魚。","好鳥不妄飛，野人半巢居。","喜見淳樸俗，坦然心神舒。","東郊尚格鬬，巨猾何時除。","故鄉有弟妹，流落隨丘墟。","成都萬事好，豈若歸吾廬。"]', '["五盤雖云險，山色佳有餘。","仰凌棧道細，俯映江木疎。","地僻無網罟，水清反多鱼。","好鸟不妄飞，野人半巢居。","喜见淳樸俗，坦然心神舒。","东郊尚格鬬，巨猾何时除。","故乡有弟妹，流落隨丘墟。","成都万事好，豈若归吾廬。"]', '诗', 'shi', '', NULL, '五盤 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7526293-9b93-4acd-afb5-8a75a32e7c27', '龍門閣', '龙门閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清江下龍門，絕壁無尺土。","長風駕高浪，浩浩自太古。","危途中縈盤，仰望垂綫縷。","滑石攲誰鑿，浮梁裊相拄。","目眩隕雜花，頭風吹過雨。","百年不敢料，一墜那得取。","飽聞經瞿塘，足見度大庾。","終身歷艱險，恐懼從此數。"]', '["清江下龙门，絕壁無尺土。","长风駕高浪，浩浩自太古。","危途中縈盤，仰望垂綫縷。","滑石攲誰鑿，浮梁裊相拄。","目眩隕杂花，头风吹過雨。","百年不敢料，一墜那得取。","飽闻經瞿塘，足见度大庾。","終身歷艱險，恐懼從此數。"]', '诗', 'shi', '', NULL, '龍門閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d7e65e-5a99-4597-a1cc-d716c5380584', '石櫃閣', '石櫃閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["季冬日已長，山晚半天赤。","蜀道多早花，江間饒奇石。","石櫃曾波上，臨虛蕩高壁。","清暉回羣鷗，暝色帶遠客。","羈棲負幽意，感歎向絕跡。","信甘孱懦嬰，不獨凍餒迫。","優游謝康樂，放浪陶彭澤。","吾衰未自安，謝爾性所適。"]', '["季冬日已长，山晚半天赤。","蜀道多早花，江间饒奇石。","石櫃曾波上，臨虛蕩高壁。","清暉回羣鷗，暝色带远客。","羈棲負幽意，感歎向絕跡。","信甘孱懦嬰，不独凍餒迫。","優游謝康乐，放浪陶彭澤。","吾衰未自安，謝爾性所適。"]', '诗', 'shi', '', NULL, '石櫃閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5eac1bc-e28b-46ee-b970-69da0951eba1', '桔柏渡', '桔柏渡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青冥寒江渡，駕竹爲長橋。","竿濕煙漠漠，江永風蕭蕭。","連笮動嫋娜，征衣颯飄颻。","急流鴇鷁散，絕岸黿鼉驕。","西轅自茲異，東逝不可要。","高通荆門路，闊會滄海潮。","孤光隱顧眄，遊子悵寂寥。","無以洗心胸，前登但山椒。"]', '["青冥寒江渡，駕竹爲长橋。","竿濕煙漠漠，江永风蕭蕭。","連笮动嫋娜，征衣颯飄颻。","急流鴇鷁散，絕岸黿鼉驕。","西轅自茲異，东逝不可要。","高通荆门路，闊會滄海潮。","孤光隐顧眄，游子悵寂寥。","無以洗心胸，前登但山椒。"]', '诗', 'shi', '', NULL, '桔柏渡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2d1332-4163-4dfa-ba76-34563c44f1a6', '劒門', '劒门', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["惟天有設險，劒門天下壯。","連山抱西南，石角皆北向。","兩崖崇墉倚，刻畫城郭狀。","一夫怒臨關，百萬未可傍。","珠玉走中原，岷峨氣悽愴。","三皇五帝前，雞犬各相放。","後王尚柔遠，職貢道已喪。","至今英雄人，高視見霸王。","幷吞與割據，極力不相讓。","吾將罪真宰，意欲鏟疊嶂。","恐此復偶然，臨風默惆悵。"]', '["惟天有設險，劒门天下壯。","連山抱西南，石角皆北向。","兩崖崇墉倚，刻畫城郭狀。","一夫怒臨关，百万未可傍。","珠玉走中原，岷峨氣悽愴。","三皇五帝前，雞犬各相放。","後王尚柔远，職貢道已喪。","至今英雄人，高視见霸王。","幷吞與割據，極力不相讓。","吾將罪真宰，意欲鏟叠嶂。","恐此复偶然，臨风默惆悵。"]', '诗', 'shi', '', NULL, '劒門 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19a0f62-4ea4-4ed7-a8e6-7b0057c2dece', '鹿頭山', '鹿头山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鹿頭何亭亭，是日慰飢渴。","連山西南斷，俯見千里豁。","遊子出京華，劒門不可越。","及茲險阻盡，始喜原野闊。","殊方昔三分，霸氣曾間發。","天下今一家，雲端失雙闕。","悠然想揚馬，繼起名硉兀。","有文令人傷，何處埋爾骨。","紆餘脂膏地，慘澹豪俠窟。","仗鉞非老臣，宣風豈專達。","冀公柱石姿，論道邦國活。","斯人亦何幸，公鎮逾歲月。"]', '["鹿头何亭亭，是日慰飢渴。","連山西南斷，俯见千里豁。","游子出京华，劒门不可越。","及茲險阻尽，始喜原野闊。","殊方昔三分，霸氣曾间發。","天下今一家，云端失雙闕。","悠然想揚马，繼起名硉兀。","有文令人傷，何处埋爾骨。","紆餘脂膏地，慘澹豪俠窟。","仗鉞非老臣，宣风豈專達。","冀公柱石姿，論道邦国活。","斯人亦何幸，公鎮逾歲月。"]', '诗', 'shi', '', NULL, '鹿頭山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b624d5-60a5-42e4-8417-298431fb7625', '成都府', '成都府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["翳翳桑榆日，照我征衣裳。","我行山川異，忽在天一方。","但逢新人民，未卜見故鄉。","大江東流去，游子去日長。","曾城填華屋，季冬樹木蒼。","喧然名都會，吹簫間笙簧。","信美無與適，側身望川梁。","鳥[雀]夜各歸，中原杳茫茫。","初月出不高，衆星尚爭光。","自古有羈旅，我何苦哀傷。"]', '["翳翳桑榆日，照我征衣裳。","我行山川異，忽在天一方。","但逢新人民，未卜见故乡。","大江东流去，游子去日长。","曾城填华屋，季冬樹木蒼。","喧然名都會，吹簫间笙簧。","信美無與適，側身望川梁。","鸟[雀]夜各归，中原杳茫茫。","初月出不高，衆星尚爭光。","自古有羈旅，我何苦哀傷。"]', '诗', 'shi', '', NULL, '成都府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7821c3f6-933b-486e-a712-48aac9999a7e', '石筍行', '石筍行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見益州城西門，陌上石筍雙高蹲。","古來相傳是海眼，苔蘚蝕盡波濤痕。","雨多往往得瑟瑟此事恍惚難明論。","恐是昔時卿相墓，立石爲表今仍存。","惜哉俗態好蒙蔽，亦如小臣媚至尊。","政化錯迕失大體，坐看傾危受厚恩。","嗟爾石筍擅虛名，後來未識猶駿奔。","安得壯士擲天外，使人不疑見本根。"]', '["君不见益州城西门，陌上石筍雙高蹲。","古来相傳是海眼，苔蘚蝕尽波濤痕。","雨多往往得瑟瑟此事恍惚难明論。","恐是昔时卿相墓，立石爲表今仍存。","惜哉俗態好蒙蔽，亦如小臣媚至尊。","政化錯迕失大體，坐看傾危受厚恩。","嗟爾石筍擅虛名，後来未識猶駿奔。","安得壯士擲天外，使人不疑见本根。"]', '诗', 'shi', '', NULL, '石筍行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1286ea-af42-4c24-8aa6-ebe54624d63e', '石犀行', '石犀行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見秦時蜀太守，刻石立作三犀牛。","自古雖有厭勝法，天生江水向東流。","蜀人矜誇一千載，汎溢不近張儀樓。","今年灌口損戶口，此事或恐爲神羞。","終藉隄防出衆力，高擁木石當清秋。","先王作法皆正道，鬼怪何得參人謀。","嗟爾三犀不經濟，缺訛只與長川逝。","但見元氣常調和，自免洪濤恣凋瘵。","安得壯士提天綱，再平水土犀奔茫。"]', '["君不见秦时蜀太守，刻石立作三犀牛。","自古雖有厭勝法，天生江水向东流。","蜀人矜誇一千載，汎溢不近張儀楼。","今年灌口損戶口，此事或恐爲神羞。","終藉隄防出衆力，高擁木石當清秋。","先王作法皆正道，鬼怪何得參人謀。","嗟爾三犀不經濟，缺訛只與长川逝。","但见元氣常調和，自免洪濤恣凋瘵。","安得壯士提天綱，再平水土犀奔茫。"]', '诗', 'shi', '', NULL, '石犀行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91233d92-0156-4ead-9981-a5b834f9a3d2', '杜鵑行', '杜鵑行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見昔日蜀天子，化作杜鵑似老烏。","寄巢生子不自啄，羣鳥至今與哺雛。","雖同君臣有舊禮，骨肉滿眼身羈孤。","業工竄伏深樹裏，四月五月偏號呼。","其聲哀痛口流血，所訴何事常區區。","爾豈摧殘始發憤，羞帶羽翮傷形愚。","蒼天變化誰料得，萬事反覆何所無。","萬事反覆何所無，豈憶當殿羣臣趨。"]', '["君不见昔日蜀天子，化作杜鵑似老烏。","寄巢生子不自啄，羣鸟至今與哺雛。","雖同君臣有旧禮，骨肉满眼身羈孤。","業工竄伏深樹裏，四月五月偏號呼。","其声哀痛口流血，所訴何事常區區。","爾豈摧殘始發憤，羞带羽翮傷形愚。","蒼天变化誰料得，万事反覆何所無。","万事反覆何所無，豈憶當殿羣臣趨。"]', '诗', 'shi', '', NULL, '杜鵑行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83272b8-1f96-4b0a-a211-f3f7870d4f9f', '贈蜀僧閭丘師兄', '贈蜀僧閭丘師兄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大師銅梁秀，籍籍名家孫。","嗚呼先博士，炳靈精氣奔。","惟昔武皇后，臨軒御乾坤。","多士盡儒冠，墨客藹雲屯。","當時上紫殿，不獨卿相尊。","世傳閭丘筆峻極逾崑崙。","鳳藏丹宵暮，龍去白水渾。","青熒雪嶺東，碑碣舊製存。","斯文散都邑，高價越璵璠。","晚看作者意，妙絕與誰論。","吾祖詩冠古，同年蒙主恩。","豫章夾日月，歲久空深根。","小子思疎闊，豈能達詞門。","窮愁一揮淚，相遇即諸昆。","我住錦官城，兄居祇樹圖。","地近慰旅愁，往來當丘樊。","天涯歇滯雨，稉稻臥不翻。","漂然薄遊倦，始與道侶敦。","景晏步修廊，而無車馬喧。","夜闌接軟語，落月如金盆。","漠漠世界黑，驅車爭奪繁。","惟有摩尼珠，可照濁水源。"]', '["大師銅梁秀，籍籍名家孫。","嗚呼先博士，炳靈精氣奔。","惟昔武皇后，臨軒御乾坤。","多士尽儒冠，墨客藹云屯。","當时上紫殿，不独卿相尊。","世傳閭丘笔峻極逾崑崙。","鳳藏丹宵暮，龙去白水渾。","青熒雪嶺东，碑碣旧製存。","斯文散都邑，高價越璵璠。","晚看作者意，妙絕與誰論。","吾祖诗冠古，同年蒙主恩。","豫章夾日月，歲久空深根。","小子思疎闊，豈能達词门。","窮愁一揮泪，相遇即諸昆。","我住錦官城，兄居祇樹圖。","地近慰旅愁，往来當丘樊。","天涯歇滯雨，稉稻臥不翻。","漂然薄游倦，始與道侶敦。","景晏步修廊，而無车马喧。","夜闌接軟語，落月如金盆。","漠漠世界黑，驱车爭奪繁。","惟有摩尼珠，可照濁水源。"]', '诗', 'shi', '', NULL, '贈蜀僧閭丘師兄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1b60ee-3d4e-4551-b39e-44195638c9bb', '泛溪', '泛溪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落景下高堂，進州泛回溪。","誰謂築居小，未盡喬木西。","遠郊信荒僻，秋色有餘淒。","練練峰上雪，纖纖雲表霓。","童戲左右岸，罟弋畢提攜。","翻倒荷芰亂，指揮徑路迷。","得魚已割鱗，采藕不洗泥。","人情逐鮮美，物賤事已睽。","吾邨藹暝姿，異舍雞亦棲。","蕭條欲何適，出處無可齊。","衣上見新月，霜中登故畦。","濁醪自初熟，東城多鼓鼙。"]', '["落景下高堂，進州泛回溪。","誰謂築居小，未尽喬木西。","远郊信荒僻，秋色有餘淒。","練練峰上雪，纖纖云表霓。","童戲左右岸，罟弋畢提携。","翻倒荷芰亂，指揮徑路迷。","得鱼已割鱗，采藕不洗泥。","人情逐鲜美，物賤事已睽。","吾邨藹暝姿，異舍雞亦棲。","蕭條欲何適，出处無可齊。","衣上见新月，霜中登故畦。","濁醪自初熟，东城多鼓鼙。"]', '诗', 'shi', '', NULL, '泛溪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb04222-21b9-4866-91a1-7426027b5fa6', '題壁畫馬歌', '題壁畫马歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["韋侯別我有所適，知我憐君畫無敵。","戲拈禿筆埽驊騮，歘見騏驎出東壁。","一匹齕草一匹嘶，坐看千里當霜蹄。","時危安得真致此，與人同生亦同死。"]', '["韋侯別我有所適，知我怜君畫無敵。","戲拈禿笔埽驊騮，歘见騏驎出东壁。","一匹齕草一匹嘶，坐看千里當霜蹄。","时危安得真致此，與人同生亦同死。"]', '诗', 'shi', '', NULL, '題壁畫馬歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1c6979-d71b-48ab-b50d-9a9a210ec4c9', '戲題畫山水圖歌', '戲題畫山水圖歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["十日畫一水，五日畫一石。","能事不受相促迫，王宰始肯留真跡。","壯哉崑崙方壺圖，挂君高堂之素壁。","巴陵洞庭日本東，赤岸水與銀河通，中有雲氣隨飛龍。","舟人漁子入浦溆，山木盡亞洪濤風。","尤工遠勢古莫比，咫尺應須論萬里。","焉得幷州快剪刀，剪取吳松半江水。"]', '["十日畫一水，五日畫一石。","能事不受相促迫，王宰始肯留真跡。","壯哉崑崙方壺圖，挂君高堂之素壁。","巴陵洞庭日本东，赤岸水與銀河通，中有云氣隨飞龙。","舟人漁子入浦溆，山木尽亞洪濤风。","尤工远勢古莫比，咫尺應須論万里。","焉得幷州快剪刀，剪取吳松半江水。"]', '诗', 'shi', '', NULL, '戲題畫山水圖歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8488fbf4-2bde-444f-b639-a3324e23b23c', '題李尊師松樹障子歌', '題李尊師松樹障子歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老夫清晨梳白頭，玄都道士來相訪。","握髮呼兒延入戶，手提新畫青松障。","障子松林靜杳冥，憑軒忽若無丹青。","陰崖却承霜雪幹，偃蓋反走虯龍形。","老夫平生好奇古，對此興與精靈聚。","已知仙客意相親，更覺良工心獨苦。","松下丈人巾屨同，偶坐似是商山翁。","悵望聊歌紫芝曲，時危慘澹來悲風。"]', '["老夫清晨梳白头，玄都道士来相訪。","握髮呼兒延入戶，手提新畫青松障。","障子松林静杳冥，憑軒忽若無丹青。","陰崖却承霜雪幹，偃蓋反走虯龙形。","老夫平生好奇古，对此兴與精靈聚。","已知仙客意相親，更覺良工心独苦。","松下丈人巾屨同，偶坐似是商山翁。","悵望聊歌紫芝曲，时危慘澹来悲风。"]', '诗', 'shi', '', NULL, '題李尊師松樹障子歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de7b248-dde5-44c1-a68d-b46cf13c62a5', '戲爲雙松圖歌', '戲爲雙松圖歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天下幾人畫古松，畢宏已老韋偃少。","絕筆長風起纖末，滿堂動色嗟神妙。","兩株慘裂苔蘚皮，屈鐵交錯回高枝，白摧朽骨龍虎死。","黑入太陰雷雨垂，松根胡僧憩寂寞。","龐眉皓首無住著，偏袒右肩露雙脚。","葉裏松子僧前落，韋侯韋侯數相見。","我有一匹好東絹，重之不減錦繡段。","已命拂拭光凌亂，請公放筆爲直幹。"]', '["天下幾人畫古松，畢宏已老韋偃少。","絕笔长风起纖末，满堂动色嗟神妙。","兩株慘裂苔蘚皮，屈鐵交錯回高枝，白摧朽骨龙虎死。","黑入太陰雷雨垂，松根胡僧憩寂寞。","龐眉皓首無住著，偏袒右肩露雙脚。","葉裏松子僧前落，韋侯韋侯數相见。","我有一匹好东絹，重之不減錦繡段。","已命拂拭光凌亂，請公放笔爲直幹。"]', '诗', 'shi', '', NULL, '戲爲雙松圖歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09366fe4-04f9-4665-abc0-810b9a9c6720', '投簡成華兩縣諸子', '投簡成华兩縣諸子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["赤縣官曹擁材傑，軟裘快馬當冰雪。","長安苦寒誰獨悲，杜陵野老骨欲折。","南山豆苗早荒穢，青門瓜地新凍裂。","鄉里兒童項領成，朝廷故舊禮數絕。","自然棄擲與時異，況乃疎頑臨事拙。","飢臥動即向一旬，敝裘何啻聯百結。","君不見空牆日色晚，此老無聲淚垂血。"]', '["赤縣官曹擁材傑，軟裘快马當冰雪。","长安苦寒誰独悲，杜陵野老骨欲折。","南山豆苗早荒穢，青门瓜地新凍裂。","乡里兒童項領成，朝廷故旧禮數絕。","自然棄擲與时異，況乃疎頑臨事拙。","飢臥动即向一旬，敝裘何啻聯百結。","君不见空牆日色晚，此老無声泪垂血。"]', '诗', 'shi', '', NULL, '投簡成華兩縣諸子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a1ab7c-8206-4c5c-b333-d5410c429a19', '徐卿二子歌', '徐卿二子歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見徐卿二子生絕奇，感應吉夢相追隨。","孔子釋氏親抱送，竝是天上麒麟兒。","大兒九齡色清澈，秋水爲神玉爲骨。","小兒五歲氣食牛，滿堂賓客皆回頭。","吾知徐公百不憂，積善衮衮生公侯。","丈夫生兒有如此二雛者，名位豈肯悲微休。"]', '["君不见徐卿二子生絕奇，感應吉梦相追隨。","孔子釋氏親抱送，竝是天上麒麟兒。","大兒九齡色清澈，秋水爲神玉爲骨。","小兒五歲氣食牛，满堂賓客皆回头。","吾知徐公百不憂，積善衮衮生公侯。","丈夫生兒有如此二雛者，名位豈肯悲微休。"]', '诗', 'shi', '', NULL, '徐卿二子歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b60930e-556e-433e-a978-8a175c33ee87', '病柏', '病柏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有柏生崇岡，童童狀車蓋。","偃蹙龍虎姿，主當風雲會。","神明依正直，故老多再拜。","豈知千年根，中路顏色壞。","出非不得地，蟠據亦高大。","歲寒忽無憑，日夜柯葉改。","丹鳳領九雛，哀鳴翔其外。","鴟鴞志意滿，養子穿穴內。","客從何鄉來，佇立久吁怪。","靜求元精理，浩蕩難倚賴。"]', '["有柏生崇岡，童童狀车蓋。","偃蹙龙虎姿，主當风云會。","神明依正直，故老多再拜。","豈知千年根，中路顏色壞。","出非不得地，蟠據亦高大。","歲寒忽無憑，日夜柯葉改。","丹鳳領九雛，哀鳴翔其外。","鴟鴞志意满，養子穿穴內。","客從何乡来，佇立久吁怪。","静求元精理，浩蕩难倚賴。"]', '诗', 'shi', '', NULL, '病柏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7b79ad-21b9-4628-ab5f-ddc8ba1343b6', '病橘', '病橘', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣橘少生意，雖多亦奚爲。","惜哉結實小，酸澀如棠棃。","剖之盡蠹蟲，采掇爽其宜。","紛然不適口，豈只存其皮。","蕭蕭半死葉，未忍別故枝。","玄冬霜雪積，況乃回風吹。","嘗聞蓬萊殿，羅列瀟湘姿。","此物歲不稔，玉食失光輝。","寇盜尚憑陵，當君減膳時。","汝病是天意，吾諗罪有司。","憶昔南海使，奔騰獻荔支。","百馬死山谷，到今耆舊悲。"]', '["羣橘少生意，雖多亦奚爲。","惜哉結實小，酸澀如棠棃。","剖之尽蠹蟲，采掇爽其宜。","紛然不適口，豈只存其皮。","蕭蕭半死葉，未忍別故枝。","玄冬霜雪積，況乃回风吹。","嘗闻蓬萊殿，羅列瀟湘姿。","此物歲不稔，玉食失光輝。","寇盜尚憑陵，當君減膳时。","汝病是天意，吾諗罪有司。","憶昔南海使，奔腾獻荔支。","百马死山谷，到今耆旧悲。"]', '诗', 'shi', '', NULL, '病橘 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c10ce9-23b4-4e64-9b20-fc62a84e288c', '枯椶', '枯椶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蜀門多椶櫚，高者十八九。","其皮割剝甚，雖衆亦易朽。","徒布如雲葉，青黃歲寒後。","交橫集斧斤，凋喪先蒲柳。","傷時苦軍乏，一物官盡取。","嗟爾江漢人，生成復何有。","有同枯椶木，使我沈歎久。","死者即已休，生者何自守。","啾啾黃雀啅，側見寒蓬走。","念爾形影乾，摧殘沒藜莠。"]', '["蜀门多椶櫚，高者十八九。","其皮割剝甚，雖衆亦易朽。","徒布如云葉，青黄歲寒後。","交橫集斧斤，凋喪先蒲柳。","傷时苦軍乏，一物官尽取。","嗟爾江漢人，生成复何有。","有同枯椶木，使我沈歎久。","死者即已休，生者何自守。","啾啾黄雀啅，側见寒蓬走。","念爾形影乾，摧殘沒藜莠。"]', '诗', 'shi', '', NULL, '枯椶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c1e693-521d-40f1-9384-a5ecdc3a3f8e', '枯柟', '枯柟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楩柟枯崢嶸，鄉黨皆莫記。","不知幾百歲，慘慘無生意。","上枝摩皇天，下根蟠厚地。","巨圍雷霆坼，萬孔蟲蟻萃。","凍雨落流膠，衝風奪佳氣。","白鵠遂不來，天雞爲愁思。","猶含棟梁具，無復霄漢志。","良工古昔少，識者出涕淚。","種榆水中央，成長何容易。","截承金露盤，褭褭不自畏。"]', '["楩柟枯崢嶸，乡黨皆莫記。","不知幾百歲，慘慘無生意。","上枝摩皇天，下根蟠厚地。","巨圍雷霆坼，万孔蟲蟻萃。","凍雨落流膠，衝风奪佳氣。","白鵠遂不来，天雞爲愁思。","猶含棟梁具，無复霄漢志。","良工古昔少，識者出涕泪。","種榆水中央，成长何容易。","截承金露盤，褭褭不自畏。"]', '诗', 'shi', '', NULL, '枯柟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccea1790-b4a4-422a-b1f0-2cd37caad120', '麗春', '丽春', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百草競春華，麗春應最勝。","少須好顏色，多漫枝條賸。","紛紛桃李枝，處處總能移。","如何貴此重，却怕有人知。"]', '["百草競春华，丽春應最勝。","少須好顏色，多漫枝條賸。","紛紛桃李枝，处处總能移。","如何貴此重，却怕有人知。"]', '诗', 'shi', '', NULL, '麗春 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0cbff86-2ace-41db-b528-c33689a3afe8', '丈人山', '丈人山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自爲青城客，不唾青城地。","爲愛丈人山，丹梯近幽意。","丈人祠西佳氣濃，緣雲擬住最高峰。","埽除白髮黃精在，君看他時冰雪容。"]', '["自爲青城客，不唾青城地。","爲愛丈人山，丹梯近幽意。","丈人祠西佳氣濃，緣云擬住最高峰。","埽除白髮黄精在，君看他时冰雪容。"]', '诗', 'shi', '', NULL, '丈人山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76f179f-60ec-45ef-82b8-8d0e7c121bb5', '百憂集行', '百憂集行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶年十五心尚孩，健如黃犢走復來。","庭前八月棃棗熟，一日上樹能千回。","即今倏忽已五十，坐臥只多少行立。","強將笑語供主人，悲見生涯百憂集。","入門依舊四壁空，老妻覩我顏色同。","癡兒未知父子禮，叫怒索飯啼門東。"]', '["憶年十五心尚孩，健如黄犢走复来。","庭前八月棃棗熟，一日上樹能千回。","即今倏忽已五十，坐臥只多少行立。","強將笑語供主人，悲见生涯百憂集。","入门依旧四壁空，老妻覩我顏色同。","癡兒未知父子禮，叫怒索飯啼门东。"]', '诗', 'shi', '', NULL, '百憂集行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554a25ee-27ba-40ed-a77c-0edde1d4fea2', '戲作花卿歌', '戲作花卿歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["成都猛將有花卿，學語小兒知姓名。","用如快鶻風火生，見賊唯多身始輕。","緜州副使著柘黃，我卿埽除即日平。","子章髑髏血糢糊，手提擲還崔大夫。","李侯重有此節度，人道我卿絕世無。"]', '["成都猛將有花卿，学語小兒知姓名。","用如快鶻风火生，见賊唯多身始轻。","緜州副使著柘黄，我卿埽除即日平。","子章髑髏血糢糊，手提擲還崔大夫。","李侯重有此節度，人道我卿絕世無。"]', '诗', 'shi', '', NULL, '戲作花卿歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968777d5-0571-4d7b-a00d-8549f311ac3a', '入奏行贈西山檢察使竇侍御', '入奏行贈西山檢察使竇侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竇侍御，驥之子，鳳之雛。","年未三十忠義俱，骨鯁絕代無。","炯如一段清冰出萬壑，置在迎風寒露之玉壺。","蔗漿歸廚金盌凍，洗滌煩熱足以寧君軀。","政用疎通合典則，戚聯豪貴耽文儒。","兵革未息人未蘇，天子亦念西南隅。","吐蕃憑陵氣頗麤，竇氏檢察應時須。","運糧繩橋壯士喜，斬木火井窮猿呼。","八州刺史思一戰，三城守邊却可圖。","此行入奏計未小，密奉賢旨恩宜殊。","繡衣春當霄漢立，綵服日向庭闈趨。","省郎京尹必俯拾，江花未落還成都。","江花未落還成都，肯訪浣花老翁無。","爲君酤酒滿眼酤，與奴白飯馬青芻。"]', '["竇侍御，驥之子，鳳之雛。","年未三十忠義俱，骨鯁絕代無。","炯如一段清冰出万壑，置在迎风寒露之玉壺。","蔗漿归廚金盌凍，洗滌煩熱足以寧君軀。","政用疎通合典則，戚聯豪貴耽文儒。","兵革未息人未蘇，天子亦念西南隅。","吐蕃憑陵氣頗麤，竇氏檢察應时須。","運糧繩橋壯士喜，斬木火井窮猿呼。","八州刺史思一戰，三城守邊却可圖。","此行入奏計未小，密奉賢旨恩宜殊。","繡衣春當霄漢立，綵服日向庭闈趨。","省郎京尹必俯拾，江花未落還成都。","江花未落還成都，肯訪浣花老翁無。","爲君酤酒满眼酤，與奴白飯马青芻。"]', '诗', 'shi', '', NULL, '入奏行贈西山檢察使竇侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdeeaa87-d383-44e2-8245-d18fcffb107f', '柟樹爲風雨所拔歎', '柟樹爲风雨所拔歎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["倚江柟樹草堂前，故老相傳二百年。","誅茅卜居總爲此，五月髣髴聞寒蟬。","東南飄風動地至，江翻石走流雲氣。","幹排雷雨猶力爭，根斷泉源豈天意。","滄波老樹性所愛，浦上童童一青蓋。","野客頻留懼雪霜，行人不過聽竽籟。","虎倒龍顛委榛棘，淚痕血點垂胷臆。","我有新詩何處吟，草堂自此無顏色。"]', '["倚江柟樹草堂前，故老相傳二百年。","誅茅卜居總爲此，五月髣髴闻寒蟬。","东南飄风动地至，江翻石走流云氣。","幹排雷雨猶力爭，根斷泉源豈天意。","滄波老樹性所愛，浦上童童一青蓋。","野客頻留懼雪霜，行人不過听竽籟。","虎倒龙顛委榛棘，泪痕血点垂胷臆。","我有新诗何处吟，草堂自此無顏色。"]', '诗', 'shi', '', NULL, '柟樹爲風雨所拔歎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ea879f4-9781-469a-8b52-fc5777e633c2', '茅屋爲秋風所破歌', '茅屋爲秋风所破歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["八月秋高風怒號，卷我屋上三重茅。","茅飛度江灑江郊，高者挂罥長林梢。","下者飄轉沈塘坳，南邨羣童欺我老無力。","忍能對面爲盜賊，公然抱茅入竹去。","脣焦口燥呼不得，歸來倚仗自歎息。","俄頃風定雲墨色，秋天漠漠向昏黑。","布衾多年冷似鐵，驕兒惡臥踏裏裂。","牀牀屋漏無乾處，雨脚如麻未斷絕。","自經喪亂少睡眠，長夜霑濕何由徹。","安得廣廈千萬間，大庇天下寒士俱歡顏。","風雨不動安如山，嗚呼！何時眼前突兀見此屋？","吾廬獨破受凍死亦足。"]', '["八月秋高风怒號，卷我屋上三重茅。","茅飞度江灑江郊，高者挂罥长林梢。","下者飄轉沈塘坳，南邨羣童欺我老無力。","忍能对面爲盜賊，公然抱茅入竹去。","脣焦口燥呼不得，归来倚仗自歎息。","俄頃风定云墨色，秋天漠漠向昏黑。","布衾多年冷似鐵，驕兒惡臥踏裏裂。","牀牀屋漏無乾处，雨脚如麻未斷絕。","自經喪亂少睡眠，长夜霑濕何由徹。","安得廣廈千万间，大庇天下寒士俱歡顏。","风雨不动安如山，嗚呼！何时眼前突兀见此屋？","吾廬独破受凍死亦足。"]', '诗', 'shi', '', NULL, '茅屋爲秋風所破歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc49c20-317b-4ef3-9b79-8229b5925fd9', '大雨', '大雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西蜀冬不雪，春農尚嗷嗷。","上天回哀眷，朱夏雲鬱陶。","執熱乃沸鼎，纖絺成緼袍。","風雷颯萬里，霈澤施蓬蒿。","敢辭茅葦漏，已喜黍豆高。","三日無行人，二江聲怒號。","流惡邑里清，矧茲遠江臯。","荒庭步鸛鶴，隱几望波濤。","沈疴聚藥餌，頓忘所進勞。","則知潤物功，可以貸不毛。","陰色靜隴畝，勸耕自官曹。","四鄰耒耜出，何必吾家操。"]', '["西蜀冬不雪，春農尚嗷嗷。","上天回哀眷，朱夏云鬱陶。","執熱乃沸鼎，纖絺成緼袍。","风雷颯万里，霈澤施蓬蒿。","敢辞茅葦漏，已喜黍豆高。","三日無行人，二江声怒號。","流惡邑里清，矧茲远江臯。","荒庭步鸛鹤，隐几望波濤。","沈疴聚藥餌，頓忘所進勞。","則知潤物功，可以貸不毛。","陰色静隴畝，勸耕自官曹。","四鄰耒耜出，何必吾家操。"]', '诗', 'shi', '', NULL, '大雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2284b2b3-acf3-4bb9-b736-de901b0967f9', '溪漲', '溪漲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["當時浣花橋，溪水纔尺餘。","白石明可把，水中有行車。","秋夏忽泛溢，豈惟入吾廬。","蛟龍亦狼狽，況是鼈與魚。","茲晨已半落，歸路跬步疎。","馬嘶未敢動，前有深填淤。","青青屋東麻，散亂牀上書。","不意遠山雨，夜來復何如。","我遊都市間，晚憩必邨墟。","乃知久行客，終日思其居。"]', '["當时浣花橋，溪水纔尺餘。","白石明可把，水中有行车。","秋夏忽泛溢，豈惟入吾廬。","蛟龙亦狼狽，況是鼈與鱼。","茲晨已半落，归路跬步疎。","马嘶未敢动，前有深填淤。","青青屋东麻，散亂牀上书。","不意远山雨，夜来复何如。","我游都市间，晚憩必邨墟。","乃知久行客，終日思其居。"]', '诗', 'shi', '', NULL, '溪漲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7d2d75-2f42-495c-adef-f37738b0f8d1', '戲贈友二首 一', '戲贈友二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["元年建巳月，郎有焦校書。","自誇足膂力，能騎生馬駒。","一朝被馬踏，脣裂版齒無。","壯心不肯已，欲得東擒胡。"]', '["元年建巳月，郎有焦校书。","自誇足膂力，能騎生马駒。","一朝被马踏，脣裂版齒無。","壯心不肯已，欲得东擒胡。"]', '诗', 'shi', '', NULL, '戲贈友二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c6007d-579e-4a76-9e11-e0fbd8d54d0a', '戲贈友二首 二', '戲贈友二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["元年建巳月，官有王司直。","馬驚折左臂，骨折面如墨。","駑駘漫深泥，何不避雨色。","勸君休歎恨，未必不爲福。"]', '["元年建巳月，官有王司直。","马驚折左臂，骨折面如墨。","駑駘漫深泥，何不避雨色。","勸君休歎恨，未必不爲福。"]', '诗', 'shi', '', NULL, '戲贈友二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c49fcc2-e014-4a5f-8b7b-bc592de83062', '遭田父泥飲美嚴中丞', '遭田父泥饮美嚴中丞', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["步屧隨春風，邨邨自花柳。","田翁逼社日，邀我嘗春酒。","酒酣誇新尹，畜眼未見有。","回頭指大男，渠是弓弩手。","名在飛騎籍，長番歲時久。","前日放營農，辛苦救衰朽。","差料死則已，誓不舉家走。","今年大作社，拾遺能住否。","叫婦開大缾，盆中爲吾取。","感此氣揚揚，須知風化首。","語多雖雜亂，說尹終在口。","朝來偶然出，自卯將及酉。","久客惜人情，如何拒鄰叟。","高聲索果栗，欲起時被肘。","指揮過無禮，未覺邨野醜。","月出遮我留，仍嗔問升斗。"]', '["步屧隨春风，邨邨自花柳。","田翁逼社日，邀我嘗春酒。","酒酣誇新尹，畜眼未见有。","回头指大男，渠是弓弩手。","名在飞騎籍，长番歲时久。","前日放營農，辛苦救衰朽。","差料死則已，誓不舉家走。","今年大作社，拾遺能住否。","叫婦开大缾，盆中爲吾取。","感此氣揚揚，須知风化首。","語多雖杂亂，说尹終在口。","朝来偶然出，自卯將及酉。","久客惜人情，如何拒鄰叟。","高声索果栗，欲起时被肘。","指揮過無禮，未覺邨野醜。","月出遮我留，仍嗔问升斗。"]', '诗', 'shi', '', NULL, '遭田父泥飲美嚴中丞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c4e10d-6c09-4fc2-a702-b55dbba16ee4', '喜雨', '喜雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春旱天地昏，日色赤如血。","農事都已休，兵戈況騷屑。","巴人困軍須，慟哭厚土熱。","滄江夜來雨，真宰罪一雪。","穀根小蘇息，沴氣終不滅。","何由見寧歲，解我憂思結。","崢嶸羣山雲，交會未斷絕。","安得鞭雷公，滂沱洗吳越。"]', '["春旱天地昏，日色赤如血。","農事都已休，兵戈況騷屑。","巴人困軍須，慟哭厚土熱。","滄江夜来雨，真宰罪一雪。","穀根小蘇息，沴氣終不滅。","何由见寧歲，解我憂思結。","崢嶸羣山云，交會未斷絕。","安得鞭雷公，滂沱洗吳越。"]', '诗', 'shi', '', NULL, '喜雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00e139f-4480-4c4a-afbf-5cdc94ad8714', '漁陽', '漁陽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漁陽突騎猶精銳，赫赫雍王都節制。","猛將飄然恐後時，本朝不入非高計。","祿山北築雄武城，舊防敗走歸其營。","繫書請問燕耆舊，今日何須十萬兵。"]', '["漁陽突騎猶精銳，赫赫雍王都節制。","猛將飄然恐後时，本朝不入非高計。","祿山北築雄武城，旧防敗走归其營。","繫书請问燕耆旧，今日何須十万兵。"]', '诗', 'shi', '', NULL, '漁陽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0bc117-6db3-4fe7-a7ac-6df03c52a62a', '天邊行', '天邊行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天邊老人歸未得，日暮東臨大江哭。","隴右河源不種田，胡騎羌兵入巴蜀。","洪濤滔天風拔木，前飛禿鶖後鴻鵠。","九度附書向洛陽，十年骨肉無消息。"]', '["天邊老人归未得，日暮东臨大江哭。","隴右河源不種田，胡騎羌兵入巴蜀。","洪濤滔天风拔木，前飞禿鶖後鴻鵠。","九度附书向洛陽，十年骨肉無消息。"]', '诗', 'shi', '', NULL, '天邊行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744dfdaa-67fa-4f01-9649-8e94cb50e16e', '大麥行', '大麦行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大麥乾枯小麥黃，婦女行泣夫走藏。","東至集壁西梁洋，問誰腰鐮胡與羌。","豈無蜀兵三千人，部領辛苦江山長。","安得如鳥有羽翅，托身白雲還故鄉。"]', '["大麦乾枯小麦黄，婦女行泣夫走藏。","东至集壁西梁洋，问誰腰鐮胡與羌。","豈無蜀兵三千人，部領辛苦江山长。","安得如鸟有羽翅，托身白云還故乡。"]', '诗', 'shi', '', NULL, '大麥行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30658953-4fd6-4433-9d53-632ddbdd6113', '苦戰行', '苦戰行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苦戰身死馬將軍，自云伏波之子孫。","干戈未定失壯士，使我歎恨傷精魂。","去年江南討狂賊，臨江把臂再難得。","別時孤雲今不飛，時獨看雲淚橫臆。"]', '["苦戰身死马將軍，自云伏波之子孫。","干戈未定失壯士，使我歎恨傷精魂。","去年江南討狂賊，臨江把臂再难得。","別时孤云今不飞，时独看云泪橫臆。"]', '诗', 'shi', '', NULL, '苦戰行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f7f097-466f-4f6a-b76f-96d443de7109', '去秋行', '去秋行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去秋涪江木落時，臂槍走馬誰家兒。","到今不知白骨處，部曲有去皆無歸。","遂州城中漢節在，遂州城外巴人稀。","戰場冤魂每夜哭，空令野營猛士悲。"]', '["去秋涪江木落时，臂槍走马誰家兒。","到今不知白骨处，部曲有去皆無归。","遂州城中漢節在，遂州城外巴人稀。","戰場冤魂每夜哭，空令野營猛士悲。"]', '诗', 'shi', '', NULL, '去秋行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cdab883-fb3c-408e-b908-c96abc8ddcd1', '述古三首 一', '述古三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["赤驥頓長纓，非無萬里姿。","悲鳴淚至地，爲問馭者誰。","鳳凰從東來，何意復高飛。","竹花不結實，念子忍朝飢。","古時君臣合，可以物理推。","賢人識定分，進退固其宜。"]', '["赤驥頓长纓，非無万里姿。","悲鳴泪至地，爲问馭者誰。","鳳凰從东来，何意复高飞。","竹花不結實，念子忍朝飢。","古时君臣合，可以物理推。","賢人識定分，進退固其宜。"]', '诗', 'shi', '', NULL, '述古三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751c9ca7-3522-455f-9af1-42be0901e4a9', '述古三首 二', '述古三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["市人日中集，於利競錐刀。","置膏烈火上，哀哀自煎熬。","農人望歲稔，相率除蓬蒿。","所務穀爲本，邪贏無乃勞。","舜舉十六相，身尊道何高。","秦時任商鞅，法令如牛毛。"]', '["市人日中集，於利競錐刀。","置膏烈火上，哀哀自煎熬。","農人望歲稔，相率除蓬蒿。","所務穀爲本，邪贏無乃勞。","舜舉十六相，身尊道何高。","秦时任商鞅，法令如牛毛。"]', '诗', 'shi', '', NULL, '述古三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0c9db7-7bbe-4d64-9fa6-e70fc28690d4', '述古三首 三', '述古三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢光得天下，祚永固有開。","豈惟高祖聖，功自蕭曹來。","經綸中興業，何代無長才。","吾慕寇鄧勳，濟時信良哉。","耿賈亦宗臣，羽翼共裴回。","休運終四百，圖畫在雲臺。"]', '["漢光得天下，祚永固有开。","豈惟高祖聖，功自蕭曹来。","經綸中兴業，何代無长才。","吾慕寇鄧勳，濟时信良哉。","耿賈亦宗臣，羽翼共裴回。","休運終四百，圖畫在云台。"]', '诗', 'shi', '', NULL, '述古三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ddd5e1f-b4a4-4973-a9ac-d379dd22ff8e', '觀打魚歌', '观打鱼歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["緜州江水之東津，魴魚鱍鱍色勝銀。","漁人漾舟沈大網，截江一擁數百鱗。","衆魚常才盡却棄，赤鯉騰出如有神。","潛龍無聲老蛟怒，回風颯颯吹沙塵。","饔子左右揮雙刀，膾飛金盤白雪高。","徐州禿尾不足憶，漢陰槎頭遠遁逃。","魴魚肥美知第一，既飽歡娛亦蕭瑟。","君不朝來割素鬐，咫尺波濤永相失。"]', '["緜州江水之东津，魴鱼鱍鱍色勝銀。","漁人漾舟沈大網，截江一擁數百鱗。","衆鱼常才尽却棄，赤鯉腾出如有神。","潛龙無声老蛟怒，回风颯颯吹沙塵。","饔子左右揮雙刀，膾飞金盤白雪高。","徐州禿尾不足憶，漢陰槎头远遁逃。","魴鱼肥美知第一，既飽歡娛亦蕭瑟。","君不朝来割素鬐，咫尺波濤永相失。"]', '诗', 'shi', '', NULL, '觀打魚歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c132205d-193f-4bf9-be2f-6c58f53a9853', '又觀打魚', '又观打鱼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蒼江魚子清晨集，設網提綱萬魚急。","能者操舟疾若風，撐突波濤挺叉入。","小魚脫漏不可記，半死半生猶戢戢。","大魚傷損皆垂頭，屈強泥沙有時立。","東津觀魚已再來，主人罷鱠還傾杯。","日暮蛟龍改窟穴，山根鱣鮪隨雲雷。","干戈兵革鬬未止，鳳凰麒麟安在哉？","吾徒胡爲縱此樂，暴殄天物聖所哀。"]', '["蒼江鱼子清晨集，設網提綱万鱼急。","能者操舟疾若风，撐突波濤挺叉入。","小鱼脫漏不可記，半死半生猶戢戢。","大鱼傷損皆垂头，屈強泥沙有时立。","东津观鱼已再来，主人罷鱠還傾杯。","日暮蛟龙改窟穴，山根鱣鮪隨云雷。","干戈兵革鬬未止，鳳凰麒麟安在哉？","吾徒胡爲縱此乐，暴殄天物聖所哀。"]', '诗', 'shi', '', NULL, '又觀打魚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c48eae-6285-411b-af3d-bb24b2520d4e', '越王樓歌', '越王楼歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["緜州州府何磊落，顯慶年中越王作。","孤城西北起高樓，碧瓦朱甍照城郭。","樓下長江百丈清，山頭落日半輪明。","君王舊跡今人賞，轉見千秋萬古情。"]', '["緜州州府何磊落，显慶年中越王作。","孤城西北起高楼，碧瓦朱甍照城郭。","楼下长江百丈清，山头落日半輪明。","君王旧跡今人賞，轉见千秋万古情。"]', '诗', 'shi', '', NULL, '越王樓歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca529f2-4ffa-4317-8f3e-21ed7b78a990', '海棕行', '海棕行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["左緜公館清江濆，海棕一株高入雲。","龍鱗犀甲相錯落，蒼稜白皮十抱文。","自是衆木亂紛紛，海棕焉知身出羣。","移栽北辰不可得，時有西域胡僧識。"]', '["左緜公館清江濆，海棕一株高入云。","龙鱗犀甲相錯落，蒼稜白皮十抱文。","自是衆木亂紛紛，海棕焉知身出羣。","移栽北辰不可得，时有西域胡僧識。"]', '诗', 'shi', '', NULL, '海棕行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db1915e5-10c1-40bd-89b7-ea85299fd569', '姜楚公畫角鷹歌', '姜楚公畫角鷹歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚公畫鷹鷹戴角，殺氣森森到幽朔。","觀者貪愁掣臂飛，畫師不是無心學。","此鷹寫真在左緜，却嗟真骨遂虛傳。","梁間燕雀休驚怕，亦未摶空上九天。"]', '["楚公畫鷹鷹戴角，殺氣森森到幽朔。","观者貪愁掣臂飞，畫師不是無心学。","此鷹寫真在左緜，却嗟真骨遂虛傳。","梁间燕雀休驚怕，亦未摶空上九天。"]', '诗', 'shi', '', NULL, '姜楚公畫角鷹歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c77587-617f-4389-b566-98d7279a8669', '相逢歌贈嚴二別駕', '相逢歌贈嚴二別駕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我行入東川，十步一回首。","城都亂罷氣蕭颯，浣花草堂亦何有。","梓中豪俊大者誰，本州從事知名久。","把臂開尊飲我酒，酒酣擊劒蛟龍吼。","烏帽拂塵青螺粟，紫衣將炙緋衣走。","銅盤燒蠟光吐日，夜如何其初促膝。","黃昏始扣主人門，誰謂俄頃膠在漆。","萬事盡付形骸外，百年未見歡娛畢。","神傾意豁真佳士，久客多憂今愈疾。","高視乾坤又可愁，一軀交態同悠悠。","垂老遇君未恨晚，似君須向古人求。"]', '["我行入东川，十步一回首。","城都亂罷氣蕭颯，浣花草堂亦何有。","梓中豪俊大者誰，本州從事知名久。","把臂开尊饮我酒，酒酣擊劒蛟龙吼。","烏帽拂塵青螺粟，紫衣將炙緋衣走。","銅盤燒蠟光吐日，夜如何其初促膝。","黄昏始扣主人门，誰謂俄頃膠在漆。","万事尽付形骸外，百年未见歡娛畢。","神傾意豁真佳士，久客多憂今愈疾。","高視乾坤又可愁，一軀交態同悠悠。","垂老遇君未恨晚，似君須向古人求。"]', '诗', 'shi', '', NULL, '相逢歌贈嚴二別駕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac4ee7e4-1e08-456e-a693-c04a4254c5c9', '光祿坂行', '光祿坂行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山行落日下絕壁，西望千山萬山赤。","樹枝有鳥亂鳴時，暝色無人獨歸客。","馬驚不憂深谷墜，草動只怕長弓射。","安得更似開元中，道路即今多擁隔。"]', '["山行落日下絕壁，西望千山万山赤。","樹枝有鸟亂鳴时，暝色無人独归客。","马驚不憂深谷墜，草动只怕长弓射。","安得更似开元中，道路即今多擁隔。"]', '诗', 'shi', '', NULL, '光祿坂行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8073152d-7f39-430b-93d2-24a9f7fc5323', '冬到金華山觀因得故拾遺陳公學堂遺跡', '冬到金华山观因得故拾遺陳公学堂遺跡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["涪右衆山內，金華紫崔嵬。","上有蔚藍天，垂光抱瓊臺。","繫舟接絕壁，杖策窮縈回。","四顧俯層巔，澹然川谷開。","雪嶺日色死，霜鴻有餘哀。","焚香玉女跪，霧裏仙人來。","陳公讀書堂，石柱仄青苔。","悲風爲我起，激烈傷雄才。"]', '["涪右衆山內，金华紫崔嵬。","上有蔚藍天，垂光抱瓊台。","繫舟接絕壁，杖策窮縈回。","四顧俯層巔，澹然川谷开。","雪嶺日色死，霜鴻有餘哀。","焚香玉女跪，霧裏仙人来。","陳公读书堂，石柱仄青苔。","悲风爲我起，激烈傷雄才。"]', '诗', 'shi', '', NULL, '冬到金華山觀因得故拾遺陳公學堂遺跡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b6faa1-eb87-421e-95e5-8733a10bd9e4', '陳拾遺故宅', '陳拾遺故宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["拾遺平昔居，大屋尚修椽。","悠揚荒山日，慘澹故園煙。","位下曷足傷，所貴者聖賢。","有才繼騷雅，哲匠不比肩。","公生揚馬後，名與日月懸。","同遊英俊人，多秉輔佐權。","彥昭超玉價，郭振起通泉。","到今素壁滑，灑翰銀鉤連。","盛事會一時，此堂豈千年。","終古立忠義，感遇有遺編。"]', '["拾遺平昔居，大屋尚修椽。","悠揚荒山日，慘澹故园煙。","位下曷足傷，所貴者聖賢。","有才繼騷雅，哲匠不比肩。","公生揚马後，名與日月懸。","同游英俊人，多秉輔佐權。","彥昭超玉價，郭振起通泉。","到今素壁滑，灑翰銀鉤連。","盛事會一时，此堂豈千年。","終古立忠義，感遇有遺編。"]', '诗', 'shi', '', NULL, '陳拾遺故宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda39e90-fcb0-4a37-8565-a8b31a46681f', '謁文公上方', '謁文公上方', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野寺隱喬木，山僧高下居。","石門日色異，絳氣橫扶疎。","窈窕入風磴，長蘆紛卷舒。","庭前猛虎臥，遂得文公廬。","俯視萬家邑，煙塵對階除。","吾師雨花外，不下十年餘。","長者自布金，禪龕只晏如。","大珠脫玷翳，白月當空虛。","甫也南北人，蕪蔓少耘鋤。","久遭詩酒污，何事忝簪裾。","王侯與螻蟻，同盡隨丘墟。","願聞第一義，回向心地初。","金篦刮眼膜，價重百車渠。","無生有汲引，茲理儻吹噓。"]', '["野寺隐喬木，山僧高下居。","石门日色異，絳氣橫扶疎。","窈窕入风磴，长蘆紛卷舒。","庭前猛虎臥，遂得文公廬。","俯視万家邑，煙塵对階除。","吾師雨花外，不下十年餘。","长者自布金，禪龕只晏如。","大珠脫玷翳，白月當空虛。","甫也南北人，蕪蔓少耘鋤。","久遭诗酒污，何事忝簪裾。","王侯與螻蟻，同尽隨丘墟。","願闻第一義，回向心地初。","金篦刮眼膜，價重百车渠。","無生有汲引，茲理儻吹噓。"]', '诗', 'shi', '', NULL, '謁文公上方 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f91037-5eae-4988-a135-88b6607ddac5', '奉贈射洪李四丈', '奉贈射洪李四丈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丈人屋上烏，人好烏亦好。","人生意氣豁，不在相逢早。","南京亂初定，所向邑枯槁。","遊子無根株，茅齋付秋草。","東征下月峽，挂席窮海島。","萬里須十金，妻孥未相保。","蒼茫風塵際，蹭蹬騏驎老。","志士懷感傷，心胸已傾倒。"]', '["丈人屋上烏，人好烏亦好。","人生意氣豁，不在相逢早。","南京亂初定，所向邑枯槁。","游子無根株，茅斋付秋草。","东征下月峽，挂席窮海島。","万里須十金，妻孥未相保。","蒼茫风塵際，蹭蹬騏驎老。","志士懷感傷，心胸已傾倒。"]', '诗', 'shi', '', NULL, '奉贈射洪李四丈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f12206-3250-4fe8-be2a-7d2b64b5e9b9', '早發射洪縣南途中作', '早發射洪縣南途中作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["將老憂貧窶，筋力豈能及。","征途乃侵星，得使諸病入。","鄙人寡道氣，在困無獨立。","俶裝逐徒旅，達曙凌險澀。","寒日出霧遲，清江轉山急。","僕夫行不進，駑馬若維縶。","汀洲稍疏散，風景開怏悒。","空慰所尚懷，終非曩遊集。","衰顏偶一破，勝事難屢挹。","茫然阮籍途，更灑楊朱泣。"]', '["將老憂貧窶，筋力豈能及。","征途乃侵星，得使諸病入。","鄙人寡道氣，在困無独立。","俶裝逐徒旅，達曙凌險澀。","寒日出霧遲，清江轉山急。","僕夫行不進，駑马若維縶。","汀洲稍疏散，风景开怏悒。","空慰所尚懷，終非曩游集。","衰顏偶一破，勝事难屢挹。","茫然阮籍途，更灑楊朱泣。"]', '诗', 'shi', '', NULL, '早發射洪縣南途中作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7650f439-72a5-4680-901f-72e235c36aab', '通泉驛南去通泉縣十五里山水作', '通泉驛南去通泉縣十五里山水作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["溪行衣自濕，亭午氣始散。","冬溫蚊蚋在，人遠鳧鴨亂。","登頓生曾陰，攲傾出高岸。","驛樓衰柳側，縣郭輕煙畔。","一川何綺麗，盡目窮壯觀。","山色遠寂寞，江光夕滋漫。","傷時媿孔父，去國同王粲。","我生苦飄零，所歷有嗟歎。"]', '["溪行衣自濕，亭午氣始散。","冬溫蚊蚋在，人远鳧鴨亂。","登頓生曾陰，攲傾出高岸。","驛楼衰柳側，縣郭轻煙畔。","一川何綺丽，尽目窮壯观。","山色远寂寞，江光夕滋漫。","傷时媿孔父，去国同王粲。","我生苦飄零，所歷有嗟歎。"]', '诗', 'shi', '', NULL, '通泉驛南去通泉縣十五里山水作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eed81ff-a045-4b87-b6c1-d1701c0361cc', '過郭代公故宅', '過郭代公故宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["豪俊初未遇，其跡或脫略。","代公尉通泉，放意何自若。","及夫登衮冕，直氣森噴薄。","磊落見異人，豈伊常情度。","定策神龍後，宮中翕清廓。","俄頃辨尊親，指揮存顧託。","羣公有慙色，王室無削弱。","迥出名臣上，丹青照臺閣。","我行得遺跡，池館皆疏鑿。","壯公臨事斷，顧步涕橫落。","高詠寶劒篇，神交付冥漠。"]', '["豪俊初未遇，其跡或脫略。","代公尉通泉，放意何自若。","及夫登衮冕，直氣森噴薄。","磊落见異人，豈伊常情度。","定策神龙後，宮中翕清廓。","俄頃辨尊親，指揮存顧託。","羣公有慙色，王室無削弱。","迥出名臣上，丹青照台閣。","我行得遺跡，池館皆疏鑿。","壯公臨事斷，顧步涕橫落。","高詠寶劒篇，神交付冥漠。"]', '诗', 'shi', '', NULL, '過郭代公故宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0975c2-29c3-47d1-a8d4-5653488ca009', '觀薛稷少保書畫壁', '观薛稷少保书畫壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["少保有古風，得之陝郊篇。","惜哉功名忤，但見書畫傳。","我游梓州東，遺跡涪江邊。","畫藏青蓮界，書入金牓懸。","仰看垂露姿，不崩亦不騫。","鬱鬱三大字，蛟龍岌相纏。","又揮西方變，發地扶屋椽。","慘澹壁飛動，到今色未填。","此行疊壯觀，郭薛俱才賢。","不知百載後，誰復來通泉。"]', '["少保有古风，得之陝郊篇。","惜哉功名忤，但见书畫傳。","我游梓州东，遺跡涪江邊。","畫藏青蓮界，书入金牓懸。","仰看垂露姿，不崩亦不騫。","鬱鬱三大字，蛟龙岌相纏。","又揮西方变，發地扶屋椽。","慘澹壁飞动，到今色未填。","此行叠壯观，郭薛俱才賢。","不知百載後，誰复来通泉。"]', '诗', 'shi', '', NULL, '觀薛稷少保書畫壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8fe6c90-8cf4-4aa7-ba1d-6b4c2a1f481c', '通泉縣署屋壁後薛少保畫鶴', '通泉縣署屋壁後薛少保畫鹤', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["薛公十一鶴，皆寫青田真。","畫色久欲盡，蒼然猶出塵。","低昂各有意，磊落如長人。","佳此志氣遠，豈惟粉墨新。","萬里不以力，羣遊森會神。","威遲白鳳態，非是倉庚鄰。","高堂未傾覆，常得慰嘉賓。","曝露牆壁外，終嗟風雨頻。","赤霄有真骨，恥飲洿池津。","冥冥任所往，脫略誰能馴。"]', '["薛公十一鹤，皆寫青田真。","畫色久欲尽，蒼然猶出塵。","低昂各有意，磊落如长人。","佳此志氣远，豈惟粉墨新。","万里不以力，羣游森會神。","威遲白鳳態，非是倉庚鄰。","高堂未傾覆，常得慰嘉賓。","曝露牆壁外，終嗟风雨頻。","赤霄有真骨，恥饮洿池津。","冥冥任所往，脫略誰能馴。"]', '诗', 'shi', '', NULL, '通泉縣署屋壁後薛少保畫鶴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e19627-4051-46fc-806c-da3defb76cd1', '陪王侍御同登東山最高頂宴姚通泉晚攜酒泛江', '陪王侍御同登东山最高頂宴姚通泉晚携酒泛江', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["姚公美政誰與儔，不減昔時陳太丘。","邑中上客有柱史，多暇日陪驄馬遊。","東山高頂羅珍羞，下顧城郭銷我憂。","清江白日落欲盡，復攜美人登綵舟。","笛聲憤怨哀中流，妙舞逶迤夜未休。","燈前往往大魚出，聽曲低昂如有求。","三更風起寒浪湧，取樂喧呼覺船重。","滿空星河光破碎，四座賓客色不動。","請公臨深莫相違，回船罷酒上馬歸。","人生歡會豈有極，無使霜過霑人衣。"]', '["姚公美政誰與儔，不減昔时陳太丘。","邑中上客有柱史，多暇日陪驄马游。","东山高頂羅珍羞，下顧城郭銷我憂。","清江白日落欲尽，复携美人登綵舟。","笛声憤怨哀中流，妙舞逶迤夜未休。","灯前往往大鱼出，听曲低昂如有求。","三更风起寒浪湧，取乐喧呼覺船重。","满空星河光破碎，四座賓客色不动。","請公臨深莫相違，回船罷酒上马归。","人生歡會豈有極，無使霜過霑人衣。"]', '诗', 'shi', '', NULL, '陪王侍御同登東山最高頂宴姚通泉晚攜酒泛江 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac1658d-0e0a-4a87-b599-6dffb7abcfbe', '春日戲題惱郝使君兄', '春日戲題惱郝使君兄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["使君意氣凌青霄，憶昨歡娛常見招。","細馬時鳴金騕褭，佳人屢出董驕饒。","東流江水西飛燕，可惜春光不相見。","願攜王趙兩紅顏，再騁肌膚如素練。","通泉百里近梓州，請公一來開我愁。","舞處重看花滿面，尊前還有錦纏頭。"]', '["使君意氣凌青霄，憶昨歡娛常见招。","細马时鳴金騕褭，佳人屢出董驕饒。","东流江水西飞燕，可惜春光不相见。","願携王趙兩紅顏，再騁肌膚如素練。","通泉百里近梓州，請公一来开我愁。","舞处重看花满面，尊前還有錦纏头。"]', '诗', 'shi', '', NULL, '春日戲題惱郝使君兄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d187686-9944-4690-bc0c-5716539e1a1d', '短歌行贈王郎司直', '短歌行贈王郎司直', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["王郎酒酣拔劒斫地歌莫哀，我能拔爾抑塞磊落之奇才。","豫章翻風白日動，鯨魚跋浪滄溟開。","且脫佩劒休裴回，西得諸侯櫂錦水。","欲向何門趿珠履，仲宣樓頭春色深。","青眼高歌望吾子，眼中之人吾老矣。"]', '["王郎酒酣拔劒斫地歌莫哀，我能拔爾抑塞磊落之奇才。","豫章翻风白日动，鯨鱼跋浪滄溟开。","且脫佩劒休裴回，西得諸侯櫂錦水。","欲向何门趿珠履，仲宣楼头春色深。","青眼高歌望吾子，眼中之人吾老矣。"]', '诗', 'shi', '', NULL, '短歌行贈王郎司直 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1ada7f0-b14f-4660-8811-aaf1b4a6b67b', '短歌行送祁錄事歸合州因寄蘇使君', '短歌行送祁錄事归合州因寄蘇使君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["前者途中一相見，人事經年記君面。","後生相動何寂寥，君有長才不貧賤。","君今起柁春江流，余亦沙邊具小舟。","幸爲達書賢府主，江花未盡會江樓。"]', '["前者途中一相见，人事經年記君面。","後生相动何寂寥，君有长才不貧賤。","君今起柁春江流，余亦沙邊具小舟。","幸爲達书賢府主，江花未尽會江楼。"]', '诗', 'shi', '', NULL, '短歌行送祁錄事歸合州因寄蘇使君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b62d8e7-b536-450c-978d-edbe5e7a4db3', '陪章留後惠義寺餞嘉州崔都督赴州', '陪章留後惠義寺餞嘉州崔都督赴州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中軍待上客，令肅事有恒。","前驅入寶地，祖帳飄金繩。","南陌既留歡，茲山亦深登。","清聞樹杪磬，遠謁雲端僧。","回策匪新岸，所攀仍舊藤。","耳激洞門飆，目存寒谷冰。","出塵閟軌躅，畢景遺炎蒸。","永願坐長夏，將衰棲大乘。","羈旅惜宴會，艱難懷友朋。","勞生共幾何，離恨兼相仍。"]', '["中軍待上客，令肅事有恒。","前驱入寶地，祖帳飄金繩。","南陌既留歡，茲山亦深登。","清闻樹杪磬，远謁云端僧。","回策匪新岸，所攀仍旧藤。","耳激洞门飆，目存寒谷冰。","出塵閟軌躅，畢景遺炎蒸。","永願坐长夏，將衰棲大乘。","羈旅惜宴會，艱难懷友朋。","勞生共幾何，離恨兼相仍。"]', '诗', 'shi', '', NULL, '陪章留後惠義寺餞嘉州崔都督赴州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea100f9a-3504-4a7d-844c-c23ba23f364b', '將適吳楚留別章使君留後兼幕府諸公得柳字', '將適吳楚留別章使君留後兼幕府諸公得柳字', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我來入蜀門，歲月亦已久。","豈惟長兒童，自覺成老醜。","常恐性坦率，失身爲杯酒。","近辭痛飲徒，折節萬夫後。","昔如縱壑魚，今如喪家狗。","既無遊方戀，行止復何有。","相逢半新故，取別隨薄厚。","不意青草湖，扁舟落吾手。","眷眷章梓州，開筵俯高柳。","樓前出騎馬，帳下羅賓友。","健兒簸紅旗，此樂或難朽。","日車隱崑崙，鳥雀噪戶牖。","波濤未足畏，三峽徒雷吼。","所憂盜賊多，重見衣冠走。","中原消息斷，黃屋今安否。","終作適荆蠻，安排用莊叟。","隨雲拜東皇，挂席上南斗。","有使即寄書，無使長回首。"]', '["我来入蜀门，歲月亦已久。","豈惟长兒童，自覺成老醜。","常恐性坦率，失身爲杯酒。","近辞痛饮徒，折節万夫後。","昔如縱壑鱼，今如喪家狗。","既無游方戀，行止复何有。","相逢半新故，取別隨薄厚。","不意青草湖，扁舟落吾手。","眷眷章梓州，开筵俯高柳。","楼前出騎马，帳下羅賓友。","健兒簸紅旗，此乐或难朽。","日车隐崑崙，鸟雀噪戶牖。","波濤未足畏，三峽徒雷吼。","所憂盜賊多，重见衣冠走。","中原消息斷，黄屋今安否。","終作適荆蠻，安排用莊叟。","隨云拜东皇，挂席上南斗。","有使即寄书，無使长回首。"]', '诗', 'shi', '', NULL, '將適吳楚留別章使君留後兼幕府諸公得柳字 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f7c1809-1a9e-4192-a02f-34ae18101cc4', '山寺', '山寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野寺根石壁，諸龕徧崔嵬。","前佛不復辨，百身一莓苔。","雖有古殿存，世尊亦塵埃。","如聞龍象泣，足令信者哀。","使君騎紫馬，捧擁從西來。","樹羽靜千里，臨江久裴回。","山僧衣藍縷，告訴棟梁摧。","公爲顧賓徒，咄嗟檀施開。","吾知多羅樹，却倚蓮華臺。","諸天必歡喜，鬼物無嫌猜。","以茲撫士卒，孰曰非周才。","窮子失淨處，高人憂禍胎。","歲晏風破肉，荒林寒可迴。","思量入道苦，自哂同嬰孩。"]', '["野寺根石壁，諸龕徧崔嵬。","前佛不复辨，百身一莓苔。","雖有古殿存，世尊亦塵埃。","如闻龙象泣，足令信者哀。","使君騎紫马，捧擁從西来。","樹羽静千里，臨江久裴回。","山僧衣藍縷，告訴棟梁摧。","公爲顧賓徒，咄嗟檀施开。","吾知多羅樹，却倚蓮华台。","諸天必歡喜，鬼物無嫌猜。","以茲撫士卒，孰曰非周才。","窮子失淨处，高人憂禍胎。","歲晏风破肉，荒林寒可迴。","思量入道苦，自哂同嬰孩。"]', '诗', 'shi', '', NULL, '山寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704494b5-291d-4f04-a07c-ac2a0c754edc', '椶拂子', '椶拂子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["椶拂且薄陋，豈知身效能。","不堪代白羽，有足除蒼蠅。","熒熒金錯刀，擢擢朱絲蠅。","非獨顏色好，亦用顧盼稱。","吾老抱疾病，家貧臥炎蒸。","咂膚倦撲滅，賴爾甘服膺。","物微世競棄，義在誰肯徵。","三歲清秋至，未敢闕緘藤。"]', '["椶拂且薄陋，豈知身效能。","不堪代白羽，有足除蒼蠅。","熒熒金錯刀，擢擢朱絲蠅。","非独顏色好，亦用顧盼稱。","吾老抱疾病，家貧臥炎蒸。","咂膚倦撲滅，賴爾甘服膺。","物微世競棄，義在誰肯徵。","三歲清秋至，未敢闕緘藤。"]', '诗', 'shi', '', NULL, '椶拂子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87600c40-eb40-430b-ac24-351551bbff5b', '桃竹杖引贈章留後', '桃竹杖引贈章留後', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江心蟠石生桃竹，蒼波噴浸尺度足。","斬根削皮如紫玉，江妃水仙惜不得。","梓潼使君開一束，滿堂賓客皆歎息。","憐我老病贈兩莖，出入爪甲鏗有聲。","老夫復欲東南征，乘濤鼓枻白帝城。","路幽必爲鬼神奪，拔劒或與蛟龍爭。","重爲告曰，杖兮！杖兮！爾之生也甚正直，慎勿見水踴躍學變化爲龍。","使我不得爾之扶持，滅跡於君山湖上之青峰。","噫！風塵澒洞兮豺虎齩人，忽失雙杖兮吾將曷從。"]', '["江心蟠石生桃竹，蒼波噴浸尺度足。","斬根削皮如紫玉，江妃水仙惜不得。","梓潼使君开一束，满堂賓客皆歎息。","怜我老病贈兩莖，出入爪甲鏗有声。","老夫复欲东南征，乘濤鼓枻白帝城。","路幽必爲鬼神奪，拔劒或與蛟龙爭。","重爲告曰，杖兮！杖兮！爾之生也甚正直，慎勿见水踴躍学变化爲龙。","使我不得爾之扶持，滅跡於君山湖上之青峰。","噫！风塵澒洞兮豺虎齩人，忽失雙杖兮吾將曷從。"]', '诗', 'shi', '', NULL, '桃竹杖引贈章留後 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0003f6ab-a650-4728-acf0-7d248dd3ca3c', '寄題江外草堂', '寄題江外草堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我生性放誕，雅欲逃自然。","嗜酒愛風竹，卜居必林泉。","遭亂到蜀江，臥疴遣所便。","誅茅初一畝，廣地方連延。","經營上元始，斷手寶應年。","敢謀土木麗，自覺面勢堅。","臺亭隨高下，敞豁當清川。","雖有會心侶，數能同釣船。","干戈未偃息，安得酣歌眠。","蛟龍無定窟，黃鵠摩蒼天。","古來達士志，寧受外物牽。","顧惟魯鈍姿，豈識悔吝先。","偶攜老妻去，慘澹凌風煙。","事跡無固必，幽貞媿雙全。","尚念四小松，蔓草易拘纏。","霜骨不甚長，永爲鄰里憐。"]', '["我生性放誕，雅欲逃自然。","嗜酒愛风竹，卜居必林泉。","遭亂到蜀江，臥疴遣所便。","誅茅初一畝，廣地方連延。","經營上元始，斷手寶應年。","敢謀土木丽，自覺面勢堅。","台亭隨高下，敞豁當清川。","雖有會心侶，數能同釣船。","干戈未偃息，安得酣歌眠。","蛟龙無定窟，黄鵠摩蒼天。","古来達士志，寧受外物牽。","顧惟魯鈍姿，豈識悔吝先。","偶携老妻去，慘澹凌风煙。","事跡無固必，幽貞媿雙全。","尚念四小松，蔓草易拘纏。","霜骨不甚长，永爲鄰里怜。"]', '诗', 'shi', '', NULL, '寄題江外草堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827e44b1-7064-4ff7-9a9c-192eece94e2d', '韋諷錄事宅觀曹將軍畫馬圖', '韋諷錄事宅观曹將軍畫马圖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["國初已來畫鞍馬，神妙獨數江都王。","將軍得名三十載，人間又見真乘黃。","曾貌先帝照夜白，龍池十日飛霹靂。","內府殷紅馬腦盌，倢伃傳詔才人索。","盌賜將軍拜舞歸，輕紈細綺相追飛。","貴戚權門得筆跡，始覺屏障生光輝。","昔日太宗拳毛騧，近時郭家師子花。","今之新圖有二馬，復令識者久歎嗟。","此皆騎戰一敵萬，縞素漠漠開風沙。","其餘七匹亦殊絕，迥若寒空動煙雪。","霜蹄蹴踏長楸間，馬官廝養森成列。","可憐九馬爭神駿，顧視清高氣深穩。","借問苦心愛者誰，後有韋諷前支遁。","憶昔巡幸新豐宮，翠華拂天來向東。","騰驤磊落三萬匹，皆與此圖筋骨同。","自從獻寶朝河宗，無復射蛟江水中。","君不見金粟堆前松柏裏，龍媒去盡鳥呼風。"]', '["国初已来畫鞍马，神妙独數江都王。","將軍得名三十載，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹靂。","內府殷紅马腦盌，倢伃傳詔才人索。","盌賜將軍拜舞归，轻紈細綺相追飞。","貴戚權门得笔跡，始覺屏障生光輝。","昔日太宗拳毛騧，近时郭家師子花。","今之新圖有二马，复令識者久歎嗟。","此皆騎戰一敵万，縞素漠漠开风沙。","其餘七匹亦殊絕，迥若寒空动煙雪。","霜蹄蹴踏长楸间，马官廝養森成列。","可怜九马爭神駿，顧視清高氣深穩。","借问苦心愛者誰，後有韋諷前支遁。","憶昔巡幸新豐宮，翠华拂天来向东。","腾驤磊落三万匹，皆與此圖筋骨同。","自從獻寶朝河宗，無复射蛟江水中。","君不见金粟堆前松柏裏，龙媒去尽鸟呼风。"]', '诗', 'shi', '', NULL, '韋諷錄事宅觀曹將軍畫馬圖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7109feaf-91db-4b77-a50e-3e71c6a4c66c', '送韋諷上閬州錄事參軍', '送韋諷上閬州錄事參軍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["國步猶艱難，兵革未衰息。","萬方哀嗷嗷，十載供軍食。","庶官務割剝，不暇憂反側。","誅求何多門，賢者貴爲德。","韋生富春秋，洞徹有清識。","操持紀綱地，喜見朱絲直。","當令豪奪吏，自此無顏色。","必若救瘡痍，先應去蟊賊。","揮淚臨大江，高天意悽惻。","行行樹佳政，慰我深相憶。"]', '["国步猶艱难，兵革未衰息。","万方哀嗷嗷，十載供軍食。","庶官務割剝，不暇憂反側。","誅求何多门，賢者貴爲德。","韋生富春秋，洞徹有清識。","操持紀綱地，喜见朱絲直。","當令豪奪吏，自此無顏色。","必若救瘡痍，先應去蟊賊。","揮泪臨大江，高天意悽惻。","行行樹佳政，慰我深相憶。"]', '诗', 'shi', '', NULL, '送韋諷上閬州錄事參軍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b12259-3750-4c6d-87ee-35283ad63dab', '丹青引贈曹將軍霸', '丹青引贈曹將軍霸', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["將軍魏武之子孫，於今爲庶爲清門。","英雄割據雖已矣，文彩風流猶尚存。","學書初學衛夫人，但恨無過王右軍。","丹青不知老將至，富貴於我如浮雲。","開元之中常引見，承恩數上南熏殿。","凌煙功臣少顏色，將軍下筆開生面。","良相頭上進賢冠，猛將腰間大羽箭。","褒公鄂公毛髮動英姿颯爽來酣戰。","先帝天馬玉花驄，畫工如山貌不同。","是日牽來赤墀下，迥立閶闔生長風。","詔謂將軍拂絹素，意匠慘澹經營中。","斯須九重真龍出，一洗萬古凡馬空。","玉花却在御榻上，榻上庭前屹相向。","至尊含笑催賜金，圉人太僕皆惆悵。","弟子韓幹早入室，亦能畫馬窮殊相。","幹惟畫肉不畫骨，忍使驊騮氣凋喪。","將軍畫善蓋有神，必逢佳士亦寫真。","即今飄泊干戈際，屢貌尋常行路人。","途窮反遭俗眼白，世上未有如公貧。","但看古來盛名下，終日坎壈纏其身。"]', '["將軍魏武之子孫，於今爲庶爲清门。","英雄割據雖已矣，文彩风流猶尚存。","学书初学衛夫人，但恨無過王右軍。","丹青不知老將至，富貴於我如浮云。","开元之中常引见，承恩數上南熏殿。","凌煙功臣少顏色，將軍下笔开生面。","良相头上進賢冠，猛將腰间大羽箭。","褒公鄂公毛髮动英姿颯爽来酣戰。","先帝天马玉花驄，畫工如山貌不同。","是日牽来赤墀下，迥立閶闔生长风。","詔謂將軍拂絹素，意匠慘澹經營中。","斯須九重真龙出，一洗万古凡马空。","玉花却在御榻上，榻上庭前屹相向。","至尊含笑催賜金，圉人太僕皆惆悵。","弟子韓幹早入室，亦能畫马窮殊相。","幹惟畫肉不畫骨，忍使驊騮氣凋喪。","將軍畫善蓋有神，必逢佳士亦寫真。","即今飄泊干戈際，屢貌尋常行路人。","途窮反遭俗眼白，世上未有如公貧。","但看古来盛名下，終日坎壈纏其身。"]', '诗', 'shi', '', NULL, '丹青引贈曹將軍霸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3553a22-2323-4926-a694-752c3481e2a5', '閬州東樓筵奉送十一舅往青城縣得昏字', '閬州东楼筵奉送十一舅往青城縣得昏字', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["曾城有高樓，制古丹雘存。","迢迢百餘尺，豁達開四門。","雖有車馬客，而無人世喧。","遊目俯大江，列筵慰別魂。","是時秋冬交，節往顏色昏。","天寒鳥獸休，霜露在草根。","今我送舅氏，萬感集清尊。","豈伊山川間，回首盜賊繁。","高賢意不暇，王命久崩奔。","臨風欲慟哭，聲出已復吞。"]', '["曾城有高楼，制古丹雘存。","迢迢百餘尺，豁達开四门。","雖有车马客，而無人世喧。","游目俯大江，列筵慰別魂。","是时秋冬交，節往顏色昏。","天寒鸟獸休，霜露在草根。","今我送舅氏，万感集清尊。","豈伊山川间，回首盜賊繁。","高賢意不暇，王命久崩奔。","臨风欲慟哭，声出已复吞。"]', '诗', 'shi', '', NULL, '閬州東樓筵奉送十一舅往青城縣得昏字 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf6124b-d0ca-48b1-9b9a-c62824a7d759', '嚴氏溪放歌行', '嚴氏溪放歌行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天下甲馬未盡銷，豈免溝壑常漂漂。","劒南歲月不可度，邊頭公卿仍獨驕。","費心姑息是一役，肥肉大酒徒相要。","嗚呼古人已糞土，獨覺志士甘漁樵。","況我飄轉無定所，終日慽慽忍羈旅。","秋宿霜溪素月高，喜得與子長夜語。","東遊西還力實倦，從此將身更何許。","知子松根長茯苓，遲暮有有意來同煮。"]', '["天下甲马未尽銷，豈免溝壑常漂漂。","劒南歲月不可度，邊头公卿仍独驕。","費心姑息是一役，肥肉大酒徒相要。","嗚呼古人已糞土，独覺志士甘漁樵。","況我飄轉無定所，終日慽慽忍羈旅。","秋宿霜溪素月高，喜得與子长夜語。","东游西還力實倦，從此將身更何許。","知子松根长茯苓，遲暮有有意来同煮。"]', '诗', 'shi', '', NULL, '嚴氏溪放歌行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b2e460-ab50-438c-b53e-57ef2aae3d8d', '南池', '南池', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["崢嶸巴閬間，所向盡山谷。","安知有蒼池，萬頃浸坤軸。","呀然閬城南，枕帶巴江腹。","芰荷入異縣，稉稻共比屋。","皇天不無意，美利戒止足。","高田失西成，此物頗豐熟。","清源多衆魚，遠岸富喬木。","獨歎楓香林，春時好顏色。","南有漢王祠，終朝走巫祝。","歌舞散靈衣，荒哉舊風俗。","高堂亦明王，魂魄猶正直。","不應空陂上，縹緲親酒食。","淫祀自古昔，非唯一川瀆。","干戈浩茫茫，地僻傷極目。","平生江海興，遭亂身局促。","駐馬問漁舟，躊躇慰羈束。"]', '["崢嶸巴閬间，所向尽山谷。","安知有蒼池，万頃浸坤軸。","呀然閬城南，枕带巴江腹。","芰荷入異縣，稉稻共比屋。","皇天不無意，美利戒止足。","高田失西成，此物頗豐熟。","清源多衆鱼，远岸富喬木。","独歎楓香林，春时好顏色。","南有漢王祠，終朝走巫祝。","歌舞散靈衣，荒哉旧风俗。","高堂亦明王，魂魄猶正直。","不應空陂上，縹緲親酒食。","淫祀自古昔，非唯一川瀆。","干戈浩茫茫，地僻傷極目。","平生江海兴，遭亂身局促。","駐马问漁舟，躊躇慰羈束。"]', '诗', 'shi', '', NULL, '南池 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0932954f-3895-490b-864a-1469ef8e16df', '發閬中', '發閬中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["前有毒蛇後猛虎，溪行盡日無邨塢。","江風蕭蕭雲拂地，山木慘慘天欲雨。","女病妻憂歸意速，秋花錦石誰復數。","別家三月一得書，避地何時免愁苦。"]', '["前有毒蛇後猛虎，溪行尽日無邨塢。","江风蕭蕭云拂地，山木慘慘天欲雨。","女病妻憂归意速，秋花錦石誰复數。","別家三月一得书，避地何时免愁苦。"]', '诗', 'shi', '', NULL, '發閬中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d303931-f900-4f29-a8b9-caea611a521f', '寄韓諫議', '寄韓諫議', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今我不樂思岳陽，身欲奮飛病在牀。","美人娟娟隔秋水，濯足洞庭望八荒。","鴻飛冥冥日月白，青楓葉赤天雨霜。","玉京羣帝集北斗，或騎騏驎翳鳳皇。","芙蓉旌旗煙霧樂，影動倒景搖瀟湘。","星宮之君醉瓊漿，羽人稀少不在旁。","似聞昨者赤松子，恐是漢代韓張良。","昔隨劉氏定長安，帷幄未改神慘傷。","國家成敗吾豈敢，色難腥腐餐風香。","周南留滯古所惜，南極老人應壽昌。","美人胡爲隔秋水，焉得置之貢玉堂。"]', '["今我不乐思岳陽，身欲奮飞病在牀。","美人娟娟隔秋水，濯足洞庭望八荒。","鴻飞冥冥日月白，青楓葉赤天雨霜。","玉京羣帝集北斗，或騎騏驎翳鳳皇。","芙蓉旌旗煙霧乐，影动倒景搖瀟湘。","星宮之君醉瓊漿，羽人稀少不在旁。","似闻昨者赤松子，恐是漢代韓張良。","昔隨劉氏定长安，帷幄未改神慘傷。","国家成敗吾豈敢，色难腥腐餐风香。","周南留滯古所惜，南極老人應壽昌。","美人胡爲隔秋水，焉得置之貢玉堂。"]', '诗', 'shi', '', NULL, '寄韓諫議 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cee205e-5c59-46e5-b060-9b0916c64a3f', '憶昔二首 一', '憶昔二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昔先皇巡朔方，千乘萬騎入咸陽。","陰山驕子汗血馬，長驅東胡胡走藏。","鄴城反覆不足怪，關中小兒壞紀綱，張后不樂上爲忙。","至今今上猶撥亂，勞身焦思補四方。","我昔近侍叨奉引，出兵整肅不可當。","爲留猛士守未央，致使岐雍防西羌。","犬戎直來坐御牀，百官跣足隨天王願見北地傅介子，老儒不用尚書郎。"]', '["憶昔先皇巡朔方，千乘万騎入咸陽。","陰山驕子汗血马，长驱东胡胡走藏。","鄴城反覆不足怪，关中小兒壞紀綱，張后不乐上爲忙。","至今今上猶撥亂，勞身焦思補四方。","我昔近侍叨奉引，出兵整肅不可當。","爲留猛士守未央，致使岐雍防西羌。","犬戎直来坐御牀，百官跣足隨天王願见北地傅介子，老儒不用尚书郎。"]', '诗', 'shi', '', NULL, '憶昔二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d0b9f1-7ae5-4b37-a34b-9e0d0e62e3fe', '憶昔二首 二', '憶昔二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昔開元全盛日，小邑猶藏萬家室。","稻米流脂粟米白，公私蒼廩俱豐實。","九州道路無豺虎，遠行不勞吉日出。","齊紈魯縞車班班，男耕女桑不相失。","宮中聖人奏雲門，天下朋友皆膠漆。","百餘年間未災變，叔孫禮樂蕭何律。","豈聞一絹直萬錢，有田種穀今流血。","洛陽宮殿燒焚盡，宗廟新除狐兔穴。","傷心不忍問耆舊，復恐初從亂離說。","小臣魯鈍無所能，朝廷記識蒙祿秩。","周宣中興望我皇，灑血江漢身衰疾。"]', '["憶昔开元全盛日，小邑猶藏万家室。","稻米流脂粟米白，公私蒼廩俱豐實。","九州道路無豺虎，远行不勞吉日出。","齊紈魯縞车班班，男耕女桑不相失。","宮中聖人奏云门，天下朋友皆膠漆。","百餘年间未災变，叔孫禮乐蕭何律。","豈闻一絹直万錢，有田種穀今流血。","洛陽宮殿燒焚尽，宗廟新除狐兔穴。","傷心不忍问耆旧，复恐初從亂離说。","小臣魯鈍無所能，朝廷記識蒙祿秩。","周宣中兴望我皇，灑血江漢身衰疾。"]', '诗', 'shi', '', NULL, '憶昔二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e95c3fb-b575-4343-a576-39168cb01163', '冬狩行', '冬狩行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見東川節度兵馬雄，校獵亦似觀成功。","夜發猛士三千人，清晨合圍步驟同。","禽獸已斃十七八，殺聲落日回蒼穹。","幕前生致九青兕，駱駝𡾋峞垂玄熊。","東西南北百里間，髣髴蹴踏寒山空。","有鳥名鸜鵒，力不能高飛逐走蓬。","肉味不足登鼎俎，何爲見羈虞羅中。","春蒐冬狩侯得同，使君五馬一馬驄。","況今攝行大將權，號令頗有前賢風。","飄然時危一老翁，十年厭見旌旗紅。","喜君士卒甚整肅，爲我回轡擒西戎。","草中狐兔盡何益，天子不在咸陽宮。","朝廷雖無幽王禍，得不哀痛塵再蒙。","嗚呼，得不哀痛塵再蒙。"]', '["君不见东川節度兵马雄，校獵亦似观成功。","夜發猛士三千人，清晨合圍步驟同。","禽獸已斃十七八，殺声落日回蒼穹。","幕前生致九青兕，駱駝𡾋峞垂玄熊。","东西南北百里间，髣髴蹴踏寒山空。","有鸟名鸜鵒，力不能高飞逐走蓬。","肉味不足登鼎俎，何爲见羈虞羅中。","春蒐冬狩侯得同，使君五马一马驄。","況今攝行大將權，號令頗有前賢风。","飄然时危一老翁，十年厭见旌旗紅。","喜君士卒甚整肅，爲我回轡擒西戎。","草中狐兔尽何益，天子不在咸陽宮。","朝廷雖無幽王禍，得不哀痛塵再蒙。","嗚呼，得不哀痛塵再蒙。"]', '诗', 'shi', '', NULL, '冬狩行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b207dcff-1823-4283-88d7-57d8c780c8ab', '自平', '自平', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自平宮中呂太一，收珠南海千餘日。","近供生犀翡翠稀，復恐征戎干戈密。","蠻溪豪族小動搖，世封刺史非時朝。","蓬萊殿前諸主將，才如伏波不得驕。"]', '["自平宮中呂太一，收珠南海千餘日。","近供生犀翡翠稀，复恐征戎干戈密。","蠻溪豪族小动搖，世封刺史非时朝。","蓬萊殿前諸主將，才如伏波不得驕。"]', '诗', 'shi', '', NULL, '自平 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da4b0f7-bb52-4477-a9ef-88d6922198c7', '釋悶', '釋悶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四海十年不解兵，犬戎也復臨咸京。","失道非關出襄野，揚鞭忽是過胡城。","豺狼塞路人斷絕，烽火照夜屍縱橫。","天子亦應厭奔走，羣公固合思升平。","但恐誅求不改轍，聞道嬖孽能全生。","江邊老翁錯料事，眼暗不見風塵清。"]', '["四海十年不解兵，犬戎也复臨咸京。","失道非关出襄野，揚鞭忽是過胡城。","豺狼塞路人斷絕，烽火照夜屍縱橫。","天子亦應厭奔走，羣公固合思升平。","但恐誅求不改轍，闻道嬖孽能全生。","江邊老翁錯料事，眼暗不见风塵清。"]', '诗', 'shi', '', NULL, '釋悶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d70a6c-0d49-4e83-99d7-4bd2ece32100', '贈別賀蘭銛', '贈別賀蘭銛', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃雀飽野粟，羣飛動荆榛。","今君抱何恨，寂寞向時人。","老驥倦驤首，蒼鷹愁易馴。","高賢世未識，固合嬰飢貧。","國步初返正，乾坤尚風塵。","悲歌鬢髮白，遠赴湘吳春。","我戀岷下芋，君思千里蓴。","生離與死別，自古鼻酸辛。"]', '["黄雀飽野粟，羣飞动荆榛。","今君抱何恨，寂寞向时人。","老驥倦驤首，蒼鷹愁易馴。","高賢世未識，固合嬰飢貧。","国步初返正，乾坤尚风塵。","悲歌鬢髮白，远赴湘吳春。","我戀岷下芋，君思千里蓴。","生離與死別，自古鼻酸辛。"]', '诗', 'shi', '', NULL, '贈別賀蘭銛 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0dd9a8d-397b-44c3-878d-de914dc5b68c', '別唐十五誡因寄禮部賈侍郎', '別唐十五誡因寄禮部賈侍郎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["九載一相逢，百年能幾何。","復爲萬里別，送子山之阿。","白鶴久同林，潛魚本同河。","未知棲集期，衰老強高歌。","歌罷兩悽惻，六龍忽蹉跎。","相視髮皓白，況難駐羲和。","胡星墜燕地，漢將仍橫戈。","蕭條四海內，人少豺虎多。","少人慎莫投，多虎信所過。","飢有易子食，獸猶畏虞羅。","子負經濟才，天門鬱嵯峨。","飄颻適東周，來往若崩波。","南宮吾故人，白馬金盤陀。","雄筆映千古，見賢心靡他。","念子善師事，歲寒守舊柯。","爲吾謝賈公，病肺臥江沱。"]', '["九載一相逢，百年能幾何。","复爲万里別，送子山之阿。","白鹤久同林，潛鱼本同河。","未知棲集期，衰老強高歌。","歌罷兩悽惻，六龙忽蹉跎。","相視髮皓白，況难駐羲和。","胡星墜燕地，漢將仍橫戈。","蕭條四海內，人少豺虎多。","少人慎莫投，多虎信所過。","飢有易子食，獸猶畏虞羅。","子負經濟才，天门鬱嵯峨。","飄颻適东周，来往若崩波。","南宮吾故人，白马金盤陀。","雄笔映千古，见賢心靡他。","念子善師事，歲寒守旧柯。","爲吾謝賈公，病肺臥江沱。"]', '诗', 'shi', '', NULL, '別唐十五誡因寄禮部賈侍郎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14504b92-0aab-4daf-8a8d-623c5a59b487', '閬山歌', '閬山歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["閬州城中靈山白，閬州城北玉臺碧。","松浮欲盡不盡雲，江動將崩未崩石。","那知根無鬼神會，已覺氣與嵩華敵。","中原格鬬且未歸，應結茅齋看青壁。"]', '["閬州城中靈山白，閬州城北玉台碧。","松浮欲尽不尽云，江动將崩未崩石。","那知根無鬼神會，已覺氣與嵩华敵。","中原格鬬且未归，應結茅斋看青壁。"]', '诗', 'shi', '', NULL, '閬山歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d04448-935e-4e7a-ad7e-9a69c31b0ad7', '閬水歌', '閬水歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嘉陵江色何所似，石黛碧玉相因依。","正憐日破浪花出，更復春從沙際歸。","巴童蕩槳攲側過，水雞銜魚來去飛。","閬中勝事可腸斷，閬州城南天下稀。"]', '["嘉陵江色何所似，石黛碧玉相因依。","正怜日破浪花出，更复春從沙際归。","巴童蕩槳攲側過，水雞銜鱼来去飞。","閬中勝事可腸斷，閬州城南天下稀。"]', '诗', 'shi', '', NULL, '閬水歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bfdf4c-b903-4517-8f91-d25331134e12', '草堂', '草堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔我去草堂，蠻夷塞成都。","今我歸草堂，成都適無虞。","請陳初亂時，反復乃須臾。","大將赴朝廷，羣小起異圖。","中宵斬白馬，盟歃氣已麤。","西取邛南兵，北斷劒閣隅。","布衣數十人，亦擁專城居。","其勢不兩大，始聞蕃漢殊。","西卒却倒戈，賊臣互相誅。","焉知肘腋禍，自及梟獍徒。","義士皆痛憤，紀綱亂相踰。","一國實三公，萬人欲爲魚。","唱和作威福，孰肯辨無辜。","眼前列杻械，背後吹笙竽。","談笑行殺戮，濺血滿長衢。","到今用鉞地，風雨聞號呼。","鬼妾與鬼馬，色悲充爾娛。","國家法令在，此又足驚吁。","賤子且奔走，三年望東吳。","弧矢暗江海，難爲遊五湖。","不忍竟舍此，復來薙榛蕪。","入門四松在，步屧萬竹疎。","舊犬喜我歸，低徊入衣裾。","鄰舍喜我歸，酤酒攜胡蘆。","大官喜我來，遣騎問所須。","城郭喜我來，賓客隘邨墟。","天下尚未寧，健兒勝腐儒。","飄颻風塵際，何地置老夫。","於時見疣贅，骨髓幸未枯。","飲啄媿殘生，食薇不敢餘。"]', '["昔我去草堂，蠻夷塞成都。","今我归草堂，成都適無虞。","請陳初亂时，反复乃須臾。","大將赴朝廷，羣小起異圖。","中宵斬白马，盟歃氣已麤。","西取邛南兵，北斷劒閣隅。","布衣數十人，亦擁專城居。","其勢不兩大，始闻蕃漢殊。","西卒却倒戈，賊臣互相誅。","焉知肘腋禍，自及梟獍徒。","義士皆痛憤，紀綱亂相踰。","一国實三公，万人欲爲鱼。","唱和作威福，孰肯辨無辜。","眼前列杻械，背後吹笙竽。","談笑行殺戮，濺血满长衢。","到今用鉞地，风雨闻號呼。","鬼妾與鬼马，色悲充爾娛。","国家法令在，此又足驚吁。","賤子且奔走，三年望东吳。","弧矢暗江海，难爲游五湖。","不忍竟舍此，复来薙榛蕪。","入门四松在，步屧万竹疎。","旧犬喜我归，低徊入衣裾。","鄰舍喜我归，酤酒携胡蘆。","大官喜我来，遣騎问所須。","城郭喜我来，賓客隘邨墟。","天下尚未寧，健兒勝腐儒。","飄颻风塵際，何地置老夫。","於时见疣贅，骨髓幸未枯。","饮啄媿殘生，食薇不敢餘。"]', '诗', 'shi', '', NULL, '草堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1762014e-d551-478c-8547-d0e2ac0caa6e', '四松', '四松', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四松初移時，大抵三尺強。","別來忽三載，離立如人長。","會看根不拔，莫計枝凋傷。","幽色幸秀發，疎柯亦昂藏。","所插小藩籬，本亦有隄防。","終然掁撥損，得恡千葉黃。","敢爲故林主，黎庶猶未康。","避賊今始歸，春草滿空堂。","覽物歎衰謝，及茲慰淒涼。","清風爲我起，灑面若微霜。","足以送老姿，聊侍偃蓋張。","我生無根帶，配爾亦茫茫。","有情且賦詩，事迹可兩望。","勿矜千載後，慘澹蟠穹蒼。"]', '["四松初移时，大抵三尺強。","別来忽三載，離立如人长。","會看根不拔，莫計枝凋傷。","幽色幸秀發，疎柯亦昂藏。","所插小藩籬，本亦有隄防。","終然掁撥損，得恡千葉黄。","敢爲故林主，黎庶猶未康。","避賊今始归，春草满空堂。","覽物歎衰謝，及茲慰淒涼。","清风爲我起，灑面若微霜。","足以送老姿，聊侍偃蓋張。","我生無根带，配爾亦茫茫。","有情且賦诗，事迹可兩望。","勿矜千載後，慘澹蟠穹蒼。"]', '诗', 'shi', '', NULL, '四松 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be10e787-c739-44b9-a572-397e10138d0c', '水檻', '水檻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蒼江多風飆，雲雨晝夜飛。","茅軒駕巨浪，焉得不低垂。","遊子久在外，門戶無人持。","高岸尚如谷，何傷浮柱攲。","扶顛有勸誡，恐貽識者嗤。","既殊大廈傾，可以一木支。","臨川視萬里，何必闌檻爲。","人生感故物，慷慨有餘悲。"]', '["蒼江多风飆，云雨晝夜飞。","茅軒駕巨浪，焉得不低垂。","游子久在外，门戶無人持。","高岸尚如谷，何傷浮柱攲。","扶顛有勸誡，恐貽識者嗤。","既殊大廈傾，可以一木支。","臨川視万里，何必闌檻爲。","人生感故物，慷慨有餘悲。"]', '诗', 'shi', '', NULL, '水檻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbecdcf9-c56b-42c0-bac4-7b05f9864f2a', '破船', '破船', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["平生江海心，宿昔具扁舟。","豈惟青溪上，日傍柴門遊。","蒼皇避亂兵，緬邈懷舊丘。","鄰人亦已非，野竹獨修修。","船舷不重扣，埋沒已經秋。","仰看西飛翼，下媿東逝流。","故者或可掘，新者亦易求。","所悲數奔竄，白屋難久留。"]', '["平生江海心，宿昔具扁舟。","豈惟青溪上，日傍柴门游。","蒼皇避亂兵，緬邈懷旧丘。","鄰人亦已非，野竹独修修。","船舷不重扣，埋沒已經秋。","仰看西飞翼，下媿东逝流。","故者或可掘，新者亦易求。","所悲數奔竄，白屋难久留。"]', '诗', 'shi', '', NULL, '破船 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb069d9-b053-49cc-8007-8e5bb98c2573', '營屋', '營屋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我有陰江竹，能令朱夏寒。","陰通積水內，高入浮雲端。","甚疑鬼物憑，不顧翦伐殘。","東偏若面勢，戶牖永可安。","愛惜已六載，茲晨去千竿。","蕭蕭見白日，洶洶開奔湍。","度堂匪華麗，養拙異考槃。","草茅雖薙葺，衰疾方少寬。","洗然順所適，此足代加餐。","寂無斤斧響，庶遂憩息歡。"]', '["我有陰江竹，能令朱夏寒。","陰通積水內，高入浮云端。","甚疑鬼物憑，不顧翦伐殘。","东偏若面勢，戶牖永可安。","愛惜已六載，茲晨去千竿。","蕭蕭见白日，洶洶开奔湍。","度堂匪华丽，養拙異考槃。","草茅雖薙葺，衰疾方少寬。","洗然順所適，此足代加餐。","寂無斤斧响，庶遂憩息歡。"]', '诗', 'shi', '', NULL, '營屋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69bfe05-49ed-4c28-9f39-6aaae0e2aa74', '除草', '除草', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草有害於人，曾何生阻修。","其毒甚蜂蠆，其多彌道周。","清晨步前林，江色未散憂。","芒刺在我眼，焉能待高秋。","霜露一霑凝，蕙葉亦難留。","荷鋤先童穉，日入仍討求。","轉致水中央，豈無雙釣舟。","頑根易滋蔓，敢使依舊丘。","自茲藩籬曠，更覺松竹幽。","芟夷不可闕，疾惡信如讎。"]', '["草有害於人，曾何生阻修。","其毒甚蜂蠆，其多彌道周。","清晨步前林，江色未散憂。","芒刺在我眼，焉能待高秋。","霜露一霑凝，蕙葉亦难留。","荷鋤先童穉，日入仍討求。","轉致水中央，豈無雙釣舟。","頑根易滋蔓，敢使依旧丘。","自茲藩籬曠，更覺松竹幽。","芟夷不可闕，疾惡信如讎。"]', '诗', 'shi', '', NULL, '除草 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06f921a-9125-4a21-aad1-f98a429e4727', '揚旗', '揚旗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江雨颯長夏，府中有餘清。","我公會賓客，肅肅有異聲。","初筵閱軍裝，羅列照廣庭。","庭空六馬入，駊騀揚旗旌。","回回偃飛蓋，熠熠迸流星。","來纏風飆急，去擘山岳傾。","材歸俯身盡，妙取略地平。","虹霓就掌握，舒卷隨人輕。","三州陷犬戎，但見西嶺青。","公來練猛士，欲奪天邊城。","此堂不易升，庸蜀日已寧。","吾徒且加餐，休適蠻與荆。"]', '["江雨颯长夏，府中有餘清。","我公會賓客，肅肅有異声。","初筵閱軍裝，羅列照廣庭。","庭空六马入，駊騀揚旗旌。","回回偃飞蓋，熠熠迸流星。","来纏风飆急，去擘山岳傾。","材归俯身尽，妙取略地平。","虹霓就掌握，舒卷隨人轻。","三州陷犬戎，但见西嶺青。","公来練猛士，欲奪天邊城。","此堂不易升，庸蜀日已寧。","吾徒且加餐，休適蠻與荆。"]', '诗', 'shi', '', NULL, '揚旗 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e025699-a493-49b3-8b9d-be47fd65a2ae', '太子張舍人遺織成褥段', '太子張舍人遺织成褥段', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客從西北來，遺我翠織成。","開緘風濤湧，中有掉尾鯨。","逶迤羅水族，瑣細不足名。","客云充君褥，承君終宴榮。","空堂魑魅走，高枕形神清。","領客珍重意，顧我非公卿。","留之懼不祥，施之混柴荆。","服飾定尊卑，大哉萬古程。","今我一賤老，裋褐更無營。","煌煌珠宮物，寢處禍所嬰。","歎息當路子，干戈尚縱橫。","掌握有權柄，衣馬自肥輕。","李鼎死岐陽，實以驕貴盈。","來瑱賜自盡，氣豪直阻兵。","皆聞黃金多，坐見悔吝生。","奈何田舍翁，受此厚貺情。","錦鯨卷還客，始覺心和平。","振我麤席塵，媿客茹藜羹。"]', '["客從西北来，遺我翠织成。","开緘风濤湧，中有掉尾鯨。","逶迤羅水族，瑣細不足名。","客云充君褥，承君終宴榮。","空堂魑魅走，高枕形神清。","領客珍重意，顧我非公卿。","留之懼不祥，施之混柴荆。","服飾定尊卑，大哉万古程。","今我一賤老，裋褐更無營。","煌煌珠宮物，寢处禍所嬰。","歎息當路子，干戈尚縱橫。","掌握有權柄，衣马自肥轻。","李鼎死岐陽，實以驕貴盈。","来瑱賜自尽，氣豪直阻兵。","皆闻黄金多，坐见悔吝生。","奈何田舍翁，受此厚貺情。","錦鯨卷還客，始覺心和平。","振我麤席塵，媿客茹藜羹。"]', '诗', 'shi', '', NULL, '太子張舍人遺織成褥段 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840f36d1-df6e-4cfe-87ac-692fc102ff44', '莫相疑行', '莫相疑行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["男兒生無所成頭皓白，牙齒欲落真可惜。","憶獻三賦蓬萊宮，自怪一日聲輝赫。","集賢學士如堵牆，觀我落筆中書堂。","往時文彩動人主，此日飢寒趨路旁。","晚將末契託年少，當面輸心背面笑。","寄謝悠悠世上兒，不爭好惡莫相疑。"]', '["男兒生無所成头皓白，牙齒欲落真可惜。","憶獻三賦蓬萊宮，自怪一日声輝赫。","集賢学士如堵牆，观我落笔中书堂。","往时文彩动人主，此日飢寒趨路旁。","晚將末契託年少，當面輸心背面笑。","寄謝悠悠世上兒，不爭好惡莫相疑。"]', '诗', 'shi', '', NULL, '莫相疑行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0dd009-15ad-4537-ab58-29593bc44970', '別蔡十四著作', '別蔡十四著作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賈生慟哭後，寥落無其人。","安知蔡夫子，高義邁等倫。","獻書謁皇帝，志以清風塵。","流涕灑丹極，萬乘爲酸辛。","天地則創痍，朝廷當正臣。","異才復間出，周道日惟新。","使蜀見知己，別顏始一伸。","主人薨城府，扶櫬歸咸秦。","巴道此相逢，會我病江濱。","憶念鳳翔都，聚散俄十春。","我衰不足道，但願子意陳。","稍令社稷安，自契魚水親。","我雖消渴甚，敢望帝力勤。","尚思未朽骨，復覩耕桑民。","積水架三峽，浮龍倚長津。","揚舲洪濤間，仗子濟物身。","鞍馬下秦塞，王城通北辰。","玄甲聚不散，兵久食恐貧。","窮谷無粟帛，使者來相因。","若憑南轅吏，書札到天垠。"]', '["賈生慟哭後，寥落無其人。","安知蔡夫子，高義邁等倫。","獻书謁皇帝，志以清风塵。","流涕灑丹極，万乘爲酸辛。","天地則創痍，朝廷當正臣。","異才复间出，周道日惟新。","使蜀见知己，別顏始一伸。","主人薨城府，扶櫬归咸秦。","巴道此相逢，會我病江濱。","憶念鳳翔都，聚散俄十春。","我衰不足道，但願子意陳。","稍令社稷安，自契鱼水親。","我雖消渴甚，敢望帝力勤。","尚思未朽骨，复覩耕桑民。","積水架三峽，浮龙倚长津。","揚舲洪濤间，仗子濟物身。","鞍马下秦塞，王城通北辰。","玄甲聚不散，兵久食恐貧。","窮谷無粟帛，使者来相因。","若憑南轅吏，书札到天垠。"]', '诗', 'shi', '', NULL, '別蔡十四著作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c507b869-c422-46dc-be74-0d9ca10a7217', '杜鵑', '杜鵑', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西川有杜鵑，東川無杜鵑。","涪萬無杜鵑，雲安有杜鵑。","我昔遊錦城，結廬錦水邊。","有竹一頃餘，喬木上參天。","杜鵑暮春至，哀哀叫其間。","我見常再拜，重是古帝魂。","生子百鳥巢，百鳥不敢嗔。","仍爲餧其子，禮若奉至尊。","鴻雁及羔羊，有禮太古前。","行飛與跪乳，識序如知恩。","聖賢古法則，付與後世傳。","君看禽鳥情，猶解事杜鵑。","今忽暮春間，值我病經年。","身病不能拜，淚下如迸泉。"]', '["西川有杜鵑，东川無杜鵑。","涪万無杜鵑，云安有杜鵑。","我昔游錦城，結廬錦水邊。","有竹一頃餘，喬木上參天。","杜鵑暮春至，哀哀叫其间。","我见常再拜，重是古帝魂。","生子百鸟巢，百鸟不敢嗔。","仍爲餧其子，禮若奉至尊。","鴻雁及羔羊，有禮太古前。","行飞與跪乳，識序如知恩。","聖賢古法則，付與後世傳。","君看禽鸟情，猶解事杜鵑。","今忽暮春间，值我病經年。","身病不能拜，泪下如迸泉。"]', '诗', 'shi', '', NULL, '杜鵑 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf0e59c3-a674-4d8b-aaf9-03e64bee7588', '客居', '客居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客居所居堂，前江後山根。","下塹萬尋岸，蒼濤鬱飛飜。","蔥青衆木梢，邪豎雜石痕。","子規晝夜啼，壯士斂精魂。","峽開四千里，水合數百源。","人虎相半居，相傷終兩存。","蜀麻久不來，吳鹽擁荆門。","西南失大將，商旅自星奔。","今又降元戎，已聞動行軒。","舟子候利涉，亦憑節制尊。","我在路中央，生理不得論。","臥愁病脚廢，徐步視小園。","短畦帶碧草，悵望思王孫。","鳳隨其皇去，籬雀暮喧繁。","覽物想故國，十年別荒邨。","日暮歸幾翼，北林空自昏。","安得覆八溟，爲君洗乾坤。","稷契易爲力，犬戎何足吞。","儒生老無成，臣子憂四番。","篋中有舊筆，情至時復援。"]', '["客居所居堂，前江後山根。","下塹万尋岸，蒼濤鬱飞飜。","蔥青衆木梢，邪豎杂石痕。","子規晝夜啼，壯士斂精魂。","峽开四千里，水合數百源。","人虎相半居，相傷終兩存。","蜀麻久不来，吳鹽擁荆门。","西南失大將，商旅自星奔。","今又降元戎，已闻动行軒。","舟子候利涉，亦憑節制尊。","我在路中央，生理不得論。","臥愁病脚廢，徐步視小园。","短畦带碧草，悵望思王孫。","鳳隨其皇去，籬雀暮喧繁。","覽物想故国，十年別荒邨。","日暮归幾翼，北林空自昏。","安得覆八溟，爲君洗乾坤。","稷契易爲力，犬戎何足吞。","儒生老無成，臣子憂四番。","篋中有旧笔，情至时复援。"]', '诗', 'shi', '', NULL, '客居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a1e3ad-8246-4b60-a17c-fc27951dd35a', '客堂', '客堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昨離少城，而今異楚蜀。","舍舟復深山，窅窕一林麓。","棲泊雲安縣，消中內相毒。","舊疾甘載來，衰年得無足。","死爲殊方鬼，頭白免短促。","老馬終望雲，南雁意在北。","別家長兒女，欲起慙筋力。","客堂序節改，具物對羈束。","石暄蕨芽紫，渚秀蘆筍綠。","巴鶯紛未稀，徼麥早向熟。","悠悠日動江，漠漠春辭木。","臺郎選才俊，自顧亦已極。","前輩聲名人，埋沒何所得。","居然綰章紱，受性本幽獨。","平生憩息地，必種數竿竹。","事業只濁醪，營葺但草屋。","上公有記者，累奏資薄祿。","主憂豈濟時，身遠彌曠職。","循文廟算正，獻可天衢直。","尚想趨朝廷，毫髮裨社稷。","形骸今若是，進退委行色。"]', '["憶昨離少城，而今異楚蜀。","舍舟复深山，窅窕一林麓。","棲泊云安縣，消中內相毒。","旧疾甘載来，衰年得無足。","死爲殊方鬼，头白免短促。","老马終望云，南雁意在北。","別家长兒女，欲起慙筋力。","客堂序節改，具物对羈束。","石暄蕨芽紫，渚秀蘆筍綠。","巴鶯紛未稀，徼麦早向熟。","悠悠日动江，漠漠春辞木。","台郎選才俊，自顧亦已極。","前輩声名人，埋沒何所得。","居然綰章紱，受性本幽独。","平生憩息地，必種數竿竹。","事業只濁醪，營葺但草屋。","上公有記者，累奏資薄祿。","主憂豈濟时，身远彌曠職。","循文廟算正，獻可天衢直。","尚想趨朝廷，毫髮裨社稷。","形骸今若是，進退委行色。"]', '诗', 'shi', '', NULL, '客堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de59ac9-a4b2-4e1a-a4c7-9ae2505b8cf4', '石研詩', '石研诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["平公今詩伯，秀發吾所羨。","奉使三峽中，長嘯得石研。","巨璞禹鑿餘，異壯君獨見。","其滑乃波濤，其光或雷電。","聊坳各盡墨，多水遞隱現。","揮灑容數人，十手可對面。","比公頭上冠，貞質未爲賤。","當公賦佳句，況得終清宴。","公含起草姿，不遠明光殿。","致於丹青地，知汝隨顧眄。"]', '["平公今诗伯，秀發吾所羨。","奉使三峽中，长嘯得石研。","巨璞禹鑿餘，異壯君独见。","其滑乃波濤，其光或雷電。","聊坳各尽墨，多水遞隐現。","揮灑容數人，十手可对面。","比公头上冠，貞質未爲賤。","當公賦佳句，況得終清宴。","公含起草姿，不远明光殿。","致於丹青地，知汝隨顧眄。"]', '诗', 'shi', '', NULL, '石研詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c287ae-d6f5-414a-a05b-f69d7baff4a0', '水閣朝霽奉簡嚴雲安', '水閣朝霽奉簡嚴云安', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東城抱春岑，江閣鄰石面。","崔嵬晨雲白，朝旭射芳甸。","雨檻臥花叢，風牀展書卷。","鉤簾宿鷺起，丸藥流鶯囀。","呼婢取酒壺，績兒誦文選。","晚交嚴明府，矧此數相見。"]', '["东城抱春岑，江閣鄰石面。","崔嵬晨云白，朝旭射芳甸。","雨檻臥花叢，风牀展书卷。","鉤簾宿鷺起，丸藥流鶯囀。","呼婢取酒壺，績兒誦文選。","晚交嚴明府，矧此數相见。"]', '诗', 'shi', '', NULL, '水閣朝霽奉簡嚴雲安 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75727b65-afda-4363-abdf-a7c94fc9e380', '贈鄭十八賁', '贈鄭十八賁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["溫溫士君子，令我懷抱盡。","靈芝冠衆芳，安得闕親近。","遭亂意不歸，竄身跡非隱。","細人尚姑息，吾子色愈謹。","高懷見物理，識者安肯哂。","卑飛欲何待，捷徑應未忍。","示我百篇文，詩家一標準。","羇離交屈宋，牢落值顏閔。","水路迷畏途，藥餌駐修軫。","古人日以遠，青史字不泯。","步趾詠唐虞，追隨飯葵堇。","數杯資好事，異味煩縣尹。","心雖在朝謁，力與願矛盾。","抱病排金門，衰容豈爲敏。"]', '["溫溫士君子，令我懷抱尽。","靈芝冠衆芳，安得闕親近。","遭亂意不归，竄身跡非隐。","細人尚姑息，吾子色愈謹。","高懷见物理，識者安肯哂。","卑飞欲何待，捷徑應未忍。","示我百篇文，诗家一標準。","羇離交屈宋，牢落值顏閔。","水路迷畏途，藥餌駐修軫。","古人日以远，青史字不泯。","步趾詠唐虞，追隨飯葵堇。","數杯資好事，異味煩縣尹。","心雖在朝謁，力與願矛盾。","抱病排金门，衰容豈爲敏。"]', '诗', 'shi', '', NULL, '贈鄭十八賁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57744626-3438-4f25-a2e6-3b9978376056', '三韻三篇 一', '三韻三篇 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高馬勿唾面，長魚無損鱗。","辱馬馬毛焦，困魚魚有神。","君看磊落士，不肯易其身。"]', '["高马勿唾面，长鱼無損鱗。","辱马马毛焦，困鱼鱼有神。","君看磊落士，不肯易其身。"]', '诗', 'shi', '', NULL, '三韻三篇 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2859274-fd6f-4c48-a4a5-53e1754b6aa2', '三韻三篇 二', '三韻三篇 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蕩蕩萬斛船，影若揚白虹。","起檣必椎牛，挂席集衆功。","自非風動天，莫置大水中。"]', '["蕩蕩万斛船，影若揚白虹。","起檣必椎牛，挂席集衆功。","自非风动天，莫置大水中。"]', '诗', 'shi', '', NULL, '三韻三篇 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73368692-b14f-4e13-a388-ff5acccf9a12', '三韻三篇 三', '三韻三篇 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["烈士惡多門，小人自同調。","名利苟可取，殺身傍權要。","何當官曹清，爾輩堪一笑。"]', '["烈士惡多门，小人自同調。","名利苟可取，殺身傍權要。","何當官曹清，爾輩堪一笑。"]', '诗', 'shi', '', NULL, '三韻三篇 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f15368-7b2d-445a-95c8-835ddcbd03bf', '青絲', '青絲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青絲白馬誰家子，麤豪且逐風塵起。","不聞漢主放妃嬪，近靜潼關埽蠭蟻。","殿前兵馬破汝時，十月即爲齏粉期。","未如面縛歸金闕，萬一皇恩下玉墀。"]', '["青絲白马誰家子，麤豪且逐风塵起。","不闻漢主放妃嬪，近静潼关埽蠭蟻。","殿前兵马破汝时，十月即爲齏粉期。","未如面縛归金闕，万一皇恩下玉墀。"]', '诗', 'shi', '', NULL, '青絲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e237c6-27c4-46c7-a998-d5c3bd12426b', '近聞', '近闻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["近聞犬戎遠遁逃，牧馬不敢侵臨洮。","渭水逶迤白日淨，隴山蕭瑟秋雲高。","崆峒五原亦無事，北庭數有關中使。","似聞贊普更求親，舅甥和好應難棄。"]', '["近闻犬戎远遁逃，牧马不敢侵臨洮。","渭水逶迤白日淨，隴山蕭瑟秋云高。","崆峒五原亦無事，北庭數有关中使。","似闻贊普更求親，舅甥和好應难棄。"]', '诗', 'shi', '', NULL, '近聞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a655242-25cf-4681-9d4d-9fb7e217b214', '蠶穀行', '蠶穀行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天下郡國向萬城，無有一城無甲兵。","焉得鑄甲作農器，一寸荒田牛得耕。","牛盡耕，蠶亦成。","不勞烈士淚滂沱，男穀女絲行復歌。"]', '["天下郡国向万城，無有一城無甲兵。","焉得鑄甲作農器，一寸荒田牛得耕。","牛尽耕，蠶亦成。","不勞烈士泪滂沱，男穀女絲行复歌。"]', '诗', 'shi', '', NULL, '蠶穀行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479f5094-eb0e-4254-a729-84bef1043f97', '折檻行', '折檻行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嗚呼房魏不復見，秦王學士時難羨。","青衿胄子困泥塗，白馬將軍若雷電。","千載少似朱雲人，至今折檻空嶙峋。","婁公不語宋公語，尚憶先皇容直臣。"]', '["嗚呼房魏不复见，秦王学士时难羨。","青衿胄子困泥塗，白马將軍若雷電。","千載少似朱云人，至今折檻空嶙峋。","婁公不語宋公語，尚憶先皇容直臣。"]', '诗', 'shi', '', NULL, '折檻行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c527981-a52c-4127-b686-3f4596e38818', '引水', '引水', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["月峽瞿塘雲作頂，亂石崢嶸俗無井。","雲安酤水奴僕悲，魚復移居心力省。","白帝城西萬竹蟠，接筒引水喉不乾。","人生留滯生理難，斗水何直百憂寬。"]', '["月峽瞿塘云作頂，亂石崢嶸俗無井。","云安酤水奴僕悲，鱼复移居心力省。","白帝城西万竹蟠，接筒引水喉不乾。","人生留滯生理难，斗水何直百憂寬。"]', '诗', 'shi', '', NULL, '引水 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383d41a8-5155-4fff-b91f-87d5585ff03e', '古柏行', '古柏行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孔明廟前有老柏，柯如青銅根如石。","霜皮溜雨四十圍，黛色參天二千尺。","君臣已與時際會，樹木猶爲人愛惜。","雲來氣接巫峽長，月出寒通雪山白。","憶昨路繞錦亭東，先主武侯同閟宮。","崔嵬枝幹郊原古，窈窕丹青戶牖空。","落落盤踞雖得地，冥冥孤高多烈風。","扶持自是神明力，正直原因造化功。","大廈如傾要梁棟，萬牛回首丘山重。","不露文章世已驚，未辭剪伐誰能送。","苦心豈免容螻蟻，香葉終經宿鸞鳳。","志士幽人莫怨嗟，古來材大難爲用。"]', '["孔明廟前有老柏，柯如青銅根如石。","霜皮溜雨四十圍，黛色參天二千尺。","君臣已與时際會，樹木猶爲人愛惜。","云来氣接巫峽长，月出寒通雪山白。","憶昨路繞錦亭东，先主武侯同閟宮。","崔嵬枝幹郊原古，窈窕丹青戶牖空。","落落盤踞雖得地，冥冥孤高多烈风。","扶持自是神明力，正直原因造化功。","大廈如傾要梁棟，万牛回首丘山重。","不露文章世已驚，未辞剪伐誰能送。","苦心豈免容螻蟻，香葉終經宿鸾鳳。","志士幽人莫怨嗟，古来材大难爲用。"]', '诗', 'shi', '', NULL, '古柏行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94d5bf5-9fcd-4ab4-984d-0c537f9e37d6', '縛雞行', '縛雞行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["小奴縛雞向市賣，雞被縛急相喧爭。","家中厭雞食蟲蟻，不知雞賣還遭烹。","蟲雞與人何厚薄，吾叱奴人解其縛。","雞蟲得失無了時，注目寒江倚山閣。"]', '["小奴縛雞向市賣，雞被縛急相喧爭。","家中厭雞食蟲蟻，不知雞賣還遭烹。","蟲雞與人何厚薄，吾叱奴人解其縛。","雞蟲得失無了时，注目寒江倚山閣。"]', '诗', 'shi', '', NULL, '縛雞行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4b9cac-65c4-42e8-949c-4dabc621de01', '負薪行', '負薪行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夔州處女髮半華，四十五十無夫家。","更遭喪亂嫁不售，一生抱恨堪咨嗟。","土風坐男使女立，應當門戶女出入。","十猶八九負薪歸，賣薪得錢應供給。","至老雙鬟只垂頸，野花山葉銀釵竝。","筋力登危集市門，死生射利兼鹽井。","面妝首飾雜啼痕，地褊衣寒困石根。","若道巫山女麤醜，何得此有昭君邨。"]', '["夔州处女髮半华，四十五十無夫家。","更遭喪亂嫁不售，一生抱恨堪咨嗟。","土风坐男使女立，應當门戶女出入。","十猶八九負薪归，賣薪得錢應供給。","至老雙鬟只垂頸，野花山葉銀釵竝。","筋力登危集市门，死生射利兼鹽井。","面妝首飾杂啼痕，地褊衣寒困石根。","若道巫山女麤醜，何得此有昭君邨。"]', '诗', 'shi', '', NULL, '負薪行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbbba72-14ae-42d1-9f5a-09a077f2d0c6', '最能行', '最能行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽中丈夫絕輕死，少在公門多在水。","富豪有錢駕大舸，貧窮取給行艓子。","小兒學問止論語，大兒結束隨商旅。","攲帆側柁入波濤，撇漩捎濆無險阻。","朝發白帝暮江陵，頃來目擊幸有徵。","瞿堂漫天虎鬚怒，歸州長年行最能。","此鄉之人氣量窄，誤競南風疎北客。","若道土無英俊才，何得山有屈原宅。"]', '["峽中丈夫絕轻死，少在公门多在水。","富豪有錢駕大舸，貧窮取給行艓子。","小兒学问止論語，大兒結束隨商旅。","攲帆側柁入波濤，撇漩捎濆無險阻。","朝發白帝暮江陵，頃来目擊幸有徵。","瞿堂漫天虎鬚怒，归州长年行最能。","此乡之人氣量窄，誤競南风疎北客。","若道土無英俊才，何得山有屈原宅。"]', '诗', 'shi', '', NULL, '最能行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e675d0f2-e768-41b3-8c9e-da83383287bd', '寄裴施州', '寄裴施州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["廊廟之具裴施州，宿昔一逢無此流。","金鐘大鏞在東序，冰壺玉衡懸清秋。","自從相遇感多病，三歲爲客寬邊愁。","堯有四岳明至理，漢二千石真分憂。","幾度寄書白鹽北，苦寒贈我青羔裘。","霜雪回光避錦袖，龍蛇動篋蟠銀鉤。","紫衣使者辭復命，再拜故人謝佳政。","將老已失子孫憂，後來況接才華盛。"]', '["廊廟之具裴施州，宿昔一逢無此流。","金鐘大鏞在东序，冰壺玉衡懸清秋。","自從相遇感多病，三歲爲客寬邊愁。","堯有四岳明至理，漢二千石真分憂。","幾度寄书白鹽北，苦寒贈我青羔裘。","霜雪回光避錦袖，龙蛇动篋蟠銀鉤。","紫衣使者辞复命，再拜故人謝佳政。","將老已失子孫憂，後来況接才华盛。"]', '诗', 'shi', '', NULL, '寄裴施州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c676620-1448-4ee7-815d-35512077d8ad', '鄭典設自施州歸', '鄭典設自施州归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾憐滎陽秀，冒暑初有適。","名賢慎所出，不肯妄行役。","旅茲殊俗遠，竟以屢空迫。","南謁裴施州，氣合無險僻。","攀援懸根木，登頓入天石。","青山自一川，城郭洗憂慼。","聽子話此邦，令我心悅懌。","其俗則純樸，不知有主客。","溫溫諸侯門，禮亦如古昔。","敕廚倍常羞，杯盤頗狼藉。","時雖屬喪亂，事貴賞匹敵。","中宵愜良會，裴鄭非遠戚。","羣書一萬卷，博涉供務隙。","他日辱銀鉤，森疎見矛戟。","倒屣喜旋歸，畫地求所歷。","乃聞風土質，又重田疇闢。","刺史似寇恂，列郡宜競惜。","北風吹瘴癘，羸老思散策。","渚拂蒹葭塞，嶠穿蘿蔦冪。","此身仗兒僕，高興潛有激。","孟冬方首路，強飯取崖壁。","歎爾疲駑駘，汗溝血不赤。","終然備外飾，駕馭何所益。","我有平肩輿，前途猶準的。","翩翩入鳥道，庶脫蹉跌厄。"]', '["吾怜滎陽秀，冒暑初有適。","名賢慎所出，不肯妄行役。","旅茲殊俗远，竟以屢空迫。","南謁裴施州，氣合無險僻。","攀援懸根木，登頓入天石。","青山自一川，城郭洗憂慼。","听子話此邦，令我心悅懌。","其俗則純樸，不知有主客。","溫溫諸侯门，禮亦如古昔。","敕廚倍常羞，杯盤頗狼藉。","时雖屬喪亂，事貴賞匹敵。","中宵愜良會，裴鄭非远戚。","羣书一万卷，博涉供務隙。","他日辱銀鉤，森疎见矛戟。","倒屣喜旋归，畫地求所歷。","乃闻风土質，又重田疇闢。","刺史似寇恂，列郡宜競惜。","北风吹瘴癘，羸老思散策。","渚拂蒹葭塞，嶠穿蘿蔦冪。","此身仗兒僕，高兴潛有激。","孟冬方首路，強飯取崖壁。","歎爾疲駑駘，汗溝血不赤。","終然備外飾，駕馭何所益。","我有平肩輿，前途猶準的。","翩翩入鸟道，庶脫蹉跌厄。"]', '诗', 'shi', '', NULL, '鄭典設自施州歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae472a2c-7977-4ed6-a893-7ef7c3136666', '柴門', '柴门', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孤舟登瀼西，回首望兩崖。","東城乾旱天，其氣如焚柴。","長影沒窈窕，餘光散唅呀。","大江蟠嵌根，歸海成一家。","下衝割坤軸，竦壁攢鏌铘。","蕭颯灑秋色，氛昏霾日車。","峽門自此始，最窄容浮查。","禹功翊造化，疎鑿就攲斜。","巨渠決太古，衆水爲長蛇。","風煙渺吳蜀，舟楫通鹽麻。","我今遠遊子，飄轉混泥沙。","萬物附本性，約身不願奢。","茅棟蓋一牀，清池有餘花。","濁醪與脫粟，在眼無咨嗟。","山荒人民少，地僻日夕佳。","貧病固其常，富貴任生涯。","老於干戈際，宅幸蓬蓽遮。","石亂上雲氣，杉清延月華。","賞妍又分外，理愜夫何誇。","足了垂白年，敢居高士差。","書此豁平昔，回首猶暮霞。"]', '["孤舟登瀼西，回首望兩崖。","东城乾旱天，其氣如焚柴。","长影沒窈窕，餘光散唅呀。","大江蟠嵌根，归海成一家。","下衝割坤軸，竦壁攢鏌铘。","蕭颯灑秋色，氛昏霾日车。","峽门自此始，最窄容浮查。","禹功翊造化，疎鑿就攲斜。","巨渠決太古，衆水爲长蛇。","风煙渺吳蜀，舟楫通鹽麻。","我今远游子，飄轉混泥沙。","万物附本性，約身不願奢。","茅棟蓋一牀，清池有餘花。","濁醪與脫粟，在眼無咨嗟。","山荒人民少，地僻日夕佳。","貧病固其常，富貴任生涯。","老於干戈際，宅幸蓬蓽遮。","石亂上云氣，杉清延月华。","賞妍又分外，理愜夫何誇。","足了垂白年，敢居高士差。","书此豁平昔，回首猶暮霞。"]', '诗', 'shi', '', NULL, '柴門 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70cfbaa0-6ea5-4a6a-a6ac-0e8bbfd8413c', '貽華陽柳少府', '貽华陽柳少府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["繫馬喬木間，問人野寺門。","柳侯披衣笑，見我顏色溫。","竝坐石下堂，俛視大江奔。","火雲洗月露，絕壁上朝暾。","自非曉相訪，觸熱生病根。","南方六七月，出入異中原。","老少多暍死，汗踰水漿飜。","俊才得之子，筋力不辭煩。","指揮當世事，語及戎馬存。","涕淚濺我裳，悲氣排帝閽。","鬱陶抱長策，義仗知者論。","吾衰臥江漢，但媿識璵璠。","文章一小技，於道未爲尊。","起予幸斑白，因是託子孫。","俱客古信州，結廬依毀垣。","相去四五里，徑微山葉繁。","時危挹佳士，況免軍旅喧。","醉從趙女舞，歌鼓秦人盆。","子壯顧我傷，我驩兼淚痕。","餘生如過鳥，故里今空邨。"]', '["繫马喬木间，问人野寺门。","柳侯披衣笑，见我顏色溫。","竝坐石下堂，俛視大江奔。","火云洗月露，絕壁上朝暾。","自非晓相訪，觸熱生病根。","南方六七月，出入異中原。","老少多暍死，汗踰水漿飜。","俊才得之子，筋力不辞煩。","指揮當世事，語及戎马存。","涕泪濺我裳，悲氣排帝閽。","鬱陶抱长策，義仗知者論。","吾衰臥江漢，但媿識璵璠。","文章一小技，於道未爲尊。","起予幸斑白，因是託子孫。","俱客古信州，結廬依毀垣。","相去四五里，徑微山葉繁。","时危挹佳士，況免軍旅喧。","醉從趙女舞，歌鼓秦人盆。","子壯顧我傷，我驩兼泪痕。","餘生如過鸟，故里今空邨。"]', '诗', 'shi', '', NULL, '貽華陽柳少府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5177af03-db57-45b9-836b-9f888b793d8b', '雷', '雷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大旱山岳燋，密雲復無雨。","南方瘴癘地，罹此農事苦。","封內必舞雩，峽中喧擊鼓。","真龍竟寂莫，土梗空俯僂。","吁嗟公私病，稅斂缺不補。","故老仰面啼，瘡痍向誰數。","暴尫或前聞，鞭巫非稽古。","請先偃甲兵，處分聽人主。","萬邦但各業，一物休盡取。","水旱其數然，堯湯免親覩。","上天鑠金石，羣盜亂豺虎。","二者存一端，愆陽不猶愈。","昨宵殷其雷，風過齊萬弩。","復吹霾翳散，虛覺神靈聚。","氣暍腸胃融，汗滋衣裳污。","吾衰尤拙計，失望築場圃。"]', '["大旱山岳燋，密云复無雨。","南方瘴癘地，罹此農事苦。","封內必舞雩，峽中喧擊鼓。","真龙竟寂莫，土梗空俯僂。","吁嗟公私病，稅斂缺不補。","故老仰面啼，瘡痍向誰數。","暴尫或前闻，鞭巫非稽古。","請先偃甲兵，处分听人主。","万邦但各業，一物休尽取。","水旱其數然，堯湯免親覩。","上天鑠金石，羣盜亂豺虎。","二者存一端，愆陽不猶愈。","昨宵殷其雷，风過齊万弩。","复吹霾翳散，虛覺神靈聚。","氣暍腸胃融，汗滋衣裳污。","吾衰尤拙計，失望築場圃。"]', '诗', 'shi', '', NULL, '雷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0f88ac-e2a2-4251-b333-08f5d799cfeb', '火', '火', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚山經月火，大旱則斯舉。","舊俗燒蛟龍，驚惶致雷雨。","爆嵌魑魅泣，崩凍嵐陰昈。","羅落沸百泓，根源皆萬古。","青林一灰燼，雲氣無處所。","入夜殊赫然，新秋照牛女。","風吹巨燄作，河櫂騰煙柱。","勢欲焚崑崙，光彌焮洲渚。","腥至焦長蛇，聲吼纏猛虎。","神物已高飛，不見石與土。","爾寧要謗讟，憑此近熒侮。","薄關長吏憂，甚昧至精主。","遠遷誰撲滅，將恐及環堵。","流汗臥江亭，更深氣如縷。"]', '["楚山經月火，大旱則斯舉。","旧俗燒蛟龙，驚惶致雷雨。","爆嵌魑魅泣，崩凍嵐陰昈。","羅落沸百泓，根源皆万古。","青林一灰燼，云氣無处所。","入夜殊赫然，新秋照牛女。","风吹巨燄作，河櫂腾煙柱。","勢欲焚崑崙，光彌焮洲渚。","腥至焦长蛇，声吼纏猛虎。","神物已高飞，不见石與土。","爾寧要謗讟，憑此近熒侮。","薄关长吏憂，甚昧至精主。","远遷誰撲滅，將恐及环堵。","流汗臥江亭，更深氣如縷。"]', '诗', 'shi', '', NULL, '火 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2413b7a-cfda-4d88-8c24-6684aa4bcf8a', '七月三日亭午已後較熱退晚加小涼穩睡有詩因論壯年樂事戲呈元二十一曹長', '七月三日亭午已後較熱退晚加小涼穩睡有诗因論壯年乐事戲呈元二十一曹长', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今茲商用事，餘熱亦已末。","衰年旅炎方，生意從此活。","亭午減汗流，北鄰耐人聒。","晚風爽烏匼，筋力蘇摧折。","閉目踰十旬，大江不止渴。","退藏恨雨師，健步聞旱魃。","園蔬抱金玉，無以供采掇。","密雲雖聚散，徂暑終衰歇。","前聖眘焚巫，武王親救暍。","陰陽相主客，時序遞回斡。","灑落唯清秋，昏霾一空闊。","蕭蕭紫塞雁，南向欲行列。","歘思紅顏日，霜露凍階闥。","胡馬挾雕弓，鳴弦不虛發。","長鈚逐狡兔，突羽當滿月。","惆悵白頭吟，蕭條游俠窟。","臨軒望山閣，縹緲安可越。","高人鍊丹砂，未念將朽骨。","少壯跡頗疎，歡樂曾倏忽。","杖藜風塵際，老醜難翦拂。","吾子得神仙，本是池中物。","賤夫美一睡，煩促嬰詞筆。"]', '["今茲商用事，餘熱亦已末。","衰年旅炎方，生意從此活。","亭午減汗流，北鄰耐人聒。","晚风爽烏匼，筋力蘇摧折。","閉目踰十旬，大江不止渴。","退藏恨雨師，健步闻旱魃。","园蔬抱金玉，無以供采掇。","密云雖聚散，徂暑終衰歇。","前聖眘焚巫，武王親救暍。","陰陽相主客，时序遞回斡。","灑落唯清秋，昏霾一空闊。","蕭蕭紫塞雁，南向欲行列。","歘思紅顏日，霜露凍階闥。","胡马挾雕弓，鳴弦不虛發。","长鈚逐狡兔，突羽當满月。","惆悵白头吟，蕭條游俠窟。","臨軒望山閣，縹緲安可越。","高人鍊丹砂，未念將朽骨。","少壯跡頗疎，歡乐曾倏忽。","杖藜风塵際，老醜难翦拂。","吾子得神仙，本是池中物。","賤夫美一睡，煩促嬰词笔。"]', '诗', 'shi', '', NULL, '七月三日亭午已後較熱退晚加小涼穩睡有詩因論壯年樂事戲呈元二十一曹長 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449c81fd-d52a-40f2-ae8c-9d3fc5ddd290', '牽牛織女', '牽牛织女', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["牽牛出河西，織女處其東。","萬古永相望，七夕誰見同。","神光意難候，此事終蒙朧。","颯然精靈合，何必秋遂通。","亭亭新妝立，龍駕具曾空。","世人亦爲爾，祈請走兒童。","稱家隨豐儉，白屋達公宮。","膳夫翊堂殿，鳴玉淒房櫳。","曝衣徧天下，曳月揚微風。","蛛絲小人態，曲綴瓜果中。","初筵裛重露，日出甘所終。","嗟汝未嫁女，秉心鬱忡忡。","防身動如律，竭力機杼中。","雖無姑舅事，敢昧織作功。","明明君臣契，咫尺或未容。","義無棄禮法，恩始夫婦恭。","小大有佳期，戒之在至公。","方圓苟齟齬，丈夫多英雄。"]', '["牽牛出河西，织女处其东。","万古永相望，七夕誰见同。","神光意难候，此事終蒙朧。","颯然精靈合，何必秋遂通。","亭亭新妝立，龙駕具曾空。","世人亦爲爾，祈請走兒童。","稱家隨豐儉，白屋達公宮。","膳夫翊堂殿，鳴玉淒房櫳。","曝衣徧天下，曳月揚微风。","蛛絲小人態，曲綴瓜果中。","初筵裛重露，日出甘所終。","嗟汝未嫁女，秉心鬱忡忡。","防身动如律，竭力機杼中。","雖無姑舅事，敢昧织作功。","明明君臣契，咫尺或未容。","義無棄禮法，恩始夫婦恭。","小大有佳期，戒之在至公。","方圓苟齟齬，丈夫多英雄。"]', '诗', 'shi', '', NULL, '牽牛織女 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4229906f-4467-4500-9cf5-149be471eb11', '毒熱寄簡崔評事十六弟', '毒熱寄簡崔評事十六弟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大暑運金氣，荆揚不知秋。","林下有塌翼，水中無行舟。","千室但埽地，閉關人事休。","老夫轉不樂，旅次兼百憂。","蝮蛇暮偃蹇，空牀難暗投。","炎宵惡明燭，況乃懷舊丘。","開襟仰內弟，執熱露白頭。","束帶負芒刺，接居成阻修。","何當清霜飛，會子臨江樓。","載聞大易義，諷興詩家流。","蘊藉異時輩，檢身非苟求。","皇皇使臣體，信是德業優。","楚材擇杞梓，漢苑歸驊騮。","短章達我心，理爲識者籌。"]', '["大暑運金氣，荆揚不知秋。","林下有塌翼，水中無行舟。","千室但埽地，閉关人事休。","老夫轉不乐，旅次兼百憂。","蝮蛇暮偃蹇，空牀难暗投。","炎宵惡明燭，況乃懷旧丘。","开襟仰內弟，執熱露白头。","束带負芒刺，接居成阻修。","何當清霜飞，會子臨江楼。","載闻大易義，諷兴诗家流。","蘊藉異时輩，檢身非苟求。","皇皇使臣體，信是德業優。","楚材擇杞梓，漢苑归驊騮。","短章達我心，理爲識者籌。"]', '诗', 'shi', '', NULL, '毒熱寄簡崔評事十六弟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5dacfb-7444-484e-96d8-66ff88e6f10a', '殿中楊監見示張旭草書圖', '殿中楊監见示張旭草书圖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["斯人已云亡，草聖祕難得。","及茲煩見示，滿目一淒惻。","悲風生微綃，萬里起古色。","鏘鏘鳴玉動，落落羣松直。","連山蟠其間，溟漲與筆力。","有練實先書，臨池真盡墨。","俊拔爲之主，暮年思轉極。","未知張王後，誰竝百代則。","嗚呼東吳精，逸氣感清識。","楊公拂篋笥，舒卷忘寢食。","念昔揮毫端，不獨觀酒德。"]', '["斯人已云亡，草聖祕难得。","及茲煩见示，满目一淒惻。","悲风生微綃，万里起古色。","鏘鏘鳴玉动，落落羣松直。","連山蟠其间，溟漲與笔力。","有練實先书，臨池真尽墨。","俊拔爲之主，暮年思轉極。","未知張王後，誰竝百代則。","嗚呼东吳精，逸氣感清識。","楊公拂篋笥，舒卷忘寢食。","念昔揮毫端，不独观酒德。"]', '诗', 'shi', '', NULL, '殿中楊監見示張旭草書圖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3a92a7-6f2f-4e3f-9790-313e9daf1e9d', '楊監又出畫鷹十二扇', '楊監又出畫鷹十二扇', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["近時馮紹正，能畫鷙鳥樣。","明公出此圖，無乃傳其狀。","殊姿各獨立，清絕心有向。","疾禁千里馬，氣敵萬人將。","憶昔驪山宮，冬移含元仗。","天寒大羽獵，此物神俱王。","當時無凡材，百中皆用壯。","粉墨形似間，識者一惆悵。","干戈少暇日，真骨老崖嶂。","爲君除狡兔，會是飜韝上。"]', '["近时馮紹正，能畫鷙鸟樣。","明公出此圖，無乃傳其狀。","殊姿各独立，清絕心有向。","疾禁千里马，氣敵万人將。","憶昔驪山宮，冬移含元仗。","天寒大羽獵，此物神俱王。","當时無凡材，百中皆用壯。","粉墨形似间，識者一惆悵。","干戈少暇日，真骨老崖嶂。","爲君除狡兔，會是飜韝上。"]', '诗', 'shi', '', NULL, '楊監又出畫鷹十二扇 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf99b21-ab26-43d3-aabb-9a06cf6d8953', '送殿中楊監赴蜀見相公', '送殿中楊監赴蜀见相公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去水絕還波，洩雲無定姿。","人生在世間，聚散亦暫時。","離別重相逢，偶然豈定期。","送子清秋暮，風物長年悲。","豪俊貴勳業，邦家頻出師。","相公鎮梁益，軍事無孑遺。","解榻再見今，用才復擇誰。","況子已高位，爲郡得固辭。","難拒供給費，慎哀漁奪私。","干戈未甚息，紀綱正所持。","泛舟巨石橫，登陸草露滋。","山門日易久，當念居者思。"]', '["去水絕還波，洩云無定姿。","人生在世间，聚散亦暫时。","離別重相逢，偶然豈定期。","送子清秋暮，风物长年悲。","豪俊貴勳業，邦家頻出師。","相公鎮梁益，軍事無孑遺。","解榻再见今，用才复擇誰。","況子已高位，爲郡得固辞。","难拒供給費，慎哀漁奪私。","干戈未甚息，紀綱正所持。","泛舟巨石橫，登陸草露滋。","山门日易久，當念居者思。"]', '诗', 'shi', '', NULL, '送殿中楊監赴蜀見相公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebfe689-4572-4375-82b0-820b7f14d4fb', '贈李十五丈別', '贈李十五丈別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽人鳥獸居，其室附層顛。","下臨不測江，中有萬里船。","多病紛倚薄，少留改歲年。","絕域誰慰懷，開顏喜名賢。","孤陋忝末親，等級敢比肩。","人生意頗合，相與襟袂連。","一日兩遣僕，三日一共筵。","揚論展寸心，壯筆過飛泉。","玄成美價存，子山舊業傳。","不聞八尺軀，常受衆目憐。","且爲辛苦行，蓋被生事牽。","北回白帝櫂，南入黔陽天。","汧公制方隅，迥出諸侯先。","封內如太古，時危獨蕭然。","清高金莖露，正直朱絲弦。","昔在堯四岳，今之黃潁川。","于邁恨不同，所思無由宣。","山深水增波，解榻秋露懸。","客遊雖云久，主要月再圓。","晨集風渚亭，醉操雲嶠篇。","丈夫貴知己，歡罷念歸旋。"]', '["峽人鸟獸居，其室附層顛。","下臨不測江，中有万里船。","多病紛倚薄，少留改歲年。","絕域誰慰懷，开顏喜名賢。","孤陋忝末親，等級敢比肩。","人生意頗合，相與襟袂連。","一日兩遣僕，三日一共筵。","揚論展寸心，壯笔過飞泉。","玄成美價存，子山旧業傳。","不闻八尺軀，常受衆目怜。","且爲辛苦行，蓋被生事牽。","北回白帝櫂，南入黔陽天。","汧公制方隅，迥出諸侯先。","封內如太古，时危独蕭然。","清高金莖露，正直朱絲弦。","昔在堯四岳，今之黄潁川。","于邁恨不同，所思無由宣。","山深水增波，解榻秋露懸。","客游雖云久，主要月再圓。","晨集风渚亭，醉操云嶠篇。","丈夫貴知己，歡罷念归旋。"]', '诗', 'shi', '', NULL, '贈李十五丈別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57990c9f-c5a0-479a-81bc-284da6828046', '西閣曝日', '西閣曝日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["凜冽倦玄冬，負暄嗜飛閣。","羲和流德澤，顓頊媿倚薄。","毛髮具自和，肌膚潛沃若。","太陽信深仁，衰氣歘有託。","攲傾煩注眼，容易收病脚。","流離木杪猨，翩躚山顛鶴。","用知苦聚散，哀樂日已作。","即事會賦詩，人生忽如昨。","古來遭喪亂，賢聖盡蕭索。","胡爲將暮年，憂世心力弱。"]', '["凜冽倦玄冬，負暄嗜飞閣。","羲和流德澤，顓頊媿倚薄。","毛髮具自和，肌膚潛沃若。","太陽信深仁，衰氣歘有託。","攲傾煩注眼，容易收病脚。","流離木杪猨，翩躚山顛鹤。","用知苦聚散，哀乐日已作。","即事會賦诗，人生忽如昨。","古来遭喪亂，賢聖尽蕭索。","胡爲將暮年，憂世心力弱。"]', '诗', 'shi', '', NULL, '西閣曝日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a334a5a-5aad-4261-b2e3-54524c4ad9f2', '課伐木', '課伐木', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長夏無所爲，客居課奴僕。","清晨飯其腹，持斧入白谷。","青冥曾巔後，十里斬陰木。","人肩四根已，亭午下山麓。","尚聞丁丁聲，功課日各足。","蒼皮成委積，素節相照燭。","藉汝跨小籬，當仗苦虛竹。","空荒咆熊羆，乳獸待人肉。","不示知禁情，豈惟干戈哭。","城中賢府主，處貴如白屋。","蕭蕭理體淨，蠭蠆不敢毒。","虎穴連里閭，隄防舊風俗。","泊舟滄江岸，久客慎所觸。","舍西崖嶠壯，雷雨蔚含蓄。","牆宇資屢修，衰年怯幽獨。","爾曹輕執熱，爲我忍煩促。","秋光近青岑，季月當泛菊。","報之以微寒，共給酒一斛。"]', '["长夏無所爲，客居課奴僕。","清晨飯其腹，持斧入白谷。","青冥曾巔後，十里斬陰木。","人肩四根已，亭午下山麓。","尚闻丁丁声，功課日各足。","蒼皮成委積，素節相照燭。","藉汝跨小籬，當仗苦虛竹。","空荒咆熊羆，乳獸待人肉。","不示知禁情，豈惟干戈哭。","城中賢府主，处貴如白屋。","蕭蕭理體淨，蠭蠆不敢毒。","虎穴連里閭，隄防旧风俗。","泊舟滄江岸，久客慎所觸。","舍西崖嶠壯，雷雨蔚含蓄。","牆宇資屢修，衰年怯幽独。","爾曹轻執熱，爲我忍煩促。","秋光近青岑，季月當泛菊。","報之以微寒，共給酒一斛。"]', '诗', 'shi', '', NULL, '課伐木 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c01eb1-1eb8-4d68-b25e-ae244c049afc', '園人送瓜', '园人送瓜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江間雖炎瘴，瓜熟亦不早。","柏公鎮夔國，滯務茲一埽。","食新先戰士，共少及溪老。","傾筐蒲鴿青，滿眼顏色好。","竹竿接嵌竇，引注來鳥道。","沈浮亂水玉，愛惜如芝草。","落刃嚼冰霜，開懷慰枯槁。","許以秋蔕除，仍看小童抱。","東陵跡蕪絕，楚漢休征討。","園人非故侯，種此何草草。"]', '["江间雖炎瘴，瓜熟亦不早。","柏公鎮夔国，滯務茲一埽。","食新先戰士，共少及溪老。","傾筐蒲鴿青，满眼顏色好。","竹竿接嵌竇，引注来鸟道。","沈浮亂水玉，愛惜如芝草。","落刃嚼冰霜，开懷慰枯槁。","許以秋蔕除，仍看小童抱。","东陵跡蕪絕，楚漢休征討。","园人非故侯，種此何草草。"]', '诗', 'shi', '', NULL, '園人送瓜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eef1d5f-2011-4417-be2c-57667aa3bea6', '信行遠修水筒', '信行远修水筒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝性不茹葷，清靜僕夫內。","秉心識本源，於事少滯礙。","雲端水筒坼，林表山石碎。","觸熱藉子修，通流與廚會。","往來四十里，荒險崖谷大。","日熏驚未餐，貌赤媿相對。","浮瓜供老病，裂餅嘗所愛。","於斯荅恭謹，足以殊殿最。","詎要方士符，何假將軍蓋。","行諸直如筆，用意崎嶇外。"]', '["汝性不茹葷，清静僕夫內。","秉心識本源，於事少滯礙。","云端水筒坼，林表山石碎。","觸熱藉子修，通流與廚會。","往来四十里，荒險崖谷大。","日熏驚未餐，貌赤媿相对。","浮瓜供老病，裂餅嘗所愛。","於斯荅恭謹，足以殊殿最。","詎要方士符，何假將軍蓋。","行諸直如笔，用意崎嶇外。"]', '诗', 'shi', '', NULL, '信行遠修水筒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca42b16b-5f16-40f4-8291-34970d922fac', '槐葉冷淘', '槐葉冷淘', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青青高槐葉，采掇付中廚。","新麪來近市，汁滓宛相俱。","入鼎資過熟，加餐愁欲無。","碧鮮俱照箸，香飯兼苞蘆。","經齒冷於雪，勸人投此珠。","願隨金騕褭，走置錦屠蘇。","路遠思恐泥，興深終不渝。","獻芹則小小，薦藻明區區。","萬里露寒殿，開冰清玉壺。","君王納涼晚，此味亦時須。"]', '["青青高槐葉，采掇付中廚。","新麪来近市，汁滓宛相俱。","入鼎資過熟，加餐愁欲無。","碧鲜俱照箸，香飯兼苞蘆。","經齒冷於雪，勸人投此珠。","願隨金騕褭，走置錦屠蘇。","路远思恐泥，兴深終不渝。","獻芹則小小，薦藻明區區。","万里露寒殿，开冰清玉壺。","君王納涼晚，此味亦时須。"]', '诗', 'shi', '', NULL, '槐葉冷淘 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed927451-c3fd-4566-97a2-c86f8c2fa756', '行官張望補稻畦水歸', '行官張望補稻畦水归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東屯大江北，百頃平若案。","六月青稻多，千畦碧泉亂。","插秧適云已，引溜加溉灌。","更僕往方塘，決渠當斷岸。","公私各地著，浸潤無天旱。","主守問家臣，分明見溪伴。","芊芊炯翠羽，剡剡生銀漢。","歐鳥鏡裏來，關山雲邊看。","秋菰成黑米，精鑿傳白粲。","玉粒足晨炊，紅鮮任霞散。","終然添旅食，作苦期壯觀。","遺穗及衆多，我倉戒滋蔓。"]', '["东屯大江北，百頃平若案。","六月青稻多，千畦碧泉亂。","插秧適云已，引溜加溉灌。","更僕往方塘，決渠當斷岸。","公私各地著，浸潤無天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生銀漢。","歐鸟镜裏来，关山云邊看。","秋菰成黑米，精鑿傳白粲。","玉粒足晨炊，紅鲜任霞散。","終然添旅食，作苦期壯观。","遺穗及衆多，我倉戒滋蔓。"]', '诗', 'shi', '', NULL, '行官張望補稻畦水歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8eb9d52-faa2-42b8-9ed3-3bec5f1413d6', '催宗文樹雞柵', '催宗文樹雞柵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾衰怯行邁，旅次展崩迫。","愈風傳烏雞，秋卵方漫喫。","自春生成者，隨母向百翮。","驅趁制不禁，喧呼山腰宅。","課奴殺青竹，終日憎赤幘。","蹋藉盤案飜，塞蹊使之隔。","牆東有隙地，可以樹高柵。","避熱時來歸，問兒所爲跡。","織籠曹其內，令入不得擲。","稀間可突過，觜爪還污席。","我寬螻蟻遭，彼免狐貉厄。","應宜各長幼，自此均勍敵。","籠柵念有修，近身見損益。","明明領處分，一一當剖析。","不昧風雨晨，亂離減憂慽。","其流則凡鳥，其氣心匪石。","倚賴窮歲晏，撥煩去冰釋。","未似尸鄉翁，拘留蓋阡陌。"]', '["吾衰怯行邁，旅次展崩迫。","愈风傳烏雞，秋卵方漫喫。","自春生成者，隨母向百翮。","驱趁制不禁，喧呼山腰宅。","課奴殺青竹，終日憎赤幘。","蹋藉盤案飜，塞蹊使之隔。","牆东有隙地，可以樹高柵。","避熱时来归，问兒所爲跡。","织籠曹其內，令入不得擲。","稀间可突過，觜爪還污席。","我寬螻蟻遭，彼免狐貉厄。","應宜各长幼，自此均勍敵。","籠柵念有修，近身见損益。","明明領处分，一一當剖析。","不昧风雨晨，亂離減憂慽。","其流則凡鸟，其氣心匪石。","倚賴窮歲晏，撥煩去冰釋。","未似尸乡翁，拘留蓋阡陌。"]', '诗', 'shi', '', NULL, '催宗文樹雞柵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246ff90e-bd5c-4e81-8637-f1605fa647d9', '園官送茶', '园官送茶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清晨蒙菜把，常荷地主恩。","守者愆實數，略有其名存。","苦苣刺如針，馬齒葉亦繁。","青青嘉蔬色，埋沒在中園。","園吏未足怪，世事固堪論。","嗚呼戰伐久，荆棘暗長原。","乃知苦苣輩，傾奪蕙草根。","小人塞道路，爲態何喧喧。","又如馬齒盛，氣擁葵荏昏。","點染不易虞，絲麻雜羅紈。","一經器物內，永挂麤刺痕。","志士采紫芝，放歌避戎軒。","畦丁負籠至，感動百慮端。"]', '["清晨蒙菜把，常荷地主恩。","守者愆實數，略有其名存。","苦苣刺如針，马齒葉亦繁。","青青嘉蔬色，埋沒在中园。","园吏未足怪，世事固堪論。","嗚呼戰伐久，荆棘暗长原。","乃知苦苣輩，傾奪蕙草根。","小人塞道路，爲態何喧喧。","又如马齒盛，氣擁葵荏昏。","点染不易虞，絲麻杂羅紈。","一經器物內，永挂麤刺痕。","志士采紫芝，放歌避戎軒。","畦丁負籠至，感动百慮端。"]', '诗', 'shi', '', NULL, '園官送茶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26580e07-44fb-4e5c-b6a2-9da99a0ef0a1', '上後園山脚', '上後园山脚', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朱夏熱所嬰，清旭步北林。","小園背高岡，挽葛上崎崟。","曠望延駐目，飄颻散疎襟。","潛鱗恨水壯，去翼依雲深。","勿謂地無疆，劣於山有陰。","石榞徧天下，水陸兼浮沈。","自我登隴首，十年經碧岑。","劒門來巫峽，薄倚浩至今。","故園暗戎馬，骨肉失追尋。","時危無消息，老去多歸心。","志士惜白日，久客藉黃金。","敢爲蘇門嘯，庶作梁父吟。"]', '["朱夏熱所嬰，清旭步北林。","小园背高岡，挽葛上崎崟。","曠望延駐目，飄颻散疎襟。","潛鱗恨水壯，去翼依云深。","勿謂地無疆，劣於山有陰。","石榞徧天下，水陸兼浮沈。","自我登隴首，十年經碧岑。","劒门来巫峽，薄倚浩至今。","故园暗戎马，骨肉失追尋。","时危無消息，老去多归心。","志士惜白日，久客藉黄金。","敢爲蘇门嘯，庶作梁父吟。"]', '诗', 'shi', '', NULL, '上後園山脚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ebb60f-02a0-4915-900a-eade0191f674', '驅豎子摘蒼耳', '驱豎子摘蒼耳', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江上秋已分，林中瘴猶劇。","畦丁告勞苦，無以供日夕。","蓬莠獨不焦，野蔬暗泉石。","卷耳況療風，童兒且時摘。","侵星驅之去，爛熳任遠適。","放筐亭午際，洗剝相蒙冪。","登牀半生熟，下箸還小益。","加點瓜薤間，依稀橘奴跡。","亂世誅求急，黎民糠籺窄。","飽食復何心，荒哉膏粱客。","富家廚肉臭，戰地骸骨白。","寄語惡少年，黃金且休擲。"]', '["江上秋已分，林中瘴猶劇。","畦丁告勞苦，無以供日夕。","蓬莠独不焦，野蔬暗泉石。","卷耳況療风，童兒且时摘。","侵星驱之去，爛熳任远適。","放筐亭午際，洗剝相蒙冪。","登牀半生熟，下箸還小益。","加点瓜薤间，依稀橘奴跡。","亂世誅求急，黎民糠籺窄。","飽食复何心，荒哉膏粱客。","富家廚肉臭，戰地骸骨白。","寄語惡少年，黄金且休擲。"]', '诗', 'shi', '', NULL, '驅豎子摘蒼耳 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bf5676-319c-460e-b5b2-e53daad7f6d0', '秋行官張請督促東渚耗稻向畢清晨遣女奴阿稽豎子阿段往問', '秋行官張請督促东渚耗稻向畢清晨遣女奴阿稽豎子阿段往问', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東渚雨今足，佇聞稉稻香。","上天無偏頗，蒲稗各自長。","人情見非類，田家戒其荒。","功夫競搰搰，除草置岸旁。","穀者命之本，客居安可忘。","青春具所務，勤墾免亂常。","吳牛力容易，竝驅動莫當。","豐苗亦已穊，雲水照方塘。","有生固蔓延，靜一資隄防。","督領不無人，提攜頗在綱。","荆揚風土暖，肅肅候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢僕，寄語踰崇岡。","西成聚必散，不獨陵我倉。","豈要仁里譽，感此亂世忙。","北風吹蒹葭，蟋蟀近中堂。","荏苒百工休，鬱紆遲暮傷。"]', '["东渚雨今足，佇闻稉稻香。","上天無偏頗，蒲稗各自长。","人情见非類，田家戒其荒。","功夫競搰搰，除草置岸旁。","穀者命之本，客居安可忘。","青春具所務，勤墾免亂常。","吳牛力容易，竝驱动莫當。","豐苗亦已穊，云水照方塘。","有生固蔓延，静一資隄防。","督領不無人，提携頗在綱。","荆揚风土暖，肅肅候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢僕，寄語踰崇岡。","西成聚必散，不独陵我倉。","豈要仁里譽，感此亂世忙。","北风吹蒹葭，蟋蟀近中堂。","荏苒百工休，鬱紆遲暮傷。"]', '诗', 'shi', '', NULL, '秋行官張請督促東渚耗稻向畢清晨遣女奴阿稽豎子阿段往問 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b39f91-4d82-4166-b291-d73be5d35733', '阻雨不得歸瀼西甘林', '阻雨不得归瀼西甘林', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三伏適已過，驕陽化爲霖。","欲歸瀼西宅，阻此江浦深。","壞舟百版坼，峻岸復萬尋。","篙工初一棄，恐泥勞寸心。","佇立東城隅，悵望高飛禽。","草堂亂懸圃，不隔崑崙岑。","昏渾衣裳外，曠絕同層陰。","園甘長成時，三寸如黃金。","諸侯舊上計，厥貢傾千林。","邦人不足重，所迫豪吏侵。","客居暫封殖，日夜偶瑤琴。","虛徐五株態，側塞煩胸襟。","焉得輟兩足，杖藜出嶇嶔。","條流數翠實，偃息歸碧潯。","拂拭烏皮几，喜聞樵牧音。","令兒快搔背，脫我頭上簪。"]', '["三伏適已過，驕陽化爲霖。","欲归瀼西宅，阻此江浦深。","壞舟百版坼，峻岸复万尋。","篙工初一棄，恐泥勞寸心。","佇立东城隅，悵望高飞禽。","草堂亂懸圃，不隔崑崙岑。","昏渾衣裳外，曠絕同層陰。","园甘长成时，三寸如黄金。","諸侯旧上計，厥貢傾千林。","邦人不足重，所迫豪吏侵。","客居暫封殖，日夜偶瑤琴。","虛徐五株態，側塞煩胸襟。","焉得輟兩足，杖藜出嶇嶔。","條流數翠實，偃息归碧潯。","拂拭烏皮几，喜闻樵牧音。","令兒快搔背，脫我头上簪。"]', '诗', 'shi', '', NULL, '阻雨不得歸瀼西甘林 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c092e6-cdc6-43e3-a7cd-54397c4f31dd', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽雲行清曉，煙霧相裴回。","風吹蒼江樹，雨灑石壁來。","淒淒生餘寒，殷殷兼出雷。","白谷變氣候，朱炎安在哉？","高鳥濕不下，居人門未開。","楚宮久已滅，幽佩爲誰哀。","侍臣書王夢，賦有冠古才。","冥冥翠龍駕，多自巫山臺。"]', '["峽云行清晓，煙霧相裴回。","风吹蒼江樹，雨灑石壁来。","淒淒生餘寒，殷殷兼出雷。","白谷变氣候，朱炎安在哉？","高鸟濕不下，居人门未开。","楚宮久已滅，幽佩爲誰哀。","侍臣书王梦，賦有冠古才。","冥冥翠龙駕，多自巫山台。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c35064-6bb1-4b91-a555-c2ae3768ec7c', '雨二首 一', '雨二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青山澹無姿，白露誰能數。","片片水上雲，蕭蕭沙中雨。","殊俗狀巢居，曾臺俯風渚。","佳客適萬里，沈思情延佇。","挂帆遠色外，驚浪滿吳楚。","久陰蛟螭出，寇盜復幾許。"]', '["青山澹無姿，白露誰能數。","片片水上云，蕭蕭沙中雨。","殊俗狀巢居，曾台俯风渚。","佳客適万里，沈思情延佇。","挂帆远色外，驚浪满吳楚。","久陰蛟螭出，寇盜复幾許。"]', '诗', 'shi', '', NULL, '雨二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0befbd-3655-4d16-8413-0d699c88e75c', '雨二首 二', '雨二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["空山中宵陰，微冷先枕席。","迴風起清曙，萬象萋已碧。","落落出岫雲，渾渾倚天石。","日假何道行，雨含長江白。","連檣荆州船，有士荷矛戟。","南防草鎮慘，霑濕赴遠役。","羣盜下辟山，總戎備強敵。","水深雲光廓，鳴櫓各有適。","漁艇息悠悠，夷歌負樵客。","留滯一老翁，書時記朝夕。"]', '["空山中宵陰，微冷先枕席。","迴风起清曙，万象萋已碧。","落落出岫云，渾渾倚天石。","日假何道行，雨含长江白。","連檣荆州船，有士荷矛戟。","南防草鎮慘，霑濕赴远役。","羣盜下辟山，總戎備強敵。","水深云光廓，鳴櫓各有適。","漁艇息悠悠，夷歌負樵客。","留滯一老翁，书时記朝夕。"]', '诗', 'shi', '', NULL, '雨二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5a9040-28e2-4179-8a83-b211cd4b0341', '晚登瀼上堂', '晚登瀼上堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故躋瀼岸高，頗免崖石擁。","開襟野堂豁，繫馬林花動。","雉堞粉如雲，山田麥無壠。","春氣晚更生，江流靜猶湧。","四序嬰我懷，羣盜久相踵。","黎民困逆節，天子渴垂拱。","所思注東北，深峽轉修聳。","衰老自成病，郎官未爲冗。","淒其望呂葛，不復夢周孔。","濟世數嚮時，斯人各枯冢。","楚星南天黑，蜀月西霧重。","安得隨鳥翎，迫此懼將恐。"]', '["故躋瀼岸高，頗免崖石擁。","开襟野堂豁，繫马林花动。","雉堞粉如云，山田麦無壠。","春氣晚更生，江流静猶湧。","四序嬰我懷，羣盜久相踵。","黎民困逆節，天子渴垂拱。","所思注东北，深峽轉修聳。","衰老自成病，郎官未爲冗。","淒其望呂葛，不复梦周孔。","濟世數嚮时，斯人各枯冢。","楚星南天黑，蜀月西霧重。","安得隨鸟翎，迫此懼將恐。"]', '诗', 'shi', '', NULL, '晚登瀼上堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6dd0da-55f1-411a-bfd7-a85c4693c996', '又上後園山脚', '又上後园山脚', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔我遊山東，憶戲東嶽陽。","窮秋立日觀，矯首望八荒。","朱崖著毫髮，碧海吹衣裳。","蓐收困用事，玄冥蔚強梁。","逝水自朝宗，鎮名各其方。","平原獨顦顇，農力廢耕桑。","非關風露凋，曾是戍役傷。","於時國用富，足以守邊疆。","朝廷任猛將，遠奪戎虜場。","到今事反覆，故老淚萬行。","龜蒙不復見，況乃懷舊鄉。","肺萎屬久戰，骨出熱中腸。","憂來杖匣劒，更上林北岡。","瘴毒猨鳥落，峽乾南日黃。","秋風亦已起，江漢始如湯。","登高欲有往，蕩析川無梁。","哀彼遠征人，去家死路旁。","不及祖父塋，纍纍冢相當。"]', '["昔我游山东，憶戲东嶽陽。","窮秋立日观，矯首望八荒。","朱崖著毫髮，碧海吹衣裳。","蓐收困用事，玄冥蔚強梁。","逝水自朝宗，鎮名各其方。","平原独顦顇，農力廢耕桑。","非关风露凋，曾是戍役傷。","於时国用富，足以守邊疆。","朝廷任猛將，远奪戎虜場。","到今事反覆，故老泪万行。","龟蒙不复见，況乃懷旧乡。","肺萎屬久戰，骨出熱中腸。","憂来杖匣劒，更上林北岡。","瘴毒猨鸟落，峽乾南日黄。","秋风亦已起，江漢始如湯。","登高欲有往，蕩析川無梁。","哀彼远征人，去家死路旁。","不及祖父塋，纍纍冢相當。"]', '诗', 'shi', '', NULL, '又上後園山脚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5abbb6-01a9-4346-8ba9-29770f446154', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山雨不作埿，江雲薄爲霧。","晴飛半嶺鶴，風亂平沙樹。","明滅洲景微，隱見巖姿露。","拘悶出門遊，曠絕經目趣。","消中日伏枕，臥久塵及屨。","豈無平肩輿，莫辨望鄉路。","兵戈浩未息，蛇虺反相顧。","悠悠邊月破，鬱鬱流年度。","針灸阻朋曹，糠籺對童孺。","一命須屈色，新知漸成故。","窮荒益自卑，飄泊欲誰訴。","虺羸愁應接，俄頃恐違迕。","浮俗何萬端，幽人有獨步。","龐公竟獨往，尚子終罕遇。","宿留洞庭秋，天寒瀟湘素。","杖策可入舟，送此齒髮暮。"]', '["山雨不作埿，江云薄爲霧。","晴飞半嶺鹤，风亂平沙樹。","明滅洲景微，隐见巖姿露。","拘悶出门游，曠絕經目趣。","消中日伏枕，臥久塵及屨。","豈無平肩輿，莫辨望乡路。","兵戈浩未息，蛇虺反相顧。","悠悠邊月破，鬱鬱流年度。","針灸阻朋曹，糠籺对童孺。","一命須屈色，新知漸成故。","窮荒益自卑，飄泊欲誰訴。","虺羸愁應接，俄頃恐違迕。","浮俗何万端，幽人有独步。","龐公竟独往，尚子終罕遇。","宿留洞庭秋，天寒瀟湘素。","杖策可入舟，送此齒髮暮。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3c8790-6ad2-47ce-8295-ee5512ba2d28', '甘林', '甘林', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舍舟越西岡，入林解我衣。","青芻適馬性，好鳥知人歸。","晨光映遠岫，夕露見日晞。","遲暮少寢食，清曠喜荆扉。","經過倦俗態，在野無所違。","試問甘藜藿，未肯羨輕肥。","喧靜不同科，出處各天機。","勿矜朱門是，陋此白屋非。","明朝步鄰里，長老可以依。","時危賦斂數，脫粟爲爾揮。","相攜行荳田，秋花靄菲菲。","子實不得喫，貨市送王畿。","盡添軍旅用，迫此公家威。","主人長跪問，戎馬何時稀。","我衰易悲傷，屈指數賊圍。","勸其死王命，慎莫遠奮飛。"]', '["舍舟越西岡，入林解我衣。","青芻適马性，好鸟知人归。","晨光映远岫，夕露见日晞。","遲暮少寢食，清曠喜荆扉。","經過倦俗態，在野無所違。","試问甘藜藿，未肯羨轻肥。","喧静不同科，出处各天機。","勿矜朱门是，陋此白屋非。","明朝步鄰里，长老可以依。","时危賦斂數，脫粟爲爾揮。","相携行荳田，秋花靄菲菲。","子實不得喫，貨市送王畿。","尽添軍旅用，迫此公家威。","主人长跪问，戎马何时稀。","我衰易悲傷，屈指數賊圍。","勸其死王命，慎莫远奮飞。"]', '诗', 'shi', '', NULL, '甘林 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f9e8b4-e32d-49e7-af89-50e05880b662', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["行雲遞崇高，飛雨靄而至。","潺潺石間溜，汩汩松上駛。","亢陽乘秋熱，百穀皆已棄。","皇天德澤降，焦卷有生意。","前雨傷卒暴，今雨喜容易。","不可無雷霆，間作鼓增氣。","佳聲達中宵，所望時一致。","清霜九月天，髣髴見滯穗。","郊扉及我私，我圃日蒼翠。","恨無抱甕力，庶減臨江費。"]', '["行云遞崇高，飞雨靄而至。","潺潺石间溜，汩汩松上駛。","亢陽乘秋熱，百穀皆已棄。","皇天德澤降，焦卷有生意。","前雨傷卒暴，今雨喜容易。","不可無雷霆，间作鼓增氣。","佳声達中宵，所望时一致。","清霜九月天，髣髴见滯穗。","郊扉及我私，我圃日蒼翠。","恨無抱甕力，庶減臨江費。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44b9d2a-65fb-40d6-ba19-6cea71b89b53', '種萵苣', '種萵苣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陰陽一錯亂，驕蹇不復理。","枯旱於其中，炎方慘如燬。","植物半蹉跎，嘉生將已矣。","雲雷歘奔命，師伯集所使。","指麾赤白日，澒洞青光起。","雨聲先已風，散足盡西靡。","山泉落滄江，霹靂猶在耳。","終朝紆颯沓，信宿罷瀟灑。","堂下可以畦，呼童對經始。","苣兮蔬之常，隨事蓺其子。","破塊數席間，荷鋤功易止。","兩旬不甲坼，空惜埋泥滓。","野莧迷汝來，宗生實於此。","此輩豈無秋，亦蒙寒露委。","飜然出地速，滋蔓戶庭毀。","因知邪干正，掩抑至沒齒。","賢良雖得祿，守道不封己。","擁寒敗芝蘭，衆多盛荆杞。","中園陷蕭艾，老圃永爲恥。","登於白玉盤，藉以如霞綺。","莧也無所施，胡顏入筐篚。"]', '["陰陽一錯亂，驕蹇不复理。","枯旱於其中，炎方慘如燬。","植物半蹉跎，嘉生將已矣。","云雷歘奔命，師伯集所使。","指麾赤白日，澒洞青光起。","雨声先已风，散足尽西靡。","山泉落滄江，霹靂猶在耳。","終朝紆颯沓，信宿罷瀟灑。","堂下可以畦，呼童对經始。","苣兮蔬之常，隨事蓺其子。","破塊數席间，荷鋤功易止。","兩旬不甲坼，空惜埋泥滓。","野莧迷汝来，宗生實於此。","此輩豈無秋，亦蒙寒露委。","飜然出地速，滋蔓戶庭毀。","因知邪干正，掩抑至沒齒。","賢良雖得祿，守道不封己。","擁寒敗芝蘭，衆多盛荆杞。","中园陷蕭艾，老圃永爲恥。","登於白玉盤，藉以如霞綺。","莧也無所施，胡顏入筐篚。"]', '诗', 'shi', '', NULL, '種萵苣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc01d10d-a14f-40e0-9e3e-74a2a3c01115', '暇日小園散病將種秋菜督勒耕牛兼書觸目', '暇日小园散病將種秋菜督勒耕牛兼书觸目', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不愛入州府，畏人嫌我真。","及乎歸茅宇，旁舍未曾嗔。","老病忌拘束，應接喪精神。","江邨意自放，林木心所欣。","秋耕屬地濕，山雨近甚勻。","冬菁飯之半，牛力晚來新。","深耕種數畝，未甚後四鄰。","嘉蔬既不一，名數頗具陳。","荆巫非苦寒，采擷接青春。","飛來兩白鶴，暮啄泥中芹。","雄者左翮垂，損傷已露筋。","一步再流血，尚經矰繳勤。","三步六號叫，志屈悲哀頻。","鸞皇不相待，側頸訴高旻。","杖藜俯沙渚，爲汝鼻酸辛。"]', '["不愛入州府，畏人嫌我真。","及乎归茅宇，旁舍未曾嗔。","老病忌拘束，應接喪精神。","江邨意自放，林木心所欣。","秋耕屬地濕，山雨近甚勻。","冬菁飯之半，牛力晚来新。","深耕種數畝，未甚後四鄰。","嘉蔬既不一，名數頗具陳。","荆巫非苦寒，采擷接青春。","飞来兩白鹤，暮啄泥中芹。","雄者左翮垂，損傷已露筋。","一步再流血，尚經矰繳勤。","三步六號叫，志屈悲哀頻。","鸾皇不相待，側頸訴高旻。","杖藜俯沙渚，爲汝鼻酸辛。"]', '诗', 'shi', '', NULL, '暇日小園散病將種秋菜督勒耕牛兼書觸目 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40c8fa66-2802-43df-ada6-1bd286cb49db', '八哀詩 贈司空王公思禮', '八哀诗 贈司空王公思禮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["司空出東夷，童稚刷勁翮。","追隨燕薊兒，穎銳物不隔。","服事哥舒翰，意無流沙磧。","未甚拔行間，犬戎大充斥。","短小精悍姿，屹然強寇敵。","貫穿百萬衆，出入由咫尺。","馬鞍懸將首，甲外控鳴鏑。","洗劒青海水，刻銘天山石。","九曲非外蕃，其王轉深壁。","飛兔不近駕，鷙鳥資遠擊。","曉達兵家流，飽聞春秋癖。","胷襟日沈靜，肅肅自有適。","潼關初潰散，萬乘猶辟易。","偏裨無所施，元帥見手格。","太子入朔方，至尊狩梁益。","胡馬纏伊洛，中原氣甚逆。","肅宗登寶位，塞望勢敦迫。","公時徒步至，請罪將厚責。","際會清河公，間道傳玉冊天王拜跪畢，讜議果冰釋。","翠華卷飛雪，熊虎亙阡陌。","屯兵鳳皇山，帳殿涇渭闢。","金成賊咽喉詔鎮雄所搤。","禁暴清無雙，爽氣春淅瀝。","巷有從公歌，野多青青麥。","及夫哭廟後，復領太原役恐懼祿位高，悵望王土窄。","不得見清時，嗚呼就窀穸。","永繫五湖舟，悲甚田橫客。","千秋汾晉間，事與雲水白。","昔觀文苑傳，豈述廉藺績。","嗟嗟鄧大夫，士卒終倒戟。"]', '["司空出东夷，童稚刷勁翮。","追隨燕薊兒，穎銳物不隔。","服事哥舒翰，意無流沙磧。","未甚拔行间，犬戎大充斥。","短小精悍姿，屹然強寇敵。","貫穿百万衆，出入由咫尺。","马鞍懸將首，甲外控鳴鏑。","洗劒青海水，刻銘天山石。","九曲非外蕃，其王轉深壁。","飞兔不近駕，鷙鸟資远擊。","晓達兵家流，飽闻春秋癖。","胷襟日沈静，肅肅自有適。","潼关初潰散，万乘猶辟易。","偏裨無所施，元帥见手格。","太子入朔方，至尊狩梁益。","胡马纏伊洛，中原氣甚逆。","肅宗登寶位，塞望勢敦迫。","公时徒步至，請罪將厚責。","際會清河公，间道傳玉冊天王拜跪畢，讜議果冰釋。","翠华卷飞雪，熊虎亙阡陌。","屯兵鳳皇山，帳殿涇渭闢。","金成賊咽喉詔鎮雄所搤。","禁暴清無雙，爽氣春淅瀝。","巷有從公歌，野多青青麦。","及夫哭廟後，复領太原役恐懼祿位高，悵望王土窄。","不得见清时，嗚呼就窀穸。","永繫五湖舟，悲甚田橫客。","千秋汾晉间，事與云水白。","昔观文苑傳，豈述廉藺績。","嗟嗟鄧大夫，士卒終倒戟。"]', '诗', 'shi', '', NULL, '八哀詩 贈司空王公思禮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee523bdd-916e-4c51-b261-5bbc2d6f5bfd', '八哀詩 故司徒李公光弼', '八哀诗 故司徒李公光弼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["司徒天寶末，北收晉陽甲。","胡騎攻吾城，愁寂意不愜。","人安若泰山，薊北斷右脅。","朔方氣乃蘇，黎首見帝業。","二宮泣西郊，九廟起頹壓。","未散河陽卒，思明僞臣妾。","復自碣石來，火焚乾坤獵。","高視笑祿山，公又大獻捷。","異王冊崇勳，小敵信所怯。","擁兵鎮河汴，千里初妥帖。","青蠅紛營營，風雨秋一葉。","內省未入朝死淚終映睫。","大屋去高棟，長城埽遺堞。","平生白羽扇，零落蛟龍匣。","雅望與英姿，惻愴槐里接。","三軍晦光彩，烈士痛稠疊。","直筆在史臣，將來洗箱篋。","吾思哭孤冢，南紀阻歸楫。","扶顛永蕭條，未濟失利涉。","疲{艹/尔}竟何人，灑涕巴東峽。"]', '["司徒天寶末，北收晉陽甲。","胡騎攻吾城，愁寂意不愜。","人安若泰山，薊北斷右脅。","朔方氣乃蘇，黎首见帝業。","二宮泣西郊，九廟起頹壓。","未散河陽卒，思明僞臣妾。","复自碣石来，火焚乾坤獵。","高視笑祿山，公又大獻捷。","異王冊崇勳，小敵信所怯。","擁兵鎮河汴，千里初妥帖。","青蠅紛營營，风雨秋一葉。","內省未入朝死泪終映睫。","大屋去高棟，长城埽遺堞。","平生白羽扇，零落蛟龙匣。","雅望與英姿，惻愴槐里接。","三軍晦光彩，烈士痛稠叠。","直笔在史臣，將来洗箱篋。","吾思哭孤冢，南紀阻归楫。","扶顛永蕭條，未濟失利涉。","疲{艹/尔}竟何人，灑涕巴东峽。"]', '诗', 'shi', '', NULL, '八哀詩 故司徒李公光弼 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fcfc8f-4993-43a2-a154-615b75a5105f', '八哀詩 贈左僕射鄭國公嚴公武', '八哀诗 贈左僕射鄭国公嚴公武', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭公瑚璉器，華岳金天晶。","昔在童子日，已聞老成名。","嶷然大賢後，復見秀骨清。","開口取將相，小心事友生。","閱書百紙盡，落筆四座驚。","歷識匪父任，嫉邪常力爭。","漢議尚整肅，胡騎忽縱橫。","飛傳自河隴，逢人問公卿。","不知萬乘出，雪涕風悲鳴。","受詞劒閣道，謁帝蕭關城。","寂寞雲臺仗，飄颻沙塞旌。","江山少使者，笳鼓凝皇情。","壯士血相視，忠臣氣不平。","密論貞觀體，揮發岐陽征。","感激動四極，聯翩收二京。","西郊牛酒再，原廟丹青明。","匡汲俄寵辱，衛霍竟哀榮。","四登會府地，三掌華陽兵。","京兆空柳色，尚書無履聲。","羣烏自朝夕，白馬休橫行。","諸葛蜀人愛，文翁儒化成。","公來雪山重，公去雪山輕。","記室得何遜，韜鈐延子荆。","四郊失壁壘，虛館開逢迎。","堂上指圖畫，軍中吹玉笙。","豈無成都酒，憂國只細傾。","時觀錦水釣，問俗終相幷。","意待犬戎滅，人藏紅粟盈。","以茲報主願，庶或裨世程。","炯炯一心在，沈沈二豎嬰。","顏回竟短折，賈誼徒忠貞。","飛旐出江漢，孤舟輕荆衡。","虛無馬融笛，悵望龍驤塋。","空餘老賓客，身上媿簪纓。"]', '["鄭公瑚璉器，华岳金天晶。","昔在童子日，已闻老成名。","嶷然大賢後，复见秀骨清。","开口取將相，小心事友生。","閱书百紙尽，落笔四座驚。","歷識匪父任，嫉邪常力爭。","漢議尚整肅，胡騎忽縱橫。","飞傳自河隴，逢人问公卿。","不知万乘出，雪涕风悲鳴。","受词劒閣道，謁帝蕭关城。","寂寞云台仗，飄颻沙塞旌。","江山少使者，笳鼓凝皇情。","壯士血相視，忠臣氣不平。","密論貞观體，揮發岐陽征。","感激动四極，聯翩收二京。","西郊牛酒再，原廟丹青明。","匡汲俄寵辱，衛霍竟哀榮。","四登會府地，三掌华陽兵。","京兆空柳色，尚书無履声。","羣烏自朝夕，白马休橫行。","諸葛蜀人愛，文翁儒化成。","公来雪山重，公去雪山轻。","記室得何遜，韜鈐延子荆。","四郊失壁壘，虛館开逢迎。","堂上指圖畫，軍中吹玉笙。","豈無成都酒，憂国只細傾。","时观錦水釣，问俗終相幷。","意待犬戎滅，人藏紅粟盈。","以茲報主願，庶或裨世程。","炯炯一心在，沈沈二豎嬰。","顏回竟短折，賈誼徒忠貞。","飞旐出江漢，孤舟轻荆衡。","虛無马融笛，悵望龙驤塋。","空餘老賓客，身上媿簪纓。"]', '诗', 'shi', '', NULL, '八哀詩 贈左僕射鄭國公嚴公武 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45110b81-0f02-4c85-b72a-f2210d10c12f', '八哀詩 贈太子師汝陽郡王璡', '八哀诗 贈太子師汝陽郡王璡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝陽讓帝子，眉宇真天人。","虯鬚似太宗，色映塞外春。","往者開元中，主恩視遇頻。","出入獨非時，禮異見羣臣。","愛其謹潔極，倍此骨肉親。","從容聽朝後，或在風雪晨。","忽思格猛獸，苑囿騰清塵。","羽旗動若一，萬馬肅駪駪。","詔王來射雁，拜命已挺身。","箭出飛鞚內，上又回翠麟。","飜然紫塞翮，下拂明月輪。","胡人雖獲多，天笑不爲新。","王每中一物，手自與金銀。","袖中諫獵書，扣馬久上陳。","竟無銜橛虞，聖聰矧多仁。","官免供給費，水有在藻鱗。","匪唯帝老大，皆是王忠勤。","晚年務置醴，門引申白賓。","道大容無能，永懷侍芳茵。","好學尚貞烈，義形必霑巾。","揮翰綺繡揚，篇什若有神。","川廣不可泝，墓久狐兔鄰。","宛彼漢中郡，文雅見天倫。","何以開我悲，泛舟俱遠津。","溫溫昔風味，少壯已書紳。","舊遊易磨滅，衰謝增酸辛。"]', '["汝陽讓帝子，眉宇真天人。","虯鬚似太宗，色映塞外春。","往者开元中，主恩視遇頻。","出入独非时，禮異见羣臣。","愛其謹潔極，倍此骨肉親。","從容听朝後，或在风雪晨。","忽思格猛獸，苑囿腾清塵。","羽旗动若一，万马肅駪駪。","詔王来射雁，拜命已挺身。","箭出飞鞚內，上又回翠麟。","飜然紫塞翮，下拂明月輪。","胡人雖獲多，天笑不爲新。","王每中一物，手自與金銀。","袖中諫獵书，扣马久上陳。","竟無銜橛虞，聖聰矧多仁。","官免供給費，水有在藻鱗。","匪唯帝老大，皆是王忠勤。","晚年務置醴，门引申白賓。","道大容無能，永懷侍芳茵。","好学尚貞烈，義形必霑巾。","揮翰綺繡揚，篇什若有神。","川廣不可泝，墓久狐兔鄰。","宛彼漢中郡，文雅见天倫。","何以开我悲，泛舟俱远津。","溫溫昔风味，少壯已书紳。","旧游易磨滅，衰謝增酸辛。"]', '诗', 'shi', '', NULL, '八哀詩 贈太子師汝陽郡王璡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03733be3-cf7c-442c-b6ce-9918b9aa57ac', '八哀詩 贈祕書監江夏李公邕', '八哀诗 贈祕书監江夏李公邕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長嘯宇宙間，高才日陵替。","古人不可見，前輩復誰繼。","憶昔李公存，詞林有根柢。","聲華當健筆，灑落富清製。","風流散金石，追琢山岳銳。","情窮造化理，學貫天人際。","干謁走其門，碑版照四裔。","各滿深望還，森然起凡例。","蕭蕭白楊路，洞徹寶珠惠。","龍宮墖廟湧，浩劫浮雲衛。","宗儒俎豆事，故吏去思計。","眄睞已皆虛，跋涉曾不泥。","向來映當時，豈獨勸後世。","豐屋珊瑚鉤，騏驎織成罽。","紫騮隨劒几，義取無虛歲。","分宅脫驂間，感激懷未濟。","衆歸賙給美，擺落多藏穢。","獨步四十年，風聽九臯唳。","嗚呼江夏姿，竟掩宣尼袂。","往者武后朝，引用多寵嬖。","否臧太常議，面折二張勢。","衰俗凜生風，排蕩秋旻霽。","忠貞負冤恨，宮闕深旒綴。","放逐早聯翩，低垂困炎厲。","日斜鵩鳥入，魂斷蒼梧帝。","榮枯走不暇，星駕無安稅。","幾分漢廷竹，夙擁文侯[篲]。","終悲洛陽獄，事近小臣敝。","禍階初負謗，易力何深嚌。","伊昔臨淄亭，酒酣託末契。","重敍東都別，朝陰改軒砌。","論文到崔蘇，指盡流水逝。","近伏盈川雄，未甘特進麗。","是非張相國，相扼一危脆。","爭名古豈然，鍵捷歘不閉。","例及吾家詩，曠懷埽氛翳。","慷慨嗣真作，咨嗟玉山桂。","鍾律儼高懸，鯤鯨噴迢遰。","坡陀青州血，蕪沒汶陽瘞。","哀贈竟蕭條，恩波延揭厲。","子孫存如綫，舊客舟凝滯。","君臣尚論兵，將帥接燕薊。","郎吟六公篇，憂來豁蒙蔽。"]', '["长嘯宇宙间，高才日陵替。","古人不可见，前輩复誰繼。","憶昔李公存，词林有根柢。","声华當健笔，灑落富清製。","风流散金石，追琢山岳銳。","情窮造化理，学貫天人際。","干謁走其门，碑版照四裔。","各满深望還，森然起凡例。","蕭蕭白楊路，洞徹寶珠惠。","龙宮墖廟湧，浩劫浮云衛。","宗儒俎豆事，故吏去思計。","眄睞已皆虛，跋涉曾不泥。","向来映當时，豈独勸後世。","豐屋珊瑚鉤，騏驎织成罽。","紫騮隨劒几，義取無虛歲。","分宅脫驂间，感激懷未濟。","衆归賙給美，擺落多藏穢。","独步四十年，风听九臯唳。","嗚呼江夏姿，竟掩宣尼袂。","往者武后朝，引用多寵嬖。","否臧太常議，面折二張勢。","衰俗凜生风，排蕩秋旻霽。","忠貞負冤恨，宮闕深旒綴。","放逐早聯翩，低垂困炎厲。","日斜鵩鸟入，魂斷蒼梧帝。","榮枯走不暇，星駕無安稅。","幾分漢廷竹，夙擁文侯[篲]。","終悲洛陽獄，事近小臣敝。","禍階初負謗，易力何深嚌。","伊昔臨淄亭，酒酣託末契。","重敍东都別，朝陰改軒砌。","論文到崔蘇，指尽流水逝。","近伏盈川雄，未甘特進丽。","是非張相国，相扼一危脆。","爭名古豈然，鍵捷歘不閉。","例及吾家诗，曠懷埽氛翳。","慷慨嗣真作，咨嗟玉山桂。","鍾律儼高懸，鯤鯨噴迢遰。","坡陀青州血，蕪沒汶陽瘞。","哀贈竟蕭條，恩波延揭厲。","子孫存如綫，旧客舟凝滯。","君臣尚論兵，將帥接燕薊。","郎吟六公篇，憂来豁蒙蔽。"]', '诗', 'shi', '', NULL, '八哀詩 贈祕書監江夏李公邕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d07875d-bf3e-4a2e-9139-ba767079c8ad', '八哀詩 故祕書少監武功蘇公源明', '八哀诗 故祕书少監武功蘇公源明', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["武功少也孤，徒步客徐衮。","讀書東岳中，十載考墳典。","時下萊蕪郭，忍飢浮雲巘。","負米晚爲身，每食臉必泫。","夜字照爇薪，垢衣生碧蘚。","庶以勤苦志，報茲劬勞顯。","學蔚醇儒姿，文包舊史善。","灑落辭幽人，歸來潛京輦。","射君東堂策，宗匠集精選。","制可題未乾，乙科已大闡。","文章日自負，吏祿亦累踐。","晨趨閶闔內，足蹋宿昔趼。","一麾出守還，黃屋朔風卷。","不暇陪八駿，虜庭悲所遣。","平生滿尊酒，斷此朋知展。","憂憤病二秋，有恨石可轉。","肅宗復社稷，得無逆順辨。","范曄顧其兒，李斯憶黃犬。","祕書茂松意，溟漲本末淺。","青熒芙蓉劒，犀兕豈獨剸。","反爲後輩褻，予實苦懷緬。","煌煌齋房芝，事絕萬手搴。","垂之俟來者，正始徵勸勉。","不要懸黃金，胡爲投乳贙。","結交三十載，吾與誰游衍。","滎陽復冥莫，罪罟已橫罥。","嗚呼子逝日，始泰則終蹇。","長安米萬錢，凋喪盡餘喘。","戰伐何當解，歸帆阻清沔。","尚纏漳水疾，永負蒿里餞。"]', '["武功少也孤，徒步客徐衮。","读书东岳中，十載考墳典。","时下萊蕪郭，忍飢浮云巘。","負米晚爲身，每食臉必泫。","夜字照爇薪，垢衣生碧蘚。","庶以勤苦志，報茲劬勞显。","学蔚醇儒姿，文包旧史善。","灑落辞幽人，归来潛京輦。","射君东堂策，宗匠集精選。","制可題未乾，乙科已大闡。","文章日自負，吏祿亦累踐。","晨趨閶闔內，足蹋宿昔趼。","一麾出守還，黄屋朔风卷。","不暇陪八駿，虜庭悲所遣。","平生满尊酒，斷此朋知展。","憂憤病二秋，有恨石可轉。","肅宗复社稷，得無逆順辨。","范曄顧其兒，李斯憶黄犬。","祕书茂松意，溟漲本末淺。","青熒芙蓉劒，犀兕豈独剸。","反爲後輩褻，予實苦懷緬。","煌煌斋房芝，事絕万手搴。","垂之俟来者，正始徵勸勉。","不要懸黄金，胡爲投乳贙。","結交三十載，吾與誰游衍。","滎陽复冥莫，罪罟已橫罥。","嗚呼子逝日，始泰則終蹇。","长安米万錢，凋喪尽餘喘。","戰伐何當解，归帆阻清沔。","尚纏漳水疾，永負蒿里餞。"]', '诗', 'shi', '', NULL, '八哀詩 故祕書少監武功蘇公源明 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5077e64f-8b7b-489b-a9fc-6c8f11f52315', '八哀詩 故著作郎貶台州司戶滎陽鄭公虔', '八哀诗 故著作郎貶台州司戶滎陽鄭公虔', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鶢鶋至魯門，不識鐘鼓饗。","孔翠望赤霄，愁思雕籠養。","滎陽冠衆儒，早聞名公賞。","地崇士大夫，況乃氣精爽。","天然生知姿，學立游夏上。","神農極闕漏，黃石媿師長。","藥纂西極名，兵流指諸掌。","貫穿無遺恨，薈蕞何技癢。","圭臬星經奧，蟲篆丹青廣。","子雲窺未徧，方朔諧太枉。","神翰顧不一，體變鍾兼兩。","文傳天下口，大字猶在牓。","昔獻書畫圖，新詩亦俱往。","滄洲動玉陛，宣鶴誤一響。","三絕自御題，四方尤所仰。","嗜酒益疎放，彈琴視天壤。","形骸實土木，親近唯几杖。","未曾寄官曹，突兀倚書幌。","晚就芸香閣，胡塵昏坱莽。","反覆歸聖朝，點染無滌盪。","老蒙台州掾，泛泛淛江槳。","覆穿四明雪，飢拾楢溪橡。","空聞紫芝歌，不見杏壇丈。","天長眺東南，秋色餘魍魎。","別離慘至今，斑白徒懷曩。","春深秦山秀，葉墜清渭朗。","劇談王侯門，野稅林下鞅。","操紙終夕酣，時物集遐想。","詞場竟疎闊，平昔濫吹獎。","百年見存歿，牢落吾安放。","蕭條阮咸在，出處同世網。","他日訪江樓，含悽述飄蕩。"]', '["鶢鶋至魯门，不識鐘鼓饗。","孔翠望赤霄，愁思雕籠養。","滎陽冠衆儒，早闻名公賞。","地崇士大夫，況乃氣精爽。","天然生知姿，学立游夏上。","神農極闕漏，黄石媿師长。","藥纂西極名，兵流指諸掌。","貫穿無遺恨，薈蕞何技癢。","圭臬星經奧，蟲篆丹青廣。","子云窺未徧，方朔諧太枉。","神翰顧不一，體变鍾兼兩。","文傳天下口，大字猶在牓。","昔獻书畫圖，新诗亦俱往。","滄洲动玉陛，宣鹤誤一响。","三絕自御題，四方尤所仰。","嗜酒益疎放，彈琴視天壤。","形骸實土木，親近唯几杖。","未曾寄官曹，突兀倚书幌。","晚就芸香閣，胡塵昏坱莽。","反覆归聖朝，点染無滌盪。","老蒙台州掾，泛泛淛江槳。","覆穿四明雪，飢拾楢溪橡。","空闻紫芝歌，不见杏壇丈。","天长眺东南，秋色餘魍魎。","別離慘至今，斑白徒懷曩。","春深秦山秀，葉墜清渭朗。","劇談王侯门，野稅林下鞅。","操紙終夕酣，时物集遐想。","词場竟疎闊，平昔濫吹獎。","百年见存歿，牢落吾安放。","蕭條阮咸在，出处同世網。","他日訪江楼，含悽述飄蕩。"]', '诗', 'shi', '', NULL, '八哀詩 故著作郎貶台州司戶滎陽鄭公虔 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd949d64-858c-4734-b54f-fcfd99aff432', '八哀詩 故右僕射相國張公九齢', '八哀诗 故右僕射相国張公九齢', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["相國生南紀，金璞無留礦。","仙鶴下人間，獨立霜毛整。","矯然江海思，復與雲路永。","寂寞想土階，未遑等箕潁。","上君白玉堂，倚君金華省。","碣石歲崢嶸，天地日蛙黽。","退食吟大庭，何心記榛梗。","骨驚畏曩哲，鬒變負人境。","雖蒙換蟬冠，右地恧多幸。","敢忘二疏歸，痛迫蘇耽井。","紫綬映暮年，荆州謝所領。","庾公興不淺，黃霸鎮每靜。","賓客引調同，諷詠在務屏。","詩罷地有餘，篇終語清省。","一陽發陰管，淑氣含公鼎。","乃知君子心，用才文章境。","散帙起翠螭，倚薄巫廬竝。","綺麗玄暉擁，牋誄任昉騁。","自我一家則，未缺隻字警。","千秋滄海南，名繫朱鳥影。","歸老守故林，戀闕悄延頸。","波濤良史筆，蕪絕大庾嶺。","向時禮數隔，制作難上請。","再讀徐孺碑，猶思理煙艇。"]', '["相国生南紀，金璞無留礦。","仙鹤下人间，独立霜毛整。","矯然江海思，复與云路永。","寂寞想土階，未遑等箕潁。","上君白玉堂，倚君金华省。","碣石歲崢嶸，天地日蛙黽。","退食吟大庭，何心記榛梗。","骨驚畏曩哲，鬒变負人境。","雖蒙換蟬冠，右地恧多幸。","敢忘二疏归，痛迫蘇耽井。","紫綬映暮年，荆州謝所領。","庾公兴不淺，黄霸鎮每静。","賓客引調同，諷詠在務屏。","诗罷地有餘，篇終語清省。","一陽發陰管，淑氣含公鼎。","乃知君子心，用才文章境。","散帙起翠螭，倚薄巫廬竝。","綺丽玄暉擁，牋誄任昉騁。","自我一家則，未缺隻字警。","千秋滄海南，名繫朱鸟影。","归老守故林，戀闕悄延頸。","波濤良史笔，蕪絕大庾嶺。","向时禮數隔，制作难上請。","再读徐孺碑，猶思理煙艇。"]', '诗', 'shi', '', NULL, '八哀詩 故右僕射相國張公九齢 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f5d5b7-b7ac-4d43-b795-d9e76677e7e2', '寫懷二首 一', '寫懷二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["勞生共乾坤，何處異風俗。","冉冉自趨競，行行見羈束。","無貴賤不悲，無富貧亦足。","萬古一骸骨，鄰家遞歌哭。","鄙夫到巫峽，三歲如轉燭。","全命甘留滯，忘情任榮辱。","朝班及暮齒，日給還脫粟。","編蓬石城東，采藥山北谷。","用心霜雪間，不必條蔓綠。","非關故安排，曾是順幽獨。","達士如弦直，小人似鉤曲。","曲直我不知，負暄候樵牧。"]', '["勞生共乾坤，何处異风俗。","冉冉自趨競，行行见羈束。","無貴賤不悲，無富貧亦足。","万古一骸骨，鄰家遞歌哭。","鄙夫到巫峽，三歲如轉燭。","全命甘留滯，忘情任榮辱。","朝班及暮齒，日給還脫粟。","編蓬石城东，采藥山北谷。","用心霜雪间，不必條蔓綠。","非关故安排，曾是順幽独。","達士如弦直，小人似鉤曲。","曲直我不知，負暄候樵牧。"]', '诗', 'shi', '', NULL, '寫懷二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e87b554-124f-4a56-b208-4bdffe0550b9', '寫懷二首 二', '寫懷二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夜深坐南軒，明月照我膝。","驚風飜河漢，梁棟已出日。","羣生各一宿，飛動自儔匹。","吾亦驅其兒，營營爲私實。","天寒行旅稀，歲暮日月疾。","榮名忽中人，世亂如蟣蝨。","古者三皇前，滿腹志願畢。","胡爲有結繩，陷此膠與漆。","禍首燧人氏，厲階董孤筆。","君看燈燭張，轉使飛蛾密。","放神八極外，俯仰俱蕭瑟。","終契如往還，得匪合仙術。"]', '["夜深坐南軒，明月照我膝。","驚风飜河漢，梁棟已出日。","羣生各一宿，飞动自儔匹。","吾亦驱其兒，營營爲私實。","天寒行旅稀，歲暮日月疾。","榮名忽中人，世亂如蟣蝨。","古者三皇前，满腹志願畢。","胡爲有結繩，陷此膠與漆。","禍首燧人氏，厲階董孤笔。","君看灯燭張，轉使飞蛾密。","放神八極外，俯仰俱蕭瑟。","終契如往還，得匪合仙術。"]', '诗', 'shi', '', NULL, '寫懷二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982f789a-c377-4b64-808a-56f36abf9ff0', '可歎', '可歎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天上浮雲如白衣，斯須改變如蒼狗。","古往今來共一時，人生萬事無不有。","近者抉眼去其夫，河東女兒身姓柳。","丈夫正色動引經，酆城客子王季友。","羣書萬卷常暗誦，孝經一通看在手。","貧窮老瘦家賣屐，好事就之爲攜酒。","豫章太守高帝孫，引爲賓客敬頗久。","聞道三年未曾語，小心恐懼閉其口。","太守得之更不疑，人生反覆看亦醜。","明月無瑕豈容易，紫氣鬱鬱猶衝斗。","時危可仗真豪俊，二人得置君側否。","太守頃者領山南，邦人思之比父母。","王生早曾拜顏色，高山之外皆培塿。","用爲羲和天爲成，用平水土地爲厚。","王也論道阻江湖，李也丞疑曠前後。","死爲星辰終不滅，致君堯舜焉肯朽。","吾輩碌碌飽飯行，風后力牧長回首。"]', '["天上浮云如白衣，斯須改变如蒼狗。","古往今来共一时，人生万事無不有。","近者抉眼去其夫，河东女兒身姓柳。","丈夫正色动引經，酆城客子王季友。","羣书万卷常暗誦，孝經一通看在手。","貧窮老瘦家賣屐，好事就之爲携酒。","豫章太守高帝孫，引爲賓客敬頗久。","闻道三年未曾語，小心恐懼閉其口。","太守得之更不疑，人生反覆看亦醜。","明月無瑕豈容易，紫氣鬱鬱猶衝斗。","时危可仗真豪俊，二人得置君側否。","太守頃者領山南，邦人思之比父母。","王生早曾拜顏色，高山之外皆培塿。","用爲羲和天爲成，用平水土地爲厚。","王也論道阻江湖，李也丞疑曠前後。","死爲星辰終不滅，致君堯舜焉肯朽。","吾輩碌碌飽飯行，风后力牧长回首。"]', '诗', 'shi', '', NULL, '可歎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61304178-6b16-4f98-87b2-4ad6bc98da98', '觀公孫大娘弟子舞劒器行', '观公孫大娘弟子舞劒器行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔有佳人公孫氏，一舞劒氣動四方。","觀者如山色沮喪，天地爲之久低昂。","㸌如羿射九日落，矯如羣帝驂龍翔。","來如雷霆收震怒，罷如江海凝清光。","絳脣珠袖兩寂莫，況有弟子傳芬芳。","臨潁美人在白帝，妙舞此曲神揚揚。","與余問答既有以，感時撫事增惋傷。","先帝侍女八千人，公孫劒器初第一。","五十年間似反掌，風塵傾動昏王室。","棃園子弟散如煙，女樂餘姿映寒日。","金粟堆南木已拱，瞿唐石城草蕭瑟。","玳筵急管曲復終，樂極哀來月東出。","老夫不知其所往，足繭荒山轉愁疾。"]', '["昔有佳人公孫氏，一舞劒氣动四方。","观者如山色沮喪，天地爲之久低昂。","㸌如羿射九日落，矯如羣帝驂龙翔。","来如雷霆收震怒，罷如江海凝清光。","絳脣珠袖兩寂莫，況有弟子傳芬芳。","臨潁美人在白帝，妙舞此曲神揚揚。","與余问答既有以，感时撫事增惋傷。","先帝侍女八千人，公孫劒器初第一。","五十年间似反掌，风塵傾动昏王室。","棃园子弟散如煙，女乐餘姿映寒日。","金粟堆南木已拱，瞿唐石城草蕭瑟。","玳筵急管曲复終，乐極哀来月东出。","老夫不知其所往，足繭荒山轉愁疾。"]', '诗', 'shi', '', NULL, '觀公孫大娘弟子舞劒器行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec9cb88-517c-4922-a82e-e6cc561ace29', '往在', '往在', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["往在西京日，胡來滿彤宮。","中宵焚九廟，雲漢爲之紅。","解瓦飛十里，繐帷紛曾空。","疚心惜木主，一一灰悲風。","合昏排鐵騎，清旭散錦𩦺賊臣表逆節，相賀以成功。","是時妃嬪戮，連爲糞土叢。","當宁陷玉座，白間剝畫蟲。","不知二聖處，私泣百歲翁。","車駕既云還，楹桷歘穹崇。","故老復涕泗，祠官樹椅桐。","宏壯不如初，已見帝力雄。","前春禮郊廟，祀事親聖躬。","微軀忝近臣，景從陪羣公。","登階捧玉冊，峨冕耿金鍾。","侍祠恧先露，掖垣邇濯龍。","天子惟孝孫，五雲起九重。","鏡匳換粉黛，翠羽猶蔥朧。","前者厭羯胡，後來遭犬戎。","俎豆腐膻肉，罘罳行角弓。","安得自西極，申命空山東。","盡軀詣闕下，士庶塞關中。","主將曉逆順，元元歸始終。","一朝自罪己，萬里車書通。","鋒鏑供鋤犂，征戍聽所從。","冗官各復業，土著還力農。","君臣節儉足，朝野歡呼同。","中興似國初，繼體如太宗。","端拱納諫諍，和風日沖融。","赤墀櫻桃枝，隱映銀絲籠。","千春薦陵寢，永永垂無窮。","京都不再火，涇渭開愁容。","歸號故松柏，老去苦飄蓬。"]', '["往在西京日，胡来满彤宮。","中宵焚九廟，云漢爲之紅。","解瓦飞十里，繐帷紛曾空。","疚心惜木主，一一灰悲风。","合昏排鐵騎，清旭散錦𩦺賊臣表逆節，相賀以成功。","是时妃嬪戮，連爲糞土叢。","當宁陷玉座，白间剝畫蟲。","不知二聖处，私泣百歲翁。","车駕既云還，楹桷歘穹崇。","故老复涕泗，祠官樹椅桐。","宏壯不如初，已见帝力雄。","前春禮郊廟，祀事親聖躬。","微軀忝近臣，景從陪羣公。","登階捧玉冊，峨冕耿金鍾。","侍祠恧先露，掖垣邇濯龙。","天子惟孝孫，五云起九重。","镜匳換粉黛，翠羽猶蔥朧。","前者厭羯胡，後来遭犬戎。","俎豆腐膻肉，罘罳行角弓。","安得自西極，申命空山东。","尽軀詣闕下，士庶塞关中。","主將晓逆順，元元归始終。","一朝自罪己，万里车书通。","鋒鏑供鋤犂，征戍听所從。","冗官各复業，土著還力農。","君臣節儉足，朝野歡呼同。","中兴似国初，繼體如太宗。","端拱納諫諍，和风日沖融。","赤墀櫻桃枝，隐映銀絲籠。","千春薦陵寢，永永垂無窮。","京都不再火，涇渭开愁容。","归號故松柏，老去苦飄蓬。"]', '诗', 'shi', '', NULL, '往在 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb527751-8039-4031-bded-476c82a0ebe1', '昔遊', '昔游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔者與高李，晚登單父臺。","寒蕪際碣石，萬里風雲來。","桑柘葉如雨，飛藿去裴回。","清霜大澤凍，禽獸有餘哀。","是時倉廩實，洞達寰區開。","猛士思滅胡，將帥望三台。","君王無所惜，駕馭英雄材。","幽燕盛用武，供給亦勞哉。","吳門轉粟帛，泛海陵蓬萊。","肉食三十萬，獵射起黃埃。","隔河憶長眺，青歲已摧頹。","不及少年日，無復故人杯。","賦詩獨流涕，亂世想賢才。","有能市駿骨，莫恨少龍媒。","商山議得失，蜀主脫嫌猜。","呂尚封國邑，傅說已鹽梅。","景晏楚山深，水鶴去低回。","龐公任本性，攜子臥蒼苔。"]', '["昔者與高李，晚登單父台。","寒蕪際碣石，万里风云来。","桑柘葉如雨，飞藿去裴回。","清霜大澤凍，禽獸有餘哀。","是时倉廩實，洞達寰區开。","猛士思滅胡，將帥望三台。","君王無所惜，駕馭英雄材。","幽燕盛用武，供給亦勞哉。","吳门轉粟帛，泛海陵蓬萊。","肉食三十万，獵射起黄埃。","隔河憶长眺，青歲已摧頹。","不及少年日，無复故人杯。","賦诗独流涕，亂世想賢才。","有能市駿骨，莫恨少龙媒。","商山議得失，蜀主脫嫌猜。","呂尚封国邑，傅说已鹽梅。","景晏楚山深，水鹤去低回。","龐公任本性，携子臥蒼苔。"]', '诗', 'shi', '', NULL, '昔遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46013ebf-55a5-421e-a8fb-c1d55a3c67b3', '壯遊', '壯游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["往昔十四五，出遊翰墨場。","斯文崔魏徒，以我似班揚。","七齡思即壯，開口詠鳳皇。","九齡書大字，有作成一囊。","性豪業嗜酒，嫉惡懷剛腸。","脫略小時輩，結交皆老蒼。","飲酣視八極，俗物都茫茫。","東下姑蘇臺，已具浮海航。","到今有遺恨，不得窮扶桑。","王謝風流遠，闔廬丘墓荒。","劒池石壁仄，長洲荷芰香。","嵯峨閶門北，清廟映回塘。","每趨吳太伯，撫事淚浪浪。","枕戈憶句踐，渡浙想秦皇。","蒸魚聞匕首，除道哂要章。","越女天下白，鑑湖五月涼。","剡溪蘊秀異，欲罷不能忘。","歸帆拂天姥，中歲貢舊鄉。","氣劘屈賈壘，目短曹劉牆。","忤下考功第，獨辭京尹堂。","放蕩齊趙間，裘馬頗清狂。","春歌叢臺上，冬獵青丘旁。","呼鷹皁櫪林，逐獸雲雪岡。","射飛曾縱鞚，引臂落鶖鶬。","蘇侯據鞍喜，忽如攜葛強。","快意八九年，西歸到咸陽。","許與必詞伯，賞遊實賢王。","曳裾置醴地，奏賦入明光。","天子廢食召，羣公會軒裳。","脫身無所愛，痛飲信行藏。","黑貂不免敝，斑鬢兀稱觴。","杜曲晚耆舊，四郊多白楊。","坐深鄉黨敬，日覺死生忙。","朱門任傾奪，赤族迭罹殃。","國馬竭粟豆，官雞輸稻粱。","舉隅見煩費，引古惜興亡。","河朔風塵起，岷山行幸長。","兩宮各警蹕，萬里遙相望。","崆峒殺氣黑，少海旌旗黃。","禹功亦命子，涿鹿親戎行。","翠華擁英岳，螭虎噉豺狼。","爪牙一不中，胡兵更陸梁。","大軍載草草，凋瘵滿膏肓。","備員竊補衮，憂憤心飛揚。","上感九廟焚，下憫萬民瘡。","斯時伏青蒲，延爭守御牀。","君辱敢愛死，赫怒幸無傷。","聖哲體仁恕，宇縣復小康。","哭廟灰燼中，鼻酸朝未央。","小臣議論絕，老病客殊方。","鬱鬱苦不展，羽翮困低昂。","秋風動哀壑，碧蕙捐微芳。","之推避賞從，漁父濯滄浪。","榮華敵勳業，歲暮有嚴霜。","吾觀鴟夷子，才格出尋常。","羣凶逆未定，側佇英俊翔。"]', '["往昔十四五，出游翰墨場。","斯文崔魏徒，以我似班揚。","七齡思即壯，开口詠鳳皇。","九齡书大字，有作成一囊。","性豪業嗜酒，嫉惡懷剛腸。","脫略小时輩，結交皆老蒼。","饮酣視八極，俗物都茫茫。","东下姑蘇台，已具浮海航。","到今有遺恨，不得窮扶桑。","王謝风流远，闔廬丘墓荒。","劒池石壁仄，长洲荷芰香。","嵯峨閶门北，清廟映回塘。","每趨吳太伯，撫事泪浪浪。","枕戈憶句踐，渡浙想秦皇。","蒸鱼闻匕首，除道哂要章。","越女天下白，鑑湖五月涼。","剡溪蘊秀異，欲罷不能忘。","归帆拂天姥，中歲貢旧乡。","氣劘屈賈壘，目短曹劉牆。","忤下考功第，独辞京尹堂。","放蕩齊趙间，裘马頗清狂。","春歌叢台上，冬獵青丘旁。","呼鷹皁櫪林，逐獸云雪岡。","射飞曾縱鞚，引臂落鶖鶬。","蘇侯據鞍喜，忽如携葛強。","快意八九年，西归到咸陽。","許與必词伯，賞游實賢王。","曳裾置醴地，奏賦入明光。","天子廢食召，羣公會軒裳。","脫身無所愛，痛饮信行藏。","黑貂不免敝，斑鬢兀稱觴。","杜曲晚耆旧，四郊多白楊。","坐深乡黨敬，日覺死生忙。","朱门任傾奪，赤族迭罹殃。","国马竭粟豆，官雞輸稻粱。","舉隅见煩費，引古惜兴亡。","河朔风塵起，岷山行幸长。","兩宮各警蹕，万里遙相望。","崆峒殺氣黑，少海旌旗黄。","禹功亦命子，涿鹿親戎行。","翠华擁英岳，螭虎噉豺狼。","爪牙一不中，胡兵更陸梁。","大軍載草草，凋瘵满膏肓。","備員竊補衮，憂憤心飞揚。","上感九廟焚，下憫万民瘡。","斯时伏青蒲，延爭守御牀。","君辱敢愛死，赫怒幸無傷。","聖哲體仁恕，宇縣复小康。","哭廟灰燼中，鼻酸朝未央。","小臣議論絕，老病客殊方。","鬱鬱苦不展，羽翮困低昂。","秋风动哀壑，碧蕙捐微芳。","之推避賞從，漁父濯滄浪。","榮华敵勳業，歲暮有嚴霜。","吾观鴟夷子，才格出尋常。","羣凶逆未定，側佇英俊翔。"]', '诗', 'shi', '', NULL, '壯遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5003828-ec14-49f6-a2b4-9eb6ce67a9d8', '遣懷', '遣懷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔我遊宋中，惟梁孝王都。","名今陳留亞，劇則貝魏俱。","邑中九萬家，高棟照通衢。","舟車半天下，主客多歡娛。","白刃讐不義，黃金傾有無。","殺人紅塵裏，報答在斯須。","憶與高李輩，論交入酒壚。","兩公壯藻思，得我色敷腴。","氣酣登吹臺，懷古視平蕪。","芒碭雲一去，雁鶩空相呼。","先帝正好武，寰海未凋枯。","猛將收西域，長戟破林胡。","百萬攻一城，獻捷不云輸。","組練棄如泥，尺土負百夫。","拓境功未已，元和辭大爐。","亂離朋友盡，合沓歲月徂。","吾衰將焉託，存歿再嗚呼。","蕭條益堪媿，獨在天一隅。","乘黃已去矣，凡馬徒區區。","不復見顏鮑，繫舟臥荆巫。","臨餐吐更食，常恐違撫孤。"]', '["昔我游宋中，惟梁孝王都。","名今陳留亞，劇則貝魏俱。","邑中九万家，高棟照通衢。","舟车半天下，主客多歡娛。","白刃讐不義，黄金傾有無。","殺人紅塵裏，報答在斯須。","憶與高李輩，論交入酒壚。","兩公壯藻思，得我色敷腴。","氣酣登吹台，懷古視平蕪。","芒碭云一去，雁鶩空相呼。","先帝正好武，寰海未凋枯。","猛將收西域，长戟破林胡。","百万攻一城，獻捷不云輸。","組練棄如泥，尺土負百夫。","拓境功未已，元和辞大爐。","亂離朋友尽，合沓歲月徂。","吾衰將焉託，存歿再嗚呼。","蕭條益堪媿，独在天一隅。","乘黄已去矣，凡马徒區區。","不复见顏鲍，繫舟臥荆巫。","臨餐吐更食，常恐違撫孤。"]', '诗', 'shi', '', NULL, '遣懷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817f76ca-8ee1-4eb7-b20a-0d44cef2c24b', '同元使君舂陵行', '同元使君舂陵行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遭亂髮盡白，轉衰病相嬰。","沈緜盜賊際，狼狽江漢行。","歎時藥力薄，爲客羸瘵成。","吾人詩家秀，博采世上名。","粲粲元道州，前聖畏後生。","觀呼舂陵作，歘見俊哲情。","復覽賊退篇，結也實國楨。","賈誼昔流慟，匡衡常引經。","道州憂黎庶，詞氣浩縱橫。","兩章對秋月，一字偕華星。","至君唐虞際，純樸憶大庭。","何時降璽書，用爾爲丹青。","獄訟永衰息，豈唯偃甲兵。","悽惻念誅求，薄斂近休明。","乃知正人意，不苟飛長纓。","涼飆振南岳，之子寵若驚。","色阻金印大，興含滄浪清。","我多長卿病，日夕思朝廷。","肺枯渴太甚，漂泊公孫城。","呼兒具紙筆，隱几臨軒楹。","作詩呻吟內，黑澹字攲傾。","感彼危苦詞，庶幾知者聽。"]', '["遭亂髮尽白，轉衰病相嬰。","沈緜盜賊際，狼狽江漢行。","歎时藥力薄，爲客羸瘵成。","吾人诗家秀，博采世上名。","粲粲元道州，前聖畏後生。","观呼舂陵作，歘见俊哲情。","复覽賊退篇，結也實国楨。","賈誼昔流慟，匡衡常引經。","道州憂黎庶，词氣浩縱橫。","兩章对秋月，一字偕华星。","至君唐虞際，純樸憶大庭。","何时降璽书，用爾爲丹青。","獄訟永衰息，豈唯偃甲兵。","悽惻念誅求，薄斂近休明。","乃知正人意，不苟飞长纓。","涼飆振南岳，之子寵若驚。","色阻金印大，兴含滄浪清。","我多长卿病，日夕思朝廷。","肺枯渴太甚，漂泊公孫城。","呼兒具紙笔，隐几臨軒楹。","作诗呻吟內，黑澹字攲傾。","感彼危苦词，庶幾知者听。"]', '诗', 'shi', '', NULL, '同元使君舂陵行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a14f11c-1fa5-4d47-abf7-7fd511b82373', '李潮八分小篆歌', '李潮八分小篆歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蒼頡鳥跡既茫昧，字體變化如浮雲。","陳倉石鼓又已訛，大小二篆生八分。","秦有李斯漢蔡邕，中間作者寂不聞。","嶧山之碑野火焚，棗木傳客肥失真。","苦縣光和尚骨立，書貴瘦硬方通神。","惜哉李蔡不復得，吾甥李潮下筆親。","尚書韓擇木，騎曹蔡有鄰。","開元已來數八分，潮也奄有二子成三人。","況潮小篆逼秦相，快劒長戟森相向。","八分一字直百金，蛟龍盤拏肉屈強。","吳郡張顛誇草書，草書非古空雄壯。","豈如吾甥不流宕，丞相中郎丈人行。","巴東逢李潮，逾月求我歌。","我今衰老才力薄，潮乎潮乎奈汝何。"]', '["蒼頡鸟跡既茫昧，字體变化如浮云。","陳倉石鼓又已訛，大小二篆生八分。","秦有李斯漢蔡邕，中间作者寂不闻。","嶧山之碑野火焚，棗木傳客肥失真。","苦縣光和尚骨立，书貴瘦硬方通神。","惜哉李蔡不复得，吾甥李潮下笔親。","尚书韓擇木，騎曹蔡有鄰。","开元已来數八分，潮也奄有二子成三人。","況潮小篆逼秦相，快劒长戟森相向。","八分一字直百金，蛟龙盤拏肉屈強。","吳郡張顛誇草书，草书非古空雄壯。","豈如吾甥不流宕，丞相中郎丈人行。","巴东逢李潮，逾月求我歌。","我今衰老才力薄，潮乎潮乎奈汝何。"]', '诗', 'shi', '', NULL, '李潮八分小篆歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a61c679-137e-47fb-a94c-dc41ff685ab9', '覽柏中允兼子姪數人除官制詞因述父子兄弟四美載歌絲綸', '覽柏中允兼子姪數人除官制词因述父子兄弟四美載歌絲綸', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["紛然喪亂際，見此忠孝門。","蜀中寇亦甚，柏氏功彌存。","深誠補王室，戮力自元昆。","三止錦江沸，獨清玉壘昏。","高名入竹帛，新渥照乾坤。","子弟先卒伍，芝蘭疊璵璠。","同心注師律，灑血在戎軒。","絲綸實具載，紱冕已殊恩。","奉公舉骨肉，誅叛經寒溫。","金甲雪猶凍，朱旗塵不飜。","每聞戰場說，歘激懦氣奔。","聖主國多盜，賢臣官則尊。","方當節鉞用，必絕祲沴根。","吾病日回首，雲臺誰再論。","作歌挹盛事，推轂期孤騫。"]', '["紛然喪亂際，见此忠孝门。","蜀中寇亦甚，柏氏功彌存。","深誠補王室，戮力自元昆。","三止錦江沸，独清玉壘昏。","高名入竹帛，新渥照乾坤。","子弟先卒伍，芝蘭叠璵璠。","同心注師律，灑血在戎軒。","絲綸實具載，紱冕已殊恩。","奉公舉骨肉，誅叛經寒溫。","金甲雪猶凍，朱旗塵不飜。","每闻戰場说，歘激懦氣奔。","聖主国多盜，賢臣官則尊。","方當節鉞用，必絕祲沴根。","吾病日回首，云台誰再論。","作歌挹盛事，推轂期孤騫。"]', '诗', 'shi', '', NULL, '覽柏中允兼子姪數人除官制詞因述父子兄弟四美載歌絲綸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bbfc188-31b0-4e94-99b9-7622a821b815', '聽楊氏歌', '听楊氏歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["佳人絕代歌，獨立發皓齒。","滿堂慘不樂，響下清虛裏。","江城帶素月，況乃清夜起。","老夫悲暮年，壯士淚如水。","玉杯久寂寞，金管迷宮徵。","勿云聽者疲，愚智心盡死。","古來傑出士，豈待一知己。","吾聞昔秦青，傾側天下耳。"]', '["佳人絕代歌，独立發皓齒。","满堂慘不乐，响下清虛裏。","江城带素月，況乃清夜起。","老夫悲暮年，壯士泪如水。","玉杯久寂寞，金管迷宮徵。","勿云听者疲，愚智心尽死。","古来傑出士，豈待一知己。","吾闻昔秦青，傾側天下耳。"]', '诗', 'shi', '', NULL, '聽楊氏歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc77a07-c1db-4875-9e12-9574e51aab15', '荆南兵馬使太常卿趙公大食刀歌', '荆南兵马使太常卿趙公大食刀歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["太常樓船聲嗷嘈，問兵刮寇趨下牢。","牧出令奔飛百艘，猛蛟突獸紛騰逃。","白帝寒城駐錦袍，玄冬示我胡國刀。","壯士短衣頭虎毛，憑軒拔鞘天爲高。","翻風轉日木怒號，冰翼雪澹傷哀猱。","鐫錯碧甖鸊鵜膏，鋩鍔已瑩虛秋濤。","鬼物撇捩辭坑壕，蒼水使者捫赤條。","龍伯國人罷釣鼇，芮公回首顏色勞。","分閫救世用賢豪，趙公玉立高歌起。","攬環結佩相終始，萬歲持之護天子。","得君亂絲與君理，蜀江如線如鍼水。","荆岑彈丸心未已，賊臣惡子休干紀。","魑魅魍魎徒爲耳，妖腰亂領敢欣喜。","用之不高亦不庳，不似長劒須天倚。","吁嗟光祿英雄弭，大食寶刀聊可比。","丹青宛轉麒麟裏，光芒六合無泥滓。"]', '["太常楼船声嗷嘈，问兵刮寇趨下牢。","牧出令奔飞百艘，猛蛟突獸紛腾逃。","白帝寒城駐錦袍，玄冬示我胡国刀。","壯士短衣头虎毛，憑軒拔鞘天爲高。","翻风轉日木怒號，冰翼雪澹傷哀猱。","鐫錯碧甖鸊鵜膏，鋩鍔已瑩虛秋濤。","鬼物撇捩辞坑壕，蒼水使者捫赤條。","龙伯国人罷釣鼇，芮公回首顏色勞。","分閫救世用賢豪，趙公玉立高歌起。","攬环結佩相終始，万歲持之護天子。","得君亂絲與君理，蜀江如線如鍼水。","荆岑彈丸心未已，賊臣惡子休干紀。","魑魅魍魎徒爲耳，妖腰亂領敢欣喜。","用之不高亦不庳，不似长劒須天倚。","吁嗟光祿英雄弭，大食寶刀聊可比。","丹青宛轉麒麟裏，光芒六合無泥滓。"]', '诗', 'shi', '', NULL, '荆南兵馬使太常卿趙公大食刀歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3383ff3c-b6bf-44b6-900a-766acc558644', '王兵馬使二角鷹', '王兵马使二角鷹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["悲臺蕭颯石巃嵸，哀壑杈枒浩呼洶。","中有萬里之長江，迴風滔日孤光動。","角鷹飜倒壯士臂，將軍玉帳軒翠氣。","二鷹猛腦徐侯穟，目如愁胡視天地。","杉雞竹兔不自惜，溪虎野羊俱辟易。","韝上鋒稜十二翮，將軍勇銳與之敵。","將軍樹勳起安西，崑崙虞泉入馬蹄。","白羽曾肉三狻猊，敢決豈不與之齊。","荆南芮公得將軍，亦如角鷹下翔雲。","惡鳥飛飛啄金屋，安得爾輩開其羣，驅出六合梟鸞分。"]', '["悲台蕭颯石巃嵸，哀壑杈枒浩呼洶。","中有万里之长江，迴风滔日孤光动。","角鷹飜倒壯士臂，將軍玉帳軒翠氣。","二鷹猛腦徐侯穟，目如愁胡視天地。","杉雞竹兔不自惜，溪虎野羊俱辟易。","韝上鋒稜十二翮，將軍勇銳與之敵。","將軍樹勳起安西，崑崙虞泉入马蹄。","白羽曾肉三狻猊，敢決豈不與之齊。","荆南芮公得將軍，亦如角鷹下翔云。","惡鸟飞飞啄金屋，安得爾輩开其羣，驱出六合梟鸾分。"]', '诗', 'shi', '', NULL, '王兵馬使二角鷹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397cb7f5-51a4-4897-8fe0-7dd40d1ab332', '狄明府', '狄明府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["梁公曾孫我姨弟，不見十年官濟濟。","大賢之後竟陵遲，浩蕩古今同一體。","比看叔伯四十人，有才無命百寮底。","今者兄弟一百人，幾人卓絕秉周禮。","在汝更用文章爲，長兄白眉復天啓。","汝門請從曾翁說，太后當朝多巧詆。","狄公執政在末年，濁河終不污清濟。","國嗣初將付諸武，公獨廷諍守丹陛。","禁中決冊請房陵，前朝長老皆流涕。","太宗社稷一朝正，漢宮威儀重昭洗。","時危始識不世才，誰謂荼苦甘如薺。","汝曹又宜列土食，身使門戶多旌棨。","胡爲漂泊岷漢間，干謁王侯頗歷抵。","況乃山高水有波，秋風蕭蕭露泥泥。","虎之飢，下巉嵒。","蛟之橫，出清泚。","早歸來，黃土泥衣眼易眯。"]', '["梁公曾孫我姨弟，不见十年官濟濟。","大賢之後竟陵遲，浩蕩古今同一體。","比看叔伯四十人，有才無命百寮底。","今者兄弟一百人，幾人卓絕秉周禮。","在汝更用文章爲，长兄白眉复天啓。","汝门請從曾翁说，太后當朝多巧詆。","狄公執政在末年，濁河終不污清濟。","国嗣初將付諸武，公独廷諍守丹陛。","禁中決冊請房陵，前朝长老皆流涕。","太宗社稷一朝正，漢宮威儀重昭洗。","时危始識不世才，誰謂荼苦甘如薺。","汝曹又宜列土食，身使门戶多旌棨。","胡爲漂泊岷漢间，干謁王侯頗歷抵。","況乃山高水有波，秋风蕭蕭露泥泥。","虎之飢，下巉嵒。","蛟之橫，出清泚。","早归来，黄土泥衣眼易眯。"]', '诗', 'shi', '', NULL, '狄明府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02304a34-5fd7-44fc-a781-9a1ed35a8a03', '秋風二首 一', '秋风二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋風淅淅吹巫山，上牢下牢修水關。","吳檣楚柁牽百丈，暖向神都寒未還。","要路何日罷長戟，戰自青羌連百蠻。","中巴不曾消息好，暝傳戍鼓長雲間。"]', '["秋风淅淅吹巫山，上牢下牢修水关。","吳檣楚柁牽百丈，暖向神都寒未還。","要路何日罷长戟，戰自青羌連百蠻。","中巴不曾消息好，暝傳戍鼓长云间。"]', '诗', 'shi', '', NULL, '秋風二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1177b2a-c00f-4d1a-a8f8-95e33bd6c4f5', '秋風二首 二', '秋风二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋風淅淅吹我衣，東流之外西日微。","天清小城搗練急，石古細路行人稀。","不知明月爲誰好，早晚孤帆他夜歸。","會將白髮倚庭樹，故園池臺今是非。"]', '["秋风淅淅吹我衣，东流之外西日微。","天清小城捣練急，石古細路行人稀。","不知明月爲誰好，早晚孤帆他夜归。","會將白髮倚庭樹，故园池台今是非。"]', '诗', 'shi', '', NULL, '秋風二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ea423c-d3c0-4870-885f-4ebadc8b8fcf', '久雨期王將軍不至', '久雨期王將軍不至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天雨蕭蕭滯茅屋，空山無以慰幽獨。","銳頭將軍來何遲，令我心中苦不足。","數看黃霧亂玄雲，時聽嚴風折喬木。","泉源泠泠雜猿狖，泥濘漠漠飢鴻鵠。","歲暮窮陰耿未已，人生會面難再得。","憶爾腰下鐵絲箭，射殺林中雪色鹿。","前者坐皮因問毛，知子歷險人馬勞。","異獸如飛星宿落，應弦不礙蒼山高。","安得突騎只五千，崒然眉骨皆爾曹。","走平亂世相催促，一豁明主正鬱陶。","憶昔范增碎玉斗，未使吳兵著白袍。","昏昏閶闔閉氛祲，十月荆南雷怒號。"]', '["天雨蕭蕭滯茅屋，空山無以慰幽独。","銳头將軍来何遲，令我心中苦不足。","數看黄霧亂玄云，时听嚴风折喬木。","泉源泠泠杂猿狖，泥濘漠漠飢鴻鵠。","歲暮窮陰耿未已，人生會面难再得。","憶爾腰下鐵絲箭，射殺林中雪色鹿。","前者坐皮因问毛，知子歷險人马勞。","異獸如飞星宿落，應弦不礙蒼山高。","安得突騎只五千，崒然眉骨皆爾曹。","走平亂世相催促，一豁明主正鬱陶。","憶昔范增碎玉斗，未使吳兵著白袍。","昏昏閶闔閉氛祲，十月荆南雷怒號。"]', '诗', 'shi', '', NULL, '久雨期王將軍不至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a27b2b0-bc65-4741-9b66-e9cf0051358a', '別李祕書始興寺所居', '別李祕书始兴寺所居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不見祕書心若失，及見祕書失心疾。","安爲動主理信然，我獨覺子神充實。","重聞西方止觀經，老身古寺風泠泠。","妻兒待我且歸去，他日杖藜來細聽。"]', '["不见祕书心若失，及见祕书失心疾。","安爲动主理信然，我独覺子神充實。","重闻西方止观經，老身古寺风泠泠。","妻兒待我且归去，他日杖藜来細听。"]', '诗', 'shi', '', NULL, '別李祕書始興寺所居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92593a2f-df35-424b-a4e3-51521a80c50e', '虎牙行', '虎牙行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋風歘吸吹南國，天地慘慘無顏色。","洞庭揚波江漢迴，虎牙銅柱皆傾側。","巫峽陰岑朔漠氣，峰巒窈窕谿谷黑。","杜鵑不來猿狖寒，山鬼幽憂雪霜逼。","楚老長嗟憶炎瘴，三尺角弓兩斛力。","壁立石城橫塞起，金錯旌竿滿雲直。","漁陽突騎獵青丘，犬戎鎖甲聞丹極。","八荒十年防盜賊，征戍誅求寡妻哭，遠客中宵淚霑臆。"]', '["秋风歘吸吹南国，天地慘慘無顏色。","洞庭揚波江漢迴，虎牙銅柱皆傾側。","巫峽陰岑朔漠氣，峰巒窈窕谿谷黑。","杜鵑不来猿狖寒，山鬼幽憂雪霜逼。","楚老长嗟憶炎瘴，三尺角弓兩斛力。","壁立石城橫塞起，金錯旌竿满云直。","漁陽突騎獵青丘，犬戎鎖甲闻丹極。","八荒十年防盜賊，征戍誅求寡妻哭，远客中宵泪霑臆。"]', '诗', 'shi', '', NULL, '虎牙行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04b21d5-0f49-468d-963b-cfc58ae76654', '錦樹行', '錦樹行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今日苦短昨日休，歲云暮矣增離憂。","霜凋碧樹待錦樹，萬壑東逝無停留。","荒戍之城石色古，東郭老人住青丘。","飛書白帝營斗粟，琴瑟几杖柴門幽。","青草萋萋盡枯死，天馬跂足隨氂牛。","自古聖賢多薄命，姦雄惡少皆封侯。","故國三年一消息，終南渭水寒悠悠。","五陵豪貴反顛倒，鄉里小兒狐白裘。","生男墮地要膂力，一生富貴傾邦國。","莫愁父母少黃金，天下風塵兒亦得。"]', '["今日苦短昨日休，歲云暮矣增離憂。","霜凋碧樹待錦樹，万壑东逝無停留。","荒戍之城石色古，东郭老人住青丘。","飞书白帝營斗粟，琴瑟几杖柴门幽。","青草萋萋尽枯死，天马跂足隨氂牛。","自古聖賢多薄命，姦雄惡少皆封侯。","故国三年一消息，終南渭水寒悠悠。","五陵豪貴反顛倒，乡里小兒狐白裘。","生男墮地要膂力，一生富貴傾邦国。","莫愁父母少黄金，天下风塵兒亦得。"]', '诗', 'shi', '', NULL, '錦樹行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c55ddde-5ba6-4c4a-868d-a1741df7c270', '赤霄行', '赤霄行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孔雀未知牛有角，渴飲寒泉逢觝觸。","赤霄懸圃須往來，翠尾金花不辭辱。","江中淘河嚇飛燕，銜泥却落羞華屋。","皇孫猶曾蓮勺困，衛莊見貶傷其足。","老翁慎莫怪少年，葛亮貴和書有篇。","丈夫垂名動萬年，記憶細故非高賢。"]', '["孔雀未知牛有角，渴饮寒泉逢觝觸。","赤霄懸圃須往来，翠尾金花不辞辱。","江中淘河嚇飞燕，銜泥却落羞华屋。","皇孫猶曾蓮勺困，衛莊见貶傷其足。","老翁慎莫怪少年，葛亮貴和书有篇。","丈夫垂名动万年，記憶細故非高賢。"]', '诗', 'shi', '', NULL, '赤霄行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2013b6f-2707-4f63-8fc4-af831d86bc9f', '前苦寒行二首 一', '前苦寒行二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢時長安雪一丈，牛馬毛寒縮如蝟。","楚江巫峽冰入懷，虎豹哀號又堪記。","秦城老翁荆揚客，慣習炎蒸歲絺綌。","玄冥祝融氣或交，手持白羽未敢釋。"]', '["漢时长安雪一丈，牛马毛寒縮如蝟。","楚江巫峽冰入懷，虎豹哀號又堪記。","秦城老翁荆揚客，慣習炎蒸歲絺綌。","玄冥祝融氣或交，手持白羽未敢釋。"]', '诗', 'shi', '', NULL, '前苦寒行二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b91c872-6629-4b66-83a1-402a9e26238f', '前苦寒行二首 二', '前苦寒行二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去年白帝雪在山，今年白帝雪在地。","凍埋蛟龍南浦縮，寒刮肌膚北風利。","楚人四時皆麻衣，楚天萬里無晶輝。","三足之烏足恐斷，羲和送將何所歸。"]', '["去年白帝雪在山，今年白帝雪在地。","凍埋蛟龙南浦縮，寒刮肌膚北风利。","楚人四时皆麻衣，楚天万里無晶輝。","三足之烏足恐斷，羲和送將何所归。"]', '诗', 'shi', '', NULL, '前苦寒行二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfab8d8-0b21-4198-b103-275f0433a339', '後苦寒行二首 一', '後苦寒行二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南紀巫廬瘴不絕，太古以來無尺雪。","蠻夷長老怨苦寒，崑崙天關凍應折。"]', '["南紀巫廬瘴不絕，太古以来無尺雪。","蠻夷长老怨苦寒，崑崙天关凍應折。"]', '诗', 'shi', '', NULL, '後苦寒行二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad408522-3d66-49f7-be14-8ca7a8d29301', '後苦寒行二首 二', '後苦寒行二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晚來江門失大木，猛風中夜吹白屋。","天兵斬斷青海戎，殺氣南行動地軸，不爾苦寒何太酷。","巴東之峽生凌澌，彼蒼回軒人得知。"]', '["晚来江门失大木，猛风中夜吹白屋。","天兵斬斷青海戎，殺氣南行动地軸，不爾苦寒何太酷。","巴东之峽生凌澌，彼蒼回軒人得知。"]', '诗', 'shi', '', NULL, '後苦寒行二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5534cce2-5493-48fb-908d-7e13a5487c33', '晚晴', '晚晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高唐暮冬雪壯哉，舊瘴無復似塵埃。","崖沈谷沒白皚皚，江石缺裂青楓摧。","南天三旬苦霧開，赤日照耀從西來。","六龍寒急光裴回，照我衰顏忽落地，口雖吟詠心中哀。","未怪及時少年子，揚眉結義黃金臺。","洎乎吾生何飄零，支離委絕同死灰。"]', '["高唐暮冬雪壯哉，旧瘴無复似塵埃。","崖沈谷沒白皚皚，江石缺裂青楓摧。","南天三旬苦霧开，赤日照耀從西来。","六龙寒急光裴回，照我衰顏忽落地，口雖吟詠心中哀。","未怪及时少年子，揚眉結義黄金台。","洎乎吾生何飄零，支離委絕同死灰。"]', '诗', 'shi', '', NULL, '晚晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ddc03d-8cc2-48c7-9fe2-6f7dc4931a73', '復陰', '复陰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["方冬合沓玄陰塞，昨日晚晴今日黑。","萬里飛蓬映天過，孤城樹羽揚風直。","江濤簸岸黃沙走，雲雪埋山蒼兕吼。","君不見夔子之國杜陵翁，牙齒半落左耳聾。"]', '["方冬合沓玄陰塞，昨日晚晴今日黑。","万里飞蓬映天過，孤城樹羽揚风直。","江濤簸岸黄沙走，云雪埋山蒼兕吼。","君不见夔子之国杜陵翁，牙齒半落左耳聾。"]', '诗', 'shi', '', NULL, '復陰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d91507-c2a6-4260-8145-2ed3cab95504', '夜歸', '夜归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夜來歸來衝虎過，山黑家中已眠臥。","傍見北斗向江低，仰看明星當空大。","庭前把燭嗔兩炬，峽口驚猿聞一箇。","白頭老罷舞復歌，杖藜不睡誰能那。"]', '["夜来归来衝虎過，山黑家中已眠臥。","傍见北斗向江低，仰看明星當空大。","庭前把燭嗔兩炬，峽口驚猿闻一箇。","白头老罷舞复歌，杖藜不睡誰能那。"]', '诗', 'shi', '', NULL, '夜歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797a6309-5f6b-47f3-80e7-d83142478dd6', '寄柏學士林居', '寄柏学士林居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自胡之反持干戈，天下學士亦奔波。","歎彼幽棲載典籍，蕭然暴露依山阿。","青山萬里靜散地，白雨一洗空垂蘿。","亂代飄零余到此，古人成敗子如何。","荆揚春冬異風土，巫峽日夜多雲雨。","赤葉楓林百舌鳴，黃泥野岸天雞舞。","盜賊縱橫甚密邇，形神寂莫甘辛苦。","幾時高議排金門，各使蒼生有環堵。"]', '["自胡之反持干戈，天下学士亦奔波。","歎彼幽棲載典籍，蕭然暴露依山阿。","青山万里静散地，白雨一洗空垂蘿。","亂代飄零余到此，古人成敗子如何。","荆揚春冬異风土，巫峽日夜多云雨。","赤葉楓林百舌鳴，黄泥野岸天雞舞。","盜賊縱橫甚密邇，形神寂莫甘辛苦。","幾时高議排金门，各使蒼生有环堵。"]', '诗', 'shi', '', NULL, '寄柏學士林居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82840988-dfdf-4348-84e7-1d0f873bb988', '寄從孫崇簡', '寄從孫崇簡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嵯峨白帝城東西，南有龍湫北虎溪。","吾孫騎曹不騎馬，業學尸鄉多養雞。","龐公隱時盡室去，武陵春樹他人迷。","與汝林居未相失，近身藥裹酒長攜。","牧豎樵童亦無賴，莫令斬斷青雲梯。"]', '["嵯峨白帝城东西，南有龙湫北虎溪。","吾孫騎曹不騎马，業学尸乡多養雞。","龐公隐时尽室去，武陵春樹他人迷。","與汝林居未相失，近身藥裹酒长携。","牧豎樵童亦無賴，莫令斬斷青云梯。"]', '诗', 'shi', '', NULL, '寄從孫崇簡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c2af72-5550-4403-8c15-53be3d38913e', '奉酬薛十二丈判官見贈', '奉酬薛十二丈判官见贈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["忽忽峽中睡，悲風方一醒。","西來有好鳥，爲我下青冥。","羽毛淨白雪，慘澹飛雲汀。","既蒙主人顧，舉翮唳孤亭。","持以比佳士，及此慰揚舲。","清文動哀玉，見道發新硎。","欲學鴟夷子，待勒燕山銘。","誰重斷蛇劒，致君君未聽。","志在麒麟閣，無心雲母屏。","卓氏近新寡，豪家朱門扃。","相如才調逸，銀漢會雙星。","客來洗粉黛，日暮拾流螢。","不是無膏火，勸郎勤六經。","老夫自汲澗，野水日泠泠。","我歎黑頭白，君看銀印青。","臥病識山鬼，爲農知地形。","誰矜坐錦帳，苦厭食魚腥。","東西兩岸坼，橫水注滄溟。","碧色忽惆悵，風雷搜百靈。","空中右白虎，赤節引娉婷。","自云帝里女，噀雨鳳凰翎。","襄王薄行跡，莫學冷如丁。","千秋一拭淚，夢覺有微馨。","人生相感動，金石兩青熒。","丈人但安坐，休辨渭與涇。","龍蛇尚格鬬，灑血暗郊坰。","吾聞聰明主，治國用輕刑。","銷兵鑄農器，今古歲方寧。","文王日儉德，俊乂始盈庭。","榮華貴少壯，豈食楚江萍。"]', '["忽忽峽中睡，悲风方一醒。","西来有好鸟，爲我下青冥。","羽毛淨白雪，慘澹飞云汀。","既蒙主人顧，舉翮唳孤亭。","持以比佳士，及此慰揚舲。","清文动哀玉，见道發新硎。","欲学鴟夷子，待勒燕山銘。","誰重斷蛇劒，致君君未听。","志在麒麟閣，無心云母屏。","卓氏近新寡，豪家朱门扃。","相如才調逸，銀漢會雙星。","客来洗粉黛，日暮拾流螢。","不是無膏火，勸郎勤六經。","老夫自汲澗，野水日泠泠。","我歎黑头白，君看銀印青。","臥病識山鬼，爲農知地形。","誰矜坐錦帳，苦厭食鱼腥。","东西兩岸坼，橫水注滄溟。","碧色忽惆悵，风雷搜百靈。","空中右白虎，赤節引娉婷。","自云帝里女，噀雨鳳凰翎。","襄王薄行跡，莫学冷如丁。","千秋一拭泪，梦覺有微馨。","人生相感动，金石兩青熒。","丈人但安坐，休辨渭與涇。","龙蛇尚格鬬，灑血暗郊坰。","吾闻聰明主，治国用轻刑。","銷兵鑄農器，今古歲方寧。","文王日儉德，俊乂始盈庭。","榮华貴少壯，豈食楚江萍。"]', '诗', 'shi', '', NULL, '奉酬薛十二丈判官見贈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de948fac-a55e-462b-98f8-aa3b9214fc54', '醉爲馬墜諸公攜酒相看', '醉爲马墜諸公携酒相看', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["甫也諸侯老賓客，罷酒酣歌拓金戟。","騎馬忽憶少年時，散蹄迸落瞿塘石。","白帝城門水雲外，低身直下八千尺。","粉堞電轉紫遊韁，東得平岡出天壁。","江村野堂爭入眼，垂鞭嚲鞚凌紫陌。","向來皓首驚萬人，自倚紅顏能騎射。","安知決臆追風足，朱汗驂驔猶噴玉。","不虞一蹶終損傷，人生快意多所辱。","職當憂戚伏衾枕，況乃遲暮加煩促。","明知來問腆我顏，杖藜強起依僮僕。","語盡還成開口笑，提攜別埽清谿曲。","酒肉如山又一時，初筵哀絲動豪竹。","共指西日不相貸，喧呼且覆杯中淥。","何必走馬來爲問，君不見嵇康養生遭殺戮。"]', '["甫也諸侯老賓客，罷酒酣歌拓金戟。","騎马忽憶少年时，散蹄迸落瞿塘石。","白帝城门水云外，低身直下八千尺。","粉堞電轉紫游韁，东得平岡出天壁。","江村野堂爭入眼，垂鞭嚲鞚凌紫陌。","向来皓首驚万人，自倚紅顏能騎射。","安知決臆追风足，朱汗驂驔猶噴玉。","不虞一蹶終損傷，人生快意多所辱。","職當憂戚伏衾枕，況乃遲暮加煩促。","明知来问腆我顏，杖藜強起依僮僕。","語尽還成开口笑，提携別埽清谿曲。","酒肉如山又一时，初筵哀絲动豪竹。","共指西日不相貸，喧呼且覆杯中淥。","何必走马来爲问，君不见嵇康養生遭殺戮。"]', '诗', 'shi', '', NULL, '醉爲馬墜諸公攜酒相看 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc722fa9-6e62-4d59-9bcd-b8d0ef06daa6', '別李義', '別李義', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["神堯十八子，十七王其門。","道國洎舒國，督唯親弟昆。","中外貴賤殊，余亦忝諸孫。","丈人嗣三葉，之子白玉溫。","道國繼德業，請從丈人論。","丈人領宗卿，肅穆古制敦。","先朝納諫諍，直氣橫乾坤。","子建文筆壯，河間經術存。","爾克富詩禮，骨清慮不喧。","洗然遇知几，談論淮湖奔。","憶昔初見時，小襦繡芳蓀。","長成忽會面，慰我久疾魂。","三峽春冬交，江山雲霧昏。","正宜且聚集，恨此當離尊。","莫怪執杯遲，我衰涕唾煩。","重問子何之，西上岷江源。","願子少干謁，蜀都足戎軒。","誤失將帥意，不如親故恩。","少年早歸來，梅花已飛飜。","努力慎風水，豈惟數盤[飧]。","猛虎臥在岸，蛟螭出無痕。","王子自愛惜，老夫困石根。","生別古所嗟，發聲爲爾吞。"]', '["神堯十八子，十七王其门。","道国洎舒国，督唯親弟昆。","中外貴賤殊，余亦忝諸孫。","丈人嗣三葉，之子白玉溫。","道国繼德業，請從丈人論。","丈人領宗卿，肅穆古制敦。","先朝納諫諍，直氣橫乾坤。","子建文笔壯，河间經術存。","爾克富诗禮，骨清慮不喧。","洗然遇知几，談論淮湖奔。","憶昔初见时，小襦繡芳蓀。","长成忽會面，慰我久疾魂。","三峽春冬交，江山云霧昏。","正宜且聚集，恨此當離尊。","莫怪執杯遲，我衰涕唾煩。","重问子何之，西上岷江源。","願子少干謁，蜀都足戎軒。","誤失將帥意，不如親故恩。","少年早归来，梅花已飞飜。","努力慎风水，豈惟數盤[飧]。","猛虎臥在岸，蛟螭出無痕。","王子自愛惜，老夫困石根。","生別古所嗟，發声爲爾吞。"]', '诗', 'shi', '', NULL, '別李義 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26587ca4-6af1-4180-a430-b29652a14f1d', '送高司直尋封閬州', '送高司直尋封閬州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丹雀銜書來，暮棲何鄉樹。","驊騮事天子，辛苦在道路。","司直非冗官，荒山甚無趣。","借問泛舟人，胡爲入雲霧。","與子姻婭間，即親亦有故。","萬里長江邊，邂逅一相遇。","長卿消渴再，公幹沈緜屢。","清談慰老夫，開卷得佳句。","時見文章士，欣然澹情素。","伏枕聞別離，疇能忍漂寓。","良會苦短促，溪行水奔注。","熊羆咆空林，游子慎馳騖。","西謁巴中侯，艱險如跬步。","主人不世才，先帝常特顧。","拔爲天軍佐，崇大王法度。","淮海生清風，南翁尚思慕。","公宮造廣廈，木石乃無數。","初聞伐松柏，猶臥天一柱。","我瘦書不成，成字讀亦誤。","爲我問故人，勞心練征戍。"]', '["丹雀銜书来，暮棲何乡樹。","驊騮事天子，辛苦在道路。","司直非冗官，荒山甚無趣。","借问泛舟人，胡爲入云霧。","與子姻婭间，即親亦有故。","万里长江邊，邂逅一相遇。","长卿消渴再，公幹沈緜屢。","清談慰老夫，开卷得佳句。","时见文章士，欣然澹情素。","伏枕闻別離，疇能忍漂寓。","良會苦短促，溪行水奔注。","熊羆咆空林，游子慎驰騖。","西謁巴中侯，艱險如跬步。","主人不世才，先帝常特顧。","拔爲天軍佐，崇大王法度。","淮海生清风，南翁尚思慕。","公宮造廣廈，木石乃無數。","初闻伐松柏，猶臥天一柱。","我瘦书不成，成字读亦誤。","爲我问故人，勞心練征戍。"]', '诗', 'shi', '', NULL, '送高司直尋封閬州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cfeb483-2cfb-4f3e-8ed1-059eaccdd260', '君不見簡蘇徯', '君不见簡蘇徯', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見道邊廢棄池，君不見前者摧折桐。","百年死樹中琴瑟，一斛舊水藏蛟龍。","丈夫蓋棺事始定，君今幸未成老翁。","何恨顦顇在山中，深山窮谷不可處，霹靂魍魎兼狂風。"]', '["君不见道邊廢棄池，君不见前者摧折桐。","百年死樹中琴瑟，一斛旧水藏蛟龙。","丈夫蓋棺事始定，君今幸未成老翁。","何恨顦顇在山中，深山窮谷不可处，霹靂魍魎兼狂风。"]', '诗', 'shi', '', NULL, '君不見簡蘇徯 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1974de1f-6f04-486a-a348-c8f8ee0fc9c6', '贈蘇四徯', '贈蘇四徯', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["異縣昔同遊，各云厭轉蓬。","別離已五年，尚在行李中。","戎馬日衰息，乘輿安九重。","有才何棲棲，將老委所窮。","爲郎未爲賤，其奈疾病攻。","子何面黧黑，不得豁心胷。","巴蜀倦剽掠，下愚成土風。","幽薊已削平，荒徼尚彎弓。","斯人脫身來，豈非吾道東。","乾坤雖寬大，所適裝囊空。","肉食哂菜色，少壯欺老翁。","況乃主客間，古來偪側同。","君今下荆揚，獨帆如飛鴻。","二州豪俠場，人馬皆自雄。","一請甘飢寒，再請甘養蒙。"]', '["異縣昔同游，各云厭轉蓬。","別離已五年，尚在行李中。","戎马日衰息，乘輿安九重。","有才何棲棲，將老委所窮。","爲郎未爲賤，其奈疾病攻。","子何面黧黑，不得豁心胷。","巴蜀倦剽掠，下愚成土风。","幽薊已削平，荒徼尚彎弓。","斯人脫身来，豈非吾道东。","乾坤雖寬大，所適裝囊空。","肉食哂菜色，少壯欺老翁。","況乃主客间，古来偪側同。","君今下荆揚，独帆如飞鴻。","二州豪俠場，人马皆自雄。","一請甘飢寒，再請甘養蒙。"]', '诗', 'shi', '', NULL, '贈蘇四徯 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250f7cf0-6e19-4bfc-bcc3-96c0c2c67622', '寄薛三郎中', '寄薛三郎中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["人生無賢愚，飄颻若埃塵。","自非得神仙，誰免危其身。","與子俱白頭，役役常苦辛。","雖爲尚書郎，不及村野人。","憶昔村野人，其樂難具陳。","藹藹桑麻交，公侯爲等倫。","天未厭戎馬，我輩本常貧。","子尚客荆州，我亦滯江濱。","峽中一臥病，瘧癘終冬春。","春復加肺氣，此病蓋有因。","早歲與蘇鄭，痛飲情相親。","二公化爲土，嗜酒不失真。","余今委修短，豈得恨命屯。","聞子心甚壯，所遇信席珍。","上馬不用扶，每扶必怒嗔。","賦詩賓客間，揮灑動八垠。","乃知蓋代手，才力老益神。","青草洞庭湖，東浮滄海漘。","君山可避暑，況足采白蘋。","子豈無扁舟，往復江漢津。","我未下瞿塘，空念禹功勤。","聽說松門峽，吐藥攬衣巾。","高秋却束帶，鼓枻視青旻。","鳳池日澄碧，濟濟多士新。","余病不能起，健者勿逡巡。","上有明哲君，下有行化臣。"]', '["人生無賢愚，飄颻若埃塵。","自非得神仙，誰免危其身。","與子俱白头，役役常苦辛。","雖爲尚书郎，不及村野人。","憶昔村野人，其乐难具陳。","藹藹桑麻交，公侯爲等倫。","天未厭戎马，我輩本常貧。","子尚客荆州，我亦滯江濱。","峽中一臥病，瘧癘終冬春。","春复加肺氣，此病蓋有因。","早歲與蘇鄭，痛饮情相親。","二公化爲土，嗜酒不失真。","余今委修短，豈得恨命屯。","闻子心甚壯，所遇信席珍。","上马不用扶，每扶必怒嗔。","賦诗賓客间，揮灑动八垠。","乃知蓋代手，才力老益神。","青草洞庭湖，东浮滄海漘。","君山可避暑，況足采白蘋。","子豈無扁舟，往复江漢津。","我未下瞿塘，空念禹功勤。","听说松门峽，吐藥攬衣巾。","高秋却束带，鼓枻視青旻。","鳳池日澄碧，濟濟多士新。","余病不能起，健者勿逡巡。","上有明哲君，下有行化臣。"]', '诗', 'shi', '', NULL, '寄薛三郎中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d549304d-762c-49d7-a661-d008586a3ec1', '大覺高僧蘭若', '大覺高僧蘭若', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫山不見廬山遠，松林蘭若秋風晚。","一老猶鳴日暮鐘，諸僧尚乞齋時飯。","香爐峰色隱晴湖，種杏仙家近白榆。","飛錫去年啼邑子，獻花何日許門徒。"]', '["巫山不见廬山远，松林蘭若秋风晚。","一老猶鳴日暮鐘，諸僧尚乞斋时飯。","香爐峰色隐晴湖，種杏仙家近白榆。","飞錫去年啼邑子，獻花何日許门徒。"]', '诗', 'shi', '', NULL, '大覺高僧蘭若 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71817edb-5481-405b-90ae-0d67ed39c59c', '宿青溪驛奉懷張員外十五兄之緒', '宿青溪驛奉懷張員外十五兄之緒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漾舟千山內，日入泊枉渚。","我生本飄飄，今復在何許。","石根青楓林，猿鳥聚儔侶。","月明游子靜，畏虎不得語。","中夜懷友朋，乾坤此深阻。","浩蕩前後間，佳期付荆楚。"]', '["漾舟千山內，日入泊枉渚。","我生本飄飄，今复在何許。","石根青楓林，猿鸟聚儔侶。","月明游子静，畏虎不得語。","中夜懷友朋，乾坤此深阻。","浩蕩前後间，佳期付荆楚。"]', '诗', 'shi', '', NULL, '宿青溪驛奉懷張員外十五兄之緒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47efe0be-f2da-4171-9d3b-abd166ae86f9', '敬寄族弟唐十八使君', '敬寄族弟唐十八使君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["與君陶唐後，盛族多其人。","聖賢冠史籍，枝派羅源津。","在今氣磊落，巧僞莫敢親。","介立實吾弟，濟時肯殺身。","物白諱受玷，行高無污真。","得罪永泰末，放之五溪濱。","鸞鳳有鎩翮，先儒曾抱麟。","雷霆霹長松，骨大却生筋。","一失不足傷，念子孰自珍。","泊舟楚宮岸，戀闕浩酸辛。","除名配清江，厥土巫峽鄰。","登陸將首途，筆札枉所申。","歸朝跼病肺，敘舊思重陳。","春風洪濤壯，谷轉頗彌旬。","我能泛中流，搪突鼉獺瞋。","長年已省柁，慰此貞良臣。"]', '["與君陶唐後，盛族多其人。","聖賢冠史籍，枝派羅源津。","在今氣磊落，巧僞莫敢親。","介立實吾弟，濟时肯殺身。","物白諱受玷，行高無污真。","得罪永泰末，放之五溪濱。","鸾鳳有鎩翮，先儒曾抱麟。","雷霆霹长松，骨大却生筋。","一失不足傷，念子孰自珍。","泊舟楚宮岸，戀闕浩酸辛。","除名配清江，厥土巫峽鄰。","登陸將首途，笔札枉所申。","归朝跼病肺，敘旧思重陳。","春风洪濤壯，谷轉頗彌旬。","我能泛中流，搪突鼉獺瞋。","长年已省柁，慰此貞良臣。"]', '诗', 'shi', '', NULL, '敬寄族弟唐十八使君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e416ce8-2636-46ef-b193-83fe64d189e9', '憶昔行', '憶昔行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昔北尋小有洞，洪河怒濤過輕舸。","辛勤不見華蓋君，艮岑青輝慘么麼。","千崖無人萬壑靜，三步回頭五步坐。","秋山眼冷魂未歸，仙賞心違淚交墮。","弟子誰依白茅室，盧老獨啓青銅鎖。","巾拂香餘搗藥塵，階除灰死燒丹火。","懸圃滄洲莽空闊，金節羽衣飄婀娜。","落日初霞閃餘映，倏忽東西無不可。","松風澗水聲合時，青兕黃熊啼向我。","徒然咨嗟撫遺迹，至今夢想猶佐。","祕訣隱文須內教，晚歲何功使願果。","更討衡陽董鍊師，南浮早鼓瀟湘柁。"]', '["憶昔北尋小有洞，洪河怒濤過轻舸。","辛勤不见华蓋君，艮岑青輝慘么麼。","千崖無人万壑静，三步回头五步坐。","秋山眼冷魂未归，仙賞心違泪交墮。","弟子誰依白茅室，盧老独啓青銅鎖。","巾拂香餘捣藥塵，階除灰死燒丹火。","懸圃滄洲莽空闊，金節羽衣飄婀娜。","落日初霞閃餘映，倏忽东西無不可。","松风澗水声合时，青兕黄熊啼向我。","徒然咨嗟撫遺迹，至今梦想猶佐。","祕訣隐文須內教，晚歲何功使願果。","更討衡陽董鍊師，南浮早鼓瀟湘柁。"]', '诗', 'shi', '', NULL, '憶昔行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67761270-0287-499c-b702-123d49c2786d', '魏將軍歌', '魏將軍歌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["將軍昔著從事衫，鐵馬馳突重兩銜。","披堅執銳略西極，崑崙月窟東嶄巖。","君門羽林萬猛士，惡若哮虎子所監。","五年起家列霜戟，一日過海收風帆。","平生流輩徒蠢蠢，長安少年氣欲盡。","魏侯骨聳精爽緊，華岳峰尖見秋隼。","星躔寶校金盤陀，夜騎天駟超天河。","欃槍熒惑不敢動，翠蕤雲旓相蕩摩。","吾爲子起歌都護，酒闌插劒肝膽露。"]', '["將軍昔著從事衫，鐵马驰突重兩銜。","披堅執銳略西極，崑崙月窟东嶄巖。","君门羽林万猛士，惡若哮虎子所監。","五年起家列霜戟，一日過海收风帆。","平生流輩徒蠢蠢，长安少年氣欲尽。","魏侯骨聳精爽緊，华岳峰尖见秋隼。","星躔寶校金盤陀，夜騎天駟超天河。","欃槍熒惑不敢动，翠蕤云旓相蕩摩。","吾爲子起歌都護，酒闌插劒肝膽露。"]', '诗', 'shi', '', NULL, '魏將軍歌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afe3c27-812c-4eed-bb30-74e657009e41', '北風', '北风', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北風破南極，朱鳳日威垂。","洞庭秋欲雪，鴻雁將安歸。","十年殺氣盛，六合人煙稀。","吾慕漢初老，時清猶茹芝。"]', '["北风破南極，朱鳳日威垂。","洞庭秋欲雪，鴻雁將安归。","十年殺氣盛，六合人煙稀。","吾慕漢初老，时清猶茹芝。"]', '诗', 'shi', '', NULL, '北風 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89afce4e-3ab0-4e02-9a9d-a91a555a88b2', '客從', '客從', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客從南溟來，遺我泉客珠。","珠中有隱字，欲辨不成書。","緘之篋笥久，以俟公家須。","開視化爲血，哀今徵斂無。"]', '["客從南溟来，遺我泉客珠。","珠中有隐字，欲辨不成书。","緘之篋笥久，以俟公家須。","开視化爲血，哀今徵斂無。"]', '诗', 'shi', '', NULL, '客從 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be76202d-c128-4278-b070-dcb351ae96ae', '白馬', '白马', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白馬東北來，空鞍貫雙箭。","可憐馬上郎，意氣今誰見。","近時主將戳，中夜商於戰。","喪亂死多門，嗚呼淚如霰。"]', '["白马东北来，空鞍貫雙箭。","可怜马上郎，意氣今誰见。","近时主將戳，中夜商於戰。","喪亂死多门，嗚呼泪如霰。"]', '诗', 'shi', '', NULL, '白馬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c9ee6f-c868-4850-9b8e-30ab5c1891e9', '白鳧行', '白鳧行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見黃鵠高於五尺童，化爲白鳧似老翁。","故畦遺穗已蕩盡，天寒歲暮波濤中。","鱗介腥羶素不食，終日忍飢西復東。","魯門鶢鶋亦蹭蹬，聞道如今猶避風。"]', '["君不见黄鵠高於五尺童，化爲白鳧似老翁。","故畦遺穗已蕩尽，天寒歲暮波濤中。","鱗介腥羶素不食，終日忍飢西复东。","魯门鶢鶋亦蹭蹬，闻道如今猶避风。"]', '诗', 'shi', '', NULL, '白鳧行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b89639-fa5f-4458-9c0a-c4dc25fd5b97', '朱鳳行', '朱鳳行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君不見瀟湘之山衡山高，山巔朱鳳聲嗷嗷。","側身長顧求其羣，翅垂口噤心甚勞。","下愍百鳥在羅網，黃雀最小猶難逃。","願分竹實及螻蟻，盡使鴟梟相怒號。"]', '["君不见瀟湘之山衡山高，山巔朱鳳声嗷嗷。","側身长顧求其羣，翅垂口噤心甚勞。","下愍百鸟在羅網，黄雀最小猶难逃。","願分竹實及螻蟻，尽使鴟梟相怒號。"]', '诗', 'shi', '', NULL, '朱鳳行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6e299e-64bd-43d0-a15b-7512bead4c84', '惜別行送向卿進奉端午御衣之上都', '惜別行送向卿進奉端午御衣之上都', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["肅宗昔在靈武城，指揮猛將收咸京。","向公泣血灑行殿，佐佑卿相乾坤平。","逆胡冥寞隨煙燼，卿家兄弟功名震。","麒麟圖畫鴻雁行，紫極出入黃金印。","尚書勳業超千古，雄鎮荆州繼吾祖。","裁縫雲霧成御衣，拜跪題封向端午。","向卿將命寸心赤，青山落日江潮白。","卿到朝廷說老翁，漂零已是滄浪客。"]', '["肅宗昔在靈武城，指揮猛將收咸京。","向公泣血灑行殿，佐佑卿相乾坤平。","逆胡冥寞隨煙燼，卿家兄弟功名震。","麒麟圖畫鴻雁行，紫極出入黄金印。","尚书勳業超千古，雄鎮荆州繼吾祖。","裁縫云霧成御衣，拜跪題封向端午。","向卿將命寸心赤，青山落日江潮白。","卿到朝廷说老翁，漂零已是滄浪客。"]', '诗', 'shi', '', NULL, '惜別行送向卿進奉端午御衣之上都 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff1b780-5ef1-4c4f-abff-ef38d41e3c32', '醉歌行贈公安顏少府請顧八題壁', '醉歌行贈公安顏少府請顧八題壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["神仙中人不易得，顏氏之子才孤標。","天馬長鳴待駕馭，秋鷹整翮當雲霄。","君不見東吳顧文學，君不見西漢杜陵老。","詩家筆勢君不嫌，詞翰升堂爲君埽。","是日霜風凍七澤，烏蠻落照銜赤壁。","酒酣耳熱忘頭白，感君意氣無所惜，一爲歌行歌主客。"]', '["神仙中人不易得，顏氏之子才孤標。","天马长鳴待駕馭，秋鷹整翮當云霄。","君不见东吳顧文学，君不见西漢杜陵老。","诗家笔勢君不嫌，词翰升堂爲君埽。","是日霜风凍七澤，烏蠻落照銜赤壁。","酒酣耳熱忘头白，感君意氣無所惜，一爲歌行歌主客。"]', '诗', 'shi', '', NULL, '醉歌行贈公安顏少府請顧八題壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6985205-7423-47bf-ad4d-19e2ee4eaed0', '夜聞觱篥', '夜闻觱篥', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夜聞觱篥滄江上，衰年側耳情所嚮。","鄰舟一聽多感傷，塞曲三更歘悲壯。","積雪飛霜此夜寒，孤燈急管復風湍。","君知天地干戈滿，不見江湖行路難。"]', '["夜闻觱篥滄江上，衰年側耳情所嚮。","鄰舟一听多感傷，塞曲三更歘悲壯。","積雪飞霜此夜寒，孤灯急管复风湍。","君知天地干戈满，不见江湖行路难。"]', '诗', 'shi', '', NULL, '夜聞觱篥 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83fab156-6339-4b67-aca1-5ee2b16f2680', '發劉郎浦', '發劉郎浦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["挂帆早發劉郎浦，疾風颯颯昏亭午。","舟中無日不沙塵，岸上空村盡豺虎。","十日北風風未回，客行歲晚晚相催。","白頭厭伴漁人宿，黃帽青鞋歸去來。"]', '["挂帆早發劉郎浦，疾风颯颯昏亭午。","舟中無日不沙塵，岸上空村尽豺虎。","十日北风风未回，客行歲晚晚相催。","白头厭伴漁人宿，黄帽青鞋归去来。"]', '诗', 'shi', '', NULL, '發劉郎浦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c5878d-7369-4694-bf73-7d9835693502', '別董頲', '別董頲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["窮冬急風水，逆浪開帆難。","士子甘旨闕，不知道里寒。","有求彼樂土，南適小長安。","到我舟檝去，覺君衣裳單。","素聞趙公節，兼盡賓主歡。","已結門廬望，無令霜雪殘。","老夫纜亦解，脫粟朝未餐。","飄蕩兵甲際，幾時懷抱寬。","漢陽頗寧靜，峴首試考槃。","當念著白帽，采薇青雲端。"]', '["窮冬急风水，逆浪开帆难。","士子甘旨闕，不知道里寒。","有求彼乐土，南適小长安。","到我舟檝去，覺君衣裳單。","素闻趙公節，兼尽賓主歡。","已結门廬望，無令霜雪殘。","老夫纜亦解，脫粟朝未餐。","飄蕩兵甲際，幾时懷抱寬。","漢陽頗寧静，峴首試考槃。","當念著白帽，采薇青云端。"]', '诗', 'shi', '', NULL, '別董頲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d375e62b-149d-4aae-ac75-eb0457e9b7e0', '送重表姪王砅評事使南海', '送重表姪王砅評事使南海', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我之曾祖姑，爾之高祖母。","爾祖未顯時，歸爲尚書婦。","隋朝大業末，房杜俱交友長者來在門，荒年自餬口。","家貧無供給，客位但箕帚。","俄頃羞頗珍，寂寥人散後。","入怪鬢髮空，吁嗟爲之久。","自陳剪髻鬟，鬻市充杯酒。","上云天下亂，宜與英俊厚。","向竊窺數公，經綸亦俱有。","次問最少年，虯髯十八九。","子等成大名，皆因此人手。","下云風雲合，龍虎一吟吼。","願展丈夫雄，得辭兒女醜。","秦王時在坐，真氣驚戶牖。","及乎貞觀初，尚書踐台斗。","夫人常肩輿，上殿稱萬壽。","六宮師柔順，法則化妃后。","至尊均嫂叔，盛事垂不朽。","鳳雛無凡毛，五色非爾曹。","往者胡作逆，乾坤沸嗷嗷。","吾客左馮翊，爾家同遁逃。","爭奪至徒步，塊獨委蓬蒿。","逗留熱爾腸，十里却呼號。","自下所騎馬，右持腰間刀。","左牽紫遊韁，飛走使我高。","苟活到今日，寸心銘佩牢。","亂離又聚散，宿昔恨滔滔。","水花笑白首，春草隨青袍。","廷評近要津，節制收英髦。","北驅漢陽傳，南泛上瀧舠。","家聲肯墜地，利器當秋毫。","番禺親賢領，籌運神功操。","大夫出盧宋，寶貝休脂膏。","洞主降接武，海胡舶千艘。","我欲就丹砂，跋涉覺身勞。","安能陷糞土，有志乘鯨鼇。","或驂鸞騰天，聊作鶴鳴臯。"]', '["我之曾祖姑，爾之高祖母。","爾祖未显时，归爲尚书婦。","隋朝大業末，房杜俱交友长者来在门，荒年自餬口。","家貧無供給，客位但箕帚。","俄頃羞頗珍，寂寥人散後。","入怪鬢髮空，吁嗟爲之久。","自陳剪髻鬟，鬻市充杯酒。","上云天下亂，宜與英俊厚。","向竊窺數公，經綸亦俱有。","次问最少年，虯髯十八九。","子等成大名，皆因此人手。","下云风云合，龙虎一吟吼。","願展丈夫雄，得辞兒女醜。","秦王时在坐，真氣驚戶牖。","及乎貞观初，尚书踐台斗。","夫人常肩輿，上殿稱万壽。","六宮師柔順，法則化妃后。","至尊均嫂叔，盛事垂不朽。","鳳雛無凡毛，五色非爾曹。","往者胡作逆，乾坤沸嗷嗷。","吾客左馮翊，爾家同遁逃。","爭奪至徒步，塊独委蓬蒿。","逗留熱爾腸，十里却呼號。","自下所騎马，右持腰间刀。","左牽紫游韁，飞走使我高。","苟活到今日，寸心銘佩牢。","亂離又聚散，宿昔恨滔滔。","水花笑白首，春草隨青袍。","廷評近要津，節制收英髦。","北驱漢陽傳，南泛上瀧舠。","家声肯墜地，利器當秋毫。","番禺親賢領，籌運神功操。","大夫出盧宋，寶貝休脂膏。","洞主降接武，海胡舶千艘。","我欲就丹砂，跋涉覺身勞。","安能陷糞土，有志乘鯨鼇。","或驂鸾腾天，聊作鹤鳴臯。"]', '诗', 'shi', '', NULL, '送重表姪王砅評事使南海 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4216bc54-ef1a-4edf-bdcd-059248446dd2', '詠懷二首 一', '詠懷二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["人生貴是男，丈夫重天機。","未達善一身，得志行所爲。","嗟余竟轗軻，將老逢艱危。","胡雛逼神器，逆節同所歸。","河雒化爲血，公侯草間啼。","西京復陷沒，翠蓋蒙塵飛。","萬姓悲赤子，兩宮棄紫微。","倏忽向二紀，奸雄多是非。","本朝再樹立，未及貞觀時。","日給在軍儲，上官督有司。","高賢迫形勢，豈暇相扶持。","疲{艹尔}苟懷策，棲屑無所施。","先王實罪己，愁痛正爲茲。","歲月不我與，蹉跎病於斯。","夜看豐城氣，回首蛟龍池。","齒髮已自料，意深陳苦詞。"]', '["人生貴是男，丈夫重天機。","未達善一身，得志行所爲。","嗟余竟轗軻，將老逢艱危。","胡雛逼神器，逆節同所归。","河雒化爲血，公侯草间啼。","西京复陷沒，翠蓋蒙塵飞。","万姓悲赤子，兩宮棄紫微。","倏忽向二紀，奸雄多是非。","本朝再樹立，未及貞观时。","日給在軍儲，上官督有司。","高賢迫形勢，豈暇相扶持。","疲{艹尔}苟懷策，棲屑無所施。","先王實罪己，愁痛正爲茲。","歲月不我與，蹉跎病於斯。","夜看豐城氣，回首蛟龙池。","齒髮已自料，意深陳苦词。"]', '诗', 'shi', '', NULL, '詠懷二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2066e225-eae6-4861-abd4-f326a958ff93', '詠懷二首 二', '詠懷二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["邦危壞法則，聖遠益愁慕。","飄颻桂水遊，悵望蒼梧暮。","潛魚不銜鉤，走鹿無反顧。","皦皦幽曠心，拳拳異平素。","衣食相拘閡，朋知限流寓。","風濤上春沙，千里侵江樹。","逆行少吉日，時節空復度。","井竈任塵埃，舟航煩數具。","牽纏加老病，瑣細隘俗務。","萬古一死生，胡爲足名數。","多憂污桃源，拙計泥銅柱。","未辭炎瘴毒，擺落跋涉懼。","虎狼窺中原，焉得所歷住。","葛洪及許靖，避世常此路。","賢愚誠等差，自愛各馳騖。","羸瘠且如何，魄奪鍼灸屢。","擁滯僮僕慵，稽留篙師怒。","終當挂帆席，天意難告訴。","南爲祝融客，勉強親杖屨。","結託老人星，羅浮展衰步。"]', '["邦危壞法則，聖远益愁慕。","飄颻桂水游，悵望蒼梧暮。","潛鱼不銜鉤，走鹿無反顧。","皦皦幽曠心，拳拳異平素。","衣食相拘閡，朋知限流寓。","风濤上春沙，千里侵江樹。","逆行少吉日，时節空复度。","井竈任塵埃，舟航煩數具。","牽纏加老病，瑣細隘俗務。","万古一死生，胡爲足名數。","多憂污桃源，拙計泥銅柱。","未辞炎瘴毒，擺落跋涉懼。","虎狼窺中原，焉得所歷住。","葛洪及許靖，避世常此路。","賢愚誠等差，自愛各驰騖。","羸瘠且如何，魄奪鍼灸屢。","擁滯僮僕慵，稽留篙師怒。","終當挂帆席，天意难告訴。","南爲祝融客，勉強親杖屨。","結託老人星，羅浮展衰步。"]', '诗', 'shi', '', NULL, '詠懷二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cb0132-c27d-4037-abb6-c76f576b866b', '送顧八分文學適洪吉州', '送顧八分文学適洪吉州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中郎石經後，八分蓋顦顇。","願侯運鑪錘，筆力破餘地。","昔在開元中，韓蔡同贔屭。","玄宗妙其書，是以數子至。","御札早流傳，揄揚非造次。","三人竝入直，恩澤各不二。","願於韓蔡內，辨眼工小字。","分日示諸王，鉤深法更祕。","文學與我遊，蕭疎外聲利。","追隨二十載，浩蕩長安醉。","高歌卿相宅，文翰飛省寺。","視我揚馬間，白首不相棄。","驊騮入窮巷，必脫黃金轡。","一論朋友難，遲暮敢失墜。","古來事反覆，相見橫涕泗。","嚮者玉珂人，誰是青雲器。","才盡傷形體，病渴污官位。","故舊獨依然，時危話顛躓。","我甘多病老，子負憂世志。","胡爲困衣食，顏色少稱遂。","遠作辛苦行，順從衆多意。","舟檝無根蔕，蛟鼉好爲祟。","況兼水賊繁，特戒風飆駛。","崩騰戎馬際，往往殺長吏。","子干東諸侯，勸勉防縱恣。","邦以民爲本，魚飢費香餌。","請哀瘡痍深，告訴皇華使。","使臣精所擇，進德知歷試。","惻隱誅求情，固應賢愚異。","列士惡苟得，俊傑思自致。","贈子猛虎行，出效載酸鼻。"]', '["中郎石經後，八分蓋顦顇。","願侯運鑪錘，笔力破餘地。","昔在开元中，韓蔡同贔屭。","玄宗妙其书，是以數子至。","御札早流傳，揄揚非造次。","三人竝入直，恩澤各不二。","願於韓蔡內，辨眼工小字。","分日示諸王，鉤深法更祕。","文学與我游，蕭疎外声利。","追隨二十載，浩蕩长安醉。","高歌卿相宅，文翰飞省寺。","視我揚马间，白首不相棄。","驊騮入窮巷，必脫黄金轡。","一論朋友难，遲暮敢失墜。","古来事反覆，相见橫涕泗。","嚮者玉珂人，誰是青云器。","才尽傷形體，病渴污官位。","故旧独依然，时危話顛躓。","我甘多病老，子負憂世志。","胡爲困衣食，顏色少稱遂。","远作辛苦行，順從衆多意。","舟檝無根蔕，蛟鼉好爲祟。","況兼水賊繁，特戒风飆駛。","崩腾戎马際，往往殺长吏。","子干东諸侯，勸勉防縱恣。","邦以民爲本，鱼飢費香餌。","請哀瘡痍深，告訴皇华使。","使臣精所擇，進德知歷試。","惻隐誅求情，固應賢愚異。","列士惡苟得，俊傑思自致。","贈子猛虎行，出效載酸鼻。"]', '诗', 'shi', '', NULL, '送顧八分文學適洪吉州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea2d30d-eb58-425b-8b47-97368777a411', '上水遣懷', '上水遣懷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我衰太平時，身病戎馬後。","蹭蹬多拙爲，安得不皓首。","驅馳四海內，童稚日餬口。","但遇新少年，少逢舊親友。","低顏下色地，故人知善誘。","後生血氣豪，舉動見老醜。","窮迫挫曩懷，常如中風走。","一紀出西蜀，於今向南斗。","孤舟亂春華，暮齒依蒲柳。","冥冥九疑葬，聖者骨亦朽。","蹉跎陶唐人，鞭撻日月久。","中間屈賈輩，讒毀竟自取。","鬱沒二悲魂，蕭條猶在否。","崷崒清湘石，逆行雜林藪。","篙工密逞巧，氣若酣杯酒。","歌謳互激遠，回斡明受授。","善知應觸類，各藉穎脫手。","古來經濟才，何事獨罕有。","蒼蒼衆色晚，熊挂玄蛇吼。","黃羆在樹顛，正爲羣虎守。","羸骸將何適，履險顏益厚。","庶與達者論，吞聲混瑕垢。"]', '["我衰太平时，身病戎马後。","蹭蹬多拙爲，安得不皓首。","驱驰四海內，童稚日餬口。","但遇新少年，少逢旧親友。","低顏下色地，故人知善誘。","後生血氣豪，舉动见老醜。","窮迫挫曩懷，常如中风走。","一紀出西蜀，於今向南斗。","孤舟亂春华，暮齒依蒲柳。","冥冥九疑葬，聖者骨亦朽。","蹉跎陶唐人，鞭撻日月久。","中间屈賈輩，讒毀竟自取。","鬱沒二悲魂，蕭條猶在否。","崷崒清湘石，逆行杂林藪。","篙工密逞巧，氣若酣杯酒。","歌謳互激远，回斡明受授。","善知應觸類，各藉穎脫手。","古来經濟才，何事独罕有。","蒼蒼衆色晚，熊挂玄蛇吼。","黄羆在樹顛，正爲羣虎守。","羸骸將何適，履險顏益厚。","庶與達者論，吞声混瑕垢。"]', '诗', 'shi', '', NULL, '上水遣懷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e957686-af9b-4a48-ac04-e6a7fa807617', '遣遇', '遣遇', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["磬折辭主人，開帆駕洪濤。","春水滿南國，朱崖雲日高。","舟子廢寢食，飄風爭所操。","我行匪利涉，謝爾從者勞。","石間采蕨女，鬻菜輸官曹。","丈夫死百役，暮返空邨號。","聞見事略同，刻剥及錐刀。","貴人豈不仁，視汝如莠蒿。","索錢多門戶，喪亂紛嗷嗷。","奈何黠吏徒，漁奪成逋逃。","自喜遂生理，花時甘緼袍。"]', '["磬折辞主人，开帆駕洪濤。","春水满南国，朱崖云日高。","舟子廢寢食，飄风爭所操。","我行匪利涉，謝爾從者勞。","石间采蕨女，鬻菜輸官曹。","丈夫死百役，暮返空邨號。","闻见事略同，刻剥及錐刀。","貴人豈不仁，視汝如莠蒿。","索錢多门戶，喪亂紛嗷嗷。","奈何黠吏徒，漁奪成逋逃。","自喜遂生理，花时甘緼袍。"]', '诗', 'shi', '', NULL, '遣遇 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9835b47-0c0b-4f62-be13-c063e47939b6', '解憂', '解憂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["減米散同舟，路難恩共濟。","向來雲濤盤，衆力亦不細。","呀坑瞥眼過，飛櫓本無蔕。","得失瞬息間，致遠宜恐泥。","百慮視安危，分明曩賢計。","茲理庶可廣，拳拳期勿替。"]', '["減米散同舟，路难恩共濟。","向来云濤盤，衆力亦不細。","呀坑瞥眼過，飞櫓本無蔕。","得失瞬息间，致远宜恐泥。","百慮視安危，分明曩賢計。","茲理庶可廣，拳拳期勿替。"]', '诗', 'shi', '', NULL, '解憂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd25eec-c677-4c60-a12c-784ae0fa932f', '宿鑒石浦', '宿鑒石浦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["早宿賓從勞，仲春江山麗。","飄風過無時，舟檝敢不繫。","回塘澹暮色，日沒衆星嘒。","缺月殘未生，青燈死分翳。","窮途多俊異，亂世少恩惠。","鄙夫亦放蕩，草草頻卒歲。","斯文憂患餘，聖哲垂彖繫。"]', '["早宿賓從勞，仲春江山丽。","飄风過無时，舟檝敢不繫。","回塘澹暮色，日沒衆星嘒。","缺月殘未生，青灯死分翳。","窮途多俊異，亂世少恩惠。","鄙夫亦放蕩，草草頻卒歲。","斯文憂患餘，聖哲垂彖繫。"]', '诗', 'shi', '', NULL, '宿鑒石浦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fae28d1-c350-40ce-8d22-eb8e3011b580', '早行', '早行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歌哭俱在曉，行邁有期程。","孤舟似昨日，聞見同一聲。","飛鳥數求食，潛魚亦獨驚。","前王作網罟，設法害生成。","碧藻非不茂，高帆終日征。","干戈未揖讓，崩迫開其情。"]', '["歌哭俱在晓，行邁有期程。","孤舟似昨日，闻见同一声。","飞鸟數求食，潛鱼亦独驚。","前王作網罟，設法害生成。","碧藻非不茂，高帆終日征。","干戈未揖讓，崩迫开其情。"]', '诗', 'shi', '', NULL, '早行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64edbb6-04bf-4e6d-bc04-8cd4f0e0df72', '過津口', '過津口', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南岳自茲近，湘流東逝深。","和風引桂楫，春日漲雲岑。","回首過津口，而多楓樹林。","白魚困密網，黃鳥喧嘉音。","物微限通塞，惻隱仁者心。","甕餘不盡酒，膝有無聲琴。","聖賢兩寂寞，眇眇獨開襟。"]', '["南岳自茲近，湘流东逝深。","和风引桂楫，春日漲云岑。","回首過津口，而多楓樹林。","白鱼困密網，黄鸟喧嘉音。","物微限通塞，惻隐仁者心。","甕餘不尽酒，膝有無声琴。","聖賢兩寂寞，眇眇独开襟。"]', '诗', 'shi', '', NULL, '過津口 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19d92ae8-fd5a-407d-b235-7cdca38e1ca5', '次空靈岸', '次空靈岸', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["沄沄逆素浪，落落展清眺。","幸有舟檝遲，得盡所歷妙。","空靈霞石峻，楓栝隱奔峭。","青春猶無私，白日亦偏照。","可使營吾居，終焉託長嘯。","毒瘴未足憂，兵戈滿邊徼。","嚮者留遺恨，恥爲達人誚。","迴帆凱賞延，佳處領其要。"]', '["沄沄逆素浪，落落展清眺。","幸有舟檝遲，得尽所歷妙。","空靈霞石峻，楓栝隐奔峭。","青春猶無私，白日亦偏照。","可使營吾居，終焉託长嘯。","毒瘴未足憂，兵戈满邊徼。","嚮者留遺恨，恥爲達人誚。","迴帆凱賞延，佳处領其要。"]', '诗', 'shi', '', NULL, '次空靈岸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7973452-0af7-431c-9b72-bd4b5e391ab0', '宿花石戍', '宿花石戍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["午辭空靈岑，夕得花石戍。","岸疏開闢水，木雜今古樹。","地蒸南風盛，春熱西日暮。","四序本平分，氣候何迴互。","茫茫天造間，理亂豈恒數。","繫舟盤藤輪，策杖古樵路。","罷人不在村，野圃泉自注。","柴扉雖蕪沒，農器尚牢固。","山東殘逆氣，吳楚守王度。","誰能扣君門，下令減征賦。"]', '["午辞空靈岑，夕得花石戍。","岸疏开闢水，木杂今古樹。","地蒸南风盛，春熱西日暮。","四序本平分，氣候何迴互。","茫茫天造间，理亂豈恒數。","繫舟盤藤輪，策杖古樵路。","罷人不在村，野圃泉自注。","柴扉雖蕪沒，農器尚牢固。","山东殘逆氣，吳楚守王度。","誰能扣君门，下令減征賦。"]', '诗', 'shi', '', NULL, '宿花石戍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1100cc25-0c98-41cd-ba29-9d042906fbc7', '早發', '早發', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有求常百慮，斯文亦吾病。","以茲朋故多，窮老驅馳幷。","早行篙師怠，席挂風不正。","昔人戒垂堂，今則奚奔命。","濤飜黑蛟躍，日山黃霧映。","煩促瘴豈侵，頹倚睡未醒。","僕夫問盥櫛，暮顏靦青鏡。","隨意簪葛巾，仰慙林花盛。","側聞夜來寇，幸喜囊中淨。","艱危作遠客，干請傷直性。","薇蕨餓首陽，粟馬資歷聘。","賤子欲適從，疑誤此二柄。"]', '["有求常百慮，斯文亦吾病。","以茲朋故多，窮老驱驰幷。","早行篙師怠，席挂风不正。","昔人戒垂堂，今則奚奔命。","濤飜黑蛟躍，日山黄霧映。","煩促瘴豈侵，頹倚睡未醒。","僕夫问盥櫛，暮顏靦青镜。","隨意簪葛巾，仰慙林花盛。","側闻夜来寇，幸喜囊中淨。","艱危作远客，干請傷直性。","薇蕨餓首陽，粟马資歷聘。","賤子欲適從，疑誤此二柄。"]', '诗', 'shi', '', NULL, '早發 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf50e425-add3-4619-9a08-19e391591cf7', '次晚洲', '次晚洲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["參錯雲石稠，坡陀風濤壯。","晚洲適知名，秀色固異狀。","櫂經垂猨把，身在度鳥上。","擺浪散帙妨，危沙折花當。","羈離暫愉悅，羸老反惆悵。","中原未解兵，吾得終疎放。"]', '["參錯云石稠，坡陀风濤壯。","晚洲適知名，秀色固異狀。","櫂經垂猨把，身在度鸟上。","擺浪散帙妨，危沙折花當。","羈離暫愉悅，羸老反惆悵。","中原未解兵，吾得終疎放。"]', '诗', 'shi', '', NULL, '次晚洲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e89b4c-2998-4cb7-8b96-1e2b7687007f', '望嶽', '望嶽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南嶽配朱鳥，秩禮自百王。","歘吸領地靈，鴻洞半炎方。","邦家用祀典，在德非馨香。","巡守何寂寥，有虞今則亡。","洎吾隘世網，行邁越瀟湘。","渴日絕壁出，漾舟清光旁。","祝融五峰尊，峰峰次低昴。","紫蓋獨不朝，爭長嶫相望。","恭聞魏夫人，羣仙夾翱翔。","有時五峰氣，散風如飛霜。","牽迫限修途，未暇杖崇岡。","歸來覬命駕，沐浴休玉堂。","三歎問府主，曷以贊我皇。","牲璧忍衰俗，神其思降祥。"]', '["南嶽配朱鸟，秩禮自百王。","歘吸領地靈，鴻洞半炎方。","邦家用祀典，在德非馨香。","巡守何寂寥，有虞今則亡。","洎吾隘世網，行邁越瀟湘。","渴日絕壁出，漾舟清光旁。","祝融五峰尊，峰峰次低昴。","紫蓋独不朝，爭长嶫相望。","恭闻魏夫人，羣仙夾翱翔。","有时五峰氣，散风如飞霜。","牽迫限修途，未暇杖崇岡。","归来覬命駕，沐浴休玉堂。","三歎问府主，曷以贊我皇。","牲璧忍衰俗，神其思降祥。"]', '诗', 'shi', '', NULL, '望嶽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01967b0-571b-4800-90fb-b25872b5651d', '湘江宴餞裴二端公赴道州', '湘江宴餞裴二端公赴道州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白日照舟師，朱旗散廣川。","羣公餞南伯，肅肅秩初筵。","鄙人奉末眷，佩服自早年。","義均骨肉地，懷抱罄所宣。","盛名富事業，無取媿高賢。","不以喪亂嬰，保愛金石堅。","計拙百僚下，氣蘇君子前。","會合苦不久，哀樂本相纏。","交遊颯向盡，宿昔浩茫然。","促觴激百慮，掩抑淚潺湲。","熱雲集曛黑，缺月未生天。","白團爲我破，華燭蟠長煙。","鴰鶡催明星，解袂從此旋。","上請減兵甲，下請安井田。","永念病渴老，附書遠山巔。"]', '["白日照舟師，朱旗散廣川。","羣公餞南伯，肅肅秩初筵。","鄙人奉末眷，佩服自早年。","義均骨肉地，懷抱罄所宣。","盛名富事業，無取媿高賢。","不以喪亂嬰，保愛金石堅。","計拙百僚下，氣蘇君子前。","會合苦不久，哀乐本相纏。","交游颯向尽，宿昔浩茫然。","促觴激百慮，掩抑泪潺湲。","熱云集曛黑，缺月未生天。","白團爲我破，华燭蟠长煙。","鴰鶡催明星，解袂從此旋。","上請減兵甲，下請安井田。","永念病渴老，附书远山巔。"]', '诗', 'shi', '', NULL, '湘江宴餞裴二端公赴道州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7404b1-b2f2-4924-b187-b47aa50039d7', '清明', '清明', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["著處繁花務是日，長沙千人萬人出。","渡頭翠柳豔明眉，爭道朱蹄驕齧膝。","此都好遊湘西寺，諸將亦自軍中至。","馬援征行在眼前，葛強親近同心事。","金鐙下山紅粉晚，牙檣捩柁青樓遠。","古時喪亂皆可知，人世悲歡暫相遣。","弟姪雖存不得書，干戈未息苦離居。","逢迎少壯非吾道，況乃今朝更祓除。"]', '["著处繁花務是日，长沙千人万人出。","渡头翠柳豔明眉，爭道朱蹄驕齧膝。","此都好游湘西寺，諸將亦自軍中至。","马援征行在眼前，葛強親近同心事。","金鐙下山紅粉晚，牙檣捩柁青楼远。","古时喪亂皆可知，人世悲歡暫相遣。","弟姪雖存不得书，干戈未息苦離居。","逢迎少壯非吾道，況乃今朝更祓除。"]', '诗', 'shi', '', NULL, '清明 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c6a206-1a90-452e-a032-19a7665bceba', '風雨看舟前落花戲爲新句', '风雨看舟前落花戲爲新句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江上人家桃樹枝，春寒細雨出疎籬。","影遭碧水潛勾引，風妒紅花却倒吹。","吹花困癲傍舟檝，水光風力俱相怯。","赤憎輕薄遮入懷，珍重分明不來接。","濕久飛遲半日高，縈沙惹草細於毛。","蜜蜂蝴蝶生情性，偷眼蜻蜓避百勞。"]', '["江上人家桃樹枝，春寒細雨出疎籬。","影遭碧水潛勾引，风妒紅花却倒吹。","吹花困癲傍舟檝，水光风力俱相怯。","赤憎轻薄遮入懷，珍重分明不来接。","濕久飞遲半日高，縈沙惹草細於毛。","蜜蜂蝴蝶生情性，偷眼蜻蜓避百勞。"]', '诗', 'shi', '', NULL, '風雨看舟前落花戲爲新句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d893768c-c581-4169-8d36-636e552ec09e', '岳麓山道林二寺行', '岳麓山道林二寺行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["玉泉之南麓山殊，道林林壑爭盤紆。","寺門高開洞庭野，殿脚插入赤沙湖。","五月寒風冷佛骨，六時天樂朝香爐。","地靈步步雪山草，僧寶人人滄海珠。","墖劫宮牆壯麗敵，香廚松道清涼俱。","連花交響共命鳥，金牓雙迴三足烏。","方丈涉海費時節，懸圃尋河知有無。","暮年且喜經行近，春日兼蒙暄暖扶。","飄然斑白身奚適，傍此煙霞茅可誅。","桃源人家易制度，橘洲田土仍膏腴。","潭府邑中甚淳古，太守庭內不喧呼。","昔遭衰世皆晦迹，今幸樂國養微軀。","依止老宿亦未晚，富貴功名焉足圖。","久爲野客尋幽慣，細學何顒免興孤。","一重一掩吾肺腑，山鳥山花吾友于。","宋公放逐曾題壁，物色分留與老夫。"]', '["玉泉之南麓山殊，道林林壑爭盤紆。","寺门高开洞庭野，殿脚插入赤沙湖。","五月寒风冷佛骨，六时天乐朝香爐。","地靈步步雪山草，僧寶人人滄海珠。","墖劫宮牆壯丽敵，香廚松道清涼俱。","連花交响共命鸟，金牓雙迴三足烏。","方丈涉海費时節，懸圃尋河知有無。","暮年且喜經行近，春日兼蒙暄暖扶。","飄然斑白身奚適，傍此煙霞茅可誅。","桃源人家易制度，橘洲田土仍膏腴。","潭府邑中甚淳古，太守庭內不喧呼。","昔遭衰世皆晦迹，今幸乐国養微軀。","依止老宿亦未晚，富貴功名焉足圖。","久爲野客尋幽慣，細学何顒免兴孤。","一重一掩吾肺腑，山鸟山花吾友于。","宋公放逐曾題壁，物色分留與老夫。"]', '诗', 'shi', '', NULL, '岳麓山道林二寺行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6a1b8f-22a0-4450-81d3-6baf77533e5d', '奉送魏六丈佑少府之交廣', '奉送魏六丈佑少府之交廣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賢豪贊經綸，功成空名垂。","子孫不振耀，歷代皆有之。","鄭公四葉孫，長大常苦飢。","衆中見毛骨，猶是麒麟兒。","磊落貞觀事，致君樸直詞。","家聲蓋六合，行色何其微。","遇我蒼吾陰，忽驚會面稀。","議論有餘地，公侯來未遲。","虛思黃金貴，自笑青雲期。","長卿久病渴，武帝元同時。","季子黑貂敝，得無妻嫂欺。","尚爲諸侯客，獨屈州縣卑。","南游炎海甸，浩蕩從此辭。","窮途仗神道，世亂輕土宜。","解帆歲云暮，可與春風歸。","出入朱門家，華屋刻蛟螭。","玉食亞王者，樂張游子悲。","侍婢豔傾城，綃綺輕霧霏。","掌中琥珀鍾，行酒雙逶迤。","新歡繼明燭，梁棟星辰飛。","兩情顧盼合，珠碧贈于斯。","上貴見肝膽，下貴不相疑。","心事披寫間，氣酣達所爲。","錯揮鐵如意，莫避珊瑚枝。","始兼逸邁興，終慎賓主儀。","戎馬闇天宇，嗚呼生別離。"]', '["賢豪贊經綸，功成空名垂。","子孫不振耀，歷代皆有之。","鄭公四葉孫，长大常苦飢。","衆中见毛骨，猶是麒麟兒。","磊落貞观事，致君樸直词。","家声蓋六合，行色何其微。","遇我蒼吾陰，忽驚會面稀。","議論有餘地，公侯来未遲。","虛思黄金貴，自笑青云期。","长卿久病渴，武帝元同时。","季子黑貂敝，得無妻嫂欺。","尚爲諸侯客，独屈州縣卑。","南游炎海甸，浩蕩從此辞。","窮途仗神道，世亂轻土宜。","解帆歲云暮，可與春风归。","出入朱门家，华屋刻蛟螭。","玉食亞王者，乐張游子悲。","侍婢豔傾城，綃綺轻霧霏。","掌中琥珀鍾，行酒雙逶迤。","新歡繼明燭，梁棟星辰飞。","兩情顧盼合，珠碧贈于斯。","上貴见肝膽，下貴不相疑。","心事披寫间，氣酣達所爲。","錯揮鐵如意，莫避珊瑚枝。","始兼逸邁兴，終慎賓主儀。","戎马闇天宇，嗚呼生別離。"]', '诗', 'shi', '', NULL, '奉送魏六丈佑少府之交廣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4af6fc2-0752-4841-88c1-30a208a020a1', '別張十三建封', '別張十三建封', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嘗讀唐實錄，國家草昧初。","劉裴建首義，龍見尚躊躇。","秦王撥亂姿，一劒總兵符。","汾晉爲豐沛，暴隋竟滌除。","宗臣則廟食，後祀何疎蕪。","彭城英雄種，宜膺將相圖。","爾惟外曾孫，倜儻汗血駒。","眼中萬少年，用意盡崎嶇。","相逢長沙亭，乍問緒業餘。","乃吾故人子，童丱聊居諸。","揮手灑衰淚，仰看八尺軀。","內外名家流，風神蕩江湖。","范雲堪晚友，嵇紹自不孤。","擇材征南幕，湖落回鯨魚。","載感賈生慟，復聞樂毅書。","主憂急盜賊，師老荒京都。","舊丘豈稅駕，大廈傾宜扶。","君臣各有分，管葛本時須。","雖當霰雪嚴，未覺栝柏枯。","高義在雲臺，嘶鳴望天衢。","羽人埽碧海，功業竟何如。"]', '["嘗读唐實錄，国家草昧初。","劉裴建首義，龙见尚躊躇。","秦王撥亂姿，一劒總兵符。","汾晉爲豐沛，暴隋竟滌除。","宗臣則廟食，後祀何疎蕪。","彭城英雄種，宜膺將相圖。","爾惟外曾孫，倜儻汗血駒。","眼中万少年，用意尽崎嶇。","相逢长沙亭，乍问緒業餘。","乃吾故人子，童丱聊居諸。","揮手灑衰泪，仰看八尺軀。","內外名家流，风神蕩江湖。","范云堪晚友，嵇紹自不孤。","擇材征南幕，湖落回鯨鱼。","載感賈生慟，复闻乐毅书。","主憂急盜賊，師老荒京都。","旧丘豈稅駕，大廈傾宜扶。","君臣各有分，管葛本时須。","雖當霰雪嚴，未覺栝柏枯。","高義在云台，嘶鳴望天衢。","羽人埽碧海，功業竟何如。"]', '诗', 'shi', '', NULL, '別張十三建封 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b942cdf-a8ec-4bf9-8c1e-bba47e0c4726', '暮秋枉裴道州手札率爾遣興寄近呈蘇渙侍御', '暮秋枉裴道州手札率爾遣兴寄近呈蘇渙侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久客多枉友朋書，素書一月凡一束。","虛名但蒙寒溫問，泛愛不救溝壑辱。","齒落未是無心人，舌存恥作窮途哭。","道州手札適復至，紙長要自三過讀。","盈把那須滄海珠，入懷本倚崑山玉。","撥棄潭州百斛酒，蕪沒瀟岸千株菊。","使我晝立煩兒孫，令我夜坐費燈燭。","憶子初尉永嘉去，紅顏白面花映肉。","軍符侯印取豈遲，紫燕騄耳行甚速。","聖朝尚飛戰鬬塵，濟世宜引英俊人。","黎元愁痛會蘇息，夷狄跋扈徒逡巡。","授鉞築壇聞意旨，頹綱漏網期彌綸。","郭欽上書見大計，劉毅答詔驚羣臣。","他日更僕語不淺，明公論兵氣益振。","傾壺簫管黑白髮，儛劒霜雪吹青春。","宴筵曾語蘇季子，後來傑出雲孫比。","茅齋定王城郭門，藥物楚老漁商市。","市北肩輿每聯袂，郭南抱甕亦隱几。","無數將軍西第成，早作丞相東山起。","鳥雀苦肥秋粟菽，蛟龍欲蟄寒沙水。","天下鼓角何時休，陣前部曲終日死。","附書與裴因示蘇，此生已媿須人扶。","致君堯舜付公等，早據要路思捐軀。"]', '["久客多枉友朋书，素书一月凡一束。","虛名但蒙寒溫问，泛愛不救溝壑辱。","齒落未是無心人，舌存恥作窮途哭。","道州手札適复至，紙长要自三過读。","盈把那須滄海珠，入懷本倚崑山玉。","撥棄潭州百斛酒，蕪沒瀟岸千株菊。","使我晝立煩兒孫，令我夜坐費灯燭。","憶子初尉永嘉去，紅顏白面花映肉。","軍符侯印取豈遲，紫燕騄耳行甚速。","聖朝尚飞戰鬬塵，濟世宜引英俊人。","黎元愁痛會蘇息，夷狄跋扈徒逡巡。","授鉞築壇闻意旨，頹綱漏網期彌綸。","郭欽上书见大計，劉毅答詔驚羣臣。","他日更僕語不淺，明公論兵氣益振。","傾壺簫管黑白髮，儛劒霜雪吹青春。","宴筵曾語蘇季子，後来傑出云孫比。","茅斋定王城郭门，藥物楚老漁商市。","市北肩輿每聯袂，郭南抱甕亦隐几。","無數將軍西第成，早作丞相东山起。","鸟雀苦肥秋粟菽，蛟龙欲蟄寒沙水。","天下鼓角何时休，陣前部曲終日死。","附书與裴因示蘇，此生已媿須人扶。","致君堯舜付公等，早據要路思捐軀。"]', '诗', 'shi', '', NULL, '暮秋枉裴道州手札率爾遣興寄近呈蘇渙侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6176b224-9362-4973-a649-2f3de578e3ff', '奉贈李八丈判官', '奉贈李八丈判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我丈時英特，宗枝神堯後。","珊瑚市則無，騄驥人得有。","早年見標格，秀氣衝星斗。","事業富清機，官曹正獨守。","頃來樹嘉政，皆已傳衆口。","艱難體貴安，冗長吾敢取。","區區猶歷試，炯炯更持久。","討論實解頤，操割紛應手。","篋書積諷諫，宮闕限奔走。","入幕未展材，秉鈞孰爲偶。","所親問淹泊，泛愛惜衰朽。","垂白亂南翁，委身希北叟。","真成窮轍鮒，或似喪家狗。","秋枯洞庭石，風颯長沙柳。","高興激荆衡，知音爲回首。"]', '["我丈时英特，宗枝神堯後。","珊瑚市則無，騄驥人得有。","早年见標格，秀氣衝星斗。","事業富清機，官曹正独守。","頃来樹嘉政，皆已傳衆口。","艱难體貴安，冗长吾敢取。","區區猶歷試，炯炯更持久。","討論實解頤，操割紛應手。","篋书積諷諫，宮闕限奔走。","入幕未展材，秉鈞孰爲偶。","所親问淹泊，泛愛惜衰朽。","垂白亂南翁，委身希北叟。","真成窮轍鮒，或似喪家狗。","秋枯洞庭石，风颯长沙柳。","高兴激荆衡，知音爲回首。"]', '诗', 'shi', '', NULL, '奉贈李八丈判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a285196-1fe5-4d28-9ba1-dd75e9ce0af2', '歲晏行', '歲晏行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歲云暮矣多北風，瀟湘洞庭白雪中。","漁父天寒網罟凍，莫徭射雁鳴桑弓。","去年米貴闕軍食，今年米賤大傷農。","高馬達官厭酒肉，此輩杼軸茅茨空。","楚人重魚不重鳥，汝休枉殺南飛鴻。","況聞處處鬻男女，割慈忍愛還租庸。","往日用錢捉私鑄，今許鉛錫和青銅。","刻泥爲之最易得，好惡不合長相蒙。","萬國城頭吹畫角，此曲哀怨何時終。"]', '["歲云暮矣多北风，瀟湘洞庭白雪中。","漁父天寒網罟凍，莫徭射雁鳴桑弓。","去年米貴闕軍食，今年米賤大傷農。","高马達官厭酒肉，此輩杼軸茅茨空。","楚人重鱼不重鸟，汝休枉殺南飞鴻。","況闻处处鬻男女，割慈忍愛還租庸。","往日用錢捉私鑄，今許鉛錫和青銅。","刻泥爲之最易得，好惡不合长相蒙。","万国城头吹畫角，此曲哀怨何时終。"]', '诗', 'shi', '', NULL, '歲晏行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3057f1b2-f2c5-482d-a9c8-b4d1a02125e9', '追酬故高蜀州人日見寄', '追酬故高蜀州人日见寄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自蒙蜀州人日作，不意清詩久零落。","今晨散帙眼忽開，迸淚幽吟事如昨。","嗚呼壯士多慷慨，合沓高名動寥廊。","歎我悽悽求友篇，感時鬱鬱匡君略。","錦里春光空爛熳，瑤墀侍臣已冥莫。","瀟湘水國傍黿鼉，鄠杜秋天失鵰鶚。","東西南北更誰論，白首扁舟病獨存。","遙拱北辰纏寇盜，欲傾東海洗乾坤。","邊塞西蕃最充斥，衣冠南渡多崩奔。","鼓瑟至今悲帝子，曳裾何處覓王門。","文章曹植波瀾闊，服食劉安德業尊。","長笛誰能亂愁思，昭州詞翰與招魂。"]', '["自蒙蜀州人日作，不意清诗久零落。","今晨散帙眼忽开，迸泪幽吟事如昨。","嗚呼壯士多慷慨，合沓高名动寥廊。","歎我悽悽求友篇，感时鬱鬱匡君略。","錦里春光空爛熳，瑤墀侍臣已冥莫。","瀟湘水国傍黿鼉，鄠杜秋天失鵰鶚。","东西南北更誰論，白首扁舟病独存。","遙拱北辰纏寇盜，欲傾东海洗乾坤。","邊塞西蕃最充斥，衣冠南渡多崩奔。","鼓瑟至今悲帝子，曳裾何处覓王门。","文章曹植波瀾闊，服食劉安德業尊。","长笛誰能亂愁思，昭州词翰與招魂。"]', '诗', 'shi', '', NULL, '追酬故高蜀州人日見寄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e263d29c-c7b0-4cd9-a1ef-d7426a8846c8', '蘇大侍御訪江浦賦八韻記異', '蘇大侍御訪江浦賦八韻記異', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["龐公不浪出，蘇氏今有之。","再聞誦新作，突過黃初詩。","乾坤幾反覆，揚馬宣同時。","今晨清鏡中，勝食齋房芝。","余髮喜却變，白間生黑絲。","昨夜舟火滅，湘娥簾外悲。","百靈未敢散，風破寒江遲。"]', '["龐公不浪出，蘇氏今有之。","再闻誦新作，突過黄初诗。","乾坤幾反覆，揚马宣同时。","今晨清镜中，勝食斋房芝。","余髮喜却变，白间生黑絲。","昨夜舟火滅，湘娥簾外悲。","百靈未敢散，风破寒江遲。"]', '诗', 'shi', '', NULL, '蘇大侍御訪江浦賦八韻記異 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704cf3c8-46c0-4e9f-b015-7e386bd0eff2', '題衡山縣文宣王廟新學堂呈陸宰', '題衡山縣文宣王廟新学堂呈陸宰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["旄頭彗紫微，無復俎豆事。","金甲相排蕩，青衿一顦顇。","嗚呼已十年，儒服弊於地。","征夫不遑息，學者淪素志。","我行洞庭野，歘得文翁肆。","侁侁胄子行，若舞風雩至。","周室宜中興，孔門未應棄。","是以資雅才，渙然立新意。","衡山雖小邑，首唱恢大義。","因見縣尹心，根源舊宮閟。","講堂非曩搆，大屋加塗墍。","下可容百人，牆隅亦深邃。","何必三千徒，始壓戎馬氣。","林木在庭戶，密幹疊蒼翠。","有井朱夏時，轆轤凍階戺。","耳聞讀書聲，殺伐災髣髴。","故國延歸望，衰顏減愁思。","南紀改波瀾，西河共風味。","采詩倦跋涉，載筆尚可記。","高歌激宇宙，凡百慎失墜。"]', '["旄头彗紫微，無复俎豆事。","金甲相排蕩，青衿一顦顇。","嗚呼已十年，儒服弊於地。","征夫不遑息，学者淪素志。","我行洞庭野，歘得文翁肆。","侁侁胄子行，若舞风雩至。","周室宜中兴，孔门未應棄。","是以資雅才，渙然立新意。","衡山雖小邑，首唱恢大義。","因见縣尹心，根源旧宮閟。","講堂非曩搆，大屋加塗墍。","下可容百人，牆隅亦深邃。","何必三千徒，始壓戎马氣。","林木在庭戶，密幹叠蒼翠。","有井朱夏时，轆轤凍階戺。","耳闻读书声，殺伐災髣髴。","故国延归望，衰顏減愁思。","南紀改波瀾，西河共风味。","采诗倦跋涉，載笔尚可記。","高歌激宇宙，凡百慎失墜。"]', '诗', 'shi', '', NULL, '題衡山縣文宣王廟新學堂呈陸宰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0f6fa4-0e8b-449e-bb5d-0ab704403d37', '入衡州', '入衡州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兵革自久遠，興衰看帝王。","漢儀甚照耀，胡馬何猖狂。","老將一失律，清邊生戰場。","君臣忍瑕垢，河岳空金湯。","重鎮如割據，輕權絕紀綱。","軍州體不一，寬猛性所將。","嗟彼苦節士，素于圓鑿方。","寡妻從爲郡，兀者安堵牆。","凋弊惜邦本，哀矜存事常。","旌麾非其任，府庫實過防。","恕己獨在此，多憂增內傷。","偏裨限酒肉，卒伍單衣裳。","元惡迷是似，聚謀洩康莊。","竟流帳下血，大降湖南殃。","烈火發中夜，高煙焦上蒼。","至今分粟帛，殺氣吹沅湘。","福善理顛倒，明徵天莽茫。","銷魂避飛鏑，累足穿豺狼。","隱忍枳棘刺，遷延胝趼瘡。","遠歸兒侍側，猶乳女在旁。","久客幸脫免，暮年慙激昴。","蕭條向水陸，汩沒隨魚商。","報主身已老，入朝病見妨。","悠悠委薄俗，鬱鬱回剛腸。","參錯走洲渚，舂容轉林篁。","片帆左郴岸，通郭前衡陽。","華表雲鳥埤，名園花草香。","旗亭壯邑屋，烽櫓蟠城隍。","中有古刺史，盛才冠巖廓。","扶顛待柱石，獨坐飛風霜。","昨者間瓊樹，高談隨羽觴。","無論再繾綣，己是安蒼黃。","劇孟七國畏，馬卿四賦良。","門闌蘇生在，勇銳白起強。","問罪富形勢，凱歌懸否臧。","氛埃期必埽，蚊蚋焉能當。","橘井舊地宅，仙山引舟航。","此行厭暑雨，厥土聞清涼。","諸舅剖符近，開緘書札光。","頻繁命屢及，磊落字百行。","江總外家養，謝安乘興長。","下流匪珠玉，擇木羞鸞皇。","我師嵇叔夜，世賢張子房。","柴荆寄樂土，鵬路觀翱翔。"]', '["兵革自久远，兴衰看帝王。","漢儀甚照耀，胡马何猖狂。","老將一失律，清邊生戰場。","君臣忍瑕垢，河岳空金湯。","重鎮如割據，轻權絕紀綱。","軍州體不一，寬猛性所將。","嗟彼苦節士，素于圓鑿方。","寡妻從爲郡，兀者安堵牆。","凋弊惜邦本，哀矜存事常。","旌麾非其任，府庫實過防。","恕己独在此，多憂增內傷。","偏裨限酒肉，卒伍單衣裳。","元惡迷是似，聚謀洩康莊。","竟流帳下血，大降湖南殃。","烈火發中夜，高煙焦上蒼。","至今分粟帛，殺氣吹沅湘。","福善理顛倒，明徵天莽茫。","銷魂避飞鏑，累足穿豺狼。","隐忍枳棘刺，遷延胝趼瘡。","远归兒侍側，猶乳女在旁。","久客幸脫免，暮年慙激昴。","蕭條向水陸，汩沒隨鱼商。","報主身已老，入朝病见妨。","悠悠委薄俗，鬱鬱回剛腸。","參錯走洲渚，舂容轉林篁。","片帆左郴岸，通郭前衡陽。","华表云鸟埤，名园花草香。","旗亭壯邑屋，烽櫓蟠城隍。","中有古刺史，盛才冠巖廓。","扶顛待柱石，独坐飞风霜。","昨者间瓊樹，高談隨羽觴。","無論再繾綣，己是安蒼黄。","劇孟七国畏，马卿四賦良。","门闌蘇生在，勇銳白起強。","问罪富形勢，凱歌懸否臧。","氛埃期必埽，蚊蚋焉能當。","橘井旧地宅，仙山引舟航。","此行厭暑雨，厥土闻清涼。","諸舅剖符近，开緘书札光。","頻繁命屢及，磊落字百行。","江總外家養，謝安乘兴长。","下流匪珠玉，擇木羞鸾皇。","我師嵇叔夜，世賢張子房。","柴荆寄乐土，鵬路观翱翔。"]', '诗', 'shi', '', NULL, '入衡州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95fc5a3-4109-4871-8615-5d71f248eace', '舟中苦熱遣懷奉呈[陽]中丞通簡臺省諸公', '舟中苦熱遣懷奉呈[陽]中丞通簡台省諸公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["媿爲湖外客，看此戎馬亂。","中夜混黎甿，脫身亦奔竄。","平生方寸心，反掌帳下難。","嗚呼殺賢良，不叱白刃散。","吾非丈夫特，沒齒埋冰炭。","恥以風病辭，胡然泊湘岸。","入舟雖苦熱，垢膩可溉灌。","痛彼道邊人，形骸改昏旦。","中丞連帥職，封內權得按。","身當問罪先，縣實諸侯半。","士卒既輯睦，啓行促精悍。","似聞上游兵，稍逼長沙館。","鄰好彼克修，天機自明斷。","南圖卷雲水，北拱戴霄漢。","美名光史臣，長策何壯觀。","驅馳數公子，咸願同伐叛。","聲節衰有餘，夫何激衰懦。","偏裨表三上，鹵莽同一貫。","始謀誰其間，回首增憤惋。","宗英李端公，守職甚昭煥。","變通迫脅地，謀畫焉得算。","王室不肯微，凶徒略無憚。","此流須卒斬，神器資強幹。","扣寂豁煩襟，皇天照嗟歎。"]', '["媿爲湖外客，看此戎马亂。","中夜混黎甿，脫身亦奔竄。","平生方寸心，反掌帳下难。","嗚呼殺賢良，不叱白刃散。","吾非丈夫特，沒齒埋冰炭。","恥以风病辞，胡然泊湘岸。","入舟雖苦熱，垢膩可溉灌。","痛彼道邊人，形骸改昏旦。","中丞連帥職，封內權得按。","身當问罪先，縣實諸侯半。","士卒既輯睦，啓行促精悍。","似闻上游兵，稍逼长沙館。","鄰好彼克修，天機自明斷。","南圖卷云水，北拱戴霄漢。","美名光史臣，长策何壯观。","驱驰數公子，咸願同伐叛。","声節衰有餘，夫何激衰懦。","偏裨表三上，鹵莽同一貫。","始謀誰其间，回首增憤惋。","宗英李端公，守職甚昭煥。","变通迫脅地，謀畫焉得算。","王室不肯微，凶徒略無憚。","此流須卒斬，神器資強幹。","扣寂豁煩襟，皇天照嗟歎。"]', '诗', 'shi', '', NULL, '舟中苦熱遣懷奉呈[陽]中丞通簡臺省諸公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d64eae7b-aed2-4cad-b8dc-26f8f7dca88d', '聶耒陽以僕阻水書致酒肉療飢荒江詩得代懷興盡本韻至縣呈聶令陸路去方田驛四十里舟行一日時屬江漲泊於方田', '聶耒陽以僕阻水书致酒肉療飢荒江诗得代懷兴尽本韻至縣呈聶令陸路去方田驛四十里舟行一日时屬江漲泊於方田', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["耒陽馳尺素，見訪荒江眇。","義士烈女家，風流吾賢紹。","昨見狄相孫，許公人倫表。","前期翰林後，屈跡縣邑小。","知我礙湍濤，半旬獲浩溔。","麾下殺元戎，湖邊有飛旐。","孤舟增鬱鬱，僻路殊悄悄。","側驚猿猱捷，仰羨鸛鶴矯。","禮過宰肥羊，愁當置清醥。","人非西喻蜀，興在北坑趙。","方行郴岸靜，未話長沙擾。","崔師乞已至，澧卒用矜少。","問罪消息真，開顏憩亭沼。"]', '["耒陽驰尺素，见訪荒江眇。","義士烈女家，风流吾賢紹。","昨见狄相孫，許公人倫表。","前期翰林後，屈跡縣邑小。","知我礙湍濤，半旬獲浩溔。","麾下殺元戎，湖邊有飞旐。","孤舟增鬱鬱，僻路殊悄悄。","側驚猿猱捷，仰羨鸛鹤矯。","禮過宰肥羊，愁當置清醥。","人非西喻蜀，兴在北坑趙。","方行郴岸静，未話长沙擾。","崔師乞已至，澧卒用矜少。","问罪消息真，开顏憩亭沼。"]', '诗', 'shi', '', NULL, '聶耒陽以僕阻水書致酒肉療飢荒江詩得代懷興盡本韻至縣呈聶令陸路去方田驛四十里舟行一日時屬江漲泊於方田 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883fcd05-a7b4-40f8-8cbe-5d93d4fad76c', '冬日洛城北謁玄元皇帝廟', '冬日洛城北謁玄元皇帝廟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["配極玄都閟，憑虛禁禦長。","守祧嚴具禮，掌節鎮非常。","碧瓦初寒外，金莖一氣旁。","山河扶繡戶，日月近雕梁。","仙李盤根大，猗蘭奕葉光。","世家遺舊史，道德付今王。","畫手看前輩，吳生遠擅場。","森羅移地軸，妙絕動宮牆。","五聖聯龍衮，千官列雁行。","冕旒俱秀發，旌斾盡飛揚。","翠柏深留景，紅棃迥得霜。","風箏吹玉柱，露井凍銀牀。","身退卑周室，經傳拱漢皇。","谷神如不死，養拙更何鄉。"]', '["配極玄都閟，憑虛禁禦长。","守祧嚴具禮，掌節鎮非常。","碧瓦初寒外，金莖一氣旁。","山河扶繡戶，日月近雕梁。","仙李盤根大，猗蘭奕葉光。","世家遺旧史，道德付今王。","畫手看前輩，吳生远擅場。","森羅移地軸，妙絕动宮牆。","五聖聯龙衮，千官列雁行。","冕旒俱秀發，旌斾尽飞揚。","翠柏深留景，紅棃迥得霜。","风箏吹玉柱，露井凍銀牀。","身退卑周室，經傳拱漢皇。","谷神如不死，養拙更何乡。"]', '诗', 'shi', '', NULL, '冬日洛城北謁玄元皇帝廟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3698389-b134-4532-a9d1-f260824ab33a', '贈韋左丞丈', '贈韋左丞丈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["左轄頻虛位，今年得舊儒。","相門韋氏在，經術漢臣須。","時議歸前烈，天倫恨莫俱。","鴒原荒宿草，鳳沼接亨衢。","有客雖安命，衰容豈壯夫。","家人憂几杖，甲子混泥途。","不謂矜餘力，還來謁大巫。","歲寒仍顧遇，日暮且踟躕。","老驥思千里，飢鷹待一呼。","君能微感激，亦足慰榛蕪。"]', '["左轄頻虛位，今年得旧儒。","相门韋氏在，經術漢臣須。","时議归前烈，天倫恨莫俱。","鴒原荒宿草，鳳沼接亨衢。","有客雖安命，衰容豈壯夫。","家人憂几杖，甲子混泥途。","不謂矜餘力，還来謁大巫。","歲寒仍顧遇，日暮且踟躕。","老驥思千里，飢鷹待一呼。","君能微感激，亦足慰榛蕪。"]', '诗', 'shi', '', NULL, '贈韋左丞丈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc75da9-c2b9-44c9-afd3-03d6d36f8166', '投贈哥舒開府二十韻', '投贈哥舒开府二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今代麒麟閣，何人第一功。","君王自神武，駕馭必英雄。","開府當朝傑，論兵邁古風。","先鋒百勝在，略地兩隅空。","青海無傳箭，天山早挂弓。","廉頗仍走敵，魏絳已和戎。","每惜河湟棄，新兼節制通。","智謀垂睿想，出入冠諸公。","日月低秦樹，乾坤繞漢宮。","胡人愁逐北，宛馬又從東。","受命邊沙遠，歸來御席同。","軒墀曾寵鶴，畋獵舊非熊。","茅土加名數，山河誓始終。","策行遺戰伐，契合動昭融。","勳業青冥上，交親氣概中。","未爲珠履客，已見白頭翁。","壯節初題柱，生涯獨轉蓬。","幾年春草歇，今日暮途窮。","軍事留孫楚，行間識呂蒙。","防身一長劒，將欲倚崆峒。"]', '["今代麒麟閣，何人第一功。","君王自神武，駕馭必英雄。","开府當朝傑，論兵邁古风。","先鋒百勝在，略地兩隅空。","青海無傳箭，天山早挂弓。","廉頗仍走敵，魏絳已和戎。","每惜河湟棄，新兼節制通。","智謀垂睿想，出入冠諸公。","日月低秦樹，乾坤繞漢宮。","胡人愁逐北，宛马又從东。","受命邊沙远，归来御席同。","軒墀曾寵鹤，畋獵旧非熊。","茅土加名數，山河誓始終。","策行遺戰伐，契合动昭融。","勳業青冥上，交親氣概中。","未爲珠履客，已见白头翁。","壯節初題柱，生涯独轉蓬。","幾年春草歇，今日暮途窮。","軍事留孫楚，行间識呂蒙。","防身一长劒，將欲倚崆峒。"]', '诗', 'shi', '', NULL, '投贈哥舒開府二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41815024-acd3-414d-9520-a00f0ceb3edd', '上韋左相二十韻', '上韋左相二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鳳曆軒轅紀，龍飛四十春。","八荒開壽域，一氣轉洪鈞。","霖雨思賢佐，丹青憶老臣。","應圖求駿馬，驚代得麒麟。","沙汰江河濁，調和鼎鼐新。","韋賢初相漢，范叔已歸秦。","盛業今如此，傳經固絕倫。","豫樟深出地，滄海闊無津。","北斗司喉舌，東方領搢紳。","持衡留藻鑑，聽履上星辰。","獨步才超古，餘波德照鄰。","聰明過管輅，尺牘倒陳遵。","豈是池中物，由來席上珍。","廟堂知至理，風俗盡還淳。","才傑俱登用，愚蒙但隱淪。","長卿多病久，子夏索居頻。","回首驅流俗，生涯似衆人。","巫咸不可問，鄒魯莫容身。","感激時將晚，蒼茫興有神。","爲公歌此曲，涕淚在衣巾。"]', '["鳳曆軒轅紀，龙飞四十春。","八荒开壽域，一氣轉洪鈞。","霖雨思賢佐，丹青憶老臣。","應圖求駿马，驚代得麒麟。","沙汰江河濁，調和鼎鼐新。","韋賢初相漢，范叔已归秦。","盛業今如此，傳經固絕倫。","豫樟深出地，滄海闊無津。","北斗司喉舌，东方領搢紳。","持衡留藻鑑，听履上星辰。","独步才超古，餘波德照鄰。","聰明過管輅，尺牘倒陳遵。","豈是池中物，由来席上珍。","廟堂知至理，风俗尽還淳。","才傑俱登用，愚蒙但隐淪。","长卿多病久，子夏索居頻。","回首驱流俗，生涯似衆人。","巫咸不可问，鄒魯莫容身。","感激时將晚，蒼茫兴有神。","爲公歌此曲，涕泪在衣巾。"]', '诗', 'shi', '', NULL, '上韋左相二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6d843e-5cf3-4ecb-ab77-d69c7f653445', '奉贈太常張卿二十韻', '奉贈太常張卿二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["方丈三韓外，崑崙萬國西。","建標天地闊，詣絕古今迷。","氣得神仙迥，恩承雨露低。","相門清議衆，儒術大名齊。","軒冕羅天闕，琳琅識介珪。","伶官詩必誦，夔樂典猶稽。","健筆凌鸚鵡，銛鋒瑩鸊鵜。","友于皆挺拔，公望各端倪。","通籍踰青瑣，亨衢照紫泥。","靈虯傳夕箭，歸馬散霜蹄。","能事聞重譯，嘉謨及遠黎。","弼諧方一展，班序更何躋。","適越空顛躓，遊梁竟慘悽。","謬知終畫虎，微分是醯雞。","萍泛無休日，桃陰想舊蹊。","吹噓人所羨，騰躍事仍暌。","碧海真難涉，青雲不可梯。","顧深慙鍛煉，才小辱提攜。","檻束哀猨叫，枝驚夜鵲棲。","幾時陪羽獵，應指釣璜溪。"]', '["方丈三韓外，崑崙万国西。","建標天地闊，詣絕古今迷。","氣得神仙迥，恩承雨露低。","相门清議衆，儒術大名齊。","軒冕羅天闕，琳琅識介珪。","伶官诗必誦，夔乐典猶稽。","健笔凌鸚鵡，銛鋒瑩鸊鵜。","友于皆挺拔，公望各端倪。","通籍踰青瑣，亨衢照紫泥。","靈虯傳夕箭，归马散霜蹄。","能事闻重譯，嘉謨及远黎。","弼諧方一展，班序更何躋。","適越空顛躓，游梁竟慘悽。","謬知終畫虎，微分是醯雞。","萍泛無休日，桃陰想旧蹊。","吹噓人所羨，腾躍事仍暌。","碧海真难涉，青云不可梯。","顧深慙鍛煉，才小辱提携。","檻束哀猨叫，枝驚夜鵲棲。","幾时陪羽獵，應指釣璜溪。"]', '诗', 'shi', '', NULL, '奉贈太常張卿二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4349582-0e9c-466c-8a27-da4663f34029', '敬贈鄭諫議十韻', '敬贈鄭諫議十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["諫官非不達，詩義早知名。","破的由來事，先鋒孰敢爭。","思飄雲物外，律中鬼神驚。","毫髮無遺恨，波瀾獨老成。","野人寧得所，天意薄浮生。","多病休儒服，冥搜信客旌。","築居仙縹緲，旅食歲崢嶸。","使者求顏闔，諸公厭禰衡。","將期一諾重，歘使寸心傾。","君見途窮哭，宜憂阮步兵。"]', '["諫官非不達，诗義早知名。","破的由来事，先鋒孰敢爭。","思飄云物外，律中鬼神驚。","毫髮無遺恨，波瀾独老成。","野人寧得所，天意薄浮生。","多病休儒服，冥搜信客旌。","築居仙縹緲，旅食歲崢嶸。","使者求顏闔，諸公厭禰衡。","將期一諾重，歘使寸心傾。","君见途窮哭，宜憂阮步兵。"]', '诗', 'shi', '', NULL, '敬贈鄭諫議十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b2022c-a970-4fab-ab56-3b7b55e78096', '奉贈鮮于京兆二十韻', '奉贈鲜于京兆二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["王國稱多土，賢良復幾人。","異才應間出，爽氣必殊倫。","始見張京兆，宜居漢近臣。","驊騮開道路，鵰鶚離風塵。","侯伯知何等，文章實致身。","奮飛超等級，容易失沈淪。","脫略磻谿釣，操持郢匠斤。","雲霄今已逼，台衮更誰親。","鳳穴雛皆好，龍門客又新。","義聲紛感激，敗績自逡巡。","途遠欲何向，天高難重陳。","學詩猶孺子，鄉賦念嘉賓。","不得同鼌錯，吁嗟後郄詵。","計疎疑翰墨，時過憶松筠。","獻納紆皇眷，中間謁紫宸。","且隨諸彥集，方凱薄才伸。","破膽遭前政，陰謀獨秉鈞。","微生霑忌刻，萬事益酸辛。","交合丹青地，恩傾雨露辰。","有儒愁餓死，早晚報平津。"]', '["王国稱多土，賢良复幾人。","異才應间出，爽氣必殊倫。","始见張京兆，宜居漢近臣。","驊騮开道路，鵰鶚離风塵。","侯伯知何等，文章實致身。","奮飞超等級，容易失沈淪。","脫略磻谿釣，操持郢匠斤。","云霄今已逼，台衮更誰親。","鳳穴雛皆好，龙门客又新。","義声紛感激，敗績自逡巡。","途远欲何向，天高难重陳。","学诗猶孺子，乡賦念嘉賓。","不得同鼌錯，吁嗟後郄詵。","計疎疑翰墨，时過憶松筠。","獻納紆皇眷，中间謁紫宸。","且隨諸彥集，方凱薄才伸。","破膽遭前政，陰謀独秉鈞。","微生霑忌刻，万事益酸辛。","交合丹青地，恩傾雨露辰。","有儒愁餓死，早晚報平津。"]', '诗', 'shi', '', NULL, '奉贈鮮于京兆二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e164a6-e25b-497c-993b-6a2f63e25daa', '贈特進汝陽王二十韻', '贈特進汝陽王二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["特進羣公表，天人夙德升。","霜蹄千里駿，風翮九霄鵬。","服禮求毫髮，惟忠忘寢興。","聖情常有眷，朝退若無憑。","仙醴來浮蟻，奇毛或賜鷹。","清關塵不雜，中使日相乘。","晚節嬉遊簡，平居孝義稱。","自多親棣萼，誰敢問山陵。","學業醇儒富，辭華哲匠能。","筆飛鸞聳立，章罷鳳騫騰。","精理通談笑，忘形向友朋。","寸長堪繾綣，一諾豈驕矜。","已忝歸曹植，何知對李膺。","招要恩屢至，崇重力難勝。","披霧初歡夕，高秋爽氣澄。","尊罍臨極浦，鳧雁宿張燈。","花月窮游宴，炎天避鬱蒸。","研寒金井水，檐動玉壺冰。","瓢飲唯三徑，巖棲在百層。","且持蠡測海，況挹酒如澠。","鴻寶寧全祕，丹梯庶可凌。","淮王門有客，終不媿孫登。"]', '["特進羣公表，天人夙德升。","霜蹄千里駿，风翮九霄鵬。","服禮求毫髮，惟忠忘寢兴。","聖情常有眷，朝退若無憑。","仙醴来浮蟻，奇毛或賜鷹。","清关塵不杂，中使日相乘。","晚節嬉游簡，平居孝義稱。","自多親棣萼，誰敢问山陵。","学業醇儒富，辞华哲匠能。","笔飞鸾聳立，章罷鳳騫腾。","精理通談笑，忘形向友朋。","寸长堪繾綣，一諾豈驕矜。","已忝归曹植，何知对李膺。","招要恩屢至，崇重力难勝。","披霧初歡夕，高秋爽氣澄。","尊罍臨極浦，鳧雁宿張灯。","花月窮游宴，炎天避鬱蒸。","研寒金井水，檐动玉壺冰。","瓢饮唯三徑，巖棲在百層。","且持蠡測海，況挹酒如澠。","鴻寶寧全祕，丹梯庶可凌。","淮王门有客，終不媿孫登。"]', '诗', 'shi', '', NULL, '贈特進汝陽王二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a35a5c8-851b-4f2d-aa73-a0fd3b2fd2b6', '鄭駙馬宅宴洞中', '鄭駙马宅宴洞中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["主家陰洞細煙霧，留客夏簟清琅玕。","春酒杯濃琥珀薄，冰漿椀碧瑪瑙寒。","誤疑茅堂過江麓，已入風磴霾雲端。","自是秦樓壓鄭谷，時聞雜佩聲珊珊。"]', '["主家陰洞細煙霧，留客夏簟清琅玕。","春酒杯濃琥珀薄，冰漿椀碧瑪瑙寒。","誤疑茅堂過江麓，已入风磴霾云端。","自是秦楼壓鄭谷，时闻杂佩声珊珊。"]', '诗', 'shi', '', NULL, '鄭駙馬宅宴洞中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac8ab3a-5948-40f6-a552-ac94361bfe7e', '李監宅', '李監宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["尚覺王孫貴，豪家意頗濃。","屏開金孔雀，褥隱繡芙蓉。","且食雙魚美，誰看異味重。","門闌多喜色，女壻近乘龍。"]', '["尚覺王孫貴，豪家意頗濃。","屏开金孔雀，褥隐繡芙蓉。","且食雙鱼美，誰看異味重。","门闌多喜色，女壻近乘龙。"]', '诗', 'shi', '', NULL, '李監宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10022fe3-6956-474b-b41e-531c8ef9fc16', '重題鄭氏東亭', '重題鄭氏东亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["華亭入翠微，秋日亂清暉。","崩石欹山樹，清漣曳水衣。","紫鱗衝岸躍，蒼隼護巢歸。","向晚尋征路，殘雲傍馬飛。"]', '["华亭入翠微，秋日亂清暉。","崩石欹山樹，清漣曳水衣。","紫鱗衝岸躍，蒼隼護巢归。","向晚尋征路，殘云傍马飞。"]', '诗', 'shi', '', NULL, '重題鄭氏東亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf913d33-9ec7-4d06-a644-07dc1adafde1', '題張氏隱居二首 一', '題張氏隐居二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春山無伴獨相求，伐木丁丁山更幽。","澗道餘寒歷冰雪，石門斜日到林丘。","不貪夜識金銀氣，遠害朝看糜鹿遊。","乘興杳然迷出處，對君疑是泛虛舟。"]', '["春山無伴独相求，伐木丁丁山更幽。","澗道餘寒歷冰雪，石门斜日到林丘。","不貪夜識金銀氣，远害朝看糜鹿游。","乘兴杳然迷出处，对君疑是泛虛舟。"]', '诗', 'shi', '', NULL, '題張氏隱居二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e70521-2e35-4f23-bde4-64b7cc9a0400', '題張氏隱居二首 二', '題張氏隐居二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["之子時相見，邀人晚興留。","霽潭鱣發發，春草鹿呦呦。","杜酒偏勞勸，張棃不外求。","前村山路險，歸醉每無愁。"]', '["之子时相见，邀人晚兴留。","霽潭鱣發發，春草鹿呦呦。","杜酒偏勞勸，張棃不外求。","前村山路險，归醉每無愁。"]', '诗', 'shi', '', NULL, '題張氏隱居二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4755aa-a07d-4e0a-97b6-afdf906a3f00', '天寶初南曹小司寇舅於我太夫人堂下累土爲山一匱盈尺以代彼朽木承諸焚香瓷甌甌甚安矣旁植慈竹蓋茲數峰嶔岑嬋娟宛有塵外數致乃不知興之所至而作是詩', '天寶初南曹小司寇舅於我太夫人堂下累土爲山一匱盈尺以代彼朽木承諸焚香瓷甌甌甚安矣旁植慈竹蓋茲數峰嶔岑嬋娟宛有塵外數致乃不知兴之所至而作是诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一匱功盈尺，三峰意出羣。","望中疑在野，幽處欲生雲。","慈竹春陰覆，香爐曉勢分。","惟南將獻壽，佳氣日氛氳。"]', '["一匱功盈尺，三峰意出羣。","望中疑在野，幽处欲生云。","慈竹春陰覆，香爐晓勢分。","惟南將獻壽，佳氣日氛氳。"]', '诗', 'shi', '', NULL, '天寶初南曹小司寇舅於我太夫人堂下累土爲山一匱盈尺以代彼朽木承諸焚香瓷甌甌甚安矣旁植慈竹蓋茲數峰嶔岑嬋娟宛有塵外數致乃不知興之所至而作是詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa5d85b7-f78f-4be4-9419-8453c46dd842', '龍門', '龙门', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["龍門橫野斷，驛樹出城來。","氣色皇居近，金銀佛寺開。","往還時屢改，川水日悠哉。","相閱征途上，生涯盡幾迴。"]', '["龙门橫野斷，驛樹出城来。","氣色皇居近，金銀佛寺开。","往還时屢改，川水日悠哉。","相閱征途上，生涯尽幾迴。"]', '诗', 'shi', '', NULL, '龍門 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c762309-e91e-4231-bf09-ab28d7802bd4', '奉寄河南韋尹丈人', '奉寄河南韋尹丈人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有客傳河尹，逢人問孔融。","青囊仍隱逸，章甫尚西東。","鼎石分門戶，詞場繼國風。","尊榮瞻地絕，疎放憶途窮。","濁酒尋陶令，丹砂訪葛洪。","江湖漂短褐，霜雪滿飛蓬。","牢落乾坤大，周流道術空。","謬慙知薊子，真怯笑揚雄。","盤錯神明懼，謳歌德義豐。","尸鄉餘土室，難說祝雞翁。"]', '["有客傳河尹，逢人问孔融。","青囊仍隐逸，章甫尚西东。","鼎石分门戶，词場繼国风。","尊榮瞻地絕，疎放憶途窮。","濁酒尋陶令，丹砂訪葛洪。","江湖漂短褐，霜雪满飞蓬。","牢落乾坤大，周流道術空。","謬慙知薊子，真怯笑揚雄。","盤錯神明懼，謳歌德義豐。","尸乡餘土室，难说祝雞翁。"]', '诗', 'shi', '', NULL, '奉寄河南韋尹丈人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb56d01-0200-4756-88c3-e8708cc5ca44', '赠李白', '赠李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋來相顧尚飄蓬，未就丹砂媿葛洪。","痛飲狂歌空度日，飛揚跋扈爲誰雄。"]', '["秋来相顧尚飄蓬，未就丹砂媿葛洪。","痛饮狂歌空度日，飞揚跋扈爲誰雄。"]', '诗', 'shi', '', NULL, '赠李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1499110-9316-46f9-bc91-4a57ec461761', '與任城許主簿遊南池', '與任城許主簿游南池', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋水通溝洫，城隅進小船。","晚涼看洗馬，森木亂鳴蟬。","菱熟經時雨，蒲荒八月天。","晨朝降白露，遙憶舊青氊。"]', '["秋水通溝洫，城隅進小船。","晚涼看洗马，森木亂鳴蟬。","菱熟經时雨，蒲荒八月天。","晨朝降白露，遙憶旧青氊。"]', '诗', 'shi', '', NULL, '與任城許主簿遊南池 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eabe74ad-1a13-481d-92e4-9207a59396c5', '登兖州城樓', '登兖州城楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東郡趨庭日，南樓縱目初。","浮雲連海嶽，平野入青徐。","孤嶂秦碑在，荒城魯殿餘。","從來多古意，臨眺獨躊躇。"]', '["东郡趨庭日，南楼縱目初。","浮云連海嶽，平野入青徐。","孤嶂秦碑在，荒城魯殿餘。","從来多古意，臨眺独躊躇。"]', '诗', 'shi', '', NULL, '登兖州城樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a04ad47-c0ea-461f-aa52-f89454a1b4eb', '劉九法曹鄭瑕丘石門宴集', '劉九法曹鄭瑕丘石门宴集', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋水清無底，蕭然靜客心。","掾曹乘逸興，鞍馬去相尋。","能吏逢聊璧，華筵直一金。","晚來橫吹好，泓下亦龍吟。"]', '["秋水清無底，蕭然静客心。","掾曹乘逸兴，鞍马去相尋。","能吏逢聊璧，华筵直一金。","晚来橫吹好，泓下亦龙吟。"]', '诗', 'shi', '', NULL, '劉九法曹鄭瑕丘石門宴集 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2d7277-b99e-4dec-88ae-2ccd1fe594c9', '暫如臨邑至㟙山湖亭奉懷李員外率爾成興', '暫如臨邑至㟙山湖亭奉懷李員外率爾成兴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野亭逼湖水，歇馬高林間。","鼉吼風奔浪，魚跳日映山。","暫遊阻詞伯，却望懷青關。","靄靄生雲霧，唯應促駕還。"]', '["野亭逼湖水，歇马高林间。","鼉吼风奔浪，鱼跳日映山。","暫游阻词伯，却望懷青关。","靄靄生云霧，唯應促駕還。"]', '诗', 'shi', '', NULL, '暫如臨邑至㟙山湖亭奉懷李員外率爾成興 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fea6e004-d905-4fa0-9f6c-c813af7862e6', '對雨書懷走邀許十一簿公', '对雨书懷走邀許十一簿公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東岳雲峰起，溶溶滿太虛。","震雷飜幕燕，驟雨落河魚。","座對賢人酒，門聽長者車。","相邀媿泥濘，騎馬到階除。"]', '["东岳云峰起，溶溶满太虛。","震雷飜幕燕，驟雨落河鱼。","座对賢人酒，门听长者车。","相邀媿泥濘，騎马到階除。"]', '诗', 'shi', '', NULL, '對雨書懷走邀許十一簿公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502e6a94-3ae9-4b92-920c-4ab6db1213da', '巳上人茅齋', '巳上人茅斋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巳公茅屋下，可以賦新詩。","枕簟入林僻，茶瓜留客遲。","江蓮搖白羽，天棘夢青絲空忝許詢輩，難酬支遁詞。"]', '["巳公茅屋下，可以賦新诗。","枕簟入林僻，茶瓜留客遲。","江蓮搖白羽，天棘梦青絲空忝許詢輩，难酬支遁词。"]', '诗', 'shi', '', NULL, '巳上人茅齋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47cb698a-c951-49a4-b17c-032bc033ac87', '房兵曹胡馬詩', '房兵曹胡马诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["胡馬大宛名，鋒棱瘦骨成。","竹批雙耳峻，風入四蹄輕。","所向無空闊，真堪託死生。","驍騰有如此，萬里可橫行。"]', '["胡马大宛名，鋒棱瘦骨成。","竹批雙耳峻，风入四蹄轻。","所向無空闊，真堪託死生。","驍腾有如此，万里可橫行。"]', '诗', 'shi', '', NULL, '房兵曹胡馬詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f190888-4df3-4c51-81d4-42237f9f60fc', '畫鷹', '畫鷹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["素練風霜起，蒼鷹畫作殊。","身思狡兔，俱目似愁胡。","絛旋光堪擿，軒楹勢可呼。","何當擊凡鳥，毛血灑平蕪。"]', '["素練风霜起，蒼鷹畫作殊。","身思狡兔，俱目似愁胡。","絛旋光堪擿，軒楹勢可呼。","何當擊凡鸟，毛血灑平蕪。"]', '诗', 'shi', '', NULL, '畫鷹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b7dbe3-a2e2-47a2-9ca0-32413250c0c4', '與李十二白同尋范十隱居', '與李十二白同尋范十隐居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["李侯有佳句，往往似陰鏗。","余亦東蒙客，憐君如弟兄。","醉眠秋共被，攜手日同行。","更想幽期處，還尋北郭生。","入門高興發，侍立小童清。","落景聞寒杵，屯雲對古城。","向來吟橘頌，誰欲討蓴羹。","不願論簪笏，悠悠滄海情。"]', '["李侯有佳句，往往似陰鏗。","余亦东蒙客，怜君如弟兄。","醉眠秋共被，携手日同行。","更想幽期处，還尋北郭生。","入门高兴發，侍立小童清。","落景闻寒杵，屯云对古城。","向来吟橘頌，誰欲討蓴羹。","不願論簪笏，悠悠滄海情。"]', '诗', 'shi', '', NULL, '與李十二白同尋范十隱居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df4bd05c-a0a4-4c19-8e8d-ada2db3ccbf2', '臨邑舍弟書至苦雨黃河泛溢隄防之患簿領所憂因寄此詩用寬其意', '臨邑舍弟书至苦雨黄河泛溢隄防之患簿領所憂因寄此诗用寬其意', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二儀積風雨，百谷漏波濤。","聞道洪何坼，遙連滄海高。","職思憂悄悄，郡國訴嗷嗷。","舍弟卑棲邑，防川領簿曹。","尺書前日至，版築不時操。","難假黿鼉力，空瞻烏鵲毛。","燕南吹畎畝，濟上沒蓬蒿。","螺蚌滿近郭，蛟螭乘九臯。","徐關深水府，碣石小秋毫。","白屋留孤樹，清天矢萬艘。","吾衰同泛梗，利涉想蟠桃。","倚賴天涯釣，猶能掣巨鼇。"]', '["二儀積风雨，百谷漏波濤。","闻道洪何坼，遙連滄海高。","職思憂悄悄，郡国訴嗷嗷。","舍弟卑棲邑，防川領簿曹。","尺书前日至，版築不时操。","难假黿鼉力，空瞻烏鵲毛。","燕南吹畎畝，濟上沒蓬蒿。","螺蚌满近郭，蛟螭乘九臯。","徐关深水府，碣石小秋毫。","白屋留孤樹，清天矢万艘。","吾衰同泛梗，利涉想蟠桃。","倚賴天涯釣，猶能掣巨鼇。"]', '诗', 'shi', '', NULL, '臨邑舍弟書至苦雨黃河泛溢隄防之患簿領所憂因寄此詩用寬其意 杜甫 shi');
